INSERT INTO `sync_articles` VALUES (1, '29966127', 'Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh: Nhiều ý kiến tham gia thảo luận ở tổ', 'Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh: Nhiều ý kiến tham gia thảo luận ở tổ', '/documents/37632/23566312/a1.jpg/f4d6e3ea-3c22-ddf4-fff5-6304a8ddd215?t=1761895057203', '<p>(BNP) - Sáng 31/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, sau khi nghe các báo cáo, tờ trình, các đại biểu Quốc hội tham gia thảo luận ở tổ, cho ý kiến vào các Dự án: Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế; Luật sửa đổi, bổ sung một số điều của Luật Công...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a1.jpg/f4d6e3ea-3c22-ddf4-fff5-6304a8ddd215?t=1761895057203\" style=\"width: 900px; height: 596px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh phiên thảo luận ở tổ của Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cơ bản nhất trí với các tờ trình và báo cáo thẩm tra về sự cần thiết của 2 dự án luật nhằm kịp thời quán triệt, thể chế các chủ trương, đường lối, quan điểm chỉ đạo của Đảng về ngoại giao và phát triển công nghiệp quốc phòng, anh ninh. Nội dung của 2 dự thảo luật phù hợp với chủ trương, đường lối, quan điểm chỉ đạo của Đảng; bảo đảm tính hợp hiến, hợp pháp, thống nhất trong hệ thống pháp luật. Qua đó, tạo hành lang pháp lý để tạo lập môi trường phát triển công nghiệp an ninh, đáp ứng yêu cầu cấp bách của tình hình thực tiễn; đồng thời đáp ứng yêu cầu chính trị, công tác đối ngoại, hội nhập quốc tế của Đảng và Nhà nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu cũng tham góp nhiều ý kiến xác đáng để cơ quan soạn thảo tiếp tục hoàn thiện 2 dự án luật bảo đảm tính khả thi cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Góp ý vào dự án Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp, đại biểu Trần Văn Lâm, Ủy viên chuyên trách Ủy ban Công tác đại biểu của Quốc hội cơ bản nhất trí với các quy định về Quỹ đầu tư phát triển công nghiệp an ninh, Tổ hợp công nghiệp an ninh quốc gia, với các cơ chế, chính sách đặc thù, vượt trội nhằm tạo lập môi trường phát triển công nghiệp an ninh, đáp ứng yêu cầu cấp bách của tình hình thực tiễn.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a5.jpg/b295eaa3-b8bd-c44a-646d-fe1239e170f4?t=1761895116198\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Lâm phát biểu thảo luận tại tổ, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, đại biểu cũng đề nghị Ban soạn thảo tiếp tục nghiên cứu, làm rõ và hoàn thiện một số quy định để bảo đảm tính hiệu quả và khả thi. Khi xây dựng cơ chế phải tính toán tận dụng hiệu quả các nguồn lực đầu tư để công nghệ quốc phòng có thể sử dụng cho an ninh và ngược lại công nghệ của an ninh có thể sử dụng cho quốc phòng. Cần có cơ chế phối hợp giữa hai quỹ này để khi cần huy động nguồn lực tổng hợp thì có thể cả hai quỹ này cùng hỗ trợ được, còn trong điều kiện bình thường thì các bên chủ động. Từ đó, tạo sức mạnh tổng hợp quốc gia phát triển các lĩnh vực công nghiệp quốc phòng, an ninh một cách hiệu quả nhất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Trưởng Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh Trần Thị Vân cũng nhất trí về sự cần thiết và các nội dung lớn của dự án Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp. Đồng thời góp ý một số nội dung:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về chức năng, nhiệm vụ của tổ hợp công nghiệp an ninh, đại biểu đề nghị Ban soạn thảo rà soát kỹ để bảo đảm không bỏ sót nội dung quan trọng và tránh chồng chéo với các cơ quan, tổ chức, doanh nghiệp hiện có. Xem xét bổ sung khái niệm “công nghệ chiến lược” trong phần giải thích từ ngữ của dự thảo Luật, bao quát phạm vi điều chỉnh của Luật. Luật hiện hành đã giải thích tương đối rõ các khái niệm “công nghệ nền” và “công nghệ lõi”. Trên thực tế, quá trình triển khai công nghiệp quốc phòng, an ninh cho thấy cần xác định thêm một nhóm “công nghệ chiến lược”, có ý nghĩa định hướng, chi phối, bảo đảm ưu thế công nghệ và khả năng tự chủ quốc gia trong lĩnh vực quốc phòng, an ninh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về thành phần của tổ hợp công nghiệp an ninh quốc gia, đề nghị Ban soạn thảo bổ sung khái niệm “Hội đồng quản lý phát triển công nghiệp an ninh” trong phần giải thích từ ngữ của dự thảo Luật, nhằm làm rõ vị trí pháp lý, chức năng, nhiệm vụ và thẩm quyền của tổ chức này trong hệ thống cơ quan quản lý nhà nước về công nghiệp an ninh, tránh tình trạng lúng túng trong thực thi và chồng chéo với các cơ quan quản lý, điều phối khác trong lĩnh vực công nghiệp an ninh.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a4+copy.jpg/322d4dca-0a2e-b20a-4b2d-74e43feeb521?t=1761895170266\" style=\"width: 900px; height: 649px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Thị Vân tham gia thảo luận ở tổ, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cũng đề nghị bổ sung quy định về tiêu chí lựa chọn doanh nghiệp, tổ chức tham gia Tổ hợp công nghiệp an ninh quốc gia nhằm bảo đảm tính minh bạch, khách quan và thống nhất trong quá trình lựa chọn, tránh tình trạng áp dụng tùy tiện hoặc mang tính hành chính, hình thức. Đây cũng là giải pháp quan trọng nhằm nâng cao hiệu quả hoạt động của Tổ hợp công nghiệp an ninh quốc gia, bảo đảm Tổ hợp thực sự quy tụ được các đơn vị có năng lực, uy tín, đủ sức tham gia thực hiện các nhiệm vụ trọng yếu, chiến lược về công nghiệp an ninh trong tình hình mới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về thành viên tham gia tổ hợp công nghiệp an ninh quốc gia, đại biểu cho rằng một số nội dung cần được quy định cụ thể, rõ ràng hơn để bảo đảm tính khả thi và đồng bộ với hệ thống pháp luật hiện hành:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Về tiêu chí và cơ chế lựa chọn thành viên: Hiện dự thảo mới dừng ở quy định “thành viên tham gia là tổ chức, doanh nghiệp trong và ngoài Công an nhân dân có năng lực, tiềm lực khoa học và công nghệ”. Quy định này còn chung chung, thiếu tiêu chí định lượng và cơ chế đánh giá năng lực. Đề nghị Ban soạn thảo nghiên cứu, bổ sung quy định cụ thể tiêu chí lựa chọn thành viên, bao gồm: năng lực nghiên cứu - sản xuất, tiềm lực tài chính, năng lực công nghệ, uy tín, kinh nghiệm hợp tác trong lĩnh vực an ninh, bảo đảm an ninh thông tin và bí mật nhà nước; đồng thời có quy định nhằm khuyến khích doanh nghiệp tư nhân công nghệ cao, doanh nghiệp khởi nghiệp sáng tạo, viện nghiên cứu, cơ sở giáo dục đại học đủ năng lực tham gia, tạo điều kiện mở rộng hệ sinh thái đổi mới sáng tạo trong lĩnh vực công nghiệp an ninh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Về&nbsp;cơ chế phối hợp, điều hành và chia sẻ thông tin: Hiện dự thảo chưa quy định rõ cơ chế phối hợp giữa các thành viên trong Tổ hợp. Đề nghị bổ sung quy định cụ thể cơ chế điều phối, liên kết sản xuất - nghiên cứu - thử nghiệm - thương mại hóa sản phẩm giữa các thành viên, bảo đảm hoạt động theo chuỗi giá trị, tránh trùng lặp hoặc cạnh tranh không lành mạnh; thiết lập cơ chế chia sẻ thông tin, dữ liệu và kết quả nghiên cứu trong phạm vi được phép, có cơ chế bảo vệ bí mật nhà nước và bảo mật thương mại, bảo đảm an toàn thông tin và quyền sở hữu trí tuệ; xây dựng hệ thống đánh giá, xếp hạng và kiểm tra định kỳ đối với các thành viên Tổ hợp, làm căn cứ xem xét duy trì hoặc rút tư cách thành viên, bảo đảm tính kỷ luật, chuyên nghiệp và hiệu quả trong hoạt động.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà (Phó Giám đốc Sở Tư pháp tỉnh Bắc Ninh) đóng góp ý kiến vào 3 nội dung lớn trong dự án Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a2+%281%29.jpg/ca69b020-8cea-d835-dee6-dabcf65515b1?t=1761895220926\" style=\"width: 900px; height: 616px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Việt Hà tham gia thảo luận tại tổ, sáng 31/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về hồ sơ trình về việc đàm phán điều ước quốc tế, tại khoản 3, Điều 1 dự thảo Luật bổ sung khoản 1a Điều 11 của Luật Điều ước quốc tế quy định: “Trường hợp cơ quan có thẩm quyền của Đảng, Chủ tịch nước, Thủ tướng Chính phủ đã có chỉ đạo bằng văn bản về việc quyết định đàm phán điều ước quốc tế, hồ sơ trình về việc đàm phán chỉ cần bao gồm nội dung kiến nghị ủy quyền đàm phán.”. Đồng thời, sửa đổi khoản 2 Điều 11 của Luật Điều ước quốc tế: “Trong trường hợp cần thiết, cơ quan đề xuất kiến nghị kết thúc đàm phán điều ước quốc tế. Hồ sơ trình về việc kết thúc đàm phán điều ước quốc tế phải bao gồm dự thảo điều ước quốc tế thể hiện phương án kết thúc đàm phán.” Những quy định mới này nhằm rút gọn thủ tục, tăng tính chủ động cho cơ quan đề xuất, phù hợp với chủ trương phân quyền, phân cấp trong công tác đối ngoại, đồng thời đáp ứng những tình huống thực tế phát sinh trong đàm phán quốc tế - đặc biệt là các cuộc đàm phán đa phương, hoặc đàm phán cấp cao được tiến hành trong thời gian ngắn theo chỉ đạo trực tiếp của Bộ Chính trị, Ban Bí thư, Chủ tịch nước hay Thủ tướng Chính phủ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, để bảo đảm tính minh bạch, hợp pháp và tránh bị lạm dụng, đại biểu đề nghị cần quy định cụ thể loại văn bản nào được coi là “chỉ đạo bằng văn bản” nhằm tránh trường hợp áp dụng tùy tiện các văn bản hành chính thông thường có thể ảnh hưởng đến tính pháp lý và tính chính thống của quy trình đàm phán. Về phạm vi áp dụng, cần xác định rõ những loại điều ước quốc tế nào được phép áp dụng quy định rút gọn này, không nên áp dụng đối với điều ước có nội dung tạo nghĩa vụ tài chính hoặc làm phát sinh cam kết pháp lý quốc tế phức tạp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về quy định “trong trường hợp cần thiết”, đại biểu cho rằng đây là cụm từ mang tính định tính, nếu không quy định rõ, có thể dẫn đến tùy nghi áp dụng, ảnh hưởng đến tính thống nhất và trách nhiệm giải trình. Vì vậy, đề nghị Ban soạn thảo nghiên cứu, quy định tiêu chí rõ ràng về các trường hợp cần thiết.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về chấp nhận hoặc phản đối bảo lưu của bên ký kết nước ngoài (khoản 13, Điều 1, dự thảo luật), đại biểu cho rằng cần thiết phải bổ sung nguyên tắc pháp lý rõ ràng làm cơ sở cho việc quyết định chấp nhận hay phản đối bảo lưu, đồng thời quy định rõ cơ chế phối hợp giữa Bộ Ngoại giao và các bộ, ngành trong quá trình tham mưu, đề xuất phương án xử lý để bảo đảm&nbsp;thống nhất, minh bạch và bảo vệ lợi ích quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự thảo luật cho phép Bộ Ngoại giao kịp thời thông báo khi bên nước ngoài đưa ra bảo lưu đối với điều ước quốc tế mà Việt Nam là thành viên, nhằm&nbsp;bảo đảm&nbsp;các cơ quan, tổ chức liên quan nắm bắt kịp thời, chủ động trong xử lý. Đây là quy định tiến bộ, thể hiện sự hoàn thiện về mặt quy trình trong công tác quản lý, thực thi điều ước quốc tế, đặc biệt trong bối cảnh số lượng và phạm vi điều ước mà Việt Nam tham gia ngày càng mở rộng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, dự thảo mới chỉ dừng lại ở cơ chế thông báo, mà chưa quy định cụ thể nguyên tắc, tiêu chí và thẩm quyền trong việc xem xét, quyết định chấp nhận hoặc phản đối bảo lưu của bên nước ngoài. Thực tiễn cho thấy, việc xác định quan điểm đối với bảo lưu của các quốc gia đối tác có thể ảnh hưởng trực tiếp đến hiệu lực áp dụng của điều ước quốc tế tại Việt Nam, cũng như tác động đến lợi ích, nghĩa vụ pháp lý của nước ta. Nếu thiếu căn cứ rõ ràng và thống nhất, dễ dẫn đến cách hiểu và áp dụng tùy tiện giữa các cơ quan, thậm chí tạo ra rủi ro pháp lý hoặc xung đột trong thực thi điều ước. Do đó, cần thiết phải bổ sung nguyên tắc pháp lý rõ ràng làm cơ sở cho việc quyết định chấp nhận hay phản đối bảo lưu, đồng thời quy định rõ cơ chế phối hợp giữa Bộ Ngoại giao và các bộ, ngành trong quá trình tham mưu, đề xuất phương án xử lý để đảm bảo thống nhất, minh bạch và bảo vệ lợi ích quốc gia. Đề nghị Ban soạn thảo nghiên cứu, bổ sung điểm mới vào cuối khoản 13, Điều 1 dự thảo Luật quy định về nguyên tắc bảo lưu, với nội dung: “Việc chấp nhận hoặc phản đối bảo lưu của nước ngoài được thực hiện trên cơ sở nguyên tắc bảo đảm chủ quyền, an ninh, lợi ích quốc gia, phù hợp với mục tiêu, phạm vi điều ước và thông lệ pháp lý quốc tế.”</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về đăng tải điều ước quốc tế (khoản 16, Điều 1, dự thảo luật), đại biểu tán thành với hướng sửa đổi Điều 60 của luật hiện hành. Đề nghị hoàn thiện cơ chế bảo mật, xác thực điện tử và phối hợp liên ngành để quy định này thực sự khả thi, hiệu quả và phù hợp với xu thế quản trị quốc gia hiện đại. Đề nghị Ban soạn thảo nghiên cứu, bổ sung tiêu chí rõ ràng cho việc không đăng tải công khai (điều ước liên quan đến quốc phòng, tình báo, an ninh hoặc nội dung thuộc danh mục bí mật nhà nước…); đồng thời bổ sung quy định yêu cầu cơ quan được miễn công bố phải lưu trữ và quản lý bản gốc trong hệ thống hồ sơ mật của Bộ Ngoại giao, bảo đảm truy xuất phục vụ kiểm tra, giám sát.</span></span></span></p>', '31/10/2025 14:15', 'https://bacninh.gov.vn/news/-/details/37632/-oan-ai-bieu-quoc-hoi-tinh-bac-ninh-nhieu-y-kien-tham-gia-thao-luan-o-to-29966127', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 49, 'Chính trị', 2, 'true', '38762', '{}', '2025-10-31 08:44:55.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (2, '29859613', 'Hôm nay (31/10), Quốc hội nghe Tờ trình, Báo cáo thẩm tra về một số Dự án Luật...', 'Hôm nay (31/10), Quốc hội nghe Tờ trình, Báo cáo thẩm tra về một số Dự án Luật lĩnh vực an ninh, trật tự và thảo luận ở tổ', '/documents/37632/23566312/z7169768632174_aa88d188e5b26bb764ae5fb05a3f7c25.jpg/cc35e685-2429-d7e8-0ca3-30fe488d28d7?t=1761873754805', '<p>(BNP) - Theo chương trình kỳ họp thứ 10, hôm nay (31/10), Quốc hội nghe Tờ trình, Báo cáo thẩm tra về một số Dự án Luật lĩnh vực an ninh, trật tự và thảo luận ở tổ.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23566312/z7169768632174_aa88d188e5b26bb764ae5fb05a3f7c25.jpg/cc35e685-2429-d7e8-0ca3-30fe488d28d7?t=1761873754805\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh họp tại hội trường ngày 30/10.</span></span></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong buổi sáng, Quốc hội họp phiên toàn thể tại hội trường, nghe Tờ trình và Báo cáo thẩm tra về 04 dự án: Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp; Luật An ninh mạng; Luật Bảo vệ bí mật nhà nước (sửa đổi); Luật sửa đổi, bổ sung một số điều của 10 luật có liên quan đến an ninh, trật tự; nghe Tờ trình và Báo cáo thẩm tra về dự thảo Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế. Tiếp đó, Quốc hội nghe Tờ trình và Báo cáo thẩm tra về 03 dự án: Luật Chuyển đổi số, Luật Công nghệ cao (sửa đổi), Luật sửa đổi, bổ sung một số điều của Luật Chuyển giao công nghệ. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau đó, Quốc hội thảo luận ở tổ về Dự án Luật sửa đổi, bổ sung một số điều của Luật Điều ước quốc tế; Dự án Luật sửa đổi, bổ sung một số điều của Luật Công nghiệp quốc phòng, an ninh và động viên công nghiệp. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi chiều, Quốc hội tiếp tục thảo luận ở tổ về Luật An ninh mạng; Luật Bảo vệ bí mật nhà nước (sửa đổi) và Luật sửa đổi, bổ sung một số điều của 10 luật có liên quan đến an ninh, trật tự.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng nay, Quốc hội sẽ nghe tờ trình về 16 dự thảo luật. Sau đó, Quốc hội dành thời gian còn lại của buổi sáng và cả buổi chiều để thảo luận về các luật liên quan đến lĩnh vực an ninh, trật tự.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\"></span></span></span></span></span></span></p>', '31/10/2025 08:20', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-31-10-quoc-hoi-nghe-to-trinh-bao-cao-tham-tra-ve-mot-so-du-an-luat-linh-vuc-an-ninh-trat-tu-va-thao-luan-o-to-29859613', '', 'BNP', 27, 'Chính trị', 2, 'true', '38762', '{}', '2025-10-31 08:44:55.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (3, '29507401', 'Thành lập Hội đồng Giáo dục quốc phòng và an ninh tỉnh Bắc Ninh', 'Thành lập Hội đồng Giáo dục quốc phòng và an ninh tỉnh Bắc Ninh', '/documents/37632/200616/IMG_8222.jpg/cc40d36b-0393-1d31-aabd-3b174fea4c78?t=1761809845419', '<p>(BNP) - Chủ tịch UBND tỉnh Vương Quốc Tuấn vừa ký, ban hành Quyết định số 1266/QĐ-UBND về thành lập Hội đồng Giáo dục quốc phòng và an ninh (QP&amp;AN) tỉnh Bắc Ninh.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/200616/IMG_8222.jpg/cc40d36b-0393-1d31-aabd-3b174fea4c78?t=1761809845419\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hội đồng Giáo dục QP&amp;AN tỉnh Bắc Ninh có nhiệm vụ tham mưu, thực hiện công tác giáo dục QP&amp;AN trên địa bàn tỉnh.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Theo Quyết định, Hội đồng Giáo dục QP&amp;AN tỉnh Bắc Ninh do Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn làm Chủ tịch; 04 Phó Chủ tịch Hội đồng và các thành viên là lãnh đạo các Sở, ban, ngành, tổ chức chính trị - xã hội liên quan của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Thành lập Ban Thường trực Hội đồng Giáo dục QP&amp;AN tỉnh Bắc Ninh gồm 15 thành viên là lãnh đạo các Sở, ban, ngành, tổ chức chính trị - xã hội liên quan của tỉnh do Đại tá Phạm Văn Tạo, Chỉ huy trưởng Bộ CHQS tỉnh làm Trưởng ban.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Hội đồng Giáo dục QP&amp;AN tỉnh có nhiệm vụ tham mưu, đề xuất giúp Tỉnh ủy, HĐND, UBND tỉnh chỉ đạo thực hiện nhiệm vụ công tác giáo dục QP&amp;AN của tỉnh; kiến nghị với các cơ quan chức năng cấp trên hoặc trình Chủ tịch Hội đồng Giáo dục QP&amp;AN cấp trên giải quyết những vấn đề liên quan trong quá trình thực hiện nhiệm vụ giáo dục QP&amp;AN của tỉnh. Xây dựng kế hoạch, đề án, nhiệm vụ quan trọng về công tác giá dục QP&amp;AN trình UBND tỉnh, Chủ tịch UBND tỉnh phê duyệt. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Chỉ đạo các sở, ban, ngành, đoàn thể tỉnh và Hội đồng Giáo dục QP&amp;AN các xã, phường tổ chức triển khai, thực hiện có hiệu quả các chủ trương, chính sách của Đảng, pháp luật của Nhà nước; các văn bản chỉ đạo, hướng dẫn của các Bộ, ngành Trung ương, của Tỉnh ủy, HĐND, UBND tỉnh về thực hiện công tác giáo dục QP&amp;AN. Hằng năm chỉ đạo cơ quan Thường trực Hội đồng giáo dục QP&amp;AN tỉnh phối hợp sở, ban, ngành, đoàn thể tỉnh và Hội đồng Giáo dục QP&amp;AN các xã, phường xây dựng kế hoạch, tổ chức bồi dưỡng kiến thức QP&amp;AN cho đối tượng 3, đối tượng 4 theo quy định. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Hội đồng Giáo dục QP&amp;AN tỉnh có quyền yêu cầu các cơ quan, đơn vị, địa phương, nhà trường báo cáo tình hình, cung cấp thông tin các vấn đề liên quan đến việc thực hiện nhiệm vụ giáo dục QP&amp;AN. Định kỳ hằng tháng hoặc đột xuất báo cáo kết quả giáo dục QP&amp;AN với Tỉnh ủy, UBND tỉnh, Hội đồng Giáo dục QP&amp;AN Quân khu 1, Hội đồng Giáo dục QP&amp;AN Trung ương.</span></span></span></p>', '31/10/2025 07:30', 'https://bacninh.gov.vn/news/-/details/37632/thanh-lap-hoi-ong-giao-duc-quoc-phong-va-an-ninh-tinh-bac-ninh-29507401', '', 'Hữu Thắng', 36, 'Chính trị', 2, 'true', '38762', '{}', '2025-10-31 08:44:55.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (4, '29496706', 'Đại biểu Quốc hội Trần Văn Lâm: Nghiên cứu đổi mới khâu dự toán để nâng cao hiệu quả...', 'Đại biểu Quốc hội Trần Văn Lâm: Nghiên cứu đổi mới khâu dự toán để nâng cao hiệu quả sử dụng ngân sách', '/documents/37632/23566312/%C3%90B-L%C3%A2m-1.jpg/4508f0a7-706f-36f7-fce4-2ddfcfa68f62?t=1761807080224', '<p>(BNP) - Sáng 30/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, Quốc hội thảo luận tại hội trường về tình hình kinh tế - xã hội. Ủy viên Ủy ban Công tác đại biểu của Quốc hội Trần Văn Lâm (đại biểu Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh) tham luận về việc xây dựng và quản lý, sử dụng...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C3%90B-L%C3%A2m-1.jpg/4508f0a7-706f-36f7-fce4-2ddfcfa68f62?t=1761807080224\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Lâm trong phiên thảo luận tại hội trường của Quốc hội, sáng 30/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Lâm nhất trí với báo cáo của Chính phủ và báo cáo thẩm tra của Ủy ban Kinh tế - Tài chính của Quốc hội về tình hình tài chính - ngân sách quốc gia 1 năm và 5 năm; khẳng định việc xây dựng và thực hiện có hiệu quả các chính sách tài khóa trong thời gian qua đã góp phần quan trọng ở giữ vững ổn định vĩ mô, đưa nền kinh tế đất nước ta vượt qua các khó khăn, thách thức chưa từng có để đạt được kết quả rất tích cực như đánh giá của Quốc hội trong kỳ họp lần này. Đây cũng là cơ sở để hoạch định chiến lược phát triển đất nước trong nhiệm kỳ tới với những mục tiêu to lớn hơn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu cho rằng, trong các yếu tố vĩ mô thì chỉ số bội chi và nợ công trong nhiều năm qua luôn được bảo đảm&nbsp;ở mức thấp hơn kế hoạch. Đây là một thành công lớn trong điều hành của Chính phủ. Nền kinh tế đất nước ta dưới sự điều hành linh hoạt và chắc tay của Chính phủ đã duy trì được bội chi ở mức thấp hơn dự toán và cho phép có dư địa cho tăng đầu tư công, hỗ trợ cho tăng trưởng cao hơn trong giai đoạn sau. Tuy nhiên, đây mới chỉ là nhìn nhận ở một khía cạnh là mở rộng tăng trưởng về mặt lượng. Vì nếu tăng trưởng trước mắt mà tăng bội chi nhưng các dự án đầu tư kém hiệu quả thì hệ lụy là khả năng trả nợ kém, gánh nặng nợ công lớn sẽ tạo áp lực lên nền kinh tế và kìm hãm tăng trưởng trong dài hạn. Thực tế thì lĩnh vực đầu tư công trong những năm qua đã có tiến bộ và đạt nhiều kết quả tích cực. Song bên cạnh đó vẫn còn nhiều hạn chế, bất cập đã được chỉ ra trong báo cáo của Chính phủ và báo cáo thẩm tra của Ủy ban Kinh tế -Tài chính, như: Khâu chuẩn bị dự án còn yếu nên còn tình trạng khó giao và chậm giao vốn đầu tư hoặc giao vốn nhiều lần; tỷ lệ giải ngân ở một số lĩnh vực, một số địa bàn còn thấp, đặc biệt là giải ngân ODA và giải ngân chương trình mục tiêu quốc gia; số chuyển nguồn vốn đầu tư hằng năm còn cao và có xu thế năm sau cao hơn năm trước, làm giảm hiệu quả đầu tư; mục tiêu đầu tư công dẫn dắt thu hút đầu tư tư đạt kết quả hạn chế, chưa được như kỳ vọng. Những điều này cho thấy chất lượng, hiệu quả đầu tư công vẫn còn là vấn đề cần phải đặc biệt quan tâm trong thời gian tới. Trong nhiệm kỳ tới, với việc đất nước sẽ triển khai nhiều dự án quan trọng quốc gia đòi hỏi nguồn lực đầu tư rất lớn nên việc nới rộng bội chi, tăng nợ công để tăng nguồn đầu tư là nhu cầu khách quan.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, việc nới rộng chính sách tài khóa này cần phải được xem xét, tính toán, cân nhắc một cách thận trọng, kỹ lưỡng, đi đôi với việc tăng cường chất lượng, hiệu quả đầu tư. Trong đó, những yếu kém ở tất cả các khâu, lĩnh vực đầu tư cần phải sớm được khắc phục, từ việc lựa chọn các dự án đầu tư phải thật sự cần thiết, có tiềm năng hỗ trợ tăng trưởng kinh tế bền vững đến các khâu chuẩn bị dự án, chuẩn bị đầu tư, tổ chức triển khai, thực hiện giải ngân để đưa nguồn vốn sớm phát huy hiệu quả, giảm thiểu tối đa các lãng phí do chậm giải ngân, chuyển nguồn sang năm sau. Có như vậy thì áp lực về bội chi nợ công mới được giải tỏa, các cân đối vĩ mô mới được&nbsp;bảo đảm&nbsp;vững chắc và tăng trưởng kinh tế mới thực sự đi vào chiều sâu, chất lượng và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về vấn đề dự toán ngân sách, trong báo cáo thẩm tra của Ủy ban Kinh tế - Tài chính và phát biểu của một số đại biểu đã đánh giá về hạn chế trong khâu dự toán thu ngân sách những năm qua không sát, dự toán thấp, vượt thu cao, đại biểu Trần Văn Lâm cho rằng cần nhìn nhận vấn đề này ở những khía cạnh khác để có giải pháp cho phù hợp. Nguồn lực tài chính là quan trọng hàng đầu, làm cơ sở cho xây dựng và thực hiện các kế hoạch phát triển kinh tế xã hội. Nguồn lực này đến chủ yếu từ thuế, từ kết quả nội tại của nền kinh tế, trong khi nền kinh tế của đất nước ta không phải lúc nào cũng có thể dự báo và có những biện pháp ứng phó đủ hiệu quả đối với những diễn biến phức tạp của các yếu tố tác động liên quan, do vậy khi xây dựng dự toán ngân sách cần phải cân nhắc để đảm bảo hệ số an toàn cao, không để xảy ra thiếu nguồn lực cho thực hiện các nhiệm vụ của đất nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Viện dẫn thông tin kế hoạch thu thường đặt ở cận dưới trong khung dao động có thể xảy ra để&nbsp;bảo đảm&nbsp;an toàn, nếu có điều kiện vượt thu thì việc xử lý cũng dễ hơn, vui vẻ hơn so với xử lý hụt thu dự toán. Đại biểu cho rằng tư duy này có lẽ đặc biệt phù hợp trong thực tiễn của nhiệm kỳ qua khi những lúc dịch bệnh diễn biến phức tạp, nguy cơ đổ vỡ cả nền kinh tế chứ không riêng gì khâu thu ngân sách. Tuy nhiên thực tế cho thấy khi dự toán thu thấp, nhiều địa phương vượt thu thì việc sử dụng số vượt thu chưa được căn cơ, hiệu quả, nhiều khi bố trí dàn trải cho các nhiệm vụ, các công trình, các dự án chưa thật sự cần thiết, thậm chí cả các dự án chưa có trong kế hoạch. Khâu chuẩn bị dự án vội vàng, chất lượng kém nên khó và chậm giải ngân, buộc phải chuyển nguồn. Hệ quả là nguồn lực đầu tư công bị phân tán, lãng phí, kém hiệu quả.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu đề xuất trong nhiệm kỳ tới nên nghiên cứu đổi mới khâu dự toán để vừa đặt dự toán ở mức an toàn, khả thi cao, đồng thời xác định mức dự phòng vượt thu nếu điều kiện thuận lợi cho phép. Bên cạnh dự toán thu thì cũng phải xác lập ngay dự toán chi một cách đồng bộ, tương ứng để có kế hoạch bố trí, sử dụng nguồn vượt thu dự toán cho các nhiệm vụ, các dự án theo thứ tự ưu tiên đã được xác lập ngay từ đầu. Như vậy sẽ nâng cao hiệu quả sử dụng ngân sách và cũng bớt đi nỗi băn khoăn cao thấp trong khâu lập và phê duyệt dự toán ngân sách hàng năm.</span></span></span></p>', '30/10/2025 13:50', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-tran-van-lam-nghien-cuu-oi-moi-khau-du-toan-e-nang-cao-hieu-qua-su-dung-ngan-sach-29496706', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 152, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:55.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (5, '29492101', 'Hôm nay (30/10), Quốc hội tiếp tục thảo luận về kết quả và kế hoạch phát triển kinh...', 'Hôm nay (30/10), Quốc hội tiếp tục thảo luận về kết quả và kế hoạch phát triển kinh tế - xã hội', '/documents/37632/23566312/z7169765952098_8ba9ae48079d201d42680b5a5e11029a.jpg/a56b68d7-6713-9bb5-5a1c-2f56e28d283b?t=1761805618783', '<p>(BNP) - Theo chương trình kỳ họp thứ 10, ngày 30/10 Quốc hội tiếp tục thảo luận ở hội trường về kết quả thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025; dự kiến kế hoạch phát triển kinh tế - xã hội năm 2026.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23566312/z7169765952098_8ba9ae48079d201d42680b5a5e11029a.jpg/a56b68d7-6713-9bb5-5a1c-2f56e28d283b?t=1761805618783\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh tại phiên họp sáng ngày 30/10.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong phiên buổi sáng, từ 8 giờ đến 9 giờ 30 phút, Quốc hội tiếp tục thảo luận ở hội trường về: Đánh giá kết quả thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025; dự kiến kế hoạch phát triển kinh tế - xã hội năm 2026.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021-2025: phát triển kinh tế - xã hội; cơ cấu lại nền kinh tế.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao về việc ban hành văn bản điều chỉnh nội dung thuộc thẩm quyền của Quốc hội để xử lý vấn đề phát sinh khi thực hiện sắp xếp tổ chức bộ máy nhà nước, đẩy mạnh phân cấp, phân quyền và tháo gỡ vướng mắc do quy định của pháp luật (theo quy định của Luật Tổ chức Chính phủ, Luật Tổ chức chính quyền địa phương, Nghị quyết số 190/2025/QH15 của Quốc hội quy định về xử lý một số vấn đề liên quan đến sắp xếp tổ chức bộ máy nhà nước, Nghị quyết số 206/2025/QH15 của Quốc hội về cơ chế đặc biệt xử lý khó khăn, vướng mắc do quy định của pháp luật).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Tòa án nhân dân tối cao, Viện kiểm sát nhân dân tối cao về tình hình thi hành Hiến pháp, luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội năm 2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ 9 giờ 50, Quốc hội tiếp tục thảo luận ở hội trường về: Tình hình thực hiện ngân sách nhà nước năm 2025, dự toán ngân sách nhà nước, phương án phân bổ ngân sách trung ương năm 2026 (trong đó có Kế hoạch tài chính - ngân sách nhà nước 3 năm 2026 - 2028; tình hình thực hiện kế hoạch đầu tư công vốn ngân sách nhà nước năm 2025, dự kiến kế hoạch đầu tư công vốn ngân sách nhà nước năm 2026; tình hình thực hiện kế hoạch tài chính năm 2025, dự kiến kế hoạch tài chính năm 2026 của các quỹ tài chính nhà nước ngoài ngân sách do trung ương quản lý).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021 - 2025 đầu tư công trung hạn; tài chính quốc gia và vay, trả nợ công; dự kiến các kế hoạch tài chính 5 năm quốc gia giai đoạn 2026 - 2030; đầu tư công trung hạn giai đoạn 2026-2030.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong phiên họp buổi chiều, Quốc hội tiếp tục thảo luận ở hội trường về: Tình hình thực hiện ngân sách nhà nước năm 2025, dự toán ngân sách nhà nước, phương án phân bổ ngân sách trung ương năm 2026 (trong đó có Kế hoạch tài chính - ngân sách nhà nước 3 năm 2026 - 2028; tình hình thực hiện kế hoạch đầu tư công vốn ngân sách nhà nước năm 2025, dự kiến kế hoạch đầu tư công vốn ngân sách nhà nước năm 2026; tình hình thực hiện kế hoạch tài chính năm 2025, dự kiến kế hoạch tài chính năm 2026 của các quỹ tài chính nhà nước ngoài ngân sách do trung ương quản lý).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021 - 2025: đầu tư công trung hạn; tài chính quốc gia và vay, trả nợ công; dự kiến các kế hoạch tài chính 5 năm quốc gia giai đoạn 2026 - 2030; đầu tư công trung hạn giai đoạn 2026-2030.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>', '30/10/2025 08:00', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-30-10-quoc-hoi-tiep-tuc-thao-luan-ve-ket-qua-va-ke-hoach-phat-trien-kinh-te-xa-hoi-29492101', '', 'BNP', 17, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:55.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (6, '29504304', 'Đại biểu Quốc hội Nguyễn Thị Hà: Bạo lực học đường vẫn diễn biến phức tạp', 'Đại biểu Quốc hội Nguyễn Thị Hà: Bạo lực học đường vẫn diễn biến phức tạp', '/documents/37632/23566312/%C4%90B+Ha.jpg/9a44d826-ee1a-1391-75df-3dd0222a1ab8?t=1761809243428', '<p>(BNP) - Sáng 29/10, tham gia phiên thảo luận tại hội trường của kỳ họp thứ 10, Quốc hội khóa XV, đại biểu Nguyễn Thị Hà (Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh) tham góp nhiều ý kiến xác đáng về phòng, chống bạo lực học đường.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C4%90B+Ha.jpg/9a44d826-ee1a-1391-75df-3dd0222a1ab8?t=1761809243428\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Hà thảo luận tại hội trường Quốc hội, sáng 29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Thị Hà khẳng định: Bạo lực học đường vẫn diễn biến phức tạp, gây bức xúc và lo lắng cho toàn xã hội. Bạo lực học đường hiện nay không chỉ là câu chuyện của học sinh với học sinh, mà đã mở rộng, phức tạp hơn, nguy hiểm hơn khi giáo viên trở thành nạn nhân, phụ huynh và học sinh trở thành người gây bạo lực, và bạo lực còn diễn biến phức tạp trên không gian mạng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hệ lụy của bạo lực học đường là vô cùng nghiêm trọng và lâu dài. Về thể chất, nhiều học sinh bị thương tật, thậm chí tử vong. Về tinh thần, nhiều em mang sang chấn, rối loạn tâm lý, trầm cảm, tự cô lập. Những giáo viên bị bạo lực phải sống trong lo sợ, dễ tổn thương&nbsp;và mất dần niềm tin vào giá trị tôn sư trọng đạo. Những vụ việc bạo lực học đường không còn là hiện tượng đơn lẻ, không chỉ gây bàng hoàng dư luận mà còn đặt ra câu hỏi nhức nhối: Phải chăng kỷ cương học đường đang dần bị xem nhẹ? Áp lực lớn nhất của nhiều thầy cô hôm nay không phải là đồng lương, mà là nỗi sợ hãi trong chính môi trường làm việc của mình.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều đáng nói, xã hội có xu hướng đẩy mọi trách nhiệm về phía nhà trường, xem việc ngăn chặn bạo lực là trách nhiệm của giáo viên, mà quên rằng bạo lực học đường không sinh ra từ một phía. Nó là kết quả của sự tác động đan xen từ ba trụ cột: gia đình - nhà trường - xã hội. Gia đình là trường học đầu tiên của mỗi người, là nền tảng hình thành nhân cách, nhưng một số cha mẹ ngày nay lại thiếu thời gian, thiếu kỹ năng giáo dục cảm xúc, không kiểm soát được việc con xem những sách báo, phim ảnh, game có tính bạo lực cao; thậm chí có người thể hiện hành vi bạo lực trước mặt con. Một số trường còn nặng về thành tích, chưa chú trọng giáo dục đạo đức, kỹ năng sống; các biện pháp kỷ luật chưa thực sự có hiệu quả với tình huống “bắt nạt” xảy ra, còn có giáo viên thiếu kỹ năng quản lý cảm xúc và xử lý tình huống bạo lực. Chúng ta đang sống trong thời đại truyền thông mạng xã hội bùng nổ, nơi một hành vi bạo lực có thể được tán thưởng bằng lượt xem và lượt like; xã hội thiếu gắn kết, thờ ơ và đổ lỗi cho nhà trường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dẫn thông tin Bộ Giáo dục và Đào tạo vừa ban hành Thông tư số 19&nbsp;chính thức có hiệu lực&nbsp;ngày 31/10/2025, đại biểu Nguyễn Thị Hà cho rằng, Thông tư quy định hình thức kỷ luật cao nhất là viết bản kiểm điểm hoặc phê bình với tinh thần nhân văn, hướng đến giáo dục phục hồi thay vì trừng phạt là đáng trân trọng. Tuy nhiên, sự nhân văn trong kỷ luật học sinh chỉ phát huy hiệu quả khi được bảo đảm bằng hệ thống hỗ trợ và tư vấn tâm lý học đường chuyên nghiệp. Thông tư 19 đề cập đến hoạt động “khuyên bảo, theo dõi, tư vấn, phối hợp với gia đình”, nhưng hiện nay phần lớn trường học Việt Nam chưa có đội ngũ tư vấn tâm lý chuyên nghiệp. Nhiều nơi, “phòng tư vấn học đường” chỉ tồn tại trên danh nghĩa; giáo viên chủ nhiệm phải tự xoay xở trong khi chưa được đào tạo chuyên sâu kỹ năng xử lý xung đột.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ đó, đại biểu kiến nghị một số giải pháp: Cần quy định trách nhiệm liên đới với phụ huynh khi con em là học sinh vi phạm bạo lực nghiêm trọng; đưa giáo dục kỹ năng làm cha mẹ, giáo dục cảm xúc vào chương trình đào tạo cộng đồng, coi đây là nội dung bắt buộc trong các hoạt động dân cư, công đoàn, hội phụ nữ, đoàn thể; tăng cường tư vấn tâm lý học đường thực chất, mỗi cụm trường nên có tối thiểu 1 chuyên gia tâm lý được đào tạo bài bản; xây dựng cơ chế phản ứng nhanh trong trường học, kết nối với công an, chính quyền địa phương, cơ sở y tế khi xảy ra bạo lực; các nền tảng mạng xã hội cần có trách nhiệm pháp lý trong việc đưa thông tin nhằm kiểm soát nội dung bạo lực mạng và bạo lực học đường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cơ quan chức năng cần rà soát, đánh giá tính khả thi và hiệu quả khi triển khai Thông tư 19 nhằm cân bằng giữa nhân văn và kỷ luật, theo hướng bổ sung các hình thức kỷ luật mang tính phục hồi nhưng vẫn đủ sức răn đe, điều chỉnh hành vi, giúp học sinh nhận thức được lỗi sai và không tái phạm, như: Tổ chức hoạt động lao động cộng đồng, tham gia chương trình tư vấn bắt buộc, thực hiện cam kết hành vi tích cực, hoặc hình thức xin lỗi công khai dưới sự hướng dẫn của nhà trường; xây dựng bộ tiêu chí kiểm định năng lực tư vấn tâm lý học đường - cần coi đây là cơ sở để bảo đảm tính chuyên nghiệp và hiệu quả của công tác hỗ trợ học sinh trong nhà trường.</span></span></span></p>', '29/10/2025 18:30', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-nguyen-thi-ha-bao-luc-hoc-uong-van-dien-bien-phuc-tap-29504304', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 30, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (7, '29337601', 'Đại biểu Đỗ Thị Việt Hà: Tháo gỡ những điểm nghẽn pháp lý, hoàn thiện hệ thống chính...', 'Đại biểu Đỗ Thị Việt Hà: Tháo gỡ những điểm nghẽn pháp lý, hoàn thiện hệ thống chính sách, pháp luật để vận hành tốt chính quyền địa phương 2 cấp', '/documents/37632/23566312/a2.jpg/deaa8be3-5f4c-c40b-c0a0-9187eb452075?t=1761727769142', '<p>(BNP) - Sáng 29/10, tham gia phiên thảo luận tại hội trường của kỳ họp thứ 10, Quốc hội khóa XV, đại biểu Đỗ Thị Việt Hà (Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh) đóng góp nhiều ý kiến về công tác xây dựng thể chế, thi hành Hiến pháp, luật, nghị quyết của Quốc hội và xử lý vấn đề phát sinh khi sắp...', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/a2.jpg/deaa8be3-5f4c-c40b-c0a0-9187eb452075?t=1761727769142\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà thảo luận tại hội trường của Quốc hội, sáng&nbsp;29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà khẳng định: Thời gian qua, Chính phủ, Thủ tướng Chính phủ,&nbsp;sự chủ động, tích cực, trách nhiệm của Bộ Tư pháp trong việc tham mưu đã chỉ đạo quyết liệt, dành nhiều thời gian, nguồn lực cho công tác xây dựng, hoàn thiện thể chế, tổ chức thi hành pháp luật theo yêu cầu tại Nghị quyết số 66 - NQ/TW của Bộ Chính trị và những quy định mới của Luật Ban hành văn bản quy phạm pháp luật năm 2025; đã hoàn thành khối lượng công việc đặc biệt lớn liên quan đến công tác lập pháp, trong khoảng thời gian rất ngắn đã&nbsp;thể chế hóa kịp thời chủ trương, đường lối của Đảng, tạo hành lang pháp lý đồng bộ, kịp thời cho việc thực hiện chính quyền địa phương 2 cấp. Công tác hoàn thiện, tháo gỡ các rào cản, điểm nghẽn về thể chế, pháp luật được triển khai quyết liệt, góp phần khơi thông nguồn lực cho phát triển.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ đã bám sát yêu cầu của Luật Hoạt động giám sát của Quốc hội, đánh giá cụ thể những kết quả đạt được, thẳng thắn chỉ ra những tồn tại, hạn chế, nguyên nhân, xác định nhiệm vụ cụ thể đối với công tác xây dựng, thi hành pháp luật và đưa ra giải pháp để tiếp tục nâng cao chất lượng công tác triển khai thi hành luật, pháp lệnh, nghị quyết và ban hành văn bản quy định chi tiết.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để góp phần phát huy những kết quả đạt được, khắc phục những tồn tại, hạn chế trong công tác xây dựng thể chế, thi hành Hiến pháp, luật, nghị quyết, tiếp tục giải quyết, xử lý tốt các vấn đề phát sinh khi thực hiện mô hình chính quyền địa phương 2 cấp, đại biểu Đỗ Thị Việt Hà đề xuất, kiến nghị với Chính phủ 3 nội dung:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước hết, tiếp tục tập trung, quyết liệt cho việc thực hiện có hiệu quả Nghị quyết số 66-NQ/TW, Nghị quyết số 197/2025/NQ-QH15 về cơ chế, chính sách đột phá trong công tác xây dựng, tổ chức thi hành pháp luật. Trong đó, đề nghị tập trung cho việc xây dựng, ban hành 3 văn bản gồm Quyết định của Thủ tướng Chính phủ hướng dẫn trách nhiệm, quy trình xin ý kiến các cơ quan có thẩm quyền của Đảng về nội dung văn bản quy phạm pháp luật; Nghị định quy định chi tiết, hướng dẫn thi hành Nghị quyết 197/2025/NQ-QH15 và Đề án soạn thảo văn bản quy phạm pháp luật tập trung, chuyên nghiệp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai, tiếp tục tăng cường phân cấp, phân quyền nhưng phải phù hợp với khả năng, bảo đảm được điều kiện, năng lực của các cơ quan, chủ thể được phân cấp, phân quyền. Đồng thời kịp thời ban hành văn bản hướng dẫn thực hiện các nội dung phân cấp, phân quyền.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vừa qua, khi thực hiện chính quyền địa phương 2 cấp, Chính phủ đã kịp thời ban hành 29 Nghị định về phân cấp, phân quyền từ Trung ương xuống cho địa phương; phân định thẩm quyền chuyển từ cấp cấp huyện lên cấp tỉnh, xuống cấp xã trên các lĩnh vực. Rà soát, thống kê sơ bộ thấy có khoảng 291 nội dung giao cho UBND cấp tỉnh, 206 nội dung giao Chủ tịch UBND cấp tỉnh, 95 nội dung giao cho các sở, ngành; riêng với cấp xã, có đến 204 nội dung giao cho UBND cấp xã và 103 nội dung giao cho Chủ tịch UBND cấp xã.&nbsp;Cùng với đó, có 63 nhiệm vụ được chính quyền cấp tỉnh phân cấp cho chính quyền cấp xã. Riêng về thủ tục hành chính, có 556 thủ tục hành chính được phân cấp, phân quyền từ trung ương xuống cho địa phương, chuyển từ cấp huyện lên cấp tỉnh là 18 thủ tục hành chính và số lượng thủ tục hành chính chuyển về cấp xã lên tới 278. Như vậy&nbsp;khối lượng nhiệm vụ được phân cấp, phân quyền cho cấp xã và thủ tục hành chính được chuyển về cấp xã là rất lớn. Thời gian qua đã xảy ra tình trạng quá tải trong công việc, chất lượng, hiệu quả còn thấp của chính quyền cấp xã do nhiều nguyên nhân, trong đó có nguyên nhân về khả năng thực hiện, về nguồn nhân lực, điều kiện cơ sở vật chất, trang thiết bị, phương tiện làm việc, tài chính chưa được bảo đảm, chưa đáp ứng yêu cầu nhiệm vụ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, một số quy định được phân cấp, phân quyền chưa rõ ràng, chưa được hướng dẫn, còn nhiều cách hiểu khác nhau, gây khó khăn trong áp dụng, rất cần có văn bản hướng dẫn thực hiện. Còn có những quy định về thủ tục hành chính rườm rà, phức tạp và chồng chéo; các địa phương vẫn còn gặp một số khó khăn, bất cập trong triển khai thủ tục hành chính cho người dân, doanh nghiệp, các khó khăn chủ yếu liên quan đến hạ tầng kỹ thuật như hệ thống phần mềm, dịch vụ công, kết nối dữ liệu, chữ ký số, con dấu điện tử và quy trình vận hành chưa ổn định, thông suốt, cơ sở dữ liệu chưa đồng bộ, liên thông; hạ tầng công nghệ chưa ổn định, thông suốt...</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Do đó, đề nghị Chính phủ rà soát, đánh giá kỹ lưỡng toàn diện tình hình thi hành 29 Nghị định về phân cấp, phân quyền, phân định thẩm quyền đã ban hành, trong đó có các quy định về thủ tục hành chính; đồng thời khi phân cấp, phân quyền cần đánh giá kỹ lưỡng về khả năng, điều kiện thực hiện phân cấp, phân quyền cũng như có cơ chế kiểm tra, giám sát để kịp thời có giải pháp phù hợp bảo đảm việc phân cấp, phân quyền hiệu quả.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ ba, tiếp tục thực hiện có hiệu quả công tác rà soát văn bản quy phạm pháp luật và xử lý, khắc phục các nội dung mâu thuẫn, chồng chéo, vướng mắc, bất cập phát hiện qua rà soát và đặc biệt cần tiếp tục thực hiện tốt Nghị quyết số 206/2025/NQ15 của Quốc hội về cơ chế đặc biệt xử lý khó khăn, vướng mắc do quy định của pháp luật. Trong đó đề nghị Chính phủ quan tâm 2 nội dung:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác rà soát văn bản quy phạm pháp luật có khối lượng cần thực hiện rất lớn, là một trong những nhiệm vụ được Quốc hội, Chính phủ, đặc biệt là Bộ Tư pháp cùng các bộ, ngành, các địa phương đặc biệt quan tâm, chú trọng, triển khai nhiều hoạt động rà soát; đã nghiêm túc, tích cực áp dụng nhiều giải pháp mới để kịp thời phát hiện và xử lý, khắc phục các nội dung mâu thuẫn, chồng chéo, vướng mắc, góp phần tháo gỡ những điểm nghẽn pháp lý, sơ hở, bất cập trong cơ chế, chính sách, pháp luật.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với 2.092 kiến nghị, phản ánh về các khó khăn, vướng mắc của 789 văn bản quy phạm pháp luật, các cơ quan đã xác định chỉ có 834 kiến nghị, phản ánh có cơ sở và một số cơ quan đã có văn bản gửi về địa phương trao đổi, hướng dẫn; khi địa phương nhận được văn bản hướng dẫn, trao đổi của bộ, ngành thì đều gửi đến tất cả các cơ quan, địa phương để biết và thực hiện. Hiện còn số lượng lớn là 1.237 kiến nghị, phản ánh xác định không nhất trí và còn 21 kiến nghị, phản ánh chưa có sự thống nhất giữa các cơ quan. Với các kiến nghị, phản ánh này, địa phương rất cần có văn bản của bộ, ngành để biết và thống nhất trong quá trình tổ chức thi hành. Do đó, đề nghị Chính phủ chỉ đạo các bộ, ngành có văn bản gửi các địa phương đối với cả các kiến nghị, phản ánh không nhất trí.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Căn cứ Nghị quyết số 206/2025/QH15 của Quốc hội khóa XV, vừa qua Chính phủ đã ban hành chùm các Nghị quyết từ 66.1 đến 66.5 quy định xử lý khó khăn, vướng mắc, cơ chế, chính sách đặc thù về pháp luật trong một số lĩnh vực như quy hoạch, địa chất khoáng sản, ngân sách... Đây là những văn bản&nbsp; cơ sở pháp lý rất quan trọng để tháo gỡ những khó khăn, vướng mắc của quy định hiện hành. Tuy nhiên, việc quy định những cơ chế, chính sách đặc thù đang khác với quy định hiện hành như các Nghị quyết này cũng rất cần có văn bản hướng dẫn thực hiện của Chính phủ, bộ, ngành có liên quan. Đề nghị Chính phủ giao các bộ, ngành có liên quan kịp thời tham mưu ban hành hoặc ban hành văn bản theo thẩm quyền để hướng dẫn việc thực hiện các Nghị quyết trên thực tế được bảo đảm kịp thời, thống nhất, đồng bộ, khả thi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Đỗ Thị Việt Hà khẳng định, việc ban hành Nghị quyết của Chính phủ theo Nghị quyết số 206 của Quốc hội khóa XV chỉ là giải pháp đặc biệt tạm thời để xử lý khó khăn, vướng mắc trong quy định của pháp luật; việc quy định các nội dung khác với quy định hiện hành cũng cần được hạn chế tối đa để bảo đảm tính đồng bộ, thống nhất của hệ thống pháp luật. Do đó, đề nghị Chính phủ tăng cường hơn nữa chất lượng các dự thảo luật, pháp lệnh, nghị quyết khi trình Quốc hội, Ủy ban Thường vụ Quốc hội để tránh tình trạng mâu thuẫn, chồng chéo, bảo đảm tính hợp hiến, hợp pháp, thống nhất, khả thi ngay khi ban hành luật, pháp lệnh, nghị quyết.</span></span></span></p>', '29/10/2025 15:48', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-o-thi-viet-ha-thao-go-nhung-iem-nghen-phap-ly-hoan-thien-he-thong-chinh-sach-phap-luat-e-van-hanh-tot-chinh-quyen-ia-phuong-2-cap-29337601', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 366, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (8, '29335337', 'Đại biểu Quốc hội Nguyễn Như So đề xuất 4 giải pháp trọng tâm nhằm khơi dậy tiềm lực...', 'Đại biểu Quốc hội Nguyễn Như So đề xuất 4 giải pháp trọng tâm nhằm khơi dậy tiềm lực doanh nghiệp tư nhân', '/documents/37632/23566312/ongSo.jpg/9daa3894-af62-9155-b0ad-c85bbe7c26a8?t=1761726957505', '<p>(BNP) - Sáng 29/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, Quốc hội thảo luận tại hội trường, cho ý kiến vào Báo cáo của Chính phủ về tình hình triển khai Nghị quyết số 16 của Quốc hội về Kế hoạch phát triển kinh tế - xã hội 5 năm 2021 - 2025.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/ongSo.jpg/9daa3894-af62-9155-b0ad-c85bbe7c26a8?t=1761726957505\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Như So thảo luận tại hội trường Quốc hội, sáng 29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham gia thảo luận, đại biểu Nguyễn Như So (Đoàn&nbsp;Bắc Ninh) khẳng định: Trong bối cảnh kinh tế toàn cầu biến động bởi xung đột, thuế quan và khí hậu, Việt Nam vẫn vươn lên như “hải đăng kinh tế” của khu vực: GDP quý III tăng 8,23%, xuất siêu đạt 16,82 tỷ USD, thu hút FDI đạt con số kỷ lục với 28,54 tỷ USD - minh chứng cho niềm tin quốc tế vào sức bật Việt Nam. Song để biến thành tựu ngắn hạn thành năng lực bền vững, chúng ta cần một chiến lược phát triển lấy kinh tế tư nhân làm “động cơ phản lực”. Khu vực này là mũi nhọn sáng tạo, là lực đẩy năng suất và nền tảng tự chủ quốc gia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Nguyễn Như So đề xuất 4 giải pháp trọng tâm nhằm khơi dậy tiềm lực doanh nghiệp tư nhân, đưa Việt Nam tiến vững chắc trên con đường tăng trưởng xanh, độc lập và thịnh vượng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Một là</strong></em>, cần đột phá thực chất trong cải cách thể chế, với trọng tâm là khâu thực thi chính sách - nút thắt của mọi nút thắt trong phát triển kinh tế hiện nay. Chúng ta không thiếu chính sách, mà thiếu cách thực thi hiệu quả. Nhiều chủ trương, nghị quyết đúng đắn của Đảng và Quốc hội như “bộ tứ” Nghị quyết 57, 59, 66, 68 của Bộ Chính trị hay Nghị quyết 198 đã mở hướng khơi thông nguồn lực, song kết quả thực tế lại cho thấy khoảng cách lớn giữa “chính sách trên giấy” và “đời sống doanh nghiệp”. Chỉ trong 9 tháng&nbsp;năm 2025, hơn 175 nghìn doanh nghiệp rút lui khỏi thị trường - con số phản ánh rõ độ vênh giữa ý chí chính sách và hiệu quả thực thi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đại biểu, vấn đề không nằm ở thiết kế chính sách, mà ở nút thắt thực thi. Một chính sách tốt, nếu thiếu đồng bộ, cơ chế phối hợp, hướng dẫn cụ thể, trách nhiệm cá nhân sẽ nằm lại trên bàn giấy. Gói hỗ trợ lãi suất 2% của Nghị quyết 43 là ví dụ điển hình. Mặc dù được thiết kế đúng mục tiêu&nbsp;nhưng giải ngân chỉ đạt 1,95% vì quy trình phức tạp, tiêu chí mập mờ, ngân hàng sợ rủi ro… Hệ quả là vốn không đến được nền kinh tế thực, doanh nghiệp kiệt sức, còn chính sách bị coi là “không hiệu quả”.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, đột phá thể chế phải bắt đầu từ cải cách thực thi. Mỗi chính sách ban hành cần có hướng dẫn chi tiết, thời hạn rõ ràng, tiêu chí định lượng, cơ chế giám sát công khai và người chịu trách nhiệm cụ thể. Cần số hóa toàn bộ quy trình hành chính và xóa bỏ triệt để cơ chế xin - cho. Quan trọng hơn, cần đo hiệu quả cải cách bằng trải nghiệm của doanh nghiệp, không chỉ bằng báo cáo hành chính.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chỉ khi thực thi trở thành khâu đột phá, chuyển từ “quản lý” sang “phục vụ”, từ “đúng quy trình” sang “đúng kết quả”, thể chế mới thật sự trở thành động lực tăng trưởng và củng cố niềm tin của doanh nghiệp vào chính quyền kiến tạo.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Hai là</strong></em>, cần tái cơ cấu mạnh mẽ thị trường vốn, đưa dòng tiền trở lại nền kinh tế thực, thay vì cuốn vào những chu kỳ đầu cơ ngắn hạn không tạo ra giá trị bền vững. Thị trường vốn phải trở thành mạch máu của sản xuất, không phải sân chơi của đầu cơ. Dòng vốn cần được định hướng chiến lược vào các lĩnh vực sản xuất, chế biến chế tạo, hàng tiêu dùng thiết yếu, công nghệ cao và kinh tế xanh - những trụ cột tạo giá trị gia tăng và việc làm ổn định cho đất nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ cần phát triển các kênh dẫn vốn dài hạn như quỹ đầu tư, trái phiếu doanh nghiệp, thị trường vốn mạo hiểm - nơi các quỹ đầu tư chấp nhận rủi ro để tài trợ cho đổi mới công nghệ, khởi nghiệp sáng tạo và sản xuất giá trị cao, giảm phụ thuộc vào tín dụng ngắn hạn của ngân hàng. Đồng thời, nên thiết lập cơ chế tái cấp vốn ưu đãi 2 - 5%/năm cho các dự án đổi mới công nghệ, sản xuất xanh và chuyển đổi số - qua đó giúp doanh nghiệp dễ dàng tiếp cận vốn rẻ, đầu tư cho năng suất và giá trị dài hạn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song song, cần thiết kế gói kích cầu thuế “Sản xuất xanh”, ưu tiên miễn, giảm thuế cho doanh nghiệp đầu tư vào công nghệ 4.0, năng lượng tái tạo, kinh tế tuần hoàn. Đây không chỉ là chính sách hỗ trợ tài chính, mà còn là đòn bẩy chuyển hướng dòng vốn từ đầu cơ sang sáng tạo, gắn lợi ích doanh nghiệp với tăng trưởng bền vững và trách nhiệm môi trường.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một thị trường vốn phát triển theo hướng sản xuất - sáng tạo - dài hạn, sẽ tạo nền tảng nội lực vững chắc, nâng cao năng suất quốc gia và củng cố sức chống chịu chiến lược của nền kinh tế Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Ba là</strong></em>, cần tái cấu trúc mạnh mẽ sản xuất và xuất khẩu theo hướng nâng cao giá trị gia tăng nội địa, coi đây là nhiệm vụ chiến lược để xây dựng nền kinh tế độc lập, tự chủ. Trong bối cảnh chủ nghĩa bảo hộ lan rộng và thương mại toàn cầu thu hẹp, Việt Nam không thể tiếp tục dựa vào mở rộng quy mô xuất khẩu, mà phải chuyển trọng tâm sang tăng hàm lượng giá trị trong nước. Hiện tỷ lệ nội địa hóa mới đạt 36,6%, thấp hơn đáng kể so với Trung Quốc (67,1%), Thái Lan (58,4%) hay Ấn Độ (53,3%), khiến Việt Nam dễ bị lệ thuộc, hoặc rơi vào vai trò “công xưởng trung chuyển”, khó đáp ứng tiêu chí FTA, đối mặt nguy cơ bị áp thuế cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vì vậy, cần ưu tiên hình thành lực lượng doanh nghiệp nội địa đủ quy mô và năng lực làm trụ cột cho nền kinh tế. Chính sách hỗ trợ phải tập trung vào tăng tỷ lệ nội địa hoá nguyên liệu, sản phẩm; thúc đẩy chuyển giao công nghệ, đào tạo nhân lực và phát triển năng lực thiết kế, chế tạo trong nước. Trong thu hút FDI, cần quy định rõ cam kết nội địa hóa, chuyển giao công nghệ và liên kết với doanh nghiệp Việt Nam. FDI phải là chất xúc tác cho năng lực sản xuất trong nước, nâng tầm giá trị “Make in Vietnam”, giúp doanh nghiệp Việt vươn lên làm chủ các khâu có giá trị cao trong chuỗi cung ứng toàn cầu - nền tảng cho một nền kinh tế tự chủ và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><em><strong>Bốn là</strong></em>, phát triển nguồn nhân lực chất lượng cao như “lõi thép” của tăng trưởng, coi trí tuệ Việt Nam là lợi thế cạnh tranh cốt lõi trong kỷ nguyên công nghệ và chuyển đổi số.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam đang đối mặt với điểm nghẽn nghiêm trọng: 63% lao động làm việc phi chính thức, 38 triệu người chưa qua đào tạo nghề, và chỉ 11,67% có trình độ cao - khiến năng suất lao động chỉ bằng 1/10 Singapore, 1/2 Trung Quốc. Đây không chỉ là thiếu hụt kỹ năng mà còn là “độ trễ thể chế” trong giáo dục -&nbsp;đào tạo. Để bứt phá, cần triển khai thực chất Nghị quyết 71-NQ/TW, lấy giáo dục và đào tạo làm khâu đột phá chiến lược.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chính phủ cần đầu tư có trọng tâm cho “Giáo dục tinh hoa”, xây dựng các trung tâm nghiên cứu -&nbsp;đào tạo xuất sắc trong các lĩnh vực mũi nhọn như AI, bán dẫn, năng lượng tái tạo và kinh tế số. Đồng thời, khuyến khích khu vực tư nhân tham gia sâu vào đào tạo thông qua cơ chế đặt hàng nhân lực, liên kết chặt chẽ Doanh nghiệp - Trường học - Viện nghiên cứu và ưu đãi thuế mạnh cho hoạt động R&amp;D và phát triển kỹ năng. Khi nguồn nhân lực trở thành nền tảng tri thức tự chủ, Việt Nam mới có thể vượt qua “bẫy thu nhập trung bình” và tạo vị thế vững vàng trong chuỗi giá trị toàn cầu.</span></span></span></p>', '29/10/2025 15:34', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-nguyen-nhu-so-e-xuat-4-giai-phap-trong-tam-nham-khoi-day-tiem-luc-doanh-nghiep-tu-nhan-29335337', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 624, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (9, '29334604', 'Đại biểu Quốc hội Trần Văn Tuấn: Cần tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư...', 'Đại biểu Quốc hội Trần Văn Tuấn: Cần tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư nhân', '/documents/37632/23566312/%C4%90B+Tu%E1%BA%A5n.jpg/156f1a01-30c0-9fe7-be18-68bcc98c6048?t=1761726717629', '<p>(BNP) - Sáng 29/10, tiếp tục chương trình kỳ họp thứ 10, Quốc hội khóa XV, Quốc hội thảo luận tại hội trường, cho ý kiến vào Báo cáo của Chính phủ về tình hình triển khai Nghị quyết số 16 của Quốc hội về Kế hoạch phát triển kinh tế - xã hội 5 năm 2021 - 2025.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23566312/%C4%90B+Tu%E1%BA%A5n.jpg/156f1a01-30c0-9fe7-be18-68bcc98c6048?t=1761726717629\" style=\"width: 900px; height: 540px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Quốc hội Trần Văn Tuấn thảo luận tại hội trường Quốc hội, sáng 29/10.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham luận với chủ đề “Cần tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư nhân, nhất là từ các doanh nghiệp nhỏ và vừa, để thúc đẩy kinh tế phát triển nhanh và bền vững”, Phó trưởng Đoàn Đại biểu Quốc hội tỉnh Bắc Ninh Trần Văn Tuấn khẳng định: Trong giai đoạn 2021 - 2025, bối cảnh thế giới và trong nước có nhiều khó khăn, thách thức, song với sự điều hành linh hoạt, quyết liệt của Chính phủ, dự kiến tốc độ tăng trưởng GDP bình quân đạt khoảng 6,3%. Đầu tư công, đầu tư tư nhân, thu hút đầu tư FDI và xuất khẩu là những động lực chính thúc đẩy sự tăng trưởng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuy nhiên, bên cạnh những kết quả đạt được cũng đã và đang bộc lộ những mặt hạn chế, tiềm ẩn những yếu tố có thể dẫn đến tăng trưởng thiếu sự tự chủ và bền vững, dễ bị “đứt gãy” khi một trong các động lực tăng trưởng từ đầu tư công, FDI, xuất khẩu suy yếu; cơ cấu kinh tế mất cân đối do khu vực kinh tế tư nhân trong nước chưa phát triển tương xứng, cụ thể:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong giai đoạn 2021 - 2025 hiệu quả đầu tư công còn có mặt hạn chế, chưa tương xứng với nguồn lực bỏ ra, thể hiện ở chỉ số ICOR (chi phí vốn để tăng thêm 1 đơn vị GDP) vẫn còn cao (6,4%), chưa có nhiều cải thiện so với giai đoạn trước; một số dự án vẫn gặp khó khăn về tiến độ, đội vốn, đặc biệt do vấn đề đền bù, giải phóng mặt bằng….</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tăng trưởng FDI trong lĩnh vực công nghệ cao chưa đạt mức kỳ vọng (chủ yếu gia công, lắp ráp, sử dụng linh kiện nhập khẩu). Liên kết giữa doanh nghiệp FDI với doanh nghiệp nội địa còn yếu; giá trị gia tăng tại Việt Nam thấp; chuỗi cung ứng nội địa chưa phát triển; chuyển giao công nghệ hạn chế, nhất là công nghệ cao… Đặc biệt, khi FDI chiếm tỷ trọng lớn, tiềm ẩn nguy cơ mất tự chủ, bởi các nhà đầu tư có thể rút vốn hoặc chuyển hướng đầu tư bất cứ lúc nào; rồi rủi ro khi doanh nghiệp FDI có hành vi chuyển giá, trốn thuế…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chất lượng và giá trị gia tăng của hàng hoá xuất khẩu còn thấp, chưa tham gia sâu vào chuỗi giá trị toàn cầu, phụ thuộc nhiều thị trường bên ngoài, tiềm ẩn nguy cơ nền kinh tế dễ bị tổn thương trước những biến động kinh tế, chính trị trong khu vực và thế giới (như cạnh tranh thương mại, biến động giá nguyên liệu, thay đổi chính sách của các nước nhập khẩu)…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, khi xuất khẩu vẫn phụ thuộc nhiều vào khu vực FDI (năm 2024, giá trị kim ngạch xuất khẩu từ khu vực FDI chiếm tỷ trọng 71,7%), tiềm ẩn nguy cơ khi có biến động (như suy giảm đơn hàng, dịch chuyển chuỗi cung ứng toàn cầu…) tăng trưởng xuất khẩu và GDP của Việt Nam sẽ suy giảm. Trong khi đó, kinh tế tư nhân - vốn là động lực dài hạn cho sự phát triển lại đang phải đối mặt với nhiều rào cản kìm hãm, chưa có sự bứt phá về quy mô và năng lực cạnh tranh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu Trần Văn Tuấn cho rằng, trong giai đoạn tới, bên cạnh việc tiếp tục phát huy những động lực tăng trưởng từ đầu tư công, thu hút đầu tư FDI và xuất khẩu, chúng ta cần nhanh chóng hiện thực hoá những quan điểm, mục tiêu, nhiệm vụ, giải pháp theo tinh thần Nghị quyết số 68&nbsp;ngày 4/5/2025 của Bộ Chính trị về phát triển kinh tế tư nhân. Qua đó tạo động lực mạnh mẽ hơn từ khu vực kinh tế tư nhân, nhất là từ các doanh nghiệp nhỏ và vừa, để thúc đẩy kinh tế phát triển nhanh và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chú trọng tiếp tục xây dựng, hoàn thiện hệ thống pháp luật&nbsp;với những cơ chế, chính sách đột phá, tạo môi trường thông thoáng, minh bạch, khuyến khích kinh tế tư nhân phát triển (nhất là về: đất đai, hạ tầng, đầu tư, tài chính, tín dụng, thủ tục hành chính, khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số, đào tạo nhân lực…).&nbsp;Cụ thể là cần khẩn trương nghiên cứu sửa đổi Luật Hỗ trợ doanh nghiệp nhỏ và vừa năm 2017 nhằm khắc phục một số bất cập đã bộc lộ sau hơn 7 năm triển khai thực hiện như: Tiêu chí xác định doanh nghiệp nhỏ và vừa còn chung chung; chưa rõ chính sách hỗ trợ chuyên biệt về chuyển đổi số, đổi mới sáng tạo và hội nhập quốc tế; chưa có ưu tiên rõ ràng đối với nhóm doanh nghiệp siêu nhỏ, hộ kinh doanh chuyển thành doanh nghiệp và doanh nghiệp khởi nghiệp sáng tạo…&nbsp;Qua đó tạo sự đột phá về phát triển doanh nghiệp nhỏ và vừa trong giai đoạn tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với việc xác định kinh tế tư nhân là một động lực quan trọng nhất của nền kinh tế quốc gia cũng cần coi doanh nghiệp nhỏ và vừa là “xương sống” của nền kinh tế. Thực tế, cũng như&nbsp;hầu hết các nước trên thế giới, tỷ lệ doanh nghiệp nhỏ và vừa ở Việt Nam trong tổng số doanh nghiệp đang hoạt động trong nền kinh tế luôn rất cao, hiện chiếm khoảng 98%.</span></span></span></p>', '29/10/2025 15:30', 'https://bacninh.gov.vn/news/-/details/37632/-ai-bieu-quoc-hoi-tran-van-tuan-can-tao-ong-luc-manh-me-hon-tu-khu-vuc-kinh-te-tu-nhan-29334604', '', 'Báo và Phát thanh, truyền hình Bắc Ninh', 225, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (10, '29265812', 'Hôm nay (29/10), Quốc hội thảo luận kết quả thực hiện kế hoạch phát triển kinh tế -...', 'Hôm nay (29/10), Quốc hội thảo luận kết quả thực hiện kế hoạch phát triển kinh tế - xã hội', '/documents/37632/23566312/z7163263372586_be0e51e3e96d5a0b79c2bcb74e3d4466.jpg/d0340fa1-5fb3-5da0-4409-48fcfd8b9d8e?t=1761700093634', '<p>(BNP) - Theo chương trình Kỳ họp thứ 10, ngày 29/10, Quốc hội dành cả ngày thảo luận tại hội trường về đánh giá kết quả thực hiện kế hoạch phát triển kinh tế - xã hội. Phiên họp được truyền hình và phát thanh trực tiếp.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23566312/z7163263372586_be0e51e3e96d5a0b79c2bcb74e3d4466.jpg/d0340fa1-5fb3-5da0-4409-48fcfd8b9d8e?t=1761700093634\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quốc hội thảo luận tại Hội trường ngày 28/10.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi sáng, Quốc hội thảo luận đánh giá kết quả thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025; dự kiến kế hoạch phát triển kinh tế - xã hội năm 2026.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp đó, Quốc hội thảo luận kết quả thực hiện các nghị quyết của Quốc hội về kế hoạch 5 năm giai đoạn 2021 - 2025: phát triển kinh tế - xã hội; cơ cấu lại nền kinh tế.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao về việc ban hành văn bản điều chỉnh nội dung thuộc thẩm quyền của Quốc hội để xử lý vấn đề phát sinh khi thực hiện sắp xếp tổ chức bộ máy Nhà nước, đẩy mạnh phân cấp, phân quyền và tháo gỡ vướng mắc do quy định của pháp luật (theo quy định của Luật Tổ chức Chính phủ, Luật Tổ chức chính quyền địa phương, Nghị quyết số 190/2025/QH15 của Quốc hội quy định về xử lý một số vấn đề liên quan đến sắp xếp tổ chức bộ máy nhà nước, Nghị quyết số 206/2025/QH15 của Quốc hội về cơ chế đặc biệt xử lý khó khăn, vướng mắc do quy định của pháp luật).</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo của Chính phủ, Tòa án nhân dân tối cao, Viện kiểm sát nhân dân tối cao về tình hình thi hành Hiến pháp, luật, nghị quyết của Quốc hội, pháp lệnh, nghị quyết của Ủy ban Thường vụ Quốc hội năm 2025.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thành viên Chính phủ, Chánh án Tòa án nhân dân tối cao, Viện trưởng Viện kiểm sát nhân dân tối cao giải trình, làm rõ một số vấn đề đại biểu Quốc hội nêu.</span></span></span></p>', '29/10/2025 08:06', 'https://bacninh.gov.vn/news/-/details/37632/hom-nay-29-10-quoc-hoi-thao-luan-ket-qua-thuc-hien-ke-hoach-phat-trien-kinh-te-xa-hoi-29265812', '', 'BNP', 66, 'Chính trị', 2, '', '38762', '{}', '2025-10-31 08:44:56.000000', 2, 11);
INSERT INTO `sync_articles` VALUES (11, '29900401', 'Bắc Ninh: Quy định nội dung chi và mức chi hỗ trợ hoạt động khuyến nông', 'Bắc Ninh: Quy định nội dung chi và mức chi hỗ trợ hoạt động khuyến nông', '/documents/37632/23288501/IMG_0515.jpg/b32ecd82-b595-cc4c-3b39-915bc8bb61f3?t=1761882689274', '<p>(BNP) - HĐND tỉnh Bắc Ninh vừa ban hành Nghị quyết Quy định nội dung chi và mức chi hỗ trợ hoạt động khuyến nông trên địa bàn tỉnh Bắc Ninh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/23288501/IMG_0515.jpg/b32ecd82-b595-cc4c-3b39-915bc8bb61f3?t=1761882689274\" style=\"height: 600px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các tổ chức, cá nhân có liên quan đến hoạt động khuyến nông và chuyển giao công nghệ trong nông nghiệp được hỗ trợ kinh phí.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, Nghị quyết quy định cụ thể các nội dung chi, mức chi hỗ trợ cho các hoạt động khuyến nông, chuyển giao công nghệ trong nông nghiệp bao gồm: Đào tạo, tập huấn, thông tin tuyên truyền, xây dựng mô hình trình diễn, tư vấn - dịch vụ khuyến nông, hợp tác quốc tế và các nội dung chi khác.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối tượng áp dụng là các tổ chức, cá nhân có liên quan đến hoạt động khuyến nông và chuyển giao công nghệ trong nông nghiệp; cơ quan quản lý nhà nước về hoạt động khuyến nông trên địa bàn tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể, hỗ trợ 100% chi phí tài liệu học, tiền ăn, tiền đi lại và nơi ở cho người dân, chủ trang trại, hợp tác xã, doanh nghiệp nhỏ trực tiếp tham gia đào tạo, tập huấn, nhận chuyển giao công nghệ nông nghiệp.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hỗ trợ tối đa 100% kinh phí xây dựng mô hình trình diễn tại địa bàn khó khăn, không quá 2 tỷ đồng/mô hình; mô hình ứng dụng công nghệ cao được hỗ trợ tối đa 40% tổng kinh phí, tối đa 2 tỷ đồng/mô hình.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chi phí cho hoạt động thông tin, tuyên truyền, hội chợ, hội thảo, diễn đàn, khảo sát học tập và các chương trình khuyến nông khác thực hiện theo các quy định hiện hành và hướng dẫn của Bộ Tài chính, Bộ Nông nghiệp và Môi trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguồn kinh phí thực hiện được bố trí từ ngân sách cấp tỉnh, cấp xã và các nguồn hợp pháp khác, bảo đảm sử dụng đúng mục đích, công khai, minh bạch và theo quy định tài chính hiện hành.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghị quyết có hiệu lực từ ngày 01/11/2025</span></span></span>; đồng thời bãi bỏ Nghị quyết số 06/2021/NQ-HĐND ngày 16/7/2021 của HĐND tỉnh về quy định nội dung, mức chi hỗ trợ hoạt động khuyến nông từ ngân sách nhà nước./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\">&nbsp;</p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '31/10/2025 10:48', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-quy-inh-noi-dung-chi-va-muc-chi-ho-tro-hoat-ong-khuyen-nong-29900401', '', 'BNP', 151, 'Kinh tế', 3, 'true', '38762', '{}', '2025-10-31 08:44:56.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (12, '29889461', 'Các xã, phường trong tỉnh chủ động áp dụng các biện pháp phòng, chống dịch bệnh Cúm...', 'Các xã, phường trong tỉnh chủ động áp dụng các biện pháp phòng, chống dịch bệnh Cúm gia cầm phù hợp với điều kiện thực tế tại địa phương', '/documents/37632/23288501/2+%284%29.jpg/40a8a434-551c-909c-8d20-44590bfe656e?t=1761879902232', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Lê Xuân Lợi vừa ký văn bản số 4187/UBND-NN yêu cầu các sở, ngành, địa phương tăng cường công tác phòng, chống dịch bệnh Cúm gia cầm.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288501/2+%284%29.jpg/40a8a434-551c-909c-8d20-44590bfe656e?t=1761879902232\" style=\"height: 549px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Ảnh minh họa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Cụ thể, Phó Chủ tịch UBND tỉnh Lê Xuân Lợi yêu cầu UBND các xã, phường tập trung nguồn lực phòng, chống dịch Cúm gia cầm; bảo đảm kinh phí để tổ chức triển khai kịp thời, khống chế hiệu quả khi dịch bệnh xảy ra. Chỉ đạo bộ phận chuyên môn phối hợp với Chi cục Chăn nuôi Thú y và Thủy sản quản lý chặt chẽ hoạt động giết mổ, kinh doanh, vận chuyển động vật, sản phẩm động vật trên địa bàn; xử lý nghiêm các trường hợp vi phạm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Hướng dẫn người chăn nuôi gia cầm tăng cường áp dụng nghiêm ngặt các biện pháp chăn nuôi an toàn sinh học, chủ động phòng dịch; thường xuyên vệ sinh, sát trùng bằng vôi bột, hóa chất để tiêu diệt mầm bệnh. Rà soát, tổ chức tiêm vắc xin Cúm phòng bệnh cho đàn gia cầm, bảo đảm đạt tỷ lệ trên 80% tổng đàn tại thời điểm tiêm; thường xuyên rà soát, tiêm phòng bổ sung cho đàn gia cầm mới phát sinh và chưa được tiêm phòng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tăng cường kiểm tra việc bảo đảm an toàn vệ sinh thực phẩm, các khu vực có nguy cơ tiêu hủy, vứt bỏ xác động vật trái phép như ao, hồ, sông suối; tăng cường các biện pháp vệ sinh môi trường, khơi thông cống rãnh, loại bỏ rác thải tồn đọng sau thiên tai.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tổ chức tuyên truyền sâu rộng cho người dân thực hiện nghiêm các biện pháp phòng, chống dịch bệnh Cúm gia cầm. Không buôn bán, giết mổ, tiêu thụ gia cầm mắc bệnh, nghi mắc bệnh, vứt xác gia cầm, chất thải chưa qua xử lý ra môi trường. Không sử dụng gia cầm không rõ nguồn gốc, gia cầm, sản phẩm gia cầm chưa qua kiểm dịch; khi sử dụng sản phẩm gia cầm phải nấu chín; không tham gia vào hoạt động buôn bán, vận chuyển lậu gia cầm, sản phẩm gia cầm… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các xã Yên Thế, Bố Hạ, Đồng Kỳ, Xuân Lương và Tam Tiến chỉ đạo phòng chuyên môn phối hợp với đơn vị chuyên môn của Sở Nông nghiệp và Môi trường tiếp tục thực hiện các nội dung thuộc Đề án “Xây dựng vùng an toàn dịch bệnh Cúm gia cầm và Niu-cát-xơn đối với gà trên địa bàn huyện Yên Thế, tỉnh Bắc Giang giai đoạn 2021-2025”, nhất là tập trung công tác tiêm phòng vắc xin Cúm cho đàn gà theo kế hoạch của Đề án xong trước 30/11/2025, kết hợp vệ sinh tiêu độc khử trùng môi trường phòng, chống dịch bệnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Sở Nông nghiệp và Môi trường chỉ đạo Chi cục Chăn nuôi, Thú y và Thủy sản thực hiện nghiêm, có hiệu quả các giải pháp phòng, chống dịch bệnh Cúm gia cầm A/H5N1, A/H5N6, A/H5N8 và các chủng vi rút Cúm gia cầm khác. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Phối hợp với các địa phương tăng cường quản lý, giám sát chặt chẽ tình hình dịch bệnh Cúm gia cầm trên địa bàn; tổ chức tiêm phòng vắc xin Cúm cho đàn gia cầm; chủ động lấy mẫu của gia cầm có dấu hiệu mắc bệnh, nghi mắc bệnh Cúm gia cầm, gia cầm tại các địa bàn có nguy cơ cao để xét nghiệm xác định nguyên nhân gây bệnh để kịp thời cảnh báo, xử lý, tiêu hủy đàn gia cầm mắc bệnh, nghi mắc bệnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tổ chức các Đoàn kiểm tra công tác phòng, chống dịch bệnh Cúm gia cầm đối với các xã, phường, chủ động áp dụng các biện pháp phòng, chống dịch phù hợp với điều kiện thực tế tại địa phương được kiểm tra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Đoàn kiểm tra liên ngành cơ động phòng, chống dịch động vật tăng cường kiểm tra công tác vận chuyển, kinh doanh động vật, sản phẩm động vật trên địa bàn tỉnh. Giám sát chặt chẽ hoạt động của các chợ đầu mối, các địa điểm tập kết, vận chuyển, buôn bán, giết mổ gia súc gia cầm. Xử lý nghiêm các trường hợp nhập lậu, vận chuyển động vật, sản phẩm động vật không rõ nguồn gốc, chưa qua kiểm dịch vận chuyển ra vào địa bàn tỉnh.</span></span></span></p>', '31/10/2025 10:00', 'https://bacninh.gov.vn/news/-/details/37632/cac-xa-phuong-trong-tinh-chu-ong-ap-dung-cac-bien-phap-phong-chong-dich-benh-cum-gia-cam-phu-hop-voi-ieu-kien-thuc-te-tai-ia-phuong-29889461', '', 'Nguyễn Miền', 43, 'Kinh tế', 3, 'true', '38762', '{}', '2025-10-31 08:44:56.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (13, '29557302', 'Chủ tịch UBND tỉnh Vương Quốc Tuấn: Nghiên cứu xây dựng chính sách và ứng dụng các...', 'Chủ tịch UBND tỉnh Vương Quốc Tuấn: Nghiên cứu xây dựng chính sách và ứng dụng các thành tựu khoa học công nghệ vào sản xuất, chế biến nông sản chủ lực của tỉnh', '/documents/37632/23288501/2+%283%29.jpg/568de42d-db61-daed-23c9-7de24de0bd77?t=1761824780235', '<p>(BNP) - Chiều 30/10, đồng chí Vương Quốc Tuấn, Uỷ viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đến thăm, làm việc tại một số doanh nghiệp chế biến nông sản trên địa bàn tỉnh. Cùng đi có đại diện lãnh đạo các sở, ngành, cơ quan của tỉnh.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/2+%283%29.jpg/568de42d-db61-daed-23c9-7de24de0bd77?t=1761824780235\" style=\"height: 606px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Chủ tịch&nbsp;UBND tỉnh Vương Quốc Tuấn và đoàn công tác của tỉnh đến thăm Công ty Cổ phần xuất nhập khẩu thực phẩm Toàn Cầu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch UBND tỉnh Vương Quốc Tuấn và đoàn công tác của tỉnh đến thăm Công ty Cổ phần xuất nhập khẩu thực phẩm Toàn Cầu (phường Phượng Sơn). Đây là doanh nghiệp chuyên chế biến, bảo quản và kinh doanh nông sản sơ biến xuất khẩu tươi, đông lạnh, nước trái cây như: Vải thiều, đậu tương rau, ngô ngọt, rau các loại. Quy mô sản lượng mỗi sản phẩm đạt 3 nghìn - 5 nghìn tấn mỗi năm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các vùng nguyên liệu của doanh nghiệp được canh tác theo hướng giảm phát thải, organic. Đặc biệt, sản phẩm vải thiều do doanh nghiệp chế biến có vùng liên kết được chứng nhân Organic Việt Nam. Hiện nay, 80% sản lượng chế biến của doanh nghiệp được xuất khẩu vào thị trường lớn như: Nhật, Mỹ, Hàn Quốc, Châu Âu, Úc...; doanh thu hàng năm đạt ngưỡng 5,5 triệu USD; duy trì mức tăng trưởng hàng năm 6 - 10%. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/1+%288%29.jpg/5192dad0-f5e6-fb43-7dd9-0b5ccbab3fe9?t=1761824879269\" style=\"height: 491px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Quang cảnh buổi làm việc với Công ty&nbsp;Cổ phần xuất nhập khẩu thực phẩm Toàn Cầu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thăm Công ty Cổ phần xuất nhập khẩu Vifoco (phường Bắc Giang) được thành lập năm 2008, hoạt động trong lĩnh vực sản xuất, chế biến và xuất khẩu nông sản.&nbsp;Hiện tại, doanh nghiệp áp dụng chặt chẽ quy trình chế biến khép kín, từ trồng trọt, chăm sóc đến thu hoạch, chế biến đảm bảo vệ sinh an toàn thực phẩm gắn với bảo vệ môi trường. Vifoco cũng chủ động liên kết sản xuất với nhiều địa phương thuộc các tỉnh miền núi Trung du phía Bắc; xây dựng, sản xuất thành vùng chuyên canh hàng hóa tập trung với nhiều nông sản chủ lực như: Bí đỏ, ngô ngọt, khoai lang, vải thiều, dưa chuột… đảm bảo vận hành khép kín, có thể chế biến, cung cấp khoảng 8 nghìn - 10 nghìn tấn/năm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Để góp phần nâng tầm sản phẩm nông sản Việt Nam, Công ty Vifoco xây dựng chiến lược phát triển theo hướng ưu tiên các sản phẩm nông sản đặc trưng đạt chứng nhận OCOP từ 3 sao trở lên như: Ngô ngọt nguyên hạt, khoai tây sợi IQF, vải thiều IQF, vải thiều đóng hộp, nhãn…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/3.jpg/4c1a0ff3-2df2-6976-d801-ddf3567323c6?t=1761824962421\" style=\"height: 561px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Chủ tịch UBND tỉnh Vương Quốc Tuấn và đoàn công tác thăm&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"> Công ty Cổ phần xuất nhập khẩu Vifoco.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Qua thăm, tìm hiểu mô hình sản xuất, Chủ tịch UBND tỉnh Vương Quốc Tuấn đánh giá cao những nỗ lực của các doanh nghiệp trong quá trình hoạt động, dù còn nhiều khó khăn nhưng các doanh nghiệp vẫn đạt được những con số ấn tượng, mở rộng thị phần xuất khẩu ở những thị trường khó tính, tăng doanh thu, tạo nhiều việc làm cho nhiều người lao động; xây dựng được uy tín, thương hiệu trên thị trường, đóng góp quan trọng vào dịch chuyển cơ cấu kinh tế của tỉnh, gia tăng giá trị xuất khẩu nông sản.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Ghi nhận kiến nghị của doanh nghiệp, Chủ tịch UBND tỉnh đánh giá cao khát vọng và chiến lược của các doanh nghiệp, đề nghị các doanh nghiệp tiếp tục nghiên cứu, đánh giá kỹ thị trường, mở rộng vùng nguyên liệu, nâng cao chất lượng chế biến nông sản. Đặc biệt, đối với sản phẩm vải thiều của tỉnh, Chủ tịch UBND tỉnh cho rằng, các doanh nghiệp cần đi theo hướng chuyên sâu, hiệu quả. Tỉnh giao cho Sở Khoa học và Công nghệ đóng vai trò “hiến kế, gác cửa” nhằm nghiên cứu, ứng dụng thành tựu khoa học công nghệ vào sản xuất, chế biến vải thiều nói riêng, các nông sản chủ lực nói chung. Tỉnh đặt quyết tâm đưa sản phẩm vải thiều trở thành thương hiệu mang tầm quốc tế, được xây dựng trên cơ sở giá trị thực và hướng đi bền vững. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Chủ tịch UBND tỉnh yêu cầu Sở Nông nghiệp và Môi trường, Sở Công thương phối hợp tham mưu HĐND tỉnh xây dựng một Nghị quyết riêng về phát triển cây vải thiều, bao gồm quy hoạch vùng trồng, xác định xuất xứ thương hiệu, định vị rõ thương hiệu đặc trưng cho vải thiều Bắc Ninh, hướng tới mở rộng quy mô, nâng cao giá trị sản phẩm. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/5+%281%29.jpg/dc34824b-0bf7-7143-1c5b-26c71411acd9?t=1761825038355\" style=\"height: 555px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các doanh nghiệp&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">áp dụng chặt chẽ quy trình chế biến khép kín.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Các sở, ngành liên quan tập trung nghiên cứu, hỗ trợ chế biến, nhằm tạo ra sản phẩm vải thiều trái vụ. Trước mắt, cần nghiên cứu kéo dài thời gian thu hoạch vụ vải thiều hiện có, phát triển đa dạng các sản phẩm chế biến từ vải thiều như: Nước ép, sấy khô, đông lạnh, tinh dầu, mỹ phẩm, đồ uống tự nhiên,… nhằm tăng giá trị và sức cạnh tranh quốc tế.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Ngoài ra, từ quy hoạch tổng thể của tỉnh, các ngành, địa phương phải quyết liệt hơn trong việc quy hoạch vùng trồng, tạo dựng những vùng sản xuất có giá trị thực sự. Cùng đó, nghiên cứu cơ chế, chính sách cụ thể nhằm thu hút các doanh nghiệp đầu tư quy mô lớn, hỗ trợ truy xuất nguồn gốc, xây dựng thương hiệu vùng trồng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Chủ tịch UBND tỉnh cũng đề nghị các sở, ngành liên quan tiếp tục rà soát, đánh giá tính phù hợp của các quy định hỗ trợ phát triển nông nghiệp hiện hành, tham mưu điều chỉnh, khuyến khích đổi mới sáng tạo, chuyển đổi số trong lĩnh vực nông nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Tỉnh cũng sẽ hỗ trợ doanh nghiệp, hợp tác xã triển khai truy xuất nguồn gốc, xây dựng mã số vùng trồng, tạo điều kiện cho nông sản địa phương khẳng định uy tín trên thị trường quốc tế. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"></span></span></span></p>', '30/10/2025 18:43', 'https://bacninh.gov.vn/news/-/details/37632/chu-tich-ubnd-tinh-vuong-quoc-tuan-nghien-cuu-xay-dung-chinh-sach-va-ung-dung-cac-thanh-tuu-khoa-hoc-cong-nghe-vao-san-xuat-che-bien-nong-san-chu-luc-cua-tinh-29557302', '', 'Nguyễn Miền', 342, 'Kinh tế', 3, 'true', '38762', '{}', '2025-10-31 08:44:56.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (14, '29494918', 'Điều chỉnh Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050', 'Điều chỉnh Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/29/duongsat-17617350052801071929828.jpg', '<p>(BNP) - Phó Thủ tướng Trần Hồng Hà vừa ký Quyết định số 2404/QĐ-TTg phê duyệt điều chỉnh Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050.</p>', '<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quyết định nêu rõ, điều chỉnh, bổ sung một số nội dung về mạng lưới quy hoạch:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Đối với tuyến đường sắt hiện hữu</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh phạm vi 02 tuyến: Hà Nội - Thành phố Hồ Chí Minh, Hà Nội - Lào Cai</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh lộ trình chuyển đổi công năng tuyến đường sắt Hà Nội - Hải Phòng đoạn sau ga Hải Phòng đến cảng Chùa Vẽ sau khi hoàn thành đầu tư, đưa vào khai thác ga Vật Cách.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Đối với tuyến đường sắt mới</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh tên, quy mô, lộ trình đầu tư tuyến đường sắt tốc độ cao trên trục Bắc - Nam; bổ sung tuyến đường sắt tốc độ cao Hà Nội - Quảng Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh quy mô, lộ trình đầu tư 02 tuyến: Lào Cai - Hà Nội - Hải Phòng, Thành phố Hồ Chí Minh - Lộc Ninh; điều chỉnh lộ trình đầu tư 03 tuyến: Hà Nội - Đồng Đăng, Hải Phòng - Hạ Long - Móng Cái, Tháp Chàm - Đà Lạt.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh phạm vi, quy mô 07 tuyến: Yên Viên - Phả Lại - Hạ Long - Cái Lân, vành đai phía Đông Thành phố Hà Nội, Nam Định - Thái Bình - Hải Phòng, Vũng Áng - Mụ Giạ, Biên Hòa - Vũng Tàu, Thành phố Hồ Chí Minh - Cần Thơ - Cà Mau, Đà Nẵng - Kon Tum - Gia Lai - Đắk Lắk - Đắk Nông - Bình Phước.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh không đưa vào quy hoạch tuyến Thủ Thiêm - Long Thành và chuyển thành đường sắt đô thị; giao Thành phố Hồ Chí Minh và tỉnh Đồng Nai cập nhật vào quy hoạch tỉnh và các quy hoạch liên quan.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Bổ sung tuyến đường sắt An Bình - Sài Gòn (Hòa Hưng) - Tân Kiên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Quyết định, bổ sung kết nối với đường sắt Trung Quốc tại cửa khẩu Móng Cái thông qua tuyến đường sắt Hải Phòng - Hạ Long - Móng Cái; bổ sung kết nối với Campuchia tại cửa khẩu Mộc Bài thông qua tuyến đường sắt Thành phố Hồ Chí Minh - Tây Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều chỉnh, bổ sung về kết nối các đô thị, đầu mối giao thông lớn:</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đường sắt khu đầu mối Hà Nội</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đường sắt khu đầu mối Thành phố Hồ Chí Minh</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Đường sắt khu vực thành phố Đà Nẵng bổ sung lộ trình di dời ga Đà Nẵng thực hiện trước năm 2030.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">- Điều chỉnh định hướng kết nối đường sắt với 02 cảng biển Nghi Sơn (Thanh Hóa), Hiệp Phước (Thành phố Hồ Chí Minh), Cảng hàng không quốc tế Tân Sơn Nhất (Thành phố Hồ Chí Minh), Cảng hàng không quốc tế Long Thành (Đồng Nai), Cảng hàng không quốc tế thứ hai Hà Nội, Cảng hàng không quốc tế Gia Bình, Cảng cạn Văn Lâm (Hưng Yên), Gia Bình (Bắc Ninh).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các nội dung khác giữ nguyên theo Quyết định số 1769/QĐ-TTg ngày 19/10/2021 của Thủ tướng Chính phủ phê duyệt Quy hoạch mạng lưới đường sắt thời kỳ 2021 - 2030, tầm nhìn đến năm 2050.</span></span></span></p>', '30/10/2025 13:42', 'https://bacninh.gov.vn/news/-/details/37632/-ieu-chinh-quy-hoach-mang-luoi-uong-sat-thoi-ky-2021-2030-tam-nhin-en-nam-2050-29494918', '', 'BNP', 66, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:56.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (15, '29289801', 'Tăng cường kiểm tra, kiểm soát và xử lý vi phạm tại Hội chợ Mùa Thu 2025', 'Tăng cường kiểm tra, kiểm soát và xử lý vi phạm tại Hội chợ Mùa Thu 2025', '/documents/37632/23986559/IMG_2264.jpg/67ee492f-498f-688a-ac94-e2d2ed8280fd?t=1761708589640', '<p>(BNP) - Ban Tổ chức Hội chợ Mùa Thu 2025 vừa có văn bản đề nghị UBND các tỉnh, thành phố kiểm tra, kiểm soát và xử lý vi phạm tại Hội chợ Mùa Thu 2025.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23986559/IMG_2264.jpg/67ee492f-498f-688a-ac94-e2d2ed8280fd?t=1761708589640\" style=\"height: 629px;\" /></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ Mùa Thu 2025 được tổ chức từ ngày 25/10 đến ngày 04/11/2025. Trong 3 ngày đầu diễn ra, Hội chợ đã tiếp đón lượng lớn các đối tác thương mại, khách tham quan trong và ngoài nước tới giao thương và mua sắm. Tuy nhiên, qua phản ánh của lực lượng Quản lý thị trường còn một số vấn đề tồn tại như: Một số hộ kinh doanh thực phẩm chế biến sẵn chưa ghi rõ tên cơ sở sản xuất, địa chỉ và hạn sử dụng trên bao bì sản phẩm theo quy định. Một số gian hàng kinh doanh nông sản, thực phẩm không ghi rõ tên sản phẩm, số công bố sản phẩm, thành phần hoặc hạn sử dụng; bao bì chưa đảm bảo thông tin bắt buộc theo quy định về ghi nhãn hàng hóa. Một số gian hàng kinh doanh đồ ăn tại chỗ hoặc mang đi chưa có Giấy chứng nhận đủ điều kiện an toàn thực phẩm... Bên cạnh đó còn có hiện tượng một số gian hàng tham gia Hội chợ bán sản phẩm, hàng hóa không đúng với giá niêm yết hoặc không công khai giá niêm yết; giá bán cao hơn giá thị trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm bảo đảm hoạt động thương mại, trưng bày, giới thiệu sản phẩm tại Hội chợ được diễn ra văn minh, đúng quy định pháp luật, Ban Tổ chức đề nghị UBND các tỉnh, thành phố quan tâm, chỉ đạo Sở Công Thương, Chi cục Quản lý thị trường các tỉnh, thành phố phối hợp với Ban Tổ chức kiểm tra, xử lý các hành vi vi phạm pháp luật trong lĩnh vực công thương tại hội chợ, bao gồm: Hàng giả, hàng nhái, hàng kém chất lượng, xâm phạm quyền sở hữu trí tuệ; gian lận thương mại, không niêm yết giá hoặc bán hàng không theo giá niêm yết; vi phạm quy định về an toàn thực phẩm (đối với các gian hàng kinh 2 doanh thực phẩm); vi phạm quy định về xúc tiến thương mại và các quy định khác liên quan. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng đó, xử lý hoặc kiến nghị xử lý theo quy định hiện hành đối với các trường hợp vi phạm; đồng thời nhắc nhở, tuyên truyền, hướng dẫn các doanh nghiệp, đơn vị tham gia Hội chợ thực hiện nghiêm quy định pháp luật trong các lĩnh vực nêu trên./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '29/10/2025 10:28', 'https://bacninh.gov.vn/news/-/details/37632/tang-cuong-kiem-tra-kiem-soat-va-xu-ly-vi-pham-tai-hoi-cho-mua-thu-2025-29289801', '', 'BNP', 146, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (17, '29164840', 'Tổ chức các hoạt động hưởng ứng Ngày quyền của người tiêu dùng Việt Nam năm 2026', 'Tổ chức các hoạt động hưởng ứng Ngày quyền của người tiêu dùng Việt Nam năm 2026', '/documents/37632/23986559/IMG_6600.jpg/eea2f8e6-8b12-ac27-9a37-44733fdb4e51?t=1761638150525', '<p>(BNP) - Các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam sẽ bắt đầu từ đầu năm 2026 (tháng 1) được tập trung tổ chức trong tháng 3 (tháng cao điểm) và kéo dài trong cả năm 2026.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23986559/IMG_6600.jpg/eea2f8e6-8b12-ac27-9a37-44733fdb4e51?t=1761638150525\" style=\"height: 646px;\" /></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các hoạt động vì quyền lợi người tiêu dùng tổ chức tập trung vào Tết Dương lịch, Tết Âm lịch, các mùa mua sắm hoặc các ngày cao điểm mua sắm trên thị trường.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ Công Thương vừa ban hành Kế hoạch tổ chức các hoạt động hưởng ứng Ngày quyền của người tiêu dùng Việt Nam năm 2026.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, chủ đề cho các hoạt động Ngày Quyền của người tiêu dùng Việt Nam năm 2026 là “An toàn thông tin - Gắn kết niềm tin - Tiêu dùng bền vững”. Các hoạt động vì quyền lợi người tiêu dùng được khuyến khích tổ chức và thực hiện trong suốt cả năm 2026 trong đó tập trung vào các khoảng thời gian cao điểm về kinh doanh và tiêu dùng như: Tết Dương lịch, Tết Âm lịch, các mùa mua sắm hoặc các ngày cao điểm mua sắm trên thị trường. </span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong Tháng cao điểm hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam năm 2026 sẽ diễn ra Lễ phát động Ngày Quyền của người tiêu dùng Việt Nam năm 2026. Ngay sau Lễ phát động, triển khai các hoạt động nổi bật mang tính cộng đồng, hướng đến sự tham gia rộng rãi của người dân và sự lan tỏa trên môi trường số như: Giải chạy cộng đồng; Khu trải nghiệm xanh và số; Không gian Doanh nghiệp xanh và minh bạch là khu vực trưng bày và giới thiệu sản phẩm xanh, thân thiện môi trường. Bên cạnh trưng bày thực tế, chương trình huy động sự tham gia của các sàn giao dịch trực tuyến và doanh nghiệp thương mại điện tử.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh những hoạt động trọng tâm, tạo điểm nhấn còn diễn ra các hoạt động hưởng ứng khác như: Công tác tuyên truyền, truyền thông; Hoạt động nghiên cứu, tập huấn, phổ biến kiến thức và nâng cao hiểu biết pháp luật; Chương trình tri ân và hỗ trợ người tiêu dùng; Hoạt động xúc tiến thương mại và củng cố niềm tin của người tiêu dùng vào doanh nghiệp và sản phẩm uy tín.</span></span></span></p>\n\n<p class=\"MsoBodyText\" style=\"text-align:justify; text-indent:0cm; margin-bottom:12px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:black\">Tại các địa phương ngoài các hoạt động trên còn diễn ra các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam năm 2026 bao gồm:&nbsp;</span>M<span style=\"color:black\">ít tinh, tuần hành, diễu hành; tổ chức các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam tại các chợ, siêu thị, trung tâm thương mại, cơ sở sản xuất, kinh doanh của các doanh nghiệp tại địa phương; tổ chức các chương trình tư vấn, hỗ trợ và tuyên truyền pháp luật về bảo vệ người tiêu dùng; các hoạt động thúc đẩy sự hiểu biết và tương tác giữa doanh nghiệp và người tiêu dùng; các chương trình, hoạt động tri ân người tiêu dùng; chương trình ký cam kết doanh nghiệp sản xuất, cung cấp dịch vụ đảm bảo an toàn, chất lượng vì người tiêu dùng; tuyên dương các doanh nghiệp có nhiều hoạt động hướng tới người tiêu dùng.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các hoạt động hưởng ứng Ngày Quyền của người tiêu dùng Việt Nam năm 2026 được tổ chức nhằm kêu gọi, động viên, khuyến khích sự tham gia của các cơ quan nhà nước, tổ chức xã hội, doanh nghiệp và người tiêu dùng vào các hoạt động liên quan; từng bước đưa Ngày Quyền của người tiêu dùng thành động lực và điểm nhấn quan trọng trong đời sống kinh tế - xã hội, góp phần xây dựng môi trường kinh doanh, tiêu dùng lành mạnh cho đất nước./.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:13pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><span style=\"font-size:14.0pt\"></span></span></span></span></p>', '28/10/2025 14:54', 'https://bacninh.gov.vn/news/-/details/37632/to-chuc-cac-hoat-ong-huong-ung-ngay-quyen-cua-nguoi-tieu-dung-viet-nam-nam-2026-29164840', '', 'BNP', 93, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (18, '29149836', 'Văn phòng Thường trực Ban Chỉ đạo 389 Quốc gia làm việc với Ban Chỉ đạo 389 tỉnh Bắc...', 'Văn phòng Thường trực Ban Chỉ đạo 389 Quốc gia làm việc với Ban Chỉ đạo 389 tỉnh Bắc Ninh về công tác chống buôn lậu, gian lận thương mại và hàng giả', '/documents/37632/23288501/z7164362681652_f36e649ae1b44f0ee8dfcf0f15107806.jpg/30da8331-2919-b0ce-af8e-0e3a1b2bff15?t=1761643542563', '<p>(BNP) – Chiều 28/10,&nbsp;Đoàn công tác của&nbsp;Văn phòng Thường trực&nbsp;Ban Chỉ đạo&nbsp;(BCĐ)&nbsp;389 Quốc gia&nbsp;do đồng chí Trần Đức Đông, Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia làm Trưởng đoàn có buổi làm việc với&nbsp;BCĐ&nbsp;389 tỉnh về công tác chống buôn lậu, gian lận...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7164362681652_f36e649ae1b44f0ee8dfcf0f15107806.jpg/30da8331-2919-b0ce-af8e-0e3a1b2bff15?t=1761643542563\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh buổi làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo báo cáo của BCĐ 389 tỉnh<span lang=\"VI\">, thực hiện Chỉ thị số 13/CT-TTg ngày 17/5/2025 của Thủ tướng Chính phủ về tăng cường công tác chống buôn lậu, gian lận thương mại và hàng giả trong tình hình mới, </span>BCĐ <span lang=\"VI\">389 tỉnh ban hành nhiều văn bản chỉ đạo, hướng dẫn triển khai đồng bộ tới các sở, ngành, lực lượng chức năng và địa phương.</span> <span lang=\"VI\">Các đợt cao điểm được tổ chức quyết liệt, bám sát phương châm “4 không: không khoan nhượng, không ngừng nghỉ, không có vùng cấm, không có ngoại lệ”.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Từ ngày 17/5 đến 15/10/2025, các lực lượng chức năng trong tỉnh phát hiện, xử lý 1.662 vụ vi phạm với 1.664 đối tượng, trong đó xử lý hình sự 17 vụ/19 bị can, xử lý hành chính 1.645 vụ, tổng số tiền thu nộp ngân sách Nhà nước hơn 201 tỷ đồng.</span> <span lang=\"VI\">Công an tỉnh khởi tố 17 vụ, xử phạt hành chính 81 vụ; Chi cục Quản lý thị trường xử lý 261 vụ; Cục Thuế tỉnh thanh tra, kiểm tra 727 doanh nghiệp, truy thu và xử phạt hơn 188 tỷ đồng; Chi cục Hải quan khu vực V xử lý 497 vụ, phạt hơn 4 tỷ đồng.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">B</span>ên cạnh đó, BCĐ<span lang=\"VI\"> 389 tỉnh</span> <span lang=\"VI\">nhận diện nhiều phương thức, thủ đoạn mới của các đối tượng vi phạm như lợi dụng thương mại điện tử, mạng xã hội, đơn vị vận chuyển trung gian để buôn bán hàng nhập lậu, hàng giả, hàng kém chất lượng</span>; &nbsp;thiết lập đường dây nóng và hộp thư điện tử (0981.027.389 &nbsp;<span lang=\"VI\">duongdaynong389bacninh@gmail.com) để tiếp nhận, xử lý tin báo, góp phần huy động người dân, doanh nghiệp tham gia giám sát, tố giác hành vi vi phạm.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Công tác phối hợp giữa các ngành Công an, Quản lý thị trường, Hải quan, Thuế, Y tế, Nông nghiệp… được duy trì thường xuyên, hiệu quả, góp phần răn đe, ổn định thị trường, bảo vệ quyền lợi người tiêu dùng và doanh nghiệp.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Tuy nhiên, công tác nắm bắt, dự báo tình hình còn hạn chế; lực lượng mỏng, kinh phí và phương tiện phục vụ kiểm tra, tuyên truyền còn thiếu. Một số Ban Chỉ đạo cấp xã, phường mới thành lập nên hoạt động còn lúng túng, chưa phát huy hiệu quả.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, các đại biểu tập trung&nbsp;trao đổi,&nbsp;thảo luận&nbsp;về sự phối hợp, chia sẻ thông tin giữa các ngành, địa phương; những khó khăn, vướng mắc trong kiểm tra, kiểm soát hoạt động sản xuất, kinh doanh hàng hóa, trong phát hiện, xử lý các hành vi vi phạm trong kinh doanh thương mại điện tử…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7164362690532_5a7ca69c1cda3a4db7ba443981dcbba1.jpg/c76394a3-ef02-2671-03f4-2ddf9b869a6b?t=1761643860557\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia Trần Đức Đông phát biểu kết luận.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu kết luận buổi làm việc, Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia Trần Đức Đông ghi nhận, đánh giá cao tinh thần trách nhiệm, sự chủ động, sáng tạo của BCĐ 389 tỉnh trong công tác phòng, chống buôn lậu, gian lận thương mại và hàng giả thời gian qua. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đề nghị BCĐ 389 tỉnh tiếp tục thực hiện nghiêm túc các chỉ đạo của Chính phủ, Thủ tướng Chính phủ và BCĐ 389 Quốc gia; chỉ đạo các sở, ngành, lực lượng chức năng căn cứ chức năng, nhiệm vụ được giao chủ động xây dựng, tổ chức kế hoạch cao điểm trước, trong và sau Tết Nguyên đán, tập trung kiểm tra, kiểm soát các mặt hàng thiết yếu, hàng hóa có nhu cầu tiêu thụ cao.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, tăng cường công tác phối hợp, chia sẻ thông tin giữa các lực lượng; đẩy mạnh công tác tuyên truyền, truyền thông để nâng cao nhận thức, huy động sự vào cuộc của người dân và doanh nghiệp trong việc phát hiện, tố giác hành vi vi phạm; kiên quyết xử lý nghiêm các tổ chức, cá nhân vi phạm, không để hình thành “điểm nóng” về buôn lậu, gian lận thương mại và hàng giả trên địa bàn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chánh Văn phòng Thường trực BCĐ 389 Quốc gia tin tưởng rằng, với sự vào cuộc đồng bộ, quyết liệt của cả hệ thống chính trị, công tác đấu tranh chống buôn lậu, gian lận thương mại và hàng giả trên địa bàn tỉnh Bắc Ninh tiếp tục đạt nhiều kết quả tích cực, góp phần ổn định thị trường, bảo vệ quyền lợi chính đáng của người tiêu dùng và doanh nghiệp.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288501/z7164477261237_86dbb624cd38b9a37b2253729bd04448.jpg/ee4a0895-1cdd-9dcd-5f4b-4c39681dec8e?t=1761645413785\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Giám đốc Công an tỉnh, Phó Trưởng BCĐ 389 tỉnh Nguyễn Hữu Bình tặng Bằng khen của Chủ tịch UBND tỉnh cho 02 tập thể.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span lang=\"VI\">Nhân dịp này, 02 tập thể và 07 cá nhân vinh dự được </span>tặng Bằng khen của <span lang=\"VI\">Chủ tịch UBND tỉnh Bắc Ninh vì đã có thành tích xuất sắc trong công tác phòng, chống buôn lậu, gian lận thương mại và hàng giả trên địa bàn tỉnh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></p>', '28/10/2025 13:54', 'https://bacninh.gov.vn/news/-/details/37632/van-phong-thuong-truc-ban-chi-ao-389-quoc-gia-lam-viec-voi-ban-chi-ao-389-tinh-bac-ninh-ve-cong-tac-chong-buon-lau-gian-lan-thuong-mai-va-hang-gia-29149836', '', 'Diệu Hoa', 167, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (19, '29278551', 'Phối hợp quản lý hoạt động thị trường ngoại hối', 'Phối hợp quản lý hoạt động thị trường ngoại hối', '/documents/37632/23986559/ngoai-hoi.jpeg/10d0b297-7666-4906-ef1e-307e02d74dfd?t=1761705135462', '<p>(BNP) - Ngân hàng Nhà nước Việt Nam vừa có văn bản gửi Bộ Công an, Bộ Công Thương, Thanh tra Chính phủ về việc phối hợp quản lý hoạt động thị trường ngoại hối.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23986559/ngoai-hoi.jpeg/10d0b297-7666-4906-ef1e-307e02d74dfd?t=1761705135462\" style=\"height: 599px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa (nguồn Internet)</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để chủ động các biện pháp ổn định thị trường ngoại hối, hạn chế tối đa rủi ro cho hoạt động của hệ thống ngân hàng, Ngân hàng Nhà nước Việt Nam đề nghị Bộ Công an, Bộ Công Thương, Thanh Tra Chính phủ chỉ đạo các đơn vị chức năng của Cơ quan thực hiện thanh tra, kiểm tra, giám sát, quản lý hoạt động ngoại hối của các tổ chức, cá nhân trong nền kinh tế; kịp thời phát hiện các hành vi vi phạm về quản lý ngoại hối, nhất là hoạt động mua, bán ngoại tệ trái pháp luật, hoạt động của thị trường ngoại hối không chính thức. Thực hiện các biện pháp để xử lý nghiêm các hành vi vi phạm pháp luật (nếu có) theo quy định.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời đề nghị các đơn vị liên quan phối hợp cung cấp thông tin về các vụ việc, các trường hợp vi phạm quy định về quản lý ngoại hối để Ngân hàng Nhà nước Việt Nam kịp thời triển khai các biện pháp quản lý thị trường ngoại hối hiệu quả, đảm bảo an toàn cho hoạt động của hệ thống ngân hàng./.</span></span></span></p>', '26/10/2025 09:31', 'https://bacninh.gov.vn/news/-/details/37632/phoi-hop-quan-ly-hoat-ong-thi-truong-ngoai-hoi-29278551', '', 'BNP', 20, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (20, '27783301', 'Đẩy mạnh các hoạt động kết nối cung cầu, tổ chức đưa hàng Việt về khu vực nông thôn,...', 'Đẩy mạnh các hoạt động kết nối cung cầu, tổ chức đưa hàng Việt về khu vực nông thôn, miền núi, vùng sâu vùng xa', '/documents/37632/23566312/1.jpg/05e4942c-f1fb-4693-5c34-dc4049ceaec9?t=1761209620848', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh vừa ký Công văn số 3901/UBND-KTTH về việc triển khai thực hiện Công điện số 179/CĐ-TTg ngày 29/9/2025 của Thủ tướng Chính phủ trên địa bàn tỉnh.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23566312/1.jpg/05e4942c-f1fb-4693-5c34-dc4049ceaec9?t=1761209620848\" style=\"height: 648px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổ chức các chương trình khuyến mại tập trung, kích cầu tiêu dùng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để đẩy mạnh phát triển thị trường trong nước, kích cầu tiêu dùng những tháng cuối năm 2025, Chủ tịch UBND tỉnh yêu cầu các sở, cơ quan, đơn vị tiếp tục phối hợp với Sở Công Thương triển khai các giải pháp hiệu quả, thực chất gắn với tổ chức chiến dịch truyền thông đặc biệt đẩy mạnh Cuộc vận động “Người Việt Nam ưu tiên dùng hàng Việt Nam” nhằm khẳng định chất lượng sản phẩm, hàng hóa sản xuất trong nước; phát động phong trào tiêu dùng hàng Việt trên các sàn giao dịch thương mại điện tử của Việt Nam và quốc tế. Tổ chức các chương trình xúc tiến thương mại, chương trình khuyến mại tập trung, kích cầu tiêu dùng; đẩy mạnh các hoạt động kết nối cung cầu, tổ chức đưa hàng Việt về khu vực nông thôn, miền núi, vùng sâu vùng xa, vùng kinh tế khó khăn; liên kết với các sàn giao dịch nông sản Việt Nam để luân chuyển hàng hóa đặc sản địa phương và sản phẩm đạt tiêu chuẩn OCOP. Tham gia trưng bày gian hàng tại Hội chợ Mùa Thu năm 2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Tài chính chủ trì, phối hợp với các cơ quan, đơn vị liên quan cân đối nguồn ngân sách địa phương để tham mưu UBND tỉnh bố trí kinh phí thực hiện các hoạt động xúc tiến thương mại nhằm thúc đẩy tiêu thụ xuất khẩu sản phẩm của tỉnh đảm bảo đúng quy định, tiết kiệm, hiệu quả, đặc biệt là các sự kiện lớn như: Hội chợ Mùa Thu 2025; Lễ hội trái cây và Hội chợ, Triển lãm nông sản, hàng hoá tỉnh Bắc Ninh 2025. Phối hợp chặt chẽ các cơ quan theo dõi sát tình hình giá cả, nhất là những hàng hóa, dịch vụ thiết yếu, để chủ động triển khai các giải pháp phù hợp, kịp thời, hiệu quả theo quẩm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Văn hóa, Thể thao và Du lịch chủ trì, phối hợp với các cơ quan, địa phương liên quan tập trung các giải pháp thúc đẩy các chương trình du lịch, kết hợp với các hoạt động, sự kiện văn hóa, lễ hội văn hóa, các chương trình xúc tiến thương mại trên địa bàn tỉnh, gia tăng trải nghiệm, kích cầu tiêu dùng đối với hàng hóa, dịch vụ đến du khách trong và ngoài nước, đặc biệt là các sự kiện lớn như: Hội chợ Mùa Thu 2025; Lễ hội trái cây và Hội chợ, Triển lãm nông sản, hàng hoá tỉnh Bắc Ninh 2025. Đẩy mạnh phát triển công nghiệp văn hóa, công nghiệp giải trí để nhân dân được thụ hưởng và tham gia vào quá trình thương mại hóa các sản phẩm văn hóa. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngân hàng Nhà nước chi nhánh khu vực 12 chỉ đạo các tổ chức tín dụng tích cực ứng dụng chuyển đổi số trong quy trình vay vốn, rút ngắn thời gian xử lý, tăng tính minh bạch, tạo điều kiện thuận lợi cho người dân, doanh nghiệp trong tiếp cận vốn vay, nhằm thúc đẩy tiêu dùng trong nước; nghiên cứu cung cấp các gói tín dụng nhằm hỗ trợ sản xuất kinh doanh và tiêu dùng với quy trình, điều kiện vay thuận lợi để có thể giải ngân được. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND các xã, phường đẩy mạnh triển khai các chương trình xúc tiến thương mại nhằm hỗ trợ tiêu thụ sản phẩm hàng hóa sản xuất tại địa phương, đặc biệt là sự kiện Lễ hội trái cây và Hội chợ, Triển lãm nông sản, hàng hoá tỉnh Bắc Ninh 2025. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiệp hội Doanh nghiệp nhỏ và vừa tỉnh; Hội doanh nghiệp trẻ tỉnh kịp thời nắm bắt thông tin, nhu cầu thị trường, các khó khăn, vướng mắc của các doanh nghiệp thành viên để đề xuất các cơ quan chức năng có giải pháp xử lý, tháo gỡ kịp thời, hiệu quả./.</span></span></span></p>', '24/10/2025 14:00', 'https://bacninh.gov.vn/news/-/details/37632/-ay-manh-cac-hoat-ong-ket-noi-cung-cau-to-chuc-ua-hang-viet-ve-khu-vuc-nong-thon-mien-nui-vung-sau-vung-xa-27783301', '', 'Diệu Hoa', 68, 'Kinh tế', 3, '', '38762', '{}', '2025-10-31 08:44:57.000000', 3, 11);
INSERT INTO `sync_articles` VALUES (21, '28202001', 'Bắc Ninh tổ chức xe miễn phí đưa, đón Nhân dân và du khách tham quan Hội chợ Mùa Thu...', 'Bắc Ninh tổ chức xe miễn phí đưa, đón Nhân dân và du khách tham quan Hội chợ Mùa Thu từ ngày 26/10 - 4/11/2025', '/documents/37632/18152201/hoi-cho-mua-thu-17611208863751845302975.png/14d098af-4dae-27e6-d48c-f8fcc1118388?t=1761277531805', '<p>(BNP) - Nhằm tạo điều kiện thuận lợi cho Nhân dân và du khách tham quan Hội chợ Mùa Thu 2025 với chủ đề “Kết nối con người với sản xuất, kinh doanh” - “Nơi văn hoá và giao thương hội tụ”, Sở Văn hoá, Thể thao và Du lịch tỉnh Bắc Ninh tổ chức chương trình xe đưa, đón miễn phí từ Bắc Ninh đến...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><img src=\"/documents/37632/18152201/hoi-cho-mua-thu-17611208863751845302975.png/14d098af-4dae-27e6-d48c-f8fcc1118388?t=1761277531805\" style=\"height: 522px; width: 900px;\" /></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Ảnh minh hoạ: Nguồn baochinhphu.vn.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xe đưa đón xuất phát tại 2 địa điểm: Quảng trường 3/2 (phường Bắc Giang, thành phố Bắc Ninh) và Bảo tàng Bắc Ninh số 2 (số 2, đường Lý Thái Tổ, phường Kinh Bắc, thành phố Bắc Ninh). Điểm đến là Trung tâm Triển lãm Việt Nam (VEC) - Hà Nội.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thời gian hoạt động cụ thể:</span></span></span></p>\n\n<table class=\"Table\" style=\"width:625px; border-collapse:collapse; border:none\" width=\"625\">\n	<tbody>\n		<tr>\n			<td style=\"border-bottom:1px solid black; width:215px; padding:0cm 7px 0cm 7px; height:69px; border-top:1px solid black; border-right:1px solid black; border-left:1px solid black\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Địa điểm</b></span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:208px; padding:0cm 7px 0cm 7px; height:69px; border-top:1px solid black; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Buổi sáng (đi -về)</b></span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:202px; padding:0cm 7px 0cm 7px; height:69px; border-top:1px solid black; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Buổi chiều (đi -về)</b></span></span></span></p>\n			</td>\n		</tr>\n		<tr>\n			<td style=\"border-bottom:1px solid black; width:215px; padding:0cm 7px 0cm 7px; height:25px; border-top:none; border-right:1px solid black; border-left:1px solid black\">\n			<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quảng trường 3/2</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:208px; padding:0cm 7px 0cm 7px; height:25px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">7h30 - 13h00</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:202px; padding:0cm 7px 0cm 7px; height:25px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">15h00 - 21h00</span></span></span></p>\n			</td>\n		</tr>\n		<tr>\n			<td style=\"border-bottom:1px solid black; width:215px; padding:0cm 7px 0cm 7px; height:47px; border-top:none; border-right:1px solid black; border-left:1px solid black\">\n			<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bảo tàng Bắc Ninh số 2</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:208px; padding:0cm 7px 0cm 7px; height:47px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">8h00 - 13h00</span></span></span></p>\n			</td>\n			<td style=\"border-bottom:1px solid black; width:202px; padding:0cm 7px 0cm 7px; height:47px; border-top:none; border-right:1px solid black; border-left:none\">\n			<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">15h00 - 21h00</span></span></span></p>\n			</td>\n		</tr>\n	</tbody>\n</table>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng cộng có 144 chuyến xe phục vụ trong 10 ngày, chia đều cho 2 điểm đón.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thông tin về Hội chợ Mùa Thu 2025</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ Mùa Thu 2025 là hội chợ cấp quốc gia đầu tiên do Thủ tướng Chính phủ trực tiếp chỉ đạo triển khai. Sự kiện được mệnh danh là “Siêu hội chợ 6 nhất” với: Quy mô lớn nhất, không gian hiện đại nhất, sản phẩm phong phú nhất, chất lượng cao nhất, hoạt động hấp dẫn nhất và ưu đãi tốt nhất.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ quy tụ 34 tỉnh, thành, hơn 2.500 doanh nghiệp, trong đó có 100 doanh nghiệp nước ngoài đến từ nhiều châu lục. Toàn bộ khu vực triển lãm có 3.000 gian hàng với hơn 10.000 sản phẩm được trưng bày, giao thương.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Không gian hội chợ được thiết kế như hành trình xuyên Việt qua 5 phân khu chủ đề, giới thiệu những câu chuyện sống động về con người, văn hóa và kinh tế của đất nước.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh không gian trưng bày trong nhà, chuỗi hoạt động ngoài trời diễn ra sôi động với các trò chơi, concert, biểu diễn nghệ thuật, trình diễn thời trang, giao lưu văn hoá. Điểm nhấn nổi bật là Lễ hội Ẩm thực “Thu Mỹ Vị” tại Sân Nam, gồm hai phân khu đặc sắc: “Cheer Fest - Bia &amp; Nướng Xuyên Biên Giới” và “Một Vòng Việt Nam”, mang đến không gian rực rỡ sắc thu và đậm đà hương vị Việt.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Hội chợ Mùa Thu 2025, tỉnh Bắc Ninh tham gia với gian hàng quy mô 200m² thuộc phân khu “Thu đất Việt - Sắc nước hương Thu” do Bộ Công Thương chủ trì.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại đây, Bắc Ninh sẽ trình diễn di sản văn hóa Quan họ, trưng bày và quảng bá các sản phẩm đặc trưng, sản phẩm mang nhãn hiệu tập thể, nhãn hiệu chứng nhận, chỉ dẫn địa lý của địa phương. Ngoài ra, tỉnh còn giới thiệu các món ăn truyền thống và đặc sản tiêu biểu tại Khu Ẩm thực do Công ty Triển lãm Hội chợ Việt Nam (VEC) tổ chức.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Hướng dẫn đăng ký tham gia xe đưa đón</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Người dân và du khách đăng ký online qua đường link:&nbsp;<a href=\"https://forms.gle/ehK5Dq7FEfyvmdyd9\" style=\"color:#0563c1; text-decoration:underline\" target=\"_blank\">https://forms.gle/ehK5Dq7FEfyvmdyd9</a>&nbsp;hoặc quét mã QR được cung cấp.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/M%C3%A3.png/8b58362b-0433-d644-1e89-ea95cb532ff7?t=1761277265875\" style=\"height: 300px; width: 300px;\" /><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Khi đủ số lượng đăng ký, cổng đăng ký sẽ tự động đóng. Danh sách hành khách được chốt vào 22h hàng ngày và thông báo trực tiếp trên đường link đăng ký.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>* Lưu ý:</b></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ưu tiên đăng ký online, chỉ nhận đăng ký trực tiếp khi còn chỗ trống.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mỗi lần đăng ký chỉ áp dụng cho 01 người (bao gồm cả trẻ em đi kèm).</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nếu không thể tham gia sau khi đăng ký, vui lòng nhắn tin báo hủy đến hotline 0985 284 920, ghi rõ: Họ tên - Điểm đón - Thời gian - Người đi cùng (nếu có).</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mọi thắc mắc liên hệ hotline 0985 284 920, từ 5h00 đến 23h00 hàng ngày.</span></span></span></p>', '24/10/2025 13:30', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-to-chuc-xe-mien-phi-ua-on-nhan-dan-va-du-khach-tham-quan-hoi-cho-mua-thu-tu-ngay-26-10-4-11-2025-28202001', '', 'Dương Thuỷ', 11039, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (22, '27896501', 'Phó Chủ tịch UBND tỉnh Đào Quang Khải tiếp và làm việc với Hiệp hội Du lịch Việt Nam', 'Phó Chủ tịch UBND tỉnh Đào Quang Khải tiếp và làm việc với Hiệp hội Du lịch Việt Nam', '/documents/37632/18152201/HHDL+1.jpg/2de85117-59b4-39ce-283a-2574bd00303c?t=1761216398641', '<p>(BNP) - Chiều 23/10, đồng chí Đào Quang Khải, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh Bắc Ninh tiếp và làm việc với Đoàn công tác Hiệp hội Du lịch Việt Nam do&nbsp;Chủ tịch Hiệp hội&nbsp;Vũ Thế Bình làm trưởng đoàn về khảo sát thực tế Khu du lịch tâm linh - sinh thái Tây Yên Tử (xã...', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/HHDL+1.jpg/2de85117-59b4-39ce-283a-2574bd00303c?t=1761216398641\" style=\"height: 478px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh buổi tiếp và làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, Chủ tịch Hiệp hội Du lịch Việt Nam Vũ Thế Bình cho biết, chương trình khảo sát nằm trong chuỗi hoạt động phối hợp giữa Hiệp hội và Chương trình Phát triển Liên Hợp Quốc (UNDP), nhằm thúc đẩy mô hình du lịch xanh, phát triển sản phẩm du lịch bền vững, gắn với bảo tồn giá trị văn hóa và thiên nhiên của địa phương. Theo Chủ tịch Hiệp hội, Khu du lịch tâm linh - sinh thái Tây Yên Tử không chỉ là điểm đến tâm linh nổi bật mà còn là khu vực có tiềm năng lớn phát triển các loại hình du lịch sinh thái, cộng đồng và nông nghiệp xanh - phù hợp với xu hướng phát triển du lịch bền vững mà Việt Nam đang hướng tới.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Hiệp hội Du lịch Việt Nam đánh giá cao nỗ lực của tỉnh Bắc Ninh trong quy hoạch, đầu tư hạ tầng du lịch tại khu vực Tây Yên Tử, hình thành tuyến du lịch “Hành trình về miền Trúc Lâm”, tái hiện hành trình hoằng dương Phật pháp của Phật hoàng Trần Nhân Tông. Tuyến du lịch này, nếu được đầu tư đồng bộ về hạ tầng, dịch vụ và truyền thông, sẽ trở thành sản phẩm đặc trưng vùng, thu hút đông đảo du khách trong nước và quốc tế.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Hiệp hội Du lịch Việt Nam Vũ Thế Bình cũng trao đổi một số định hướng phát triển thương mại, dịch vụ và du lịch của tỉnh Bắc Ninh. Theo đó, tỉnh cần tập trung tăng tỷ trọng thương mại - dịch vụ, phát triển các loại hình đô thị kết hợp du lịch, khai thác thế mạnh ẩm thực và sản phẩm văn hóa truyền thống. Đồng thời, cần quan tâm xây dựng sản phẩm du lịch xanh, phát huy vai trò cộng đồng địa phương, hướng tới công nhận khu sinh quyển, góp phần nâng cao nhận thức và gìn giữ giá trị văn hóa bản địa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi làm việc, Phó Chủ tịch UBND tỉnh Đào Quang Khải khẳng định, Bắc Ninh luôn quan tâm phát triển du lịch theo hướng xanh - bền vững - có trách nhiệm với môi trường, gắn với bảo tồn các giá trị văn hóa, lịch sử vùng đất Tây Yên Tử. Tỉnh đã tập trung đầu tư hạ tầng, cảnh quan và kết nối giao thông thuận lợi, tạo nền tảng cho việc hình thành Khu du lịch xanh Tây Yên Tử - điểm nhấn quan trọng trong chiến lược phát triển du lịch của địa phương.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh mong muốn, thông qua chuyến khảo sát lần này, Hiệp hội Du lịch Việt Nam sẽ hỗ trợ Bắc Ninh trong công tác quảng bá, xúc tiến, giới thiệu sản phẩm du lịch mới; qua đó thu hút thêm nhiều doanh nghiệp lữ hành và du khách đến với Tây Yên Tử.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng tại buổi làm việc, Phó Chủ tịch UBND tỉnh Đào Quang Khải thông tin thêm về các mục tiêu và dự án trọng điểm trong lĩnh vực môi trường của tỉnh. Bắc Ninh đã cơ bản xử lý các điểm nóng ô nhiễm làng nghề, hướng đến mục tiêu môi trường sống an toàn, bền vững cho thế hệ tương lai.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện tỉnh có 4 nhà máy đốt rác phát điện, sử dụng công nghệ hiện đại, công suất cao, đảm bảo xử lý toàn bộ lượng rác thải của tỉnh vào năm 2027. Các nhà máy được đầu tư theo hình thức xã hội hóa, có sự tham gia của doanh nghiệp trong và ngoài nước, góp phần đưa Bắc Ninh trở thành địa phương đi đầu trong ứng dụng công nghệ xử lý rác tiên tiến, thân thiện với môi trường.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh Bắc Ninh khẳng định luôn ưu tiên, đầu tư phát triển du lịch bền vững gắn với bảo vệ môi trường và bảo tồn giá trị văn hóa, qua đó đưa du lịch trở thành ngành kinh tế quan trọng, xây dựng Bắc Ninh trở thành điểm đến hấp dẫn của du khách trong nước và quốc tế.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"font-size:14pt\"><span style=\"line-height:normal\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></p>', '23/10/2025 17:35', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-ao-quang-khai-tiep-va-lam-viec-voi-hiep-hoi-du-lich-viet-nam-27896501', '', 'Dương Thuỷ', 594, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (23, '27033903', 'Giải Cầu lông quốc tế Felet Vietnam International Series năm 2025 diễn ra tại Bắc...', 'Giải Cầu lông quốc tế Felet Vietnam International Series năm 2025 diễn ra tại Bắc Ninh từ ngày 28/10 - 02/11/2025', '/documents/37632/18152201/z7144997552335_3e7eef478751324bfe69de592efd52e8.jpg/de22c61b-8c13-4cef-2f12-01d9d0a830cb?t=1761141512550', '<p>Ngày 22/10, tại Sở Văn hóa, Thể thao và Du lịch, Ban Tổ chức địa phương họp bàn về công tác chuẩn bị tổ chức giải Cầu lông quốc tế Felet Vietnam International Series năm 2025 sắp diễn ra tại Bắc Ninh.</p>', '<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Dự họp có đại diện lãnh đạo các Sở: Văn hóa, Thể thao và Du lịch, Giáo dục và Đào tạo, Khoa học và Công nghệ, Y tế; Công an tỉnh, Công ty Điện lực, Báo và Phát TTH tỉnh, UBND phường Bắc Giang.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/18152201/z7144997552335_3e7eef478751324bfe69de592efd52e8.jpg/de22c61b-8c13-4cef-2f12-01d9d0a830cb?t=1761141512550\" style=\"height: 540px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh cuộc họp</span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Tại cuộc họp, lãnh đạo Sở Văn hóa, Thể thao và Du lịch (cơ quan Thường trực Ban Tổ chức) thông tin tóm tắt về công tác triển khai&nbsp;chuẩn bị cho Giải Cầu lông quốc tế <span style=\"letter-spacing:-.3pt\">Felet Vietnam International </span>Series <span style=\"letter-spacing:-.3pt\">năm </span>2025. Sở đã chủ động báo cáo, xin ý kiến UBND tỉnh về công tác tổ chức giải; phối hợp với các sở, ngành, đơn vị liên quan tham mưu xây dựng Kế hoạch triển khai thực hiện; Quyết định thành lập Ban Tổ chức cấp tỉnh để tổ chức giải.&nbsp;Đồng thời chủ động phối hợp Liên đoàn Cầu lông Việt Nam thống nhất các nội dung; tiến hành kiểm tra, rà soát toàn bộ cơ sở vật chất hiện có tại Nhà Thi đấu thể thao tỉnh, Nhà tập luyện và Thi đấu thể dục thể thao tỉnh; bố trí đủ cơ sở vật chất,&nbsp;các điều kiện liên quan để tổ chức giải đấu như: Chuẩn bị 4 sân thi đấu (có thảm viền, ghế trọng tài, thước đo lưới, cây lau sàn, báo tỷ số…); chuẩn bị máy phát điện dự phòng, điều hòa nhiệt độ; bố trí bàn, ghế, nước uống, điều hòa tại các phòng chức năng...&nbsp;</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Từ ngày 28/10 - 02/11/2025, Liên đoàn Cầu lông Việt Nam phối hợp với Sở Văn hóa, Thể thao và Du lịch Bắc Ninh tổ chức Giải Cầu lông quốc tế <span style=\"letter-spacing:-.3pt\">Felet Vietnam International </span>Series <span style=\"letter-spacing:-.3pt\">năm </span>2025 tại Nhà Thi đấu thể thao tỉnh Bắc Ninh (khu đô thị phía Nam, phường Bắc Giang). Các đoàn vận động viên sẽ tập luyện tại Nhà tập luyện và Thi đấu thể dục thể thao tỉnh, ăn nghỉ tại Khách sạn Mường Thanh.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Dự kiến có hơn 300 thành viên tham dự, trong đó có 18 quốc gia đăng ký tham gia thi đấu với tổng số 260 vận động viên, huấn luyện viên, quan chức kỹ thuật quốc tế, trọng tài Việt Nam, Ban Tổ chức trung ương, nhân viên kỹ thuật... Đây là giải đấu mạnh, quy tụ những vận động viên hàng đầu, hứa hẹn mang đến nhiều trận đấu hay, kịch tính và hấp dẫn./.</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"></span></span></span></p>\n\n<p align=\"center\" style=\"margin-top:8px; margin-bottom:8px; text-align:center\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><b><i></i></b></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify; text-indent:36.0pt\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px\"><span style=\"font-size:14pt\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></p>', '22/10/2025 20:57', 'https://bacninh.gov.vn/news/-/details/37632/giai-cau-long-quoc-te-felet-vietnam-international-series-nam-2025-dien-ra-tai-bac-ninh-tu-ngay-28-10-02-11-2025-27033903', '', 'Hà Phương', 1591, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (24, '26318252', 'Khai mạc Liên hoan Chèo toàn quốc năm 2025', 'Khai mạc Liên hoan Chèo toàn quốc năm 2025', '/documents/37632/18152201/KhaimacCheo+4.jpg/a816e98e-5022-2bab-6ff5-03b002a303d8?t=1760977815112', '<p>(BNP) - Tối 20/10, tại Trung tâm Văn hóa - Triển lãm tỉnh Bắc Ninh, Bộ Văn hóa, Thể thao và Du lịch phối hợp với UBND tỉnh Bắc Ninh tổ chức khai mạc Liên hoan Chèo toàn quốc năm 2025 với sự tham gia của 12 đoàn nghệ thuật Chèo chuyên nghiệp đến từ nhiều tỉnh, thành phố trên cả nước.</p>', '<p><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+4.jpg/a816e98e-5022-2bab-6ff5-03b002a303d8?t=1760977815112\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ VH,TT&amp;DL Tạ Quang Đông (ảnh phải), Chủ tịch UBND tỉnh Bắc Ninh Vương Quốc Tuấn (thứ 5 từ trái qua) tặng hoa Hội đồng Nghệ thuật.&nbsp;</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự lễ khai mạc có đồng chí Tạ Quang Đông, Thứ trưởng Bộ Văn hóa, Thể thao và Du lịch, Trưởng Ban Chỉ đạo Liên hoan; Nghệ sĩ Nhân dân Nguyễn Xuân Bắc, Cục trưởng Cục Nghệ thuật Biểu diễn, Thành viên Ban Chỉ đạo, Trưởng Ban Tổ chức Liên hoan Chèo toàn quốc năm 2025; đồng chí Lê Trọng Nin, Phó Vụ trưởng Vụ Văn hóa - Văn nghệ, Ban Tuyên giáo và Dân vận Trung ương; Nghệ sĩ Nhân dân Trịnh Thúy Mùi, Chủ tịch Hội Nghệ sĩ Sân khấu Việt Nam; Nghệ sĩ Nhân dân Giang Mạnh Hà, Phó Chủ tịch Hội Nghệ sĩ Sân khấu Việt Nam, thành viên Ban Chỉ đạo Liên hoan; đồng chí Đặng Trần Cường, Cục trưởng Cục Điện ảnh, Văn hóa, Thể thao và Du lịch (Bộ VHTT&amp;DL).</span></span></span><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+0.jpg/575cf18a-6421-606c-9870-07384d1e0a10?t=1760977520201\" style=\"height: 507px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"line-height:1.3;\">Hàng đầu: Chủ tịch UBND tỉnh Bắc Ninh&nbsp;<span style=\"line-height:1.3;\">Vương Quốc Tuấn (thứ 2 từ trái qua),&nbsp;</span><span style=\"line-height:1.3;\">Thứ trưởng Bộ Văn hóa, Thể thao và Du lịch<span style=\"line-height:1.3;\">Tạ Quang Đông (ảnh trái),&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"line-height:1.3;\">Nghệ sĩ Nhân dân Nguyễn Xuân Bắc (ảnh phải) cùng c</span></span></span></span></span></span>ác đại biểu dự&nbsp;Liên hoan Chèo toàn quốc năm 2025.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về phía tỉnh Bắc Ninh có các đồng chí: Vương Quốc Tuấn, Ủy viên dự khuyết Ban Chấp hành Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh Bắc Ninh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; Nguyễn Văn Linh, nguyên Phó Bí thư Tỉnh uỷ Bắc Giang, Chủ tịch UBND tỉnh Bắc Giang; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy: Trần Thị Hằng, Phó Chủ tịch Thường trực HĐND tỉnh; Lâm Thị Hương Thành, Phó Chủ tịch HĐND tỉnh; Nguyễn Đình Lợi, Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy; <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lê Xuân Lợi, Phó Chủ tịch UBND tỉnh;&nbsp;</span></span></span>Tạ Đăng Đoan, Bí thư Đảng uỷ phường Kinh Bắc; cùng đại diện lãnh đạo các sở, ban, ngành, đoàn thể của tỉnh.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+00.jpg/d0c8723a-99b8-b163-96f3-7ad4983f097f?t=1760977557856\" style=\"height: 611px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ phải qua: Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyễn Việt Oanh;</span></span></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">&nbsp;Phó Chủ tịch Thường trực HĐND tỉnh&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trần Thị Hằng</span></span></span></span></span></span></span>; Phó Chủ tịch HĐND tỉnh&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lâm Thị Hương Thành</span></span></span></span></span></span></span>; <span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"> Phó Chủ tịch UBND tỉnh</span></span></span></span> <span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lê Xuân Lợi;&nbsp;</span></span></span></span></span></span></span></span></span></span></span>Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy&nbsp;<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nguyễn Đình Lợi và c</span></span></span></span></span></span></span></span></span></span></span>ác đại biểu dự&nbsp;Liên hoan Chèo toàn quốc năm 2025.</span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan còn có sự tham dự của đại diện lãnh đạo các Cục, Vụ thuộc Bộ VHTT&amp;DL; lãnh đạo các Sở VHTT&amp;DL các tỉnh, thành phố; các nghệ sĩ, diễn viên của 12 đoàn nghệ thuật Chèo chuyên nghiệp trong cả nước; cùng đông đảo khán giả yêu nghệ thuật Chèo.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình được truyền hình trực tiếp trên sóng Báo và Phát thanh truyền hình Bắc Ninh, đồng thời được tiếp sóng bởi các cơ quan Báo và Phát thanh truyền hình của 18 tỉnh, thành phố trong cả nước, giúp lan tỏa không khí của Liên hoan rộng khắp, đến với đông đảo khán giả yêu nghệ thuật Chèo.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+1.jpg/85609320-d772-1dc7-86bb-28b660ec56cf?t=1760977582774\" style=\"height: 648px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Tạ Quang Đông p<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">hát biểu khai mạc Liên hoan.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu khai mạc, Thứ trưởng <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ VHTT&amp;DL&nbsp;</span></span></span>Tạ Quang Đông khẳng định, Liên hoan Chèo toàn quốc là sự kiện nghệ thuật chuyên nghiệp quan trọng, góp phần giữ gìn và phát huy giá trị của nghệ thuật Chèo - loại hình sân khấu truyền thống độc đáo của dân tộc. Đồng thời ghi nhận sự chuẩn bị chu đáo của các đơn vị nghệ thuật và sự phối hợp tích cực, hiệu quả của UBND tỉnh Bắc Ninh - địa phương đăng cai tổ chức.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span>Thứ trưởng <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ VHTT&amp;DL&nbsp;</span></span></span></span></span></span>nhấn mạnh, việc sắp xếp, kiện toàn hệ thống các đơn vị nghệ thuật công lập là bước đi cần thiết nhằm xây dựng nền nghệ thuật chuyên nghiệp, tinh gọn, hiệu quả và phát triển bền vững. Đảng và Nhà nước luôn coi bảo tồn, phát huy giá trị văn hóa truyền thống - trong đó có nghệ thuật Chèo - là trách nhiệm và sứ mệnh trong xây dựng nền văn hóa Việt Nam tiên tiến, đậm đà bản sắc dân tộc.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, Bộ Chính trị và Chính phủ đang giao Bộ VH,TT&amp;DL chủ trì xây dựng Nghị quyết chuyên đề về chấn hưng và phát triển văn hóa Việt Nam trong thời kỳ mới, thể hiện sự quan tâm sâu sắc của Đảng, Nhà nước đối với lĩnh vực văn hóa - coi văn hóa là nền tảng tinh thần và động lực phát triển đất nước.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+2.jpg/632060db-9ec8-491c-47d6-8a3a94d04111?t=1760977641487\" style=\"height: 638px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi p<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">hát biểu chào mừng Liên hoan.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu chào mừng Liên hoan, Phó Chủ tịch UBND tỉnh Lê Xuân Lợi bày tỏ niềm vinh dự, tự hào khi Bắc Ninh được lựa chọn đăng cai tổ chức sự kiện quy mô quốc gia này. Đồng chí nhấn mạnh, Liên hoan Chèo toàn quốc năm 2025 là ngày hội lớn của sân khấu Chèo cả nước, là dịp để các nghệ sĩ giao lưu, học hỏi, trao đổi kinh nghiệm, đồng thời mang đến cho nhân dân cơ hội thưởng thức những tác phẩm đặc sắc, góp phần gìn giữ và phát huy giá trị nghệ thuật Chèo truyền thống.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh cũng giới thiệu về Bắc Ninh - vùng đất “địa linh nhân kiệt”, giàu truyền thống văn hiến, nơi khởi nguồn của dân ca Quan họ và chiếu chèo xứ Bắc - một trong “tứ chiếu chèo” nổi tiếng của Việt Nam. Bắc Ninh luôn quan tâm công tác bảo tồn, phát triển Chèo thông qua việc tổ chức hội thi, liên hoan, hội thảo; mở lớp bồi dưỡng nghệ nhân; đưa nghệ thuật Chèo vào trường học và khôi phục các làng Chèo cổ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí khẳng định, việc tổ chức Liên hoan tại Bắc Ninh thể hiện sự quan tâm của Đảng, Nhà nước và Bộ VH,TT&amp;DL đối với công tác bảo tồn nghệ thuật truyền thống; đồng thời là nguồn động viên to lớn cho các nghệ sĩ và công chúng yêu Chèo.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+3.jpg/133278d0-8dcd-62b8-a2d9-df2c94865b65?t=1760977674066\" style=\"height: 532px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghệ sĩ Nhân dân Nguyễn Xuân Bắc,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giám đốc Sở VH,TT&amp;DL</span></span></span></span>&nbsp;tỉnh Bắc Ninh&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bùi Thị Thu Thủy&nbsp;</span></span></span></span></span></span>tặng hoa cho các đoàn nghệ thuật.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại lễ khai mạc, Ban Tổ chức đã tặng hoa cho các đoàn nghệ thuật và Hội đồng Nghệ thuật tham gia Liên hoan. Các đoàn nghệ thuật cũng ủng hộ 210 triệu đồng hỗ trợ đồng bào bị ảnh hưởng bởi bão lũ tại Bắc Ninh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan Chèo toàn quốc là hoạt động nghệ thuật quy mô quốc gia, được tổ chức 3 năm một lần nhằm đánh giá, tổng kết chất lượng sáng tạo, dàn dựng và biểu diễn của các đơn vị nghệ thuật chèo trên toàn quốc. Đây cũng là dịp tôn vinh các tập thể, cá nhân có nhiều đóng góp trong công tác bảo tồn và phát huy giá trị nghệ thuật Chèo - loại hình sân khấu dân tộc đặc sắc, đậm đà bản sắc văn hóa Việt Nam. </span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+5.jpg/8051670d-e5c4-0d47-9cc6-2c6c37725565?t=1760977845408\" style=\"height: 659px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giám đốc Sở VH,TT&amp;DL</span></span></span></span>&nbsp;tỉnh Bắc Ninh&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bùi Thị Thu Thủy tiếp nhận ủng hộ của các đoàn nghệ thuật tham gia Liên hoan.</span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan năm nay quy tụ gần 900 nghệ sĩ, diễn viên và nhạc công, với 21 vở diễn được đầu tư công phu, phản ánh sâu sắc đời sống xã hội, ca ngợi quê hương, đất nước và con người Việt Nam. Công tác chấm giải được thực hiện theo Quy chế của Cục Nghệ thuật Biểu diễn, với các hạng mục Huy chương Vàng, Huy chương Bạc và Giải Xuất sắc cho tập thể, cá nhân đạt thành tích cao.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+6.jpg/451444bd-6605-3b49-0f88-cfcb0361f4d6?t=1760977884019\" style=\"height: 549px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vở diễn “Thiên mệnh” do Nhà hát Chèo Bắc Ninh biểu diễn tại Lễ khai mạc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan Chèo toàn quốc năm 2025 diễn ra từ ngày 20/10 đến 02/11/2025 tại tỉnh Bắc Ninh - vùng đất giàu truyền thống văn hóa và nghệ thuật dân gian, góp phần quảng bá hình ảnh địa phương, thúc đẩy giao lưu văn hóa, du lịch và lan tỏa giá trị nghệ thuật Chèo đến đông đảo công chúng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay sau lễ khai mạc, khán giả đã được thưởng thức vở diễn “Thiên mệnh” do Nhà hát Chèo Bắc Ninh biểu diễn.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/KhaimacCheo+000.jpg/be329009-cc4b-5430-e307-472e00b684c6?t=1760977454211\" style=\"height: 496px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình nghệ thuật chào mừng Liên hoan Chèo toàn quốc năm 2025.</span></span></span></span></p>', '20/10/2025 23:07', 'https://bacninh.gov.vn/news/-/details/37632/khai-mac-lien-hoan-cheo-toan-quoc-nam-2025-26318252', '', 'Dương Thuỷ', 738, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (25, '25904813', 'Liên hoan Chèo toàn quốc năm 2025 diễn ra từ ngày 20/10 - 02/11/2025 tại Trung tâm...', 'Liên hoan Chèo toàn quốc năm 2025 diễn ra từ ngày 20/10 - 02/11/2025 tại Trung tâm Văn hóa - Triển lãm tỉnh Bắc Ninh', '/documents/37632/18152201/LienhoanCheo.jpg/473aa723-5266-64c6-1aa2-c1c75e2f3c85?t=1760685215903', '<p>(BNP) - Thừa lệnh Chủ tịch UBND tỉnh, Phó Chánh Văn phòng UBND tỉnh Phạm Văn Đà vừa ký ban hành Công văn số 3700/UBND-KGVX về việc huy động khán giả xem, động viên, cổ vũ Liên hoan Chèo toàn quốc năm 2025 tại tỉnh Bắc Ninh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/18152201/LienhoanCheo.jpg/473aa723-5266-64c6-1aa2-c1c75e2f3c85?t=1760685215903\" style=\"height: 524px; width: 900px;\" /></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên hoan Chèo toàn quốc - 2025 do Bộ Văn hóa, Thể thao và Du lịch phối hợp với UBND tỉnh Bắc Ninh tổ chức, diễn ra từ ngày 20/10 đến ngày 02/11/2025 tại Trung tâm Văn hóa - Triển lãm tỉnh (đường Nguyễn Thị Định, phường Bắc Giang, thành phố Bắc Ninh). Đây là hoạt động văn hóa có ý nghĩa quan trọng, góp phần tôn vinh nghệ thuật Chèo, quảng bá hình ảnh vùng đất, văn hóa, con người Bắc Ninh - Kinh Bắc đến bạn bè trong và ngoài nước, lan tỏa giá trị di sản văn hóa dân tộc tới đông đảo Nhân dân, nhất là thế hệ trẻ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để Liên hoan Chèo toàn quốc - 2025 tại tỉnh Bắc Ninh thành công tốt đẹp, để lại ấn tượng sâu sắc đối với các đơn vị nghệ thuật tham dự, Chủ tịch UBND tỉnh đề nghị các sở, ban, ngành, đoàn thể và địa phương căn cứ chức năng, nhiệm vụ huy động cán bộ, công chức, viên chức, đoàn viên, hội viên, học sinh và Nhân dân tham dự, cổ vũ các đoàn nghệ thuật tham gia Liên hoan.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Giáo dục và Đào tạo chỉ đạo các trường THPT, THCS, Trung tâm Giáo dục thường xuyên, Trường Phổ thông Dân tộc nội trú tỉnh tổ chức cho học sinh, giáo viên tham dự, xem biểu diễn, coi đây là hoạt động ngoại khóa có ý nghĩa giáo dục. Riêng lễ khai mạc, huy động từ 200 học sinh, giáo viên trở lên tham dự, đảm bảo an toàn và không ảnh hưởng đến hoạt động dạy học chính khóa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên đoàn Lao động tỉnh, Hội Nông dân, Hội Liên hiệp Phụ nữ, Tỉnh Đoàn, Hội Cựu Chiến binh, Hội Người cao tuổi, Hội Cựu Thanh niên xung phong và Hội Văn học Nghệ thuật tỉnh huy động mỗi buổi biểu diễn ít nhất 50 hội viên, đoàn viên tham dự, góp phần tạo không khí sôi nổi, lan tỏa phong trào văn hóa, văn nghệ trong cộng đồng.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND phường Bắc Giang và phường Tân Tiến đẩy mạnh tuyên truyền, huy động cán bộ và Nhân dân tham dự, đảm bảo mỗi buổi diễn có từ 150 người trở lên đến xem biểu diễn tại Trung tâm Văn hóa - Triển lãm tỉnh. Các xã, phường khác trên địa bàn tỉnh thông tin rộng rãi để Nhân dân biết, tham dự cổ vũ Liên hoan.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chi tiết lịch diễn của các đơn vị tham gia Liên hoan Chèo toàn quốc - 2025:&nbsp;</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/Lich+dien+1.jpg/b025ec0a-7e04-5f36-eb46-97667f54b9bd?t=1760685673097\" style=\"height: 613px; width: 900px;\" /><br />\n<img src=\"/documents/37632/18152201/Lich-2.jpg/fb84a554-1293-4cf5-4229-f989b0287c93?t=1760685784072\" style=\"height: 613px; width: 900px;\" /><br />\n&nbsp;</p>', '17/10/2025 12:28', 'https://bacninh.gov.vn/news/-/details/37632/lien-hoan-cheo-toan-quoc-nam-2025-dien-ra-tu-ngay-20-10-02-11-2025-tai-trung-tam-van-hoa-trien-lam-tinh-bac-ninh-25904813', '', 'Dương Thuỷ', 374, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (26, '25344832', 'Hợp nhất Liên đoàn Quần vợt tỉnh Bắc Giang và tỉnh Bắc Ninh (cũ) thành Liên đoàn Quần...', 'Hợp nhất Liên đoàn Quần vợt tỉnh Bắc Giang và tỉnh Bắc Ninh (cũ) thành Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh', '/documents/37632/18152201/20230910113755-1bch.jpg/fd7e639e-85b7-1833-1024-a5ab0d21feea?t=1760343970355', '<p>(BNP) - Chủ tịch UBND tỉnh Bắc Ninh Vương Quốc Tuấn vừa ký ban hành Quyết định số 1150/QĐ-UBND về việc cho phép hợp nhất Liên đoàn Quần vợt tỉnh Bắc Giang và Liên đoàn Quần vợt tỉnh Bắc Ninh (cũ) thành Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/18152201/20230910113755-1bch.jpg/fd7e639e-85b7-1833-1024-a5ab0d21feea?t=1760343970355\" style=\"height: 507px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh hoạ (Nguồn BaoBacninh).</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh là tổ chức xã hội - nghề nghiệp, hoạt động theo Điều lệ được cấp có thẩm quyền phê duyệt, tuân thủ pháp luật và chịu sự quản lý của Sở Văn hóa, Thể thao và Du lịch cùng các cơ quan liên quan. Liên đoàn có tư cách pháp nhân, con dấu và tài khoản riêng, thực hiện các quy định về trụ sở, kinh phí, phương tiện hoạt động theo pháp luật hiện hành.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh yêu cầu, trong vòng 30 ngày kể từ ngày Quyết định có hiệu lực, hai Liên đoàn Quần vợt của Bắc Giang và Bắc Ninh (cũ) phải chuyển giao toàn bộ tài sản, tài chính, nhân sự, tổ chức và các quyền, nghĩa vụ liên quan cho Liên đoàn mới; đồng thời chấm dứt hoạt động và nộp lại con dấu cho cơ quan có thẩm quyền.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Liên đoàn Quần vợt - Pickleball tỉnh Bắc Ninh được nhất trí về nhân sự Ban Chấp hành, Chủ tịch và các Phó Chủ tịch theo Đề án hợp nhất. Trong 60 ngày làm việc, Liên đoàn có trách nhiệm tổ chức Đại hội và báo cáo kết quả lên UBND tỉnh theo quy định.</span></span></span></p>', '13/10/2025 18:30', 'https://bacninh.gov.vn/news/-/details/37632/hop-nhat-lien-oan-quan-vot-tinh-bac-giang-va-tinh-bac-ninh-cu-thanh-lien-oan-quan-vot-pickleball-tinh-bac-ninh-25344832', '', 'Dương Thuỷ', 975, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (27, '25291381', 'Khởi động dự án trùng tu, tôn tạo di tích lịch sử quốc gia chùa Hàm Long', 'Khởi động dự án trùng tu, tôn tạo di tích lịch sử quốc gia chùa Hàm Long', '/documents/37632/18152201/23+copy.jpg/4b675ddf-a248-9986-8f6d-3e66c88b0c28?t=1760319584694', '<p>(BNP) - Ngày 12/10, tại chùa Hàm Long, UBND phường Nam Sơn tổ chức Lễ khởi động dự án trùng tu, tôn tạo di tích lịch sử quốc gia chùa Hàm Long.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/23+copy.jpg/4b675ddf-a248-9986-8f6d-3e66c88b0c28?t=1760319584694\" style=\"height: 540px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh tặng hoa chúc mừng.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Dự buổi lễ có đồng chí Vương Quốc Tuấn, Ủy viên dự khuyết Ban Chấp hành Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy: Trần Thị Hằng, Phó Chủ tịch Thường trực HĐND tỉnh; Lê Xuân Lợi, Phó Chủ tịch UBND tỉnh; Nguyễn Đình Lợi, Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy; Đại lão Hòa Thượng Thích Thanh Dũng, Phó Pháp chủ, Chánh Thư ký Hội đồng Chứng minh Trung ương Giáo hội Phật giáo Việt Nam, Phó Trưởng ban trị sự kiêm Trưởng Ban pháp chế Giáo hội Phật giáo tỉnh Bắc Ninh, Viện chủ Tổ đình chùa Hàm Long; các đồng chí lãnh đạo HĐND, UBND, Đoàn Đại biểu Quốc hội tỉnh; lãnh đạo các sở, ban, ngành, địa phương trong tỉnh cùng đông đảo tăng ni, phật tử và Nhân dân địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Chùa Hàm Long là một trong những ngôi cổ tự nổi tiếng của xứ Kinh Bắc, được khởi dựng từ thế kỷ XII thời nhà Lý, tọa lạc dưới chân núi Dạm thuộc thôn Thái Bảo, phường Nam Sơn. Chùa được xếp hạng di tích lịch sử văn hóa cấp quốc gia năm 1988, gắn liền với sinh hoạt văn hóa, tín ngưỡng và đời sống tinh thần của Nhân dân Bắc Ninh. Hiện nay, di tích còn lưu trữ nhiều di vật, cổ vật quý như: Tượng Phật cổ và 14 tháp mộ cổ từ thời Trần, Hậu Lê, Nguyễn; các bức hoành phi, câu đối, cửa võng cổ...</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/20.jpg/04ead231-4599-4751-4e56-89e0cc631b8e?t=1760319612701\" style=\"height: 476px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đại biểu thực hiện nghi lễ khởi động dự án.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Những năm qua, di tích chùa Hàm Long được chính quyền các cấp, Nhân dân địa phương và phật tử gần xa quan tâm, trùng tu, tôn tạo nhiều hạng mục quan trọng. Tuy nhiên, trải qua thời gian, nhiều hạng mục chính của chùa đã xuống cấp nghiêm trọng như: Tòa Tam bảo, nhà thờ Tổ và hai dãy hành lang... Một số cấu kiện gỗ, mái ngói, nền móng bị mối mọt, lún nứt; cảnh quan chưa được quy hoạch đồng bộ; khuôn viên chùa chật hẹp, không đáp ứng nhu cầu sinh hoạt tín ngưỡng của tăng ni, phật tử và du khách.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/21.jpg/aa077144-c5a0-6343-05ea-8bc0e5feada1?t=1760319634802\" style=\"height: 540px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Vương Quốc Tuấn và đại diện Ban Trị sự Giáo hội Phật giáo Việt Nam tỉnh Bắc Ninh thực hiện nghi lễ phạt mộc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Dự án tu bổ, tôn tạo chùa Hàm Long được triển khai với quy mô diện tích 1,62 ha gồm các hạng mục: Tam bảo, hai dãy hành lang, Nhà thờ tổ, Tam quan nội, Tháp sư trụ trì, Miếu Địa tạng, Nhà bia, khu vệ sinh công cộng và hệ thống sân vườn nội bộ. Trong đó, các hạng mục kiến trúc chính được phục dựng theo phong cách truyền thống, sử dụng vật liệu tự nhiên như gỗ lim, đá xanh, ngói mũi hài, gạch Bát Tràng phục chế, bảo đảm tính nguyên gốc và giá trị thẩm mỹ cổ truyền. Ngoài ra, hạng mục Miếu Địa tạng được xây mới nhằm đáp ứng nhu cầu tín ngưỡng của đông đảo phật tử gần xa đến cầu siêu, cầu an... Thời gian thi công dự án từ năm 2025 đến 2027 bằng nguồn vốn xã hội hóa.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/18152201/22.jpg/9d0bc2e9-907f-5362-b564-d6898dc0ea97?t=1760319658113\" style=\"height: 540px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phối cảnh tổng thể dự án tu bổ, tôn tạo di tích Quốc gia chùa Hàm Long. </span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Việc trùng tu, tôn tạo chùa Hàm Long không chỉ mang ý nghĩa bảo tồn giá trị lịch sử, kiến trúc, nghệ thuật của di tích mà còn tạo điểm nhấn trong chuỗi không gian văn hóa lịch sử vùng núi Dạm. Công trình sau khi hoàn thành sẽ trở thành điểm đến hành hương, tham quan và chiêm bái của du khách trong và ngoài nước, đồng thời là nơi giáo dục truyền thống, hướng con người đến các giá trị chân, thiện, mỹ./.</span></span></span></p>', '13/10/2025 08:39', 'https://bacninh.gov.vn/news/-/details/37632/khoi-ong-du-an-trung-tu-ton-tao-di-tich-lich-su-quoc-gia-chua-ham-long-25291381', '', 'Báo và Phát thanh, Truyền hình Bắc Ninh', 632, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (28, '23520206', 'Phó Chủ tịch UBND tỉnh Bắc Ninh Ngô Tân Phượng dự kỷ niệm Ngày Quốc khánh Hàn Quốc...', 'Phó Chủ tịch UBND tỉnh Bắc Ninh Ngô Tân Phượng dự kỷ niệm Ngày Quốc khánh Hàn Quốc tại Hà Nội', '/documents/37632/210849/z7075687939647_3288e01f220469f9fc6e9024fded1002.jpg/b18e9d27-212a-b4c8-e433-47f3f83c3924?t=1759454882452', '<p>(BNP) – Nhận lời mời của Đại sứ quán Hàn Quốc tại Việt Nam, tối ngày 02/10, Đoàn đại biểu tỉnh Bắc Ninh do đồng chí Ngô Tân Phượng, Phó Chủ tịch UBND tỉnh làm trưởng đoàn đến tham dự Lễ kỷ niệm Ngày Quốc khánh của Hàn Quốc tại Hà Nội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687885951_34b82551b435785017d18fe2f5c38ac2.jpg/38448c45-3fa0-1cab-7e35-1144182d5a98?t=1759454767718\" style=\"width: 900px; height: 719px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Ngô Tân Phượng (ảnh phải) chúc mừng kỷ niệm Ngày Quốc khánh Hàn Quốc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự có <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Bộ Tài chính Nguyễn Văn Thắng;&nbsp;</span></span></span>Thượng tướng Phùng Sĩ Tấn, Phó Tổng Tham mưu trưởng Quân đội nhân dân Việt Nam; cùng đại diện lãnh đạo các Bộ, ban, ngành Trung ương và địa phương của Việt Nam, cùng đại diện đoàn ngoại giao nước ngoài tại Việt Nam.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687939647_3288e01f220469f9fc6e9024fded1002.jpg/b18e9d27-212a-b4c8-e433-47f3f83c3924?t=1759454882452\" style=\"width: 900px; height: 583px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Choi Young Sam và các khách mời tại buổi tiệc. Phó Chủ tịch UBND tỉnh Ngô Tân Phượng (thứ 4 từ phải qua) tham dự chiêu đãi.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại tiệc chiêu đãi, Đại sứ Hàn Quốc Choi Young Sam bày tỏ vui mừng trước sự phát triển của mối quan hệ Hàn Quốc - Việt Nam trong những năm qua, nhất là sau khi hai nước nâng cấp quan hệ lên Đối tác chiến lược toàn diện năm 2022; đồng thời cho rằng tiềm năng hợp tác giữa hai nước vẫn rộng mở.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại sứ Choi Young Sam bày tỏ tin tưởng, với sự nhất trí của lãnh đạo cấp cao hai nước, Việt Nam và Hàn Quốc sẽ tiếp tục hợp tác, hướng tới một bước tiến mới trong quan hệ song phương.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687829774_cacf592754d1095564ee675616058d24.jpg/38b00ed0-cde4-7fa5-cc0b-cc75b14b8e76?t=1759455073865\" style=\"width: 900px; height: 824px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Ngô Tân Phượng tặng hoa chúc mừng Đại sứ Hàn Quốc Choi Young Sam.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ trưởng Bộ Tài chính Nguyễn Văn Thắng gửi lời chúc mừng nồng nhiệt tới Chính phủ và nhân dân Hàn Quốc nhân Ngày Quốc khánh; khẳng định Việt Nam nhất quán coi trọng quan hệ với Hàn Quốc, sẵn sàng hợp tác chặt chẽ với Hàn Quốc, nhằm thúc đẩy mối quan hệ Đối tác chiến lược toàn diện phát triển thực chất, hiệu quả và lâu dài, phù hợp với nguyện vọng của nhân dân hai nước, góp phần duy trì môi trường hòa bình, ổn định, hợp tác và phát triển ở khu vực cũng như trên thế giới.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/210849/z7075687801100_82a0f7ad0df95f05f7f21c8e921b0258.jpg/e12ecd8b-046b-ede4-bc2a-c04705779acf?t=1759455174255\" style=\"width: 900px; height: 598px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu tham dự Lễ kỷ niệm Ngày Quốc khánh Hàn Quốc.&nbsp;</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\">&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Luỹ kế đến tháng 9/2025, Hàn Quốc có 1.139 dự án đầu tư tại tỉnh Bắc Ninh, tổng vốn đầu tư sau điều chỉnh đạt khoảng 20 tỷ USD (chiếm khoảng 43.5% tổng vốn đầu tư nước ngoài trên địa bàn tỉnh), là quốc gia có số vốn đầu tư cao nhất vào tỉnh. Các doanh nghiệp Hàn Quốc hoạt động hiệu quả và ổn định, tạo việc làm cho khoảng 90.000 lao động và thu hút nhiều lao động đến từ các tỉnh thành khác, đóng góp tích cực đối với phát triển kinh tế - xã hội của tỉnh. Các doanh nghiệp điển hình của Hàn Quốc đầu tư vào Bắc Ninh thời gian qua đều có sự đóng góp vào sự phát triển của địa phương như: Tổ hợp Samsung, Intops, Hanwha Techwin, Amkor, Hana Micron, Hyosung... Ngoài ra,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"background:white\"><span style=\"color:#001d35\">Bắc Ninh không chỉ là quê hương của vua Lý, n<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">ơi đây còn là điểm đến của Lý Xương Căn (hậu duệ đời thứ 31 của Lý Thái Tổ) và nhiều hậu duệ khác từ Hàn Quốc về Việt Nam tìm lại nguồn cội&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"background:white\"><span style=\"color:#001d35\">để tưởng nhớ tổ tiên.</span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></p>', '03/10/2025 08:24', 'https://bacninh.gov.vn/news/-/details/37632/pho-chu-tich-ubnd-tinh-bac-ninh-ngo-tan-phuong-du-ky-niem-ngay-quoc-khanh-han-quoc-tai-ha-noi-23520206', '', 'BNP', 381, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (29, '23104204', 'Gặp mặt Phóng viên thông tin về Đại hội Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ...', 'Gặp mặt Phóng viên thông tin về Đại hội Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030', '/documents/37632/200616/IMG_7426.jpg/fce97ccb-b58c-1ac1-b727-e620ad88c9dd?t=1759147822954', '<p>(BNP) - Chiều 29/9, ngay sau phiên trù bị Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030 đã diễn ra Chương trình gặp mặt Phóng viên thông tin về Đại hội. Các đồng chí: Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh; Nguyễn Đình Lợi, Ủy viên Ban...', '<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><em><img src=\"/documents/37632/200616/IMG_7426.jpg/fce97ccb-b58c-1ac1-b727-e620ad88c9dd?t=1759147822954\" style=\"height: 600px; width: 900px;\" /></em></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh (ảnh giữa); Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy <span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nguyễn Đình Lợi&nbsp;</span></span></span></span>(ảnh phải); Giám đốc Sở Văn hóa, Thể thao và Du lịch&nbsp;<span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bùi Thị Thu Thủy</span></span></span></span>.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tham dự có đai diện lãnh đạo, phóng viên các cơ quan báo chí - truyền thông của Trung ương và tỉnh đưa tin về Đại hội. </span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tại buổi gặp mặt, Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn thông tin đến các Phóng viên về kết quả phiên thứ Nhất, Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030 diễn ra vào chiều 29/9 tại Trung tâm Hội nghị tỉnh. Tại phiên thứ Nhất, Đại hội đã đã hoàn thành toàn bộ nội dung đề ra trong không khí đoàn kết, dân chủ, trách nhiệm. Đại hội đã bầu Đoàn Chủ tịch, Đoàn Thư ký, Ban Thẩm tra tư cách đại biểu; thông qua Chương trình, Nội quy, Quy chế làm việc và thành lập 08 Tổ thảo luận. Các Tổ đã làm việc sôi nổi, thẳng thắn, trách nhiệm, đóng góp nhiều ý kiến tâm huyết vào các dự thảo Văn kiện của Trung ương và của tỉnh.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border: none; text-align: center;\"><img src=\"/documents/37632/200616/IMG_7401.jpg/cf725c39-7a58-ed8e-81c5-d6c3e088f4de?t=1759147871714\" style=\"height: 606px; width: 900px;\" /></p>\n\n<p style=\"border: none; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn thông tin kết quả phiên thứ Nhất, Đại hội đại biểu Đảng bộ tỉnh Bắc Ninh lần thứ I.</span></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Sáng ngày 30/9/2025, Đại hội tiến hành phiên khai mạc. Đồng chí Nguyễn Duy Ngọc, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ nhiệm UBKT Trung ương sẽ thay mặt Bộ Chính trị, Ban Bí thư dự và phát biểu chỉ đạo Đại hội.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Đại hội cũng sẽ thực hiện một số nội dung trọng tâm: Thông qua và thảo luận về các văn kiện: Báo cáo chính trị; Báo cáo kiểm điểm sự lãnh đạo, chỉ đạo của Ban Chấp hành Đảng bộ tỉnh nhiệm kỳ 2020 - 2025; Chương trình hành động thực hiện Nghị quyết Đại hội; công bố và trao các Quyết định chỉ định Ban Chấp hành, Ban Thường vụ, Bí thư, Phó Bí thư Tỉnh ủy; Ủy ban Kiểm tra, Chủ nhiệm, Phó Chủ nhiệm Ủy ban Kiểm tra Tỉnh ủy, nhiệm kỳ 2025 - 2030; Quyết định chỉ định đại biểu dự Đại hội đại biểu toàn quốc lần thứ XIV của Đảng; thông qua dự thảo Nghị quyết Đại hội và bế mạc Đại hội vào chiều ngày 30/9/2025.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span></p>\n\n<p style=\"border: none; text-align: center;\"><img src=\"/documents/37632/200616/IMG_7455.jpg/4b29b0a4-6bb3-2012-ac92-8e885510f34a?t=1759147915543\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"border: none; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy Nguyễn Đình Lợi phát biểu tại buổi gặp mặt.</span></span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Để góp phần vào thành công chung của Đại hội, Phó Chủ tịch Thường trực UBND tỉnh đề nghị các phóng viên báo chí của Trung ương, tỉnh tập trung tuyên truyền làm nổi bật ý nghĩa lịch sử và tầm quan trọng của Đại hội lần thứ I - dấu mốc mở ra khát vọng phát triển mới, thể hiện tầm nhìn chiến lược của Ban Chấp hành Đảng bộ tỉnh và niềm tin, kỳ vọng của Nhân dân vào tương lai Bắc Ninh.</span></span></span></p>\n\n<p style=\"border:none; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tuyên truyền làm nổi bật tầm vóc, phương châm, mục tiêu của Đại hội “Đoàn kết - Dân chủ - Kỷ cương - Sáng tạo - Phát triển”; nhấn mạnh quyết tâm chính trị, thông qua chủ đề Đại hội: “Xây dựng Đảng và hệ thống chính trị tỉnh - gọn - mạnh, hoạt động hiệu năng, hiệu lực, hiệu quả; phát huy tiềm năng, lợi thế, bản sắc văn hóa Kinh Bắc; đoàn kết, tự lực, tự cường, tự tin xây dựng tỉnh Bắc Ninh phát triển nhanh, toàn diện, bền vững, trở thành thành phố trực thuộc Trung ương trước năm 2030”.</span></span></span></p>\n\n<p style=\"border: none; text-align: center;\"><img src=\"/documents/37632/200616/IMG_7429.jpg/868ee109-88eb-c3e6-3ebf-23e93bd713ce?t=1759147946073\" style=\"height: 603px; width: 900px;\" /></p>\n\n<p style=\"border: none; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhà báo Phùng Đô, Báo Xây dựng.</span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cùng với đó, phản ánh đậm nét quá trình tổ chức Đại hội, sự thành công của Đại hội và nhất là phản ánh tình cảm, sự tin tưởng, khí thế phấn khởi, quyết tâm của cán bộ, đảng viên, các tầng lớp nhân dân hướng về Đại hội, ra sức thi đua lập thành tích chào mừng thành công của Đại hội và sớm đưa Nghị quyết của Đại hội vào cuộc sống. Đồng thời, tích cực, chủ động đấu tranh, phản bác thông tin sai lệch, xuyên tạc, góp phần củng cố niềm tin của nhân dân với Đảng, Nhà nước và sự lãnh đạo của Ban Chấp hành Đảng bộ tỉnh khóa I, nhiệm kỳ 2025-2030.</span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tại buổi gặp mặt, các phóng viên báo chí của Trung ương, tỉnh đánh giá cao công tác chuẩn bị, tổ chức Đại hội của Ban Chấp hành Đảng bộ tỉnh, nhất là tạo điều kiện thuận lợi nhất để các phóng viên tác nghiệp, đưa tin về Đại hội. Đồng thời, đề nghị tỉnh làm rõ <span style=\"background:white\"><span style=\"color:#333333\">hơn định hướng lớn đưa ra của tỉnh Bắc Ninh về 3 khâu đột phá trong nhiệm kỳ 2025 - 2030, đặc biệt là đột phá về hạ tầng giao thông và công nghệ thông tin; phát triển hạ tầng tại các khu công nghiệp nhằm giảm thiểu tình trạng ùng tắc giao thông hiện nay; quy hoạch, phát triển đường sắt của tỉnh…</span></span></span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/200616/IMG_7441.jpg/049365f0-64ca-0485-9bf5-bfcba9d8c8e0?t=1759147993378\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"background:white\">Đại diện </span>lãnh đạo, phóng viên các cơ quan báo chí - truyền thông của Trung ương và tỉnh tham dự buổi gặp mặt.<span style=\"background:white\"></span></span></span></span></span></p>\n\n<p style=\"text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"><span style=\"background:white\"><span style=\"color:#333333\">Các ý kiến của phóng viên được đồng chí </span></span>Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh và đồng chí Nguyễn Đình Lợi, Trưởng Ban Tuyên giáo và Dân vận Tỉnh ủy<span style=\"background:white\"><span style=\"color:#333333\"> trực tiếp trao đổi, làm rõ.</span></span> Đồng thời, mong muốn tiếp tục nhận được sự phối hợp, đồng hành của các cơ quan báo chí, phóng viên, nhà báo trong và ngoài tỉnh, góp phần lan tỏa tinh thần Đại hội, đưa Nghị quyết vào cuộc sống, xây dựng tỉnh Bắc Ninh ngày càng phát triển giàu đẹp, văn minh.</span></span></span></p>', '29/09/2025 19:08', 'https://bacninh.gov.vn/news/-/details/37632/gap-mat-phong-vien-thong-tin-ve-ai-hoi-ang-bo-tinh-bac-ninh-lan-thu-i-nhiem-ky-2025-2030-23104204', '', 'Hữu Thắng', 795, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (30, '22833504', 'Bắc Ninh FC khởi tranh với Khatoco Khánh Hòa tại Giải bóng đá hạng Nhất Quốc gia 2025...', 'Bắc Ninh FC khởi tranh với Khatoco Khánh Hòa tại Giải bóng đá hạng Nhất Quốc gia 2025 - 2026 trên Sân vận động Việt Yên (Bắc Ninh)', '/documents/37632/18152201/b7.jpg/77e15f4c-e61c-d3f8-a3bf-73572aecbfb3?t=1758972160429', '<p>(BNP) - Chiều 27/9, tại Sân vận động Việt Yên, Câu lạc bộ bóng đá Bắc Ninh (Bắc Ninh FC) đã có trận đấu với Câu lạc bộ Khatoco Khánh Hòa. Đây là trận đấu tại vòng 2, trong khuôn khổ Giải bóng đá hạng Nhất Quốc gia 2025 - 2026.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/10721208/b2+%283%29.jpg/4f4002ef-c837-047b-9611-677fa34e3858?t=1758971495784\" style=\"height: 600px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các cầu thủ&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bắc Ninh FC ra sân thi đấu.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Dự và cổ vũ&nbsp;trận đấu có đồng chí&nbsp;Vương Quốc Tuấn, Ủy viên dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; các đồng chí Ủy&nbsp;viên Ban Thường vụ Tỉnh ủy: Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh; Phạm Văn Thịnh, Phó Chủ tịch UBND tỉnh, Trưởng Đoàn đại biểu Quốc hội tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Giải bóng đá hạng Nhất Quốc gia 2025 - 2026 do Liên đoàn Bóng đá Việt Nam tổ chức, chính thức khởi tranh từ ngày 19/9, với sự tham gia của 12 đội bóng chuyên nghiệp trong cả nước; thi đấu theo thể thức vòng tròn 2 lượt tính điểm sân nhà -&nbsp;sân khách. Giải đấu có tổng cộng 22 vòng với 132 trận đấu, thi đấu theo thể thức đấu bốc thăm chia cặp đấu loại trực tiếp từng vòng.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b7.jpg/77e15f4c-e61c-d3f8-a3bf-73572aecbfb3?t=1758972160429\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Các cầu thủ Bắc Ninh FC thực hiện nghi thức chào cờ, hát Quốc ca trước khi trận đấu diễn ra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Câu lạc bộ bóng đá Bắc Ninh (Bắc Ninh FC) lần đầu tiên góp mặt tại giải song đã nhận được sự quan tâm, cổ vũ rất lớn từ người hâm mộ. Bắc Ninh FC sẽ có 11 trận trên sân vận động Việt Yên (phường Việt Yên). </span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b3.jpg/78d9433b-c537-c985-74a4-9d94f736c55a?t=1758971767454\" style=\"height: 561px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Trọng tài điều khiển trận đấu.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Trận đấu tại vòng 2 giữa Bắc Ninh FC với Khatoco Khánh Hòa trong chiều nay, được đánh giá là trận đấu đầy kịch tính, chất lượng, thể hiện sự chuyên nghiệp của các cầu thủ, đáp ứng người hâm mộ bóng đá tỉnh Bắc Ninh. </span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Kết quả giành chiến <span style=\"color:#000000;\">thắng 1-0</span><span style=\"color:#000000;\">,</span><span style=\"color:red\"> </span>các cầu Bắc Ninh FC đã thể hiện thi đấu hết mình trước đội <span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Khatoco Khánh Hòa</span></span></span></span>; là cơ hội, động lực để&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Bắc Ninh FC</span></span></span></span> hướng tới những chiến thắng tiếp theo và mục tiêu thăng hạng lên hạng V- League trong một ngày không xa.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b5.jpg/823504ec-d1a4-4c17-8bc4-ae7bbfa099bc?t=1758971839612\" style=\"height: 571px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Sự&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">chuyên nghiệp của các cầu thủ, đáp ứng người hâm mộ bóng đá tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Được biết, Sân vận động Việt Yên là công trình thể thao mới, tổng diện tích hơn 8.000m² với 7.500 chỗ ngồi, sân có mặt cỏ tự nhiên, hạ tầng đồng bộ, hiện đại. Sở Văn hóa, Thể thao và Du lịch phối hợp với UBND phường Việt Yên, Công ty Cổ phần bóng đá Bắc Ninh rà soát toàn bộ cơ sở vật chất, trang thiết bị, kỹ thuật phục vụ chuyên môn, phòng chức năng của sân bảo đảm đáp ứng tốt các nhiệm vụ tổ chức giải. Để bảo đảm an ninh, an toàn cho các trận đấu, Công an tỉnh đã lên phương án cụ thể, tính toán chi tiết cho từng tình huống có thể phát sinh, bố trí lực lượng sẵn sàng thực hiện nhiệm vụ. </span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b1.jpg/36a4d65b-b6a5-638e-ea1b-d703b98bb243?t=1758971962481\" style=\"height: 559px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Người hâm mộ xếp hàng tại quầy soát vé để xem trận đấu.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:11pt\"><span style=\"font-size:14.0pt\">Các trận đấu của Bắc Ninh FC trên Sân vận động Việt Yên sẽ mở cửa tự do phục vụ khán giả, người hâm mộ; hứa hẹn sẽ là ngày hội bóng đá chung của người hâm mộ thể thao trong tỉnh. Qua đó, tiếp tục quảng bá hình ảnh tỉnh Bắc Ninh năng động, giàu bản sắc tới bạn bè trong nước và quốc tế.</span></span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/18152201/b6.jpg/52e84e57-e367-af2b-fd34-a0881ac0d443?t=1758972078456\" style=\"height: 593px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Cổ động viên trên Sân vận động Việt Yên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '27/09/2025 18:10', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-fc-khoi-tranh-voi-khatoco-khanh-hoa-tai-giai-bong-a-hang-nhat-quoc-gia-2025-2026-tren-san-van-ong-viet-yen-bac-ninh-22833504', '', 'Nguyễn Miền', 1708, 'Văn hóa', 5, '', '38762', '{}', '2025-10-31 08:44:59.000000', 5, 11);
INSERT INTO `sync_articles` VALUES (31, '29966801', 'Bắc Ninh triển khai kế hoạch thực hiện giải pháp IMO cho sản xuất vải thiều', 'Bắc Ninh triển khai kế hoạch thực hiện giải pháp IMO cho sản xuất vải thiều', '/documents/37632/23288501/3+%281%29.jpg/22374664-3ff2-d51b-5575-5f40ec51a675?t=1761895050100', '<p>(BNP) - Sở Khoa học và Công nghệ Bắc Ninh vừa ban hành Kế hoạch triển khai thí điểm mô hình thực hiện giải pháp IMO cho sản xuất vải thiều tại tỉnh.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288501/3+%281%29.jpg/22374664-3ff2-d51b-5575-5f40ec51a675?t=1761895050100\" style=\"height: 521px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Ảnh minh họa.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch triển khai thực hiện giải pháp IMO cho sản xuất vải thiều nhằm nâng cao năng lực cho cán bộ kỹ thuật và nông dân về quy trình ứng dụng chế phẩm sinh học IMO trong sản xuất vải thiều tại tỉnh Bắc Ninh. Qua đó, xây dựng mô hình thí điểm áp dụng công nghệ sinh học IMO trong canh tác vải thiều, giảm thiểu việc sử dụng thuốc bảo vệ thực vật hóa học, góp phần nâng cao chất lượng và giá trị sản phẩm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đơn vị chủ trì lựa chọn diện tích điểm với quy mô 5 ha tại 03 hộ dân trên địa bàn xã Lục Ngạn và 02 hộ xã Phúc Hòa (1ha/hộ dân). Các hộ dân được lựa chọn phải đáp ứng yêu cầu có diện tích sản xuất vải thiều từ 01ha trở lên, cây vải thiều đang thời kỳ kinh doanh. Có nhu cầu áp dụng công nghệ vi sinh trong sản xuất vải thiều, theo hướng hạn chế sử dụng phân bón hóa học và thuốc bảo vệ thực vật. Cam kết thực hiện đúng theo quy trình hướng dẫn của chuyên gia.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những diện tích chọn điểm áp dụng công nghệ sinh học IMO được sử dụng men vi sinh giống công nghiệp đa chủng, men vi sinh y tế, men rượu để lên men các nguyên liệu tạo men vi sinh IMO. Kiểm tra tính an toàn của các loại men vi sinh IMO sản xuất được và phân tích chất lượng sản phẩm. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Khoa học và Công nghệ triển khai dùng thử sản phẩm men IMO trên các giai đoạn của chu kỳ sản xuất cây vải thiều từ tháng 11/2025 - tháng 6/2025. Đồng thời theo dõi, đánh giá hiệu quả kỹ thuật, kinh tế, mức độ kiểm soát sâu bệnh và phản hồi từ nông dân.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quá trình triển khai mô hình được ghi chép, tổng hợp, đánh giá hiệu quả, làm cơ sở khoa học để UBND tỉnh xem xét, chỉ đạo nhân rộng việc ứng dụng công nghệ sinh học trong sản xuất nông nghiệp theo hướng an toàn và bền vững./.</span></span></span></p>', '31/10/2025 14:16', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-ke-hoach-thuc-hien-giai-phap-imo-cho-san-xuat-vai-thieu-29966801', '', 'Nguyễn Miền', 15, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (32, '29928666', 'Hoạt động nổi bật của lãnh đạo tỉnh từ ngày 25 - 31/10/2025', 'Hoạt động nổi bật của lãnh đạo tỉnh từ ngày 25 - 31/10/2025', '/documents/37632/23555751/ghep-anh-31-10.png/72353e82-cc2a-fd04-1274-42f7a359b046?t=1761893921635', '<p>(BNP) - Đoàn công tác Quân khu 1 thăm, chúc mừng Đảng bộ tỉnh Bắc Ninh; Chủ tịch UBND tỉnh đến thăm, làm việc tại một số doanh nghiệp chế biến nông sản trên địa bàn tỉnh; Trường Đại học Limoges (Cộng hòa Pháp) làm việc tại Bắc Ninh… là những hoạt động nổi bật của lãnh đạo tỉnh từ ngày 25 -...', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200616/IMG_9135+%281%29.jpg/7625a32a-3d16-3260-c2a0-e15f43e6e79d?t=1761654608975\" style=\"width: 900px; height: 590px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều tối ngày 28/10, tại trụ sở Tỉnh ủy, đồng chí Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy có buổi tiếp và làm việc với Đoàn công tác do Thiếu tướng Trương Mạnh Dũng, Tư lệnh Quân khu 1 dẫn đầu về thăm, chúc mừng Đảng bộ tỉnh Bắc Ninh vừa tổ chức thành công Đại hội đại biểu Đảng bộ tỉnh lần thứ I, nhiệm kỳ 2025 - 2030. Tham gia Đoàn công tác có các đồng chí: Thiếu tướng La Công Phương, Chính ủy Quân khu 1; Thiếu tướng Trần Xuân Mạnh, Phó Tư lệnh, Tham mưu trưởng Quân khu 1. Tỉnh Bắc Ninh có các đồng chí: Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Vương Quốc Tuấn, Ủy viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí trong Ban Thường vụ Tỉnh ủy, Thường trực HĐND, UBND, Ủy ban MTTQ, Đoàn ĐBQH tỉnh; lãnh đạo Bộ CHQS tỉnh, Văn phòng Tỉnh ủy, Văn phòng UBND tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288878/mt10.png/c3c7ed53-aa2f-2c29-fa01-e083eeca2535?t=1761718990364\" style=\"width: 900px; height: 551px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong 2 ngày (28 và 29/10), tại Trung tâm Hội nghị tỉnh, Ủy ban MTTQ Việt Nam tỉnh Bắc Ninh long trọng tổ chức Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030. Tham dự Đại hội, đại biểu Trung ương có đồng chí Đỗ Văn Chiến, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam; lãnh đạo Ủy ban Trung ương MTTQ Việt Nam. Đại biểu tỉnh Bắc Ninh có các đồng chí: Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Vương Quốc Tuấn, Ủy viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy; Thường trực HĐND, lãnh đạo UBND, lãnh đạo Đoàn ĐBQH tỉnh; các đồng chí nguyên Thường trực Tỉnh ủy, UBND tỉnh qua các thời kỳ; Mẹ Việt Nam Anh hùng, Anh hùng Lực lượng vũ trang Nhân dân, Anh hùng Lao động; các đồng chí nguyên lãnh đạo Ủy ban MTTQ tỉnh qua các thời kỳ, lãnh đạo Ủy ban MTTQ một số tỉnh lân cận; lãnh đạo các sở, ban, ngành, địa phương của tỉnh cùng 358 đại biểu chính thức đại diện cho các tầng lớp Nhân dân, các dân tộc, tôn giáo, lực lượng vũ trang, người con Bắc Ninh trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288501/3.jpg/4c1a0ff3-2df2-6976-d801-ddf3567323c6?t=1761824962421\" style=\"width: 900px; height: 561px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 30/10, đồng chí Vương Quốc Tuấn, Uỷ viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đến thăm, làm việc tại một số doanh nghiệp chế biến nông sản trên địa bàn tỉnh. Cùng đi có đại diện lãnh đạo các sở, ngành, cơ quan của tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288823/30-11.png/e2862176-c9f0-8191-b2df-b9b0a89b3766?t=1761814487649\" style=\"width: 900px; height: 632px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 30/10, đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Giáo sư Veronique Blanquet, Phó Hiệu trưởng Trường Đại học Limoges (Cộng hòa Pháp) đến trao đổi thúc đẩy hợp tác trong các lĩnh vực giáo dục, công nghệ cao, bán dẫn, đổi mới sáng tạo.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288823/2+%286%29.jpg/92ec3c8e-decf-3b02-953f-978d7d89930a?t=1761821866420\" style=\"width: 900px; height: 548px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chiều 30/10, tại Bệnh viện Đa khoa Bắc Ninh số 1, Sở Y tế Bắc Ninh phối hợp với Tập đoàn Vingroup và các đơn vị liên quan tổ chức công bố Quyết định thành lập Trung tâm Cấp cứu và vận chuyển 115; bàn giao xe cấp cứu và trang thiết bị y tế do Tập đoàn Vingroup tài trợ. Dự buổi lễ có các đồng chí: Giáo sư, Tiến sỹ Trần Văn Thuấn, Thứ trưởng Bộ Y tế; Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; đại diện Tập đoàn Vingroup, Quỹ Thiện Tâm cùng lãnh đạo một số sở, ngành, đơn vị liên quan.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/200628/DoanGSBoTuphap+6.jpg/279786d8-b558-8a83-8aff-da6ccf33f959?t=1761800489504\" style=\"width: 900px; height: 556px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 30/10, tại Bắc Ninh, Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính (TTHC) dựa trên dữ liệu do Thứ trưởng Bộ Tư pháp Nguyễn Thanh Tịnh làm Trưởng đoàn, đã có buổi làm việc với UBND tỉnh Bắc Ninh nhằm nắm bắt, tháo gỡ những khó khăn, vướng mắc phát sinh trong quá trình cắt giảm, đơn giản hóa TTHC dựa trên dữ liệu. Tham gia Đoàn công tác có đại diện lãnh đạo Trung tâm Dữ liệu quốc gia, Bộ Công an; Trung tâm Dữ liệu quốc gia về dân cư; Cục Cảnh sát quản lý hành chính về trật tự xã hội (Bộ Công an); cùng đại diện Văn phòng Chính phủ, Bộ Nội vụ, Bộ Tư pháp. Tiếp và làm việc với Đoàn có đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh, cùng đại diện lãnh đạo các sở, ban, ngành của tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://bacninh.gov.vn/documents/37632/23288878/26-3.png/9fb3140a-47c9-3801-fb38-cb1f3bb5bdb3?t=1761453274827\" style=\"width: 900px; height: 593px;\" /><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sáng 26/10, Hội Chiến sỹ cách mạng bị địch bắt tù đày tỉnh Bắc Ninh tổ chức Đại hội lần thứ I, nhiệm kỳ 2025 - 2030. Dự và chúc mừng Đại hội có các đồng chí: Trương Mỹ Hoa, nguyên Bí thư Trung ương Đảng, nguyên Phó Chủ tịch nước; Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; lãnh đạo Ban Liên lạc toàn quốc chiến sĩ cách mạng Việt Nam bị địch bắt tù đày và Hội Chiến sỹ cách mạng bị địch bắt tù đày một số tỉnh bạn; lãnh đạo một số sở, ban, ngành của tỉnh cùng 160 đại biểu đại diện cho hơn 300 hội viên trong toàn tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Arial&quot;,sans-serif\"></span></span></span></span></span></span></p>', '31/10/2025 14:00', 'https://bacninh.gov.vn/news/-/details/37632/hoat-ong-noi-bat-cua-lanh-ao-tinh-tu-ngay-25-31-10-2025-29928666', '', 'BNP', 34, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (33, '29923930', 'Đẩy nhanh tiến độ thực hiện tuyến đường kết nối Sân bay Gia Bình với thủ đô Hà Nội', 'Đẩy nhanh tiến độ thực hiện tuyến đường kết nối Sân bay Gia Bình với thủ đô Hà Nội', '/documents/37632/23288823/31-1.png/e9016b20-7127-678f-50d3-2b4d5e32cf49?t=1761890702608', '<p>(BNP) - Tại Văn bản số 4237/UBND-KTN, Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh chỉ đạo đẩy nhanh tiến độ thực hiện tuyến đường kết nối Cảng hàng không quốc tế Gia Bình với thủ đô Hà Nội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/31-1.png/e9016b20-7127-678f-50d3-2b4d5e32cf49?t=1761890702608\" style=\"height: 600px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Theo đó, Sở Xây dựng tăng cường công tác phối hợp, bám sát cơ quan chuyên môn của Bộ Xây dựng và Viện Kỹ thuật Công trình Đặc biệt - Học viện Kỹ thuật Quân sự sớm có ý kiến tham gia. Đồng thời, đôn đốc nhà đầu tư hoàn thiện hồ sơ, khẩn trương hoàn thành thẩm định Báo cáo nghiên cứu khả thi xong trước ngày 05/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Sở Tài chính tiếp tục đôn đốc, phối hợp với các cơ quan, địa phương hoàn thiện thẩm định của Hội đồng thẩm định, tham mưu phê duyệt dự án, phê duyệt nhà đầu tư xong trước ngày 10/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ban Quản lý dự án Giao thông và Nông nghiệp tỉnh Bắc Ninh số 2 phối hợp chặt chẽ với nhà đầu tư hoàn thành cắm mốc, bàn giao phạm vi giải phóng mặt bằng (đợt 1) đối với khu vực có đất ở, nhà ở, xong chậm nhất trong ngày 01/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">UBND xã, phường ban hành thông báo thu hồi đất (đợt 1) đối với toàn bộ khu vực thu hồi có đất ở xong trước ngày 04/11/2025, gửi Chủ tịch UBND tỉnh. Thông báo thu hồi đất (đợt 1) cho phép có sai sót về diện tích, quy chủ và sẽ được tiếp tục hiệu chỉnh trong thời hạn 30 ngày. Chủ tịch UBND xã, phường chịu trách nhiệm về các hậu quả xảy ra nếu chậm ban hành thông báo thu hồi đất (đợt 1).</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">UBND xã, phường phối hợp, cung cấp các tài liệu, số liệu có liên quan đến công tác lập dự án (như bản đồ địa chính, thống kê sử dụng đất…) cho Liên danh Công ty Cổ phần Đầu tư và Xây dựng giao thông Công Thành - Công ty TNHH Mặt trời Cẩm Phả xong trước ngày 02/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Liên danh Công ty Cổ phần Đầu tư và Xây dựng giao thông Công Thành - Công ty TNHH Mặt trời Cẩm Phả chủ động phối hợp với các cơ quan chuyên môn của tỉnh và các địa phương hoàn thiện, bổ sung đầy đủ hồ sơ trình thẩm định gửi Sở Xây dựng để tổ chức thẩm định Báo cáo nghiên cứu khả thi theo đúng quy định. Cùng với đó, nghiên cứu, tiếp thu, giải trình và hoàn thiện hồ sơ trên cơ sở các ý kiến góp ý của các thành viên Hội đồng thẩm định và các cơ quan, đơn vị, địa phương liên quan. Phối hợp với Ban Quản lý dự án Giao thông và Nông nghiệp tỉnh Bắc Ninh số 2 hoàn thành cắm mốc phạm vi giải phóng mặt bằng xong chậm nhất trong ngày 01/11/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các sở ngành, địa phương căn cứ chức năng, nhiệm vụ chủ động phối hợp, triển khai thực hiện các công việc có liên quan đảm bảo hoàn thành phê duyệt dự án trước 10/11/2025; hoàn thành giải phóng mặt bằng đất nông nghiệp xong trước ngày 21/12/2025./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '31/10/2025 13:04', 'https://bacninh.gov.vn/news/-/details/37632/-ay-nhanh-tien-o-thuc-hien-tuyen-uong-ket-noi-san-bay-gia-binh-voi-thu-o-ha-noi-29923930', '', 'Linh Ngọc', 157, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (34, '29892703', 'Bắc Ninh phê duyệt Chiến lược Chuyển đổi số giai đoạn 2025-2030', 'Bắc Ninh phê duyệt Chiến lược Chuyển đổi số giai đoạn 2025-2030', '/documents/37632/23288823/1+%284%29.jpg/5718592d-462b-b237-a8dc-ed82f2dc660f?t=1761880734965', '<p>(BNP) - Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh vừa ký Quyết định số 1305/QĐ-UBND phê duyệt Chiến lược Chuyển đổi số tỉnh Bắc Ninh giai đoạn 2025-2030.</p>', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288823/1+%284%29.jpg/5718592d-462b-b237-a8dc-ed82f2dc660f?t=1761880734965\" style=\"height: 519px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Đoàn thanh niên xã Yên Thế tuyên truyền phong trào bình dân học vụ số.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Chiến lược ban hành nhằm mục đích xây dựng và triển khai đồng bộ kiến trúc hệ thống, nền tảng dùng chung trong toàn bộ hệ thống chính trị, xuyên suốt từ Trung ương đến địa phương bảo đảm kết nối, liên thông, chia sẻ dữ liệu thông suốt bảo đảm đồng bộ, thống nhất toàn hệ thống chính trị, thực hiện các mục tiêu của Nghị quyết số 57-NQ/TW của Bộ Chính trị. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Phấn đấu 100% hệ thống công nghệ thông tin (CNTT), nền tảng dùng chung cùng với cơ sở dữ liệu của tỉnh được rà soát, đánh giá, tiếp tục xây dựng, bổ sung và chuẩn hóa toàn diện theo tiêu chuẩn chung, bảo đảm bao quát tất cả các lĩnh vực quản lý nhà nước, khả năng liên thông, kết nối, chia sẻ, tích hợp. Nâng cao chất lượng cung cấp dịch vụ công trực tuyến, phục vụ hiệu quả công tác chỉ đạo, điều hành và cải cách thủ tục hành chính dựa trên dữ liệu, đáp ứng yêu cầu thiết thực của người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Để đạt mục tiêu Chiến lược Chuyển đổi số tỉnh Bắc Ninh giai đoạn 2025-2030, UBND tỉnh tập trung triển khai 4 nhóm nhiệm vụ trọng tâm gồm: Tăng cường sự lãnh đạo, chỉ đạo của các cấp ủy Đảng, Chính quyền nhằm đổi mới tư duy, thống nhất nhận thức, tạo nền tảng chuyển đổi số; phát triển Chính quyền số; phát triển kinh tế số; phát triển xã hội số.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Phó Chủ tịch Thường trực UBND tỉnh giao Sở Khoa học và Công nghệ &nbsp;xây dựng Kế hoạch truyền thông nhằm chuyển đổi nhận thức của các cấp, các ngành, cán bộ, công chức viên chức, người dân và doanh nghiệp về chuyển đổi số gắn với Kế hoạch truyền thông Nghị quyết số 57-NQ-TW.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Các sở, ban, ngành, UBND các xã, phường gắn các mục tiêu, nhiệm vụ về chuyển đổi số lồng ghép vào trong nhiệm vụ phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh của từng ngành, địa phương, đơn vị. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Tạo lập chuyên trang, chuyên mục về chuyển đổi số trên Trang, Cổng Thông tin điện tử thành phần của cơ quan, đơn vị, địa phương. Quán triệt tới từng cán bộ, đảng viên, công chức, viên chức và người lao động về sự cần thiết và tính cấp thiết của chuyển đổi số trong cơ quan, đơn vị, địa phương mình. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">UBND các xã, phường rà soát, kiện toàn Ban chỉ đạo về phát triển khoa học, công nghệ, đổi mới sáng tạo, chuyển đổi số và Đề án 06 của địa phương để lãnh đạo, chỉ đạo công tác triển khai chuyển đổi số. Nghiên cứu xây dựng cơ chế, chính sách của tỉnh và đẩy mạnh phát triển nguồn nhân lực nhằm thúc đẩy quá trình chuyển đổi số. Chủ động liên kết với các cơ sở giáo dục đào tạo, trung tâm nghiên cứu, các đối tác trong và ngoài nước để đào tạo nguồn nhân lực, chuyển giao công nghệ phục vụ quá trình chuyển đổi số.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Chủ động rà soát, đăng ký cán bộ, công chức, viên chức tham dự đầy đủ các chương trình bồi dưỡng, nâng cao kiến thức về CNTT, chuyển đổi số. Ưu tiên bố trí sắp xếp cán bộ chuyên trách, kiêm nhiệm CNTT trong định biên của đơn vị để đảm bảo triển khai các ứng dụng CNTT và thực thi nhiệm vụ chuyển đổi số của cơ quan đạt hiệu quả./.</span></span></span></p>', '31/10/2025 10:10', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-phe-duyet-chien-luoc-chuyen-oi-so-giai-oan-2025-2030-29892703', '', 'Nguyễn Miền', 40, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (35, '29456621', 'Bắc Ninh công bố thành lập Trung tâm Cấp cứu và vận chuyển 115 - Tăng cường năng lực...', 'Bắc Ninh công bố thành lập Trung tâm Cấp cứu và vận chuyển 115 - Tăng cường năng lực cấp cứu ngoại viện', '/documents/37632/23288823/4+%283%29.jpg/bbd705e4-f081-7d89-fc00-f6372a19f8a8?t=1761821992737', '<p>(BNP) – Chiều 30/10, tại Bệnh viện Đa khoa Bắc Ninh số 1, Sở Y tế Bắc Ninh phối hợp với Tập đoàn Vingroup và các đơn vị liên quan tổ chức công bố Quyết định thành lập Trung tâm Cấp cứu và vận chuyển 115; bàn giao xe cấp cứu và trang thiết bị y tế do Tập đoàn Vingroup tài trợ.</p>', '<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/4+%283%29.jpg/bbd705e4-f081-7d89-fc00-f6372a19f8a8?t=1761821992737\" style=\"height: 462px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tập đoàn Vingroup trao biểu trưng tặng 15 xe cấp cứu cho Sở Y tế tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự buổi lễ có các đồng chí: Giáo sư, Tiến sỹ Trần Văn Thuấn, Thứ trưởng Bộ Y tế; Lê Xuân Lợi, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch UBND tỉnh; đại diện Tập đoàn Vingroup, <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quỹ Thiện Tâm cùng&nbsp;</span></span></span>lãnh đạo một số sở, ngành, đơn vị liên quan.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/2+%286%29.jpg/92ec3c8e-decf-3b02-953f-978d7d89930a?t=1761821866420\" style=\"height: 548px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi trao quyết định và chúc mừng Bệnh viện Đa khoa Bắc Ninh số 1.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi lễ, Sở Y tế công bố&nbsp;Quyết định số 373/QĐ-UBND ngày 24/10/2025 của UBND tỉnh Bắc Ninh về việc tổ chức lại Trung tâm Cấp cứu ngoại viện và Khoa Cấp cứu thành Trung tâm Cấp cứu và vận chuyển 115 trực thuộc Bệnh viện Đa khoa Bắc Ninh số 1.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trung tâm Cấp cứu và vận chuyển 115 (gọi tắt là Trung tâm) có chức năng thực hiện toàn diện công tác khám bệnh, chữa bệnh cấp cứu và vận chuyển người bệnh; tổ chức thực hiện nhiệm vụ cấp cứu thường trực 24/7; thực hiện tiếp nhận và phân loại người bệnh, thăm dò chức năng cấp cứu, can thiệp cấp cứu, theo dõi và cấp cứu người bệnh nặng, cách ly, điều trị người bệnh đột quỵ theo quy định; thực hiện nhiệm vụ cấp cứu ngoại viện, vận chuyển người bệnh giữa các tuyến hoặc về gia đình đáp ứng nhu cầu của xã hội và của người dân bằng xe cứu thương chuyên dụng, đảm bảo nhanh chóng, kịp thời, an toàn, hợp lý, hiệu quả, góp phần xây dựng, hoàn thiện mô hình và vận hành hệ thống cấp cứu đồng bộ trên địa bàn tỉnh, nâng cao chất lượng công tác bảo vệ, chăm sóc sức khỏe nhân dân.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/5+%283%29.jpg/d2244b6c-e6ac-89e6-ccae-bebec2ab4454?t=1761822036043\" style=\"height: 558px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Y tế Trần Văn Thuấn tặng hoa chúc mừng Sở Y tế.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi lễ, Thứ trưởng Bộ Y tế Trần Văn Thuấn ghi nhận và đánh giá cao sự chủ động của tỉnh Bắc Ninh trong hiện đại hóa hệ thống y tế, đặc biệt là lĩnh vực cấp cứu ngoại viện – khâu quan trọng trong chăm sóc sức khỏe Nhân dân. Việc thành lập Trung tâm là dấu mốc quan trọng, thể hiện quyết tâm của tỉnh trong triển khai Đề án phát triển hệ thống cấp cứu y tế giai đoạn 2025 – 2030, hướng tới mô hình cấp cứu thông minh, nhân văn và hiện đại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng cho biết, công tác cấp cứu ngoại viện đang nhận được sự quan tâm đặc biệt của Đảng, Chính phủ và Bộ Y tế, với nhiều chính sách, nghị quyết mới được ban hành, tạo hành lang pháp lý cho việc tổ chức và vận hành thống nhất trên toàn quốc. Đồng chí đề nghị tỉnh Bắc Ninh quan tâm chỉ đạo sâu sát 5 định hướng trọng tâm: Hoàn thiện chỉ huy, điều phối liên ngành, tích hợp công nghệ sớm, GPS, bản đồ nguy cơ; chuẩn hóa năng lực tuyến đầu và thời gian phản ứng, xây dựng đội hình \"paramedic\" đạt chuẩn; phát triển truyền thông cộng đồng, huấn luyện sơ cứu đại trà; xây dựng cơ chế tài chính đa nguồn, đảm bảo không ai bị từ chối vì thiếu chi phí vận chuyển và liên kết chặt chẽ với hệ thống cấp cứu quốc gia và trung tâm điều phối cấp cứu thông minh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bộ Y tế cam kết tiếp tục đồng hành cùng Bắc Ninh trên mọi phương diện: kỹ thuật chuyên môn, cơ chế chính sách, điều phối hệ thống, hợp tác quốc tế, đào tạo nhân lực và kết nối tài chính.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/1+%283%29.jpg/e6329f1b-3db0-fe29-0903-9a090f23145d?t=1761822069720\" style=\"height: 638px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch UBND tỉnh Lê Xuân Lợi phát biểu tại buổi lễ.</span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thay mặt lãnh đạo UBND tỉnh, Phó Chủ tịch UBND tỉnh Bắc Ninh Lê Xuân Lợi biểu dương và cảm ơn Tập đoàn Vingroup, Quỹ Thiện Tâm đã tài trợ xe cứu thương, trang thiết bị cấp cứu, kinh phí đào tạo nhân lực cho tỉnh. Việc tiếp nhận xe cứu thương, trang thiết bị góp phần hoàn thiện hệ thống cấp cứu y tế theo hướng chuyên nghiệp, đồng bộ từ tỉnh đến cơ sở; đảm bảo người dân được tiếp cận dịch vụ cấp cứu nhanh nhất, hiệu quả nhất.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Để vận hành Hệ thống cấp cứu ngoại viện hiệu quả, Phó Chủ tịch UBND tỉnh Bắc Ninh đề nghị Sở Y tế khẩn trương đưa Trung tâm trực thuộc Bệnh viện Đa khoa Bắc Ninh số 1 vào hoạt động hiệu quả, an toàn, đúng quy định; bố trí, đào tạo đội ngũ chuyên trách có chuyên môn, trách nhiệm và đạo đức nghề nghiệp. Đồng thời, hướng dẫn các cơ sở y tế trong mạng lưới Hệ thống cấp cứu ngoại viện bảo đảm trực cấp cứu, vận chuyển người bệnh thông suốt, kịp thời, lấy người bệnh làm trung tâm. Sở cũng cần xây dựng quy trình tiếp nhận, xử lý thông tin cấp cứu và kết nối hệ thống xe cứu thương.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trung tâm cần phát huy tinh thần chủ động, kỷ luật, tận tâm; tổ chức tốt công tác thường trực, điều phối, phối hợp chặt chẽ với lực lượng y tế, công an, giao thông, phòng cháy chữa cháy… để bảo đảm cấp cứu nhanh, chính xác, an toàn, phục vụ tốt nhất cho nhân dân trong mọi tình huống.</span></span></span></p>\n\n<p style=\"text-align: center;\"><img src=\"/documents/37632/23288823/6+%282%29.jpg/5ef97eae-b400-4b95-0231-cde6de532b65?t=1761822100907\" style=\"height: 616px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xe cứu thương do Tập đoàn Vingroup tài trợ&nbsp;phục vụ công tác vận chuyển, cấp cứu ngoại viện cho tỉnh Bắc Ninh. </span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi lễ, đại diện Tập đoàn Vingroup và Quỹ Thiện Tâm đã bàn giao 15 xe cứu thương và nhiều trang thiết bị y tế hiện đại phục vụ công tác vận chuyển, cấp cứu ngoại viện cho tỉnh Bắc Ninh. Mỗi xe được trang bị máy thở, máy sốc điện tích hợp monitor, siêu âm xách tay FAST exam, điện tim 12 đạo trình kết nối từ xa, bộ đặt nội khí quản có camera, nẹp cố định chấn thương và đầy đủ dụng cụ hồi sức.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc tài trợ xe cứu thương và trang thiết bị y tế hiện đại cho Bắc Ninh là một phần trong chương trình “Tăng cường năng lực cấp cứu ngoại viện” do Quỹ Thiện Tâm – Tập đoàn Vingroup triển khai tại nhiều địa phương trên cả nước. Mục tiêu của chương trình là hỗ trợ ngành Y tế các tỉnh, thành xây dựng hệ thống cấp cứu đồng bộ, chuyên nghiệp, góp phần giảm tỷ lệ tử vong và di chứng do chậm cấp cứu, đồng thời nâng cao chất lượng chăm sóc sức khỏe ban đầu cho người dân.</span></span></span></p>\n\n<p style=\"margin-bottom:8px; text-align:justify\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:115%\"><span style=\"font-family:Arial,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"text-justify:inter-ideograph\"><span style=\"line-height:115%\"><span style=\"font-family:Arial,sans-serif\"><span lang=\"VI\" style=\"font-size:14.0pt\"><span style=\"line-height:115%\"></span></span></span></span></span></span></p>', '30/10/2025 18:00', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-cong-bo-thanh-lap-trung-tam-cap-cuu-va-van-chuyen-115-tang-cuong-nang-luc-cap-cuu-ngoai-vien-29456621', '', 'Diệu Hoa', 874, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (36, '29533801', 'Hỗ trợ cán bộ chưa có nhà ở, đã có nhà ở nhưng cách xa nơi làm việc mua nhà ở xã hội', 'Hỗ trợ cán bộ chưa có nhà ở, đã có nhà ở nhưng cách xa nơi làm việc mua nhà ở xã hội', '/documents/37632/23288823/30-14.png/0baf16b7-0900-744c-abf9-211e53e50388?t=1761816876014', '<p>(BNP) - Phó Chủ tịch UBND tỉnh Phạm Văn Thịnh vừa ký Văn bản số 4161/UBND-XDCB về việc hỗ trợ cán bộ, công chức, viên chức chưa có nhà ở, đã có nhà ở thuộc sở hữu của mình nhưng cách xa địa điểm làm việc đáp ứng yêu cầu, điều kiện mua nhà ở xã hội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-14.png/0baf16b7-0900-744c-abf9-211e53e50388?t=1761816876014\" style=\"height: 622px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự án nhà ở xã hội Cát Tường Thống Nhất, phường Võ Cường, tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Theo đó, Sở Xây dựng chủ trì, phối hợp với các cơ quan, đơn vị liên quan thông tin về các dự án nhà ở xã hội đủ điều kiện bán/cho thuê/cho thuê mua nhà ở hình thành trong tương lai đến các cơ quan nhà Đảng, Nhà nước đóng trên địa bàn tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hướng dẫn về thành phần hồ sơ đăng ký mua/thuê/thuê mua nhà ở xã hội; tổng hợp danh sách (kèm theo hồ sơ đã được hướng dẫn) về nhu cầu của cán bộ, công chức, viên chức chưa có nhà ở; đã có nhà ở thuộc sở hữu của mình nhưng cách xa địa điểm làm việc. Đồng thời, xác minh việc đáp ứng yêu cầu đối tượng, điều kiện được mua/thuê/thuê mua nhà ở xã hội theo quy định của pháp luật; gửi danh sách đủ điều kiện đến các chủ đầu tư dự án nhà ở xã hội để tổ chức thực hiện việc bán/cho thuê/cho thuê mua nhà ở hình thành trong tương lai theo quy định pháp luật.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thời gian hoàn thành chậm nhất vào ngày 15/11/2025./.</span></span></span></p>', '30/10/2025 16:34', 'https://bacninh.gov.vn/news/-/details/37632/ho-tro-can-bo-chua-co-nha-o-a-co-nha-o-nhung-cach-xa-noi-lam-viec-mua-nha-o-xa-hoi-29533801', '', 'Linh Ngọc', 1199, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (37, '29525512', 'Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Trường Đại...', 'Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Trường Đại học Limoges (Cộng hòa Pháp)', '/documents/37632/23288823/30-10.png/b5cf462c-c30c-a0c7-a43d-60680c0bba58?t=1761814391208', '<p>(BNP) - Chiều 30/10, đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh tiếp và làm việc với Giáo sư Veronique Blanquet, Phó Hiệu trưởng Trường Đại học Limoges (Cộng hòa Pháp) đến trao đổi thúc đẩy hợp tác trong các lĩnh vực giáo dục, công nghệ cao, bán dẫn, đổi...', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-10.png/b5cf462c-c30c-a0c7-a43d-60680c0bba58?t=1761814391208\" style=\"height: 620px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Các đồng chí lãnh đạo tỉnh chụp ảnh lưu niệm với&nbsp;Giáo sư Veronique Blanquet.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Vui mừng chào đón đoàn công tác của Trường Đại học Limoges đến thăm và làm việc tại Bắc Ninh, đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh giới thiệu khái quát tình hình phát triển kinh tế - xã hội của tỉnh, nhất là sau khi sáp nhập 02 tỉnh Bắc Giang - Bắc Ninh (cũ). Với quy mô kinh tế đứng thứ 5 toàn quốc, lợi thế về vị trí địa lý, tiềm năng phát triển, Bắc Ninh được xác định là trung tâm công nghiệp bán dẫn của cả nước. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bắc Ninh hiện có trên 30 khu công nghiệp tập trung đã đi vào hoạt động, thu hút hàng nghìn doanh nghiệp trong và ngoài nước. Tổng vốn đầu tư nước ngoài FDI ở tất cả các ngành nghề trên địa bàn tỉnh hiện đạt khoảng 45 tỷ USD, đứng thứ 2 cả nước. Trong đó, vốn đầu tư của Pháp là hơn 135 triệu USD, tập trung vào lĩnh vực dược phẩm, may mặc…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-11.png/e2862176-c9f0-8191-b2df-b9b0a89b3766?t=1761814487649\" style=\"height: 632px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đồng chí Mai Sơn, Phó Chủ tịch Thường trực UBND tỉnh giới thiệu và tặng tranh dân gian Đông Hồ cho&nbsp;Giáo sư Veronique Blanquet.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Bên cạnh phát triển kinh tế, Bắc Ninh còn là vùng đất có truyền thống khoa bảng, hiếu học; chất lượng giáo dục của tỉnh luôn nằm trong tốp các tỉnh đứng đầu cả nước với nhiều học sinh đạt giải học sinh giỏi quốc gia, quốc tế. Ngoài ra, trên địa bàn tỉnh hiện có 01 trường Đại học; nhiều chi nhánh, cơ sở 2 của các trường Đại học lớn đầu tư tại tỉnh cùng 18 trường Cao đẳng và các trường trung cấp, trung tâm giáo dục nghề nghiệp… mỗi năm đào tạo hàng nghìn sinh viên. Để tạo bước đột phá về chất lượng nguồn lao động của tỉnh, Bắc Ninh đã ban hành nhiều chính sách hỗ trợ cho học sinh, sinh viên, giáo viên; hỗ trợ đào tạo nhân lực phục vụ các ngành công nghiệp mũi nhọn, công nghiệp bán dẫn, trí tuệ nhân tạo; hỗ trợ học sinh tốt nghiệp THPT đi học ở nước ngoài đối với các ngành điện tử, bán dẫn…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực UBND tỉnh mong muốn trong thời gian tới, Trường Đại học Limoges sẽ hợp tác với tỉnh Bắc Ninh trong các chương trình đào tạo nguồn nhân lực chất lượng cao ngành công nghệ bán dẫn, vật liệu điện tử, năng lượng và tự động hóa; phát triển các chương trình đào tạo tại chỗ; có chính sách học bổng đối với sinh viên đi du học… Từ đó, nghiên cứu, triển khai ký kết biên bản hợp tác trong đào tạo nguồn nhân lực chất lượng cao với tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực UBND tỉnh cũng mong muốn Giáo sư Veronique Blanquet bằng uy tín và mối quan hệ của mình, sẽ là cầu nối, kết nối các doanh nghiệp Pháp về tìm hiểu, đầu tư tại Bắc Ninh và liên kết với doanh nghiệp tại Bắc Ninh trong thúc đẩy hợp tác chuỗi cung ứng và ứng dụng công nghệ mới…</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-13.png/ce54907a-1b9c-a869-5e19-78dd9f21a30f?t=1761814600756\" style=\"height: 607px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giáo sư Veronique Blanquet giới thiệu khái quát về Trường&nbsp;Đại học Limoges.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Trân trọng cảm ơn sự đón tiếp trọng thị của lãnh đạo tỉnh Bắc Ninh, Giáo sư Veronique Blanquet bày tỏ ấn tượng trước sự phát triển của tỉnh trong công cuộc hội nhập, nhất là vào chuỗi giá trị công nghệ cao toàn cầu. Đồng thời cho biết, Trường Đại học Limoges được thành lập vào năm 1968, có truyền thống sản xuất đồ gốm sứ. Trường có quy mô hơn 18.000 sinh viên, trong đó gần 2.000 sinh viên quốc tế, chiếm 10,8%; đào tạo đa ngành, nổi bật với các chương trình đào tạo đa dạng từ khoa học xã hội nhân văn đến khoa học tự nhiên và ứng dụng; trong đó, đặc biệt mạnh về các ngành: Y, Dược, Luật, Kinh tế, Khoa học và Kỹ thuật, các chương trình về Kỹ thuật Dân dụng và Quản lý…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Vượt lên trên vai trò là một hệ thống đào tạo đa ngành toàn diện, Trường Đại học Limoges còn là trung tâm đổi mới sáng tạo hàng đầu châu Âu với 05 viện nghiên cứu, đóng góp vào chuỗi giá trị công nghệ chủ chốt toàn cầu về chất bán dẫn, vật liệu sinh học, năng lượng, công nghệ hạt nhân và công nghệ thông tin.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288823/30-12.png/c60c7f3b-8791-3b9e-e224-bf5d75333af5?t=1761814667474\" style=\"height: 595px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh buổi tiếp và làm việc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhấn mạnh, chuyến thăm và làm việc tại tỉnh Bắc Ninh diễn ra trong bối cảnh quan hệ giữa 02 quốc gia Pháp - Việt Nam vừa được nâng cấp lên Đối tác Chiến lược toàn diện, Phó Hiệu trưởng Trường Đại học Limoges tin tưởng vào tiềm năng hợp tác về giáo dục, nghiên cứu và công nghệ cao, hướng tới việc kiến tạo các giá trị bổ trợ lẫn nhau, đóng góp vào các mục tiêu chiến lược chung của hai bên. Đồng thời, mong muốn được chào đón các sinh viên tỉnh Bắc Ninh đến học tập, nghiên cứu tại Trường.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Giáo sư Veronique Blanquet cũng trân trọng gửi lời mời tới các đồng chí lãnh đạo tỉnh; lãnh đạo các sở, ngành liên quan đến thăm và làm việc tại Trường Đại học Limoges trong thời gian tới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngay sau buổi làm việc, đoàn công tác của Trường Đại học Limoges đến thăm quan cơ sở vật chất, mô hình đào tạo một số ngành thế mạnh tại Trường Cao đẳng Công nghiệp Bắc Ninh./.</span></span></span></p>', '30/10/2025 15:52', 'https://bacninh.gov.vn/news/-/details/37632/-ong-chi-mai-son-pho-chu-tich-thuong-truc-ubnd-tinh-tiep-va-lam-viec-voi-truong-ai-hoc-limoges-cong-hoa-phap-29525512', '', 'Linh Ngọc', 267, 'Xã hội', 6, 'true', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (38, '29509201', 'Bắc Ninh hỗ trợ 9 tỷ đồng cho thành phố Huế, Đà Nẵng, Quảng Trị, Quảng Ngãi bị thiệt...', 'Bắc Ninh hỗ trợ 9 tỷ đồng cho thành phố Huế, Đà Nẵng, Quảng Trị, Quảng Ngãi bị thiệt hại do bão lũ gây ra', 'https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/10/28/5712750021221476795906834372194270522638716475n-17616258236281709798788.jpg', '<p>(BNP) – Ban Vận động Cứu trợ tỉnh Bắc Ninh vừa ban hành Quyết định số 06/QĐ-BVĐCT về việc hỗ trợ các tỉnh, thành phố bị thiệt hại do bão lũ gây ra.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"https://images2.thanhnien.vn/thumb_w/640/528068263637045248/2025/10/28/5712750021221476795906834372194270522638716475n-17616258236281709798788.jpg\" style=\"width: 900px; height: 600px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kinh thành Huế sáng nay 28.10</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo đó, được sự nhất chí của Thường trực Tỉnh ủy về việc hỗ trợ các đơn vị bị ảnh hưởng do bão lũ gây ra, Ban Vận động cứu trợ tỉnh quyết định phân bổ số tiền 9 tỷ đồng từ nguồn Quỹ của Ban vận động cứu trợ tỉnh Bắc Ninh vào tài khoản của Ban vận động cứu trợ các tỉnh, thành phố bị thiệt hại do bão lũ gây ra.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cụ thể: hỗ trợ thành phố Huế 3 tỷ đồng; thành phố Đà Nẵng 2 tỷ đồng; tỉnh Quảng Trị 2 tỷ đồng; tỉnh <span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quảng Ngãi&nbsp;</span></span></span>2 tỷ đồng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ban Vận động cứu trợ - Ủy ban MTTQ các đơn vị có trách nhiệm hỗ trợ đảm bảo phù hợp, đúng mục đích, công khai, minh bạch, hiệu quả và thanh quyết toán theo quy định của pháp luật hiện hành.</span></span></span></p>', '30/10/2025 14:39', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-ho-tro-9-ty-ong-cho-thanh-pho-hue-a-nang-quang-tri-quang-ngai-bi-thiet-hai-do-bao-lu-gay-ra-29509201', '', 'Nguyễn Nhàn', 160, 'Xã hội', 6, '', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (39, '29130241', 'Bắc Ninh: Danh sách 342 trường hợp xe MÔ TÔ (XE MÁY) vi phạm bị phạt nguội từ ngày 17...', 'Bắc Ninh: Danh sách 342 trường hợp xe MÔ TÔ (XE MÁY) vi phạm bị phạt nguội từ ngày 17 - 26/10/2025', '/documents/37632/18835561/566329315_122153219672804369_8563098369294465191_n.jpg/e5b45c7e-16cd-42b8-e068-c71146a956bd?t=1761624627432', '<p>(BNP) - Theo thống kê từ hệ thống camera giám sát giao thông trên địa bàn tỉnh Bắc Ninh, từ ngày 17 - 26/10/2025, ghi nhận 342 trường hợp xe mô tô (xe máy)<strong> </strong>vi phạm bị phạt nguội.</p>', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/566329315_122153219672804369_8563098369294465191_n.jpg/e5b45c7e-16cd-42b8-e068-c71146a956bd?t=1761624627432\" style=\"width: 900px; height: 488px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>320 trường hợp m<span lang=\"VI\">ô tô </span>(xe máy) không chấp hành hiệu lệnh của đèn tín hiệu giao thông:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+xe+may+1+%281%29.png/4bdd0e95-2948-6377-ad41-4857395bfce5?t=1761624655996\" style=\"height: 922px;\" /><br />\n<img src=\"/documents/37632/18835561/2810+xe+may+2.png/8d26a99c-8138-e008-6ef5-1d55719f2014?t=1761624670326\" style=\"height: 1223px; width: 800px;\" /><br />\n<img src=\"/documents/37632/0/2810+xe+may+3+%281%29.png/318b14ad-f8d0-e43b-f6cd-5340e60b32be?t=1761624697027\" style=\"height: 137px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-top:8px; text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 22 trường hợp mô tô (xe máy) chạy quá tốc độ quy định:</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/0/2810+xe+may+4.png/e0cfb830-7781-44ca-dbc4-bc41e98d49cb?t=1761624733247\" style=\"height: 185px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-bottom: 11px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thông tin tra cứu trên website chính thức của Cục Cảnh sát Giao thông:&nbsp;<a href=\"https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html\" style=\"color:#467886; text-decoration:underline\" target=\"_blank\"><span style=\"color:#0070c0\">https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html</span></a><span style=\"color:#0070c0\"></span></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">Các chủ phương tiện có tên trong danh sách chủ động liên hệ Phòng CSGT Công an tỉnh Bắc Ninh hoặc các đội CSGT phụ trách địa bàn để giải quyết vi phạm theo đúng quy định.</span> <span lang=\"VI\">Các trường hợp cố tình chậm trễ sẽ bị xử lý nghiêm theo luật định.</span>/.</span></span></span></p>', '29/10/2025 07:30', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-danh-sach-342-truong-hop-xe-mo-to-xe-may-vi-pham-bi-phat-nguoi-tu-ngay-17-26-10-2025-29130241', '', 'BNP', 4542, 'Xã hội', 6, '', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (40, '29129624', 'Bắc Ninh: Danh sách 270 trường hợp xe Ô TÔ vi phạm bị phạt nguội từ ngày 17 -...', 'Bắc Ninh: Danh sách 270 trường hợp xe Ô TÔ vi phạm bị phạt nguội từ ngày 17 - 26/10/2025', '/documents/37632/18835561/572259620_122154228092804369_6980704119443601936_n.jpg/9652868f-e978-dafb-2724-ced9d74cddcf?t=1761624343977', '<p>(BNP) - Theo thống kê từ hệ thống camera giám sát giao thông trên địa bàn tỉnh Bắc Ninh, từ ngày 17 - 26/10/2025, ghi nhận 270 trường hợp xe ô tô vi phạm bị phạt nguội.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/572259620_122154228092804369_6980704119443601936_n.jpg/9652868f-e978-dafb-2724-ced9d74cddcf?t=1761624343977\" style=\"height: 506px; width: 900px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>46&nbsp;trường hợp <span lang=\"VI\">ô tô </span>không chấp hành hiệu lệnh của đèn tín hiệu giao thông:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+anh+1.png/4633456c-a462-17dc-c34d-3987c37d6f1b?t=1761624364825\" style=\"height: 341px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>96 trường hợp <span lang=\"VI\">ô tô </span>không chấp hành hiệu lệnh, chỉ dẫn của vạch kẻ đường:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+anh+2.png/ddbf243d-fa88-56a8-ec63-db8f58e11943?t=1761624402216\" style=\"height: 644px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>122 trường hợp <span lang=\"VI\">ô tô </span>điều khiển xe chạy quá tốc độ quy định:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/0/2810+anh+3.png/6c3792a2-9dde-7503-26fb-b646ee6e05d0?t=1761624444342\" style=\"height: 844px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">* </span>06 trường hợp <span lang=\"VI\">ô tô </span>rẽ trái tại nơi có biển cấm:</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><img src=\"/documents/37632/18835561/2810+anh+4+%281%29.png/2d44e78e-d165-79ca-f29c-973c778cc522?t=1761624495847\" style=\"height: 87px; width: 800px;\" /></span></span><br />\n&nbsp;</p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 01 trường hợp ô tô dừng xe dưới gầm cầu vượt: 29C-335.58;</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 11px; text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">* 01 trường hợp quay đầu xe ở phần đường dành cho người đi bộ qua đường: 99A-760.84.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\">Thông tin tra cứu trên website chính thức của Cục Cảnh sát Giao thông:&nbsp;<a href=\"https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html\" style=\"color:#467886; text-decoration:underline\" target=\"_blank\"><span style=\"color:#0070c0\">https://www.csgt.vn/tra-cuu-phuong-tien-vi-pham.html</span></a><span style=\"color:#0070c0\"></span></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span lang=\"VI\">Các chủ phương tiện có tên trong danh sách chủ động liên hệ Phòng CSGT Công an tỉnh Bắc Ninh hoặc các đội CSGT phụ trách địa bàn để giải quyết vi phạm theo đúng quy định.</span> <span lang=\"VI\">Các trường hợp cố tình chậm trễ sẽ bị xử lý nghiêm theo luật định.</span>/.</span></span></span></p>', '28/10/2025 11:03', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-danh-sach-270-truong-hop-xe-o-to-vi-pham-bi-phat-nguoi-tu-ngay-17-26-10-2025-29129624', '', 'BNP', 4746, 'Xã hội', 6, '', '38762', '{}', '2025-10-31 08:45:00.000000', 6, 11);
INSERT INTO `sync_articles` VALUES (41, '29906460', 'Bắc Ninh: Tổng kết và trao giải Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng lần thứ...', 'Bắc Ninh: Tổng kết và trao giải Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng lần thứ 21', '/documents/37632/23288878/31-10-3+%281%29.png/79351be0-452e-4edf-9830-d44d919a37db?t=1761892235498', '<p>(BNP) – Sáng 31/10, tại Trường THPT Ngô Sĩ Liên, Ban Tổ chức Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng tỉnh Bắc Ninh tổ chức Tổng kết Cuộc thi lần thứ 21, năm 2025 và trao giải cho các mô hình, sản phẩm xuất sắc. Dự chương trình có đồng chí Trần Thị Hằng, Ủy viên Ban Thường vụ Tỉnh ủy, Phó...', '<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-3+%281%29.png/79351be0-452e-4edf-9830-d44d919a37db?t=1761892235498\" style=\"height: 549px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng (ngoài cùng bên trái) và&nbsp;Chủ tịch Liên hiệp Các hội Khoa học và Kỹ thuật tỉnh Ngô Chí Vinh (ngoài cùng bên phải) trao giải Nhất cho các tác giả, nhóm tác giả Cuộc thi&nbsp;Sáng tạo thanh thiếu niên, nhi đồng lần thứ 21.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng lần thứ 21, năm 2025 do UBND tỉnh chỉ đạo, Liên hiệp các hội Khoa học và Kỹ thuật tỉnh chủ trì, phối hợp với Tỉnh Đoàn và các Sở Khoa học và Công nghệ, Giáo dục và Đào tạo, Tài chính; Báo và Phát thanh, Truyền hình tỉnh tổ chức. Cuộc thi nhằm khơi dậy tiềm năng và phát huy tư duy sáng tạo của đoàn viên, thanh thiếu niên, nhi đồng toàn tỉnh; giúp các em trau dồi kiến thức, rèn luyện kỹ năng sáng tạo và đào tạo nguồn nhân lực trẻ có chất lượng cao đáp ứng nhu cầu công nghiệp hóa, hiện đại hóa. </span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Đối tượng dự thi là đoàn viên, thanh thiếu niên và nhi đồng có độ tuổi từ 06 đến 19 tuổi. Cuộc thi có 5 lĩnh vực dự thi gồm: Đồ dùng dành cho học tập; phần mềm tin học; sản phẩm thân thiện với môi trường; các dụng cụ sinh hoạt gia đình, đồ dùng giải trí và đồ chơi trẻ em; các giải pháp nhằm ứng phó biến đổi khí hậu, bảo vệ môi trường và phát triển kinh tế. </span></span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-1.png/3849bca8-bdec-8cb0-f65f-25972e9cc253?t=1761892500951\" style=\"height: 530px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng trao Bằng khen của Chủ tịch UBND tỉnh cho các tập thể, cá nhân có thành tích xuất sắc.</span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Qua các vòng tuyển chọn, Hội đồng Giám khảo đã lựa chọn được 60 mô hình, sản phẩm vào vòng chung khảo Cuộc thi. Kết quả, có 33 mô hình, sản phẩm của 95 tác giả, đồng tác giả được trao giải. Đây đều là những mô hình mới, có hàm lượng sáng tạo cao, có khả năng ứng dụng để giải quyết những vấn đề thực tiễn đang diễn ra trong cuộc sống, học tập. Điển hình như mô hình “Chuyển đổi số, nâng cao hiệu quả trong công tác quản lý phương tiện đi lại của học sinh” của nhóm tác giả Trường THPT Tân Yên số 2; mô hình “Chế tạo vật liệu hút ẩm từ lõi cây sắn (khoai mì) bảo quản nông sản, thực phẩm” của tác giả Trường Tiểu học Phồn Xương, xã Yên Thế; mô hình “Khung xương hỗ trợ phục hồi chức năng vận động cho người đột quỵ” của nhóm tác giả Trường THPT Yên Dũng số 1; mô hình “Chiến thắng Xương Giang - Muôn thuở hào hùng” của nhóm tác giả Trường Tiểu học Đông Thành, phường Bắc Giang... </span></span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-2.png/fca99717-2587-bcd9-94f9-e74ad48e8025?t=1761892587495\" style=\"height: 547px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Phó Chủ tịch Thường trực HĐND tỉnh Trần Thị Hằng trao Bằng khen của Chủ tịch UBND tỉnh cho các tác giả, nhóm tác giả đạt giải Nhất 2 cuộc thi.</span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Tại chương trình, Ban Tổ chức Cuộc thi đã trao 02 giải nhất, 04 giải nhì, 06 giải ba và 21 giải khuyến khích với tổng trị giá tiền thưởng là 176 triệu đồng. Các tập thể, cá nhân có thành tích tiêu biểu trong tuyên truyền, tổ chức Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng năm 2025 và Cuộc thi Robocon tỉnh Bắc Ninh năm 2025 được trao tặng Bằng khen Chủ tịch UBND tỉnh. </span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Nhân dịp này, Trung ương Đoàn TNCS Hồ Chí Minh trao tặng Huy hiệu Tuổi trẻ sáng tạo cho 21 cá nhân là thanh thiếu niên tỉnh Bắc Ninh là các tác giả, nhóm tác giả đạt giải Nhất Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng và giải Nhất Cuộc thi Robocon tỉnh Bắc Ninh lần thứ 2, năm 2025; Hội Khuyến học tỉnh trao thưởng 2,5 triệu đồng cho mỗi tác giả, nhóm tác giả đạt giải Nhất 02 Cuộc thi.</span></span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-7.png/3c4247a2-3939-e66e-fec0-e458c53e3015?t=1761893048122\" style=\"height: 563px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Các tác giả, nhóm tác giả được nhận&nbsp;Huy hiệu Tuổi trẻ sáng tạo.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size: 18px; font-family: Arial, Helvetica, sans-serif;\">Cùng ngày, Ban Tổ chức phát động Cuộc thi Sáng tạo thanh thiếu niên, nhi đồng tỉnh Bắc Ninh lần thứ 22, năm 2026. Cuộc thi diễn ra từ tháng 10/2025 đến tháng 10/2026. Cuộc thi sẽ bao gồm 3 bảng thi là khối THPT, bảng khối THCS và bảng khối Tiểu học; cơ cấu giải thưởng gồm 41 giải (tăng 7 giải so với năm 2025).</span></span></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><img src=\"/documents/37632/23288878/31-10-6.png/740ef1b5-d5f6-3702-fe04-b8a98c9db4d2?t=1761893069063\" style=\"height: 564px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Các em học sinh hào hứng tham gia trải nghiệm vận hành robot tại Ngày hội.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><span style=\"line-height:1.3;\">Cũng trong buổi sáng, Liên hiệp các hội Khoa học và Kỹ thuật tỉnh phối hợp với các đơn vị liên quan tổ chức Ngày hội Sáng tạo năm 2025 với các nội dung: Trải nghiệm robot, tham gia lập trình và vận hành robot, tham gia các trò chơi vận động, gắn với các trò chơi đòi hỏi trí tuệ, tinh thần làm việc nhóm…/.</span></span></span></p>\n\n<p style=\"margin-top:8px; text-align:justify\"><span style=\"font-size:11pt\"><span style=\"line-height:130%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:130%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '31/10/2025 11:19', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-tong-ket-va-trao-giai-cuoc-thi-sang-tao-thanh-thieu-nien-nhi-ong-lan-thu-21-29906460', '', 'Nguyễn Nhàn', 29, 'Sở, ngành, địa phương', 7, 'true', '38762', '{}', '2025-10-31 08:45:01.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (42, '29855320', 'Phấn đấu đến năm 2030, có ít nhất 50% số xã, phường trong tỉnh đạt “không ma túy”', 'Phấn đấu đến năm 2030, có ít nhất 50% số xã, phường trong tỉnh đạt “không ma túy”', '/documents/37632/200628/PCMT.jpg/cfdfc639-24de-cdc4-fe6d-d588ffb04e5d?t=1761876972454', '<p>(BNP) - Chủ tịch UBND tỉnh Bắc Ninh vừa ký ban hành <a href=\"/documents/37632/23288878/116-KH-UBND.pdf/92f8bf15-c0c6-b64b-0840-3e6a166d8621?t=1761877068580\">Kế hoạch số 116/KH-UBND</a> thực hiện Chương trình mục tiêu quốc gia về phòng, chống ma túy đến năm 2030 trên địa bàn tỉnh.</p>', '<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/PCMT.jpg/cfdfc639-24de-cdc4-fe6d-d588ffb04e5d?t=1761876972454\" style=\"height: 572px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát huy sức mạnh của cả hệ thống chính trị và toàn dân tham gia công tác phòng, chống ma túy.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Mục tiêu của Kế hoạch là phát huy sức mạnh của cả hệ thống chính trị và toàn dân tham gia công tác phòng, chống ma túy; lấy phòng ngừa là chính, đấu tranh ngăn chặn từ sớm, từ xa, giảm cung, giảm cầu, giảm tác hại ma túy, góp phần xây dựng xã hội an toàn, lành mạnh, phát triển bền vững. Phấn đấu đến năm 2030, có ít nhất 50% số xã, phường đạt “không ma túy”, giảm người nghiện, người sử dụng trái phép chất ma túy và nâng cao chất lượng công tác cai nghiện, quản lý sau cai nghiện.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch đề ra nhiều chỉ tiêu cụ thể: 100% điểm tổ chức, chứa chấp, mua bán trái phép chất ma túy được phát hiện, triệt phá; trên 80% lực lượng chuyên trách được trang bị phương tiện kỹ thuật hiện đại; 100% trạm y tế cấp xã đủ điều kiện xác định tình trạng nghiện; 100% cơ sở cai nghiện ma túy công lập đủ điều kiện hoạt động; trên 80% cơ quan báo chí có chuyên trang, chuyên mục tuyên truyền phòng, chống ma túy.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình được triển khai từ năm 2025 đến năm 2030, trên phạm vi toàn tỉnh, gồm 9 dự án và nhiều tiểu dự án thành phần, tập trung vào các nội dung: Phòng ngừa, đấu tranh tội phạm ma túy; ứng dụng khoa học công nghệ; nâng cao hiệu quả cai nghiện và quản lý sau cai; tăng cường truyền thông, giáo dục, y tế, trợ giúp pháp lý; giám sát, đánh giá kết quả thực hiện.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kế hoạch xác định 6 nhóm nhiệm vụ, giải pháp trọng tâm gồm: Nâng cao hiệu quả lãnh đạo, chỉ đạo; nâng cao hiệu quả, chất lượng công tác tuyên truyền, phổ biến giáo dục phòng, chống ma túy và phát động phong trào toàn dân tham gia bảo vệ an ninh Tổ quốc; nâng cao chất lượng, hiệu quả công tác phòng ngừa, đấu tranh với tội phạm, tệ nạn ma tuý; đổi mới, nâng cao hiệu quả công tác quản lý người sử dụng trái phép chất ma túy, người nghiện ma túy, công tác cai nghiện và quản lý sau cai nghiện ma túy; nâng cao hiệu quả hợp tác quốc tế về phòng, chống ma túy; ứng dụng khoa học và công nghệ trong phòng, chống ma túy; thực hiện quản lý, giám sát, đánh giá Chương trình</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh giao Công an tỉnh là cơ quan thường trực, chủ trì tham mưu, theo dõi, đôn đốc, kiểm tra và tổng hợp kết quả thực hiện; các sở, ban, ngành, địa phương căn cứ chức năng, nhiệm vụ được phân công xây dựng kế hoạch cụ thể, bảo đảm hoàn thành các mục tiêu, chỉ tiêu đã đề ra.</span></span></span></p>', '31/10/2025 08:12', 'https://bacninh.gov.vn/news/-/details/37632/phan-au-en-nam-2030-co-it-nhat-50-so-xa-phuong-trong-tinh-at-khong-ma-tuy-29855320', '', 'Dương Thuỷ', 37, 'Sở, ngành, địa phương', 7, 'true', '38762', '{}', '2025-10-31 08:45:01.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (43, '29478603', 'Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính dựa trên dữ liệu làm...', 'Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính dựa trên dữ liệu làm việc tại tỉnh Bắc Ninh', '/documents/37632/200628/DoanGSBoTuphap+2.jpg/7e994fe0-30e1-ec78-d663-1e901951747c?t=1761800512635', '<p>(BNP) - Sáng 30/10, tại Bắc Ninh, Đoàn công tác liên ngành về rà soát, đánh giá thủ tục hành chính (TTHC) dựa trên dữ liệu do Thứ trưởng Bộ Tư pháp Nguyễn Thanh Tịnh làm Trưởng đoàn, đã có buổi làm việc với UBND tỉnh Bắc Ninh nhằm nắm bắt, tháo gỡ những khó khăn, vướng mắc phát sinh trong quá...', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+1.jpg/4400eea6-d533-bc24-992a-fc488156b566?t=1761799981519\" style=\"height: 503px; width: 900px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quang cảnh buổi làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham gia Đoàn công tác có đại diện lãnh đạo Trung tâm Dữ liệu quốc gia, Bộ Công an; Trung tâm Dữ liệu quốc gia về dân cư; Cục Cảnh sát quản lý hành chính về trật tự xã hội (Bộ Công an); cùng đại diện Văn phòng Chính phủ, Bộ Nội vụ, Bộ Tư pháp.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp và làm việc với Đoàn có đồng chí Mai Sơn, Ủy viên Ban Thường vụ Tỉnh ủy, Phó Chủ tịch Thường trực UBND tỉnh, cùng đại diện lãnh đạo các sở, ban, ngành của tỉnh.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi làm việc, Thứ trưởng Nguyễn Thanh Tịnh nhấn mạnh, t</span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">heo tinh thần chung của Bộ Tư pháp và Bộ Công an, kết quả rà soát,&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">cắt giảm, đơn giản hóa TTHC dựa trên dữ liệu đảm bảo&nbsp;</span></span></span>phản ánh thực chất, lấy dữ liệu làm căn cứ thay thế giấy tờ truyền thống. Hiện có 15 nhóm giấy tờ có thể được thay thế bằng dữ liệu từ các cơ sở dữ liệu quốc gia như dân cư, hộ tịch, lý lịch tư pháp, đất đai, tài chính. Bắc Ninh là một trong những địa phương triển khai sớm với hơn 30 thủ tục thuộc danh mục này.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Tư pháp nêu 6 điều kiện bảo đảm thành công, gồm: cơ sở pháp lý rõ ràng; dữ liệu “đúng - đủ - sạch - sống - thống nhất”; hệ thống công nghệ kết nối ổn định; lộ trình cụ thể; cơ chế tiếp nhận, xử lý phản ánh của người dân và đội ngũ cán bộ am hiểu nghiệp vụ, công nghệ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đề nghị Bắc Ninh thành lập tổ tư vấn công nghệ tại Trung tâm Phục vụ hành chính công và cấp xã, hỗ trợ người dân trong quá trình thực hiện thủ tục số.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+3.jpg/b4de1419-824d-db9c-9dc9-3db01246a0da?t=1761800060786\" style=\"height: 588px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Giám đốc Sở Tư pháp Bắc Ninh Lưu Đình Thực&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">báo cáo tại buổi làm việc.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Báo cáo tại buổi làm việc, Giám đốc Sở Tư pháp Bắc Ninh Lưu Đình Thực cho biết: Năm 2025, công tác cải cách TTHC của tỉnh đạt nhiều kết quả nổi bật, tiếp tục giữ vững vị trí nhóm đầu cả nước về chỉ số chỉ đạo, điều hành và chất lượng phục vụ người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh đã triển khai đồng bộ nhiều mô hình sáng tạo như “Ngày thứ Sáu không hẹn”, “Luồng xanh 24 giờ”, “Ngày Chủ nhật vì dân”… góp phần rút ngắn thời gian xử lý hồ sơ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hiện, 100% TTHC (trừ lĩnh vực thanh tra) được thực hiện phi địa giới hành chính; 982 dịch vụ công trực tuyến hoạt động thực chất; tỷ lệ hài lòng đạt trên 90%; tỷ lệ giải quyết hồ sơ đúng và trước hạn đạt 99,95%, qua đó đưa Bắc Ninh trong 06 tuần liên tiếp dẫn đầu cả nước với 91,73/100 điểm trên Cổng Dịch vụ công quốc gia.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, trong triển khai Đề án 06, Bắc Ninh là 1 trong 16 tỉnh hoàn thành kết nối hệ thống IOC với Cơ sở dữ liệu quốc gia về dân cư; làm sạch hơn 3 triệu dữ liệu đất đai, 2,8 triệu dữ liệu hộ tịch; thực hiện chính sách “0 đồng” cho 42 thủ tục trực tuyến, khuyến khích người dân sử dụng dịch vụ công số.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">UBND tỉnh Bắc Ninh đã rà soát 734 TTHC thuộc 16 lĩnh vực, trong đó hàng trăm thủ tục được đề xuất thay thế hồ sơ bằng dữ liệu từ các cơ sở dữ liệu quốc gia, cùng 53 TTHC đặc thù địa phương được đề xuất cắt giảm, đơn giản hóa. Tỉnh kiến nghị Văn phòng Chính phủ tiếp tục hướng dẫn, bổ sung danh mục TTHC có thể thay thế hồ sơ bằng dữ liệu, đồng thời cho phép cập nhật kết quả sau khi hoàn thiện cơ sở dữ liệu chuyên ngành.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+4.jpg/34eea1e4-0447-ec6b-e718-a84b1a97e2eb?t=1761800428502\" style=\"height: 559px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện lãnh đạo Văn phòng UBND tỉnh phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong quá trình triển khai, Bắc Ninh gặp một số khó khăn như: Thay đổi cán bộ phụ trách cải cách TTHC, nhiều công chức kiêm nhiệm nên việc cập nhật hướng dẫn còn chậm; khối lượng rà soát lớn, nhiều thủ tục chưa phát sinh hồ sơ thực tế; thời gian thực hiện gấp nên một số đơn vị lúng túng khi đối chiếu quy định với thực tế; cơ sở dữ liệu chuyên ngành chưa liên thông đầy đủ, gây hạn chế trong khai thác dữ liệu thay thế giấy tờ.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh kiến nghị Văn phòng Chính phủ hướng dẫn, bổ sung danh mục TTHC có thể thay thế bằng dữ liệu và cho phép cập nhật kết quả sau khi đồng bộ cơ sở dữ liệu; đề nghị các bộ, ngành Trung ương sớm sửa đổi quy định pháp luật, tăng cường kết nối, chia sẻ dữ liệu, bỏ yêu cầu nộp hồ sơ bản giấy với thủ tục đã xác thực điện tử, đồng thời thống nhất tính thời gian giải quyết theo ngày làm việc để thuận tiện cho người dân, doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi làm việc, đại diện lãnh đạo sở, ngành, đơn vị tỉnh Bắc Ninh nêu, trao đổi những khó khăn, vướng mắc trong quá trình thực hiện TTHC của ngành, lĩnh vực thời gian qua. Các thành viên trong Đoàn công tác đã trực tiếp trao đổi, giải đáp nhiều vấn đề mà UBND tỉnh Bắc Ninh nêu; đồng thời ghi nhận những kiến nghị, đề xuất của tỉnh để tổng hợp, báo cáo.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+6.jpg/279786d8-b558-8a83-8aff-da6ccf33f959?t=1761800489504\" style=\"height: 556px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn phát biểu tại buổi làm việc.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi làm việc, Phó Chủ tịch Thường trực UBND tỉnh Mai Sơn bày tỏ cảm ơn Đoàn công tác, coi đây là cơ hội để tỉnh nâng cao nhận thức, tháo gỡ vướng mắc và kiến nghị Trung ương hoàn thiện cơ chế pháp lý. Đồng chí đề xuất Trung ương quan tâm 3 nhóm vấn đề lớn: Hoàn thiện quy định pháp lý, điều khoản chuyển tiếp để linh hoạt xử lý trường hợp người dân chưa có dữ liệu. Xây dựng trung tâm dữ liệu cấp tỉnh với cơ chế phân định rõ thẩm quyền giữa Trung ương và địa phương. Nghiên cứu cơ chế khuyến khích doanh nghiệp tham gia cung cấp dịch vụ công, giảm thủ tục trực tiếp, nâng cao hiệu quả phục vụ.</span></span></span></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><img src=\"/documents/37632/200628/DoanGSBoTuphap+2.jpg/7e994fe0-30e1-ec78-d663-1e901951747c?t=1761800512635\" style=\"height: 583px; width: 900px;\" /></p>\n\n<p style=\"margin-top: 8px; margin-bottom: 8px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ trưởng Bộ Tư Pháp Nguyễn Thanh Tịnh k<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">ết luận buổi làm việc.</span></span></span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết luận buổi làm việc, Thứ trưởng Bộ Tư pháp Nguyễn Thanh Tịnh đánh giá cao cách làm quyết liệt, bài bản của Bắc Ninh, khẳng định chủ trương cắt giảm TTHC dựa trên dữ liệu là bước đi tất yếu trong chuyển đổi số quốc gia.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng chí đề nghị UBND tỉnh tiếp tục hoàn thiện báo cáo, nêu rõ các vướng mắc về hành chính, công nghệ, pháp lý để Bộ Tư pháp tổng hợp, báo cáo Chính phủ, bảo đảm hoàn thành rà soát, cắt giảm, đơn giản hóa thủ tục trước ngày 15/11/2025.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn công tác xác định Bắc Ninh là địa phương trọng điểm, có thể làm điểm triển khai mô hình cải cách hành chính dựa trên dữ liệu, đồng thời khuyến nghị tỉnh sớm tổ chức công tác tuyên truyền để người dân hiểu, đồng thuận và tham gia giám sát quá trình thực hiện.</span></span></span></p>', '30/10/2025 11:51', 'https://bacninh.gov.vn/news/-/details/37632/-oan-cong-tac-lien-nganh-ve-ra-soat-anh-gia-thu-tuc-hanh-chinh-dua-tren-du-lieu-lam-viec-tai-tinh-bac-ninh-29478603', '', 'Dương Thuỷ', 260, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:01.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (44, '29472846', 'Đại hội đại biểu Công đoàn Công ty Điện lực Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030', 'Đại hội đại biểu Công đoàn Công ty Điện lực Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030', '/documents/37632/23288878/30-2.png/73a7313d-fa07-d0e8-5632-b3f3b9f42334?t=1761797051407', '<p>(BNP) - Sáng 30/10, Công đoàn Công ty Điện lực Bắc Ninh tổ chức Đại hội đại biểu lần thứ I, nhiệm kỳ 2025 - 2030.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/30-2.png/73a7313d-fa07-d0e8-5632-b3f3b9f42334?t=1761797051407\" style=\"height: 576px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Lãnh đạo Công đoàn Tổng Công ty Điện lực miền Bắc chúc mừng&nbsp;Ban Chấp hành Công đoàn Công ty Điện lực Bắc Ninh khóa I.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tham dự Đại hội có lãnh đạo Công đoàn Tổng Công ty Điện lực miền Bắc; Ban Giám đốc Công ty Điện lực Bắc Ninh cùng 151 đại biểu đại diện cho gần 1.870 đoàn viên các công đoàn cơ sở thành viên.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhiệm kỳ 2021 - 2026, Công đoàn Công ty Điện lực Bắc Ninh luôn bám sát chức năng, nhiệm vụ hoạt động với nội dung “Xây dựng tổ chức Công đoàn vững mạnh”; phát huy tinh thần đoàn kết, chủ động, sáng tạo, đạt được nhiều kết quả tích cực, góp phần thiết thực hoàn thành nhiệm vụ sản xuất kinh doanh, nâng cao đời sống người lao động. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Công đoàn chú trọng đổi mới nội dung, phương thức hoạt động; thực hiện tốt chức năng đại diện, bảo vệ quyền và lợi ích hợp pháp, chính đáng của người lao động. Đồng thời, phối hợp chặt chẽ với bộ phận chuyên môn đẩy mạnh các phong trào thi đua trong lao động sản xuất, phát huy sáng kiến cải tiến kỹ thuật. Các phong trào thi đua thường xuyên được phát động và đẩy mạnh như: Quản lý kỹ thuật; An toàn bảo hộ lao động; Kinh doanh điện; Điện lực quản lý kinh doanh giỏi; Chương trình 5S từ Văn phòng ra lưới điện; Văn hóa an toàn lao động…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Cùng với đó, nắm bắt kịp thời tâm tư nguyện vọng và giải quyết những vấn đề bức xúc, cấp bách, nổi cộm của người lao động; các chế độ, chính sách được quan tâm thực hiện, giải quyết nhanh chóng, đúng quy định. Đời sống vật chất, tinh thần của cán bộ công nhân viên được nâng lên rõ rệt, thu nhập bình quân ổn định. Qua đó, tạo động lực, niềm tin để người lao động đoàn kết, gắn bó, hăng say thi đua lao động sản xuất, hoàn thành tốt nhiệm vụ được giao. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/30-3.png/29f6459e-454f-5bf1-d1e9-e5fc8c770208?t=1761797160101\" style=\"height: 633px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Phó Chủ tịch phụ trách Công đoàn Tổng Công ty Điện lực miền Bắc Trần Tuấn Khanh tặng Giấy khen cho các tập thể xuất sắc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhiều hoạt động an sinh xã hội, đền ơn đáp nghĩa, phụng dưỡng Mẹ Việt Nam Anh hùng, khen thưởng con cán bộ công nhân viên chức, lao động đạt thành tích tốt trong học tập… được duy trì hiệu quả, lan tỏa sâu rộng. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, chú trọng nâng cao, kiện toàn tổ chức công đoàn vững mạnh, tập hợp và phát triển đoàn viên, đổi mới nội dung, phương thức hoạt động của tổ chức công đoàn. Hàng năm, có hơn 90% đoàn viên Công đoàn hoàn thành tốt nhiệm vụ trở lên; hơn 90% Công đoàn cơ sở thành viên hoàn thành tốt nhiệm vụ trở lên. Công đoàn Công ty đạt vững mạnh xuất sắc hàng năm…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại hội tập trung thảo luận, chỉ ra những hạn chế, vướng mắc và nguyên nhân; từ đó, đề ra biện pháp khắc phục trong các hoạt động của Công đoàn nhiệm kỳ tới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ghi nhận và đánh giá cao những kết quả đạt được của Công đoàn Công ty Điện lực Bắc Ninh trong nhiệm kỳ vừa qua, Phó Chủ tịch phụ trách Công đoàn Tổng Công ty Điện lực miền Bắc Trần Tuấn Khanh đề nghị Công đoàn Công ty tiếp tục giữ vững vai trò đại diện, chăm lo thực chất cho người lao động; chủ động đổi mới phương thức hoạt động công đoàn trong bối cảnh chuyển đổi số; ứng dụng công nghệ thông tin trong điều hành, nâng cao kỹ năng, bản lĩnh cán bộ công đoàn, xứng đáng là chỗ dựa tin cậy cho người lao động… Cùng với đó, thường xuyên đồng hành cùng bộ phận chuyên môn thực hiện thắng lợi nhiệm vụ sản xuất, kinh doanh; đẩy mạnh các phong trào thi đua gắn với các chủ đề năm của Tổng Công ty và Công ty như: “Lao động giỏi, lao động sáng tạo, chuyển đổi số”; “Phát huy sáng kiến cải tiến kỹ thuật”… Tiếp tục thực hiện hiệu quả chương trình 5S, văn hóa doanh nghiệp; đảm bảo an toàn trong vận hành, xử lý sự cố, nói không với tai nạn lao động.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/30-4.png/ae4bfbea-2e5f-154c-abfb-ef2a54d3f63a?t=1761797353870\" style=\"height: 596px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại biểu biểu quyết thống nhất thông qua Nghị quyết Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Đại hội được nghe công bố Quyết định chỉ định Ban Chấp hành Công đoàn Công ty Điện lực Bắc Ninh khóa I, nhiệm kỳ 2025 - 2030 gồm 13 đồng chí; chỉ định 09 đại biểu chính thức đi dự Đại hội Công đoàn Tổng Công ty Điện lực miền Bắc, nhiệm kỳ 2025 - 2030. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Nhân dịp này, 3 tập thể, 6 cá nhân có thành tích xuất sắc trong hoạt động Công đoàn, nhiệm kỳ 2021 - 2026 được nhận Giấy khen của Ban Chấp hành Công đoàn Tổng Công ty Điện lực miền Bắc./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:11pt\"><span style=\"line-height:107%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:107%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '30/10/2025 11:03', 'https://bacninh.gov.vn/news/-/details/37632/-ai-hoi-ai-bieu-cong-oan-cong-ty-ien-luc-bac-ninh-lan-thu-i-nhiem-ky-2025-2030-29472846', '', 'Linh Ngọc', 153, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:01.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (45, '29335398', 'Tổ chức phi chính phủ DIVA (Hàn Quốc) làm việc tại tỉnh Bắc Ninh', 'Tổ chức phi chính phủ DIVA (Hàn Quốc) làm việc tại tỉnh Bắc Ninh', '/documents/37632/23288878/2+%285%29.jpg/8fb49834-bab8-7367-89a6-c35fffd6fd00?t=1761726871443', '<p>(BNP) - Chiều 29/10, Tổ chức phi chính phủ DIVA (Hàn Quốc) do ông Kim Wan Yong, Giám đốc đại diện tại Việt Nam làm trưởng đoàn đến thảo luận về định hướng, chương trình, dự án của Tổ chức phi chính phủ DIVA triển khai tại tỉnh Bắc Ninh thời gian tới. Phó Chánh Văn phòng UBND tỉnh Phạm Dương...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/1+%288%29.jpg/2cd60780-410a-606d-5a0f-3beb55fbaf36?t=1761726807073\" style=\"height: 547px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"color:#0000cd;\">Toàn cảnh buổi tiếp.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trao đổi tại buổi tiếp, ông Kim Wan Yong, Giám đốc Tổ chức phi chính phủ DIVA tại Việt Nam cho biết, Tổ chức DIVA là tổ chức phi chính phủ nước ngoài hoạt động trong lĩnh vực cung cấp học bổng và dạy tiếng Hàn, xây nhà cho người nghèo, hỗ trợ vật tư y tế, nước sạch và vệ sinh môi trường, khám chữa bệnh miễn phí với phạm vi hoạt động tại các tỉnh Thái Nguyên, Bắc Giang và Lạng Sơn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Từ năm 2015, tổ chức DIVA đã bắt đầu thực hiện các hoạt động hỗ trợ tại Việt Nam và chính thức nhận được Giấy đăng ký hoạt động do Cục Ngoại vụ (Bộ Ngoại giao) cấp vào năm 2018.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bắc Ninh là địa phương đang có tốc độ phát triển kinh tế nhanh, nhằm góp phần quan trọng trong chiến lược tăng trưởng&nbsp;kinh tế&nbsp;đi&nbsp;đôi&nbsp;với bảo vệ&nbsp;môi trường, ông Kim Wan Yong mong muốn sẽ được triển khai nhiều dự án nước sạch trên địa bàn tỉnh Bắc Ninh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Do vậy, để triển khai một số dự án của Tổ chức DIVA trên địa bàn tỉnh, Đoàn công tác đã tiến hành khảo sát tại các xã: Xuân Cẩm, Hoàng Vân và Hợp Thịnh và các Trường mầm non: Xuân Cẩm (xã Xuân Cẩm); Ngọc Sơn (xã Hoàng Vân); Mai Trung 2 ( xã Hợp Thịnh) liên quan đến lĩnh vực cải thiện nước sạch vệ sinh cho trường học trên địa bàn tỉnh. Qua đây, phía Tổ chức DIVA mong muốn tỉnh sẽ cung cấp các thông tin chi tiết bằng các cuộc làm việc và văn bản để các dự án được triển khai thiết thực, mang lại lợi ích cho người dân. </span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/2+%285%29.jpg/8fb49834-bab8-7367-89a6-c35fffd6fd00?t=1761726871443\" style=\"height: 520px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Phó Chánh Văn phòng UBND tỉnh Phạm Dương Tuyến tặng tranh dân gian Đông Hồ cho Đoàn công tác.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thay mặt lãnh đạo Văn phòng UBND tỉnh, đồng chí Phạm Dương Tuyến bày tỏ vui mừng được đón tiếp ông Kim Wan Yong cùng các thành viên đoàn đến thăm, làm việc. Đồng thời, thông tin đến đoàn công tác một số nét cơ bản về tình hình phát triển kinh tế - xã hội tỉnh Bắc Ninh mới và một số nội dung liên quan đến hoạt động của Tổ chức tại tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những năm gần đây, Bắc Ninh có bước phát triển vượt bậc, vững chắc. Tốc độ tăng trưởng kinh tế hàng năm luôn nằm trong nhóm các tỉnh dẫn đầu cả nước. Trong 9 tháng năm 2025, tỉnh có 09 khu công nghiệp mới được phê duyệt chủ trương đầu tư. Đặc biệt, tỉnh đang được đầu tư xây dựng Sân bay quốc tế Gia Bình, với công suất hàng hoá dự kiến lên tới 2,5 triệu tấn/năm, dự kiến khánh thành vào cuối năm 2026, là tiền đề quan trọng để tiếp tục thúc đẩy kinh tế - xã hội của tỉnh trong giai đoạn tới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chánh Văn phòng UBND tỉnh cũng cho biết, hiện trên địa bàn tỉnh có khoảng 30 tổ chức đăng ký hoạt động. Trong đó có nhiều dự án lớn của các tổ chức phi chính phủ Hàn Quốc tài trợ tại tỉnh. Các chương trình, dự án, khoản viện trợ của các tổ chức phi chính phủ và doanh nghiệp Hàn Quốc triển khai thực hiện tại tỉnh góp phần nâng cao công tác an sinh xã hội, hỗ trợ các đối tượng hưởng lợi là trẻ em, người già, người có hoàn cảnh khó khăn trên địa bàn tỉnh Bắc Ninh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đánh giá cao những đóng góp tích cực từ các dự án viện trợ Tổ chức phi chính phủ DIVA mang lại cho người dân và cộng đồng trong thời gian qua; đề nghị Tổ chức tiếp tục phối hợp với các sở, ban, ngành liên quan của tỉnh để triển khai các dự án, đồng thời tỉnh sẽ tạo điều kiện thuận lợi cho Tổ chức trong việc triển khai các dự án, đảm bảo hiệu quả, phù hợp với nhu cầu thực tiễn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '29/10/2025 15:31', 'https://bacninh.gov.vn/news/-/details/37632/to-chuc-phi-chinh-phu-diva-han-quoc-lam-viec-tai-tinh-bac-ninh-29335398', '', 'Nguyễn Miền', 136, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:02.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (46, '29296644', '101 Đảng bộ trực thuộc Tỉnh ủy Bắc Ninh dự hội nghị tập huấn triển khai ứng dụng Sổ...', '101 Đảng bộ trực thuộc Tỉnh ủy Bắc Ninh dự hội nghị tập huấn triển khai ứng dụng Sổ tay đảng viên điện tử', '/documents/37632/23288878/29-1.png/67cd7417-e234-af27-b145-303b2466c7c9?t=1761711477368', '<p>(BNP) - Sáng 29/10, tại Hà Nội, Văn phòng Trung ương Đảng phối hợp với Ban Tổ chức Trung ương tổ chức hội nghị tập huấn triển khai ứng dụng Sổ tay đảng viên điện tử theo hình thức trực tuyến kết nối tới điểm cầu các tỉnh, thành phố trong cả nước.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/29-1.png/67cd7417-e234-af27-b145-303b2466c7c9?t=1761711477368\" style=\"height: 579px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu Đảng ủy Văn phòng UBND tỉnh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại tỉnh Bắc Ninh, hội nghị được kết nối tới 294 điểm cầu tại 101 Đảng bộ trực thuộc Tỉnh ủy với hơn 18.000 đảng viên tham dự.&nbsp; </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Dự và chủ trì tại điểm cầu Đảng ủy Văn phòng UBND tỉnh có đồng chí Ngô Văn Luyến, Ủy viên Ban Thường vụ Đảng ủy Văn phòng UBND tỉnh, Phó Chánh Văn phòng UBND tỉnh; cấp ủy các chi bộ trực thuộc Đảng ủy Văn phòng UBND tỉnh. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Hội nghị tập huấn cho các cán bộ làm công tác xây dựng Đảng, công tác chuyển đổi số của các cơ quan Đảng trực thuộc Trung ương, Tỉnh ủy, Thành ủy; cấp ủy thuộc tổ chức Đảng cấp trên cơ sở, Đảng bộ cơ sở, chi bộ cơ sở, chi bộ trực thuộc Đảng bộ cấp trên cơ sở, chi bộ trực thuộc Đảng bộ cơ sở.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/29-3.png/0096f653-60f8-2e1d-4161-e056eb2ab85e?t=1761711530086\" style=\"height: 586px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu Văn phòng Tỉnh ủy Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Tại hội nghị, các đại biểu được nghe đại diện Cục Chuyển đổi số, Văn phòng Trung ương Đảng phổ biến, quán triệt các nội dung liên quan đến triển khai ứng dụng Sổ tay đảng viên điện tử như: Tổng quan về hệ thống Sổ tay đảng viên điện tử; mô hình và kiến trúc triển khai, hệ thống cài đặt tập trung, thống nhất trong toàn Đảng, sử dụng mọi lúc, mọi nơi trên 2 giao diện Web và Mobile, tích hợp AI hỗ trợ trong công tác Đảng; các chức năng chính của hệ thống và nhóm tính năng theo từng vai trò… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Ngoài ra, hướng dẫn cách cài đặt ứng dụng trên các hệ điều hành IOS, ANDROID, trên App điện thoại thông minh; cách đăng nhập trên web bằng tài khoản, đăng nhập bằng VneID; trải nghiệm các tính năng của Sổ tay đảng viên điện tử… Qua đó, giúp cán bộ, đảng viên nắm vững quy trình, kỹ năng sử dụng, sẵn sàng triển khai áp dụng hiệu quả trong thực tiễn.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\"><img src=\"/documents/37632/23288878/29-4.png/27459f3d-5cac-5dc5-1d4b-e252f077884b?t=1761711584385\" style=\"height: 606px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Quang cảnh hội nghị tại điểm cầu xã Văn Môn, tỉnh Bắc Ninh.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"line-height:1.3;\">Thông qua hội nghị nhằm tạo sự đồng bộ, thống nhất trong các cơ quan, tổ chức Đảng; hỗ trợ đảng viên trong sinh hoạt Đảng; cung cấp chính xác, kịp thời văn bản, tài liệu của Đảng, Nhà nước, các cấp ủy, tổ chức Đảng; phục vụ việc học tập nghị quyết, thực hiện nhiệm vụ đảng viên… Qua đó, góp phần nâng cao năng lực, trình độ, đạo đức, sức chiến đấu, trách nhiệm nêu gương của đảng viên và thống nhất một nền tảng ứng dụng số, tránh đầu tư dàn trải, lãng phí./.</span></span></span></p>', '29/10/2025 11:17', 'https://bacninh.gov.vn/news/-/details/37632/101-ang-bo-truc-thuoc-tinh-uy-bac-ninh-du-hoi-nghi-tap-huan-trien-khai-ung-dung-so-tay-ang-vien-ien-tu-29296644', '', 'Linh Ngọc', 238, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:02.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (47, '29278401', 'Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 – 2030 thành...', 'Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 – 2030 thành công tốt đẹp', '/documents/37632/23288878/mt11.png/c84871e7-3d67-4b38-b3c9-4a1ce0a9ea4c?t=1761718741640', '<p>(BNP) – Trong 2 ngày (28 và 29/10), tại Trung tâm Hội nghị tỉnh, Ủy ban MTTQ Việt Nam tỉnh Bắc Ninh long trọng tổ chức Đại hội đại biểu MTTQ Việt Nam tỉnh Bắc Ninh lần thứ I, nhiệm kỳ 2025 - 2030.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23288878/mt11.png/c84871e7-3d67-4b38-b3c9-4a1ce0a9ea4c?t=1761718741640\" style=\"height: 512px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đồng chí lãnh đạo Ủy ban Trung ương MTTQ Việt Nam và tỉnh tặng hoa chúc mừng&nbsp;<span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ủy ban MTTQ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025 - 2030.</span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tham dự Đại hội, đại biểu Trung ương có đồng chí Đỗ Văn Chiến, Ủy viên Bộ Chính trị, Bí thư Trung ương Đảng, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam; lãnh đạo Ủy ban Trung ương MTTQ Việt Nam.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại biểu tỉnh có các đồng chí: Nguyễn Hồng Thái, Ủy viên Trung ương Đảng, Bí thư Tỉnh ủy; Nguyễn Thị Hương, Phó Bí thư Thường trực Tỉnh ủy; Vương Quốc Tuấn, Ủy viên Dự khuyết Trung ương Đảng, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Nguyễn Việt Oanh, Phó Bí thư Tỉnh ủy, Chủ tịch HĐND tỉnh; các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy; Thường trực HĐND, lãnh đạo UBND, lãnh đạo Đoàn ĐBQH tỉnh; các đồng chí nguyên Thường trực Tỉnh ủy, UBND tỉnh qua các thời kỳ; Mẹ Việt Nam Anh hùng, Anh hùng Lực lượng vũ trang Nhân dân, Anh hùng Lao động; các đồng chí nguyên lãnh đạo Ủy ban MTTQ tỉnh qua các thời kỳ, lãnh đạo Ủy ban MTTQ một số tỉnh lân cận; lãnh đạo các sở, ban, ngành, địa phương của tỉnh cùng 358 đại biểu chính thức đại diện cho các tầng lớp Nhân dân, các dân tộc, tôn giáo, lực lượng vũ trang, người con Bắc Ninh trên địa bàn tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/MTTQ.png/9f168839-a82c-05fd-dac3-d8d4d6b55355?t=1761719427581\" style=\"height: 583px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Đỗ Văn Chiến tặng Đại hội bức tranh Bác Hồ, Bác Tôn</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiệm kỳ 2024 - 2029, Ủy ban MTTQ tỉnh Bắc Ninh và các tổ chức thành viên đã nỗ lực đổi mới, phát huy vai trò nòng cốt chính trị trong xây dựng khối đại đoàn kết toàn dân, góp phần thực hiện thắng lợi các nhiệm vụ chính trị, thúc đẩy phát triển kinh tế - xã hội, giữ vững quốc phòng - an ninh, nâng cao đời sống Nhân dân; đã hoàn thành và hoàn thành vượt mức nhiều chỉ tiêu, nhiệm vụ nhiệm kỳ đề ra. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, khối Đại đoàn kết toàn dân không ngừng được củng cố, mở rộng và phát huy. Ủy ban MTTQ tỉnh đổi mới mạnh mẽ về nội dung, phương thức, đa dạng các hình thức vận động, gắn với những phong trào thi đua yêu nước, các cuộc vận động thiết thực; chú trọng phát huy vai trò của cá nhân tiêu biểu, người có uy tín, chức sắc tôn giáo trong tuyên truyền, vận động. Qua đó, tinh thần đoàn kết, gắn bó cộng đồng, ý thức tự lực, tự cường trong Nhân dân được khơi dậy mạnh mẽ. Người dân đồng thuận thực hiện các chủ trương đường lối của Đảng, chính sách pháp luật của Nhà nước, góp phần thay đổi diện mạo nông thôn, đô thị ngày càng văn minh, hiện đại.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt10.png/c3c7ed53-aa2f-2c29-fa01-e083eeca2535?t=1761718990364\" style=\"height: 551px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái, Phó Bí thư Thường trực Tỉnh ủy Nguyễn Thị Hương, Chủ tịch UBND tỉnh Vương Quốc Tuấn, Chủ tịch HĐND tỉnh Nguyễn Việt Oanh và Phó Chủ tịch UBND tỉnh, Trưởng Đoàn ĐBQH tỉnh Phạm Văn Thịnh (<span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">bên phải)&nbsp;</span></span></span></span></span></span></span></span>trao tặng Đại hội bức Trướng \"Đoàn kết - Dân chủ - Đổi mới - Phát triển\".</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các cuộc vận động, phong trào thi đua được MTTQ triển khai có trọng tâm, trọng điểm với nhiều mô hình, phần việc cụ thể, thiết thực, khơi dậy mạnh mẽ tinh thần lao động sáng tạo của Nhân dân. Cuộc vận động “Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh\" tiếp tục giữ vai trò nòng cốt, trở thành cuộc vận động mang tính toàn dân, toàn diện, từng bước thay đổi diện mạo đô thị, nông thôn, nâng cao chất lượng đời sống Nhân dân.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong nhiệm kỳ, MTTQ các cấp phối hợp vận động người dân hiến trên 21 nghìn m² đất, đóng góp gần 40 tỷ đồng và trên 33 nghìn ngày công làm các công trình phúc lợi công cộng, góp phần xây dựng hạ tầng nông thôn, đô thị khang trang, hiện đại. Cùng với đó, tích cực chăm lo giáo dục; chăm sóc sức khỏe Nhân dân; xây dựng đời sống văn hóa; xây dựng khu dân cư an toàn, không có tội phạm, tệ nạn xã hội. Năm 2024, toàn tỉnh có 88,2% phường, thị trấn đạt chuẩn văn minh đô thị; 82,5% làng, bản, tổ dân phố văn hóa; 100% thôn, tổ dân phố thực hiện hương ước, quy ước, thực hiện nếp sống mới trong việc cưới, việc tang, lễ hội, xây dựng cộng đồng dân cư an ninh, an toàn, văn minh, hạnh phúc.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt14.png/f381553d-a214-7a3c-47cf-218d36d6ea71?t=1761719764509\" style=\"height: 540px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Chủ tịch điều hành Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác an sinh xã hội, chăm lo người nghèo, người yếu thế cũng để lại nhiều dấu ấn. Bắc Ninh là một trong những tỉnh đi đầu trong cả nước về thực hiện chương trình xóa nhà tạm, nhà dột nát cho hộ nghèo, cận nghèo và gia đình chính sách khó khăn về nhà ở. Sau 15 tháng triển khai, toàn tỉnh hỗ trợ xây dựng, sửa chữa và bàn giao hơn 2.500 nhà trị giá 150 tỷ đồng cho các hộ nghèo, cận nghèo, hộ khó khăn và gia đình chính sách. Qua đó, tạo niềm tin, động lực giúp người nghèo, người có hoàn cảnh đặc biệt khó khăn ổn định cuộc sống, vươn lên thoát nghèo. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hưởng ứng phong trào “Vì người nghèo - Không để ai bị bỏ lại phía sau\", MTTQ các cấp đã tích cực vận động các cơ quan, tổ chức, cá nhân, doanh nghiệp, nhà hảo tâm tham gia xây dựng quỹ “Vì người nghèo” và chương trình an sinh xã hội; hằng năm 100% hộ nghèo được thăm, tặng quà Tết. Công tác tham gia xây dựng Đảng, chính quyền, giám sát và phản biện xã hội tiếp tục được tăng cường, thể hiện rõ hơn vai trò đại diện bảo vệ quyền và lợi ích hợp pháp, chính đáng của đoàn viên, hội viên và Nhân dân.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt7.png/e138038f-2725-7826-de30-9d821ed163cb?t=1761719324995\" style=\"height: 578px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Đỗ Văn Chiến phát biểu chỉ đạo tại Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với chủ đề “Đoàn kết - Dân chủ - Đổi mới - Phát triển”, nhiệm kỳ 2025 - 2030, Ủy ban MTTQ tỉnh tiếp tục phát huy truyền thống, sức mạnh đại đoàn kết toàn dân; lấy nhân tố con người là trung tâm, là chủ thể, nguồn động lực, mục tiêu chủ yếu của đại đoàn kết dân tộc; tăng cường củng cố liên minh chính trị, tạo đồng thuận xã hội. Đại diện, bảo vệ quyền và lợi ích hợp pháp, chính đáng của Nhân dân. Thực hiện dân chủ, giám sát, phản biện xã hội, tham gia góp ý xây dựng Đảng, xây dựng chính quyền, phòng chống tham nhũng, tiêu cực. Đổi mới mạnh mẽ nội dung, phương thức hoạt động của MTTQ; xây dựng đội ngũ cán bộ Mặt trận đủ năng lực, phẩm chất, sáng tạo, tâm huyết, bản lĩnh, dám làm, dám chịu trách nhiệm, dám đương đầu với khó khăn, thử thách, giỏi dân vận và có khát vọng cống hiến. MTTQ các cấp tích cực vận động các tầng lớp Nhân dân cùng với cấp ủy, chính quyền tự tin, tiến mạnh trong kỷ nguyên phát triển mới của dân tộc; thực hiện thành công mục tiêu đưa Bắc Ninh phát triển nhanh, toàn diện, bền vững, trở thành thành phố trực thuộc Trung ương trước năm 2030 theo hướng văn minh, hiện đại. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt8.png/07f7c3f9-b868-16f4-e773-c24ee89b7e8d?t=1761719498619\" style=\"height: 589px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bí thư Tỉnh ủy Nguyễn Hồng Thái phát biểu chỉ đạo tại Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong đó, phấn đấu 100% cán bộ Ủy ban MTTQ và các tổ chức thành viên các cấp được quán triệt, học tập, phổ biến, tuyên truyền các chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước, Chương trình công tác của Mặt trận; 100% khu dân cư tổ chức Ngày hội Đại đoàn kết toàn dân tộc; hằng tháng, hằng quý 100% Ủy ban MTTQ các cấp và các tổ chức thành viên có báo cáo phản ánh kịp thời tình hình Nhân dân và đề xuất giải pháp, phương hướng giải quyết. Hằng năm, Ủy ban MTTQ cấp tỉnh tổ chức giám sát ít nhất 05 chương trình, nội dung; phản biện xã hội ít nhất 05 dự thảo văn bản. MTTQ cấp xã tổ chức giám sát ít nhất 03 chương trình, nội dung; phản biện xã hội ít nhất 03 dự thảo văn bản; tổ chức giám sát các nội dung theo chỉ đạo của cấp trên và những vấn đề được đông đảo quần chúng Nhân dân quan tâm. Hằng năm, tổ chức hoạt động vận động, quyên góp nguồn lực ủng hộ Quỹ “Vì người nghèo” và an sinh xã hội đạt trên 66 tỷ đồng; vận động ủng hộ Tết vì người nghèo đạt 100% hộ nghèo được nhận quà Tết; các hộ khó khăn đặc biệt được hỗ trợ thường xuyên. Phấn đấu đến hết năm 2027, toàn tỉnh không còn hộ nghèo theo chuẩn nghèo đa chiều giai đoạn 2021-2025…</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu chỉ đạo tại Đại hội, Chủ tịch Ủy ban Trung ương MTTQ Việt Nam Đỗ Văn Chiến ghi nhận, biểu dương, chúc mừng những kết quả mà Ủy ban MTTQ tỉnh Bắc Ninh đã đạt được trong thời gian vừa qua. Đồng thời, đề nghị thời gian tới, MTTQ tỉnh Bắc Ninh tiếp tục quán triệt sâu sắc nội dung Nghị quyết số 43 của Ban Chấp hành Trung ương Đảng khóa XIII về tiếp tục phát huy truyền thống sức mạnh đại đoàn kết toàn dân tộc, xây dựng đất nước ta ngày càng phồn vinh hạnh phúc. Quán triệt sâu sắc chủ trương quan điểm của Đảng: Dân là gốc, Nhân dân là trung tâm, chủ thể, mục tiêu và động lực của đổi mới. Tập hợp đoàn kết rộng rãi công nhân, nông dân, trí thức, thanh niên, phụ nữ, cựu chiến binh, cựu Công an Nhân dân, doanh nhân, đồng bào dân tộc, đồng bào tôn giáo, người Bắc Ninh sinh sống ngoài tỉnh, đóng góp trí tuệ, công sức, nguồn lực để xây dựng tỉnh Bắc Ninh giàu đẹp, văn minh hiện đại, giàu bản sắc và phấn đấu trở thành thành phố trực thuộc Trung ương trước năm 2030 và đến năm 2045 là thành phố xanh, văn minh hiện đại. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23288878/mt4.jpg/6478d812-3cb3-9e28-ea19-76fd8c6e5958?t=1761707006326\" style=\"height: 626px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Đồng chí Nguyễn Thị Hà tái cử Chủ tịch Ủy ban MTTQ tỉnh khóa I, nhiệm kỳ 2025 - 2030.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đẩy mạnh công tác giáo dục lịch sử truyền thống, bồi đắp niềm tự hào, khát vọng vươn lên, tinh thần yêu nước, đoàn kết của các tầng lớp Nhân dân tỉnh Bắc Ninh. Phát huy mạnh mẽ dân chủ đồng thuận xã hội, củng cố vững chắc niềm tin của Nhân dân với các cấp ủy Đảng, chính quyền; đẩy mạnh các phong trào thi đua yêu nước, xây dựng khu dân cư đoàn kết, ấm no, hạnh phúc; nâng cao chất lượng công tác giám sát phản biện xã hội, tích cực tham gia xây dựng Đảng, xây dựng chính quyền và hệ thống chính trị trong sạch, vững mạnh. Chủ động đề xuất phối hợp tham gia giải quyết những vấn đề phức tạp, nảy sinh trong thực tiễn, tổ chức đối thoại xã hội, tổ chức \"Tháng nghe dân nói\", tích cực tham gia phòng chống tham nhũng, lãng phí, tiêu cực. Phối hợp giám sát các hoạt động chính quyền, cán bộ đảng viên, người đứng đầu đảm bảo công khai minh bạch, hiệu quả. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, đẩy mạnh thực hiện các cuộc vận động, các phong trào thi đua yêu nước trong các tầng lớp Nhân dân một cách thực chất. Trong đó, tập trung thực hiện tốt Cuộc vận động \"Toàn dân đoàn kết xây dựng nông thôn mới, đô thị văn minh\", Cuộc vận động \"Cả nước chung tay vì người nghèo, không để ai bị bỏ lại phía sau\", Cuộc vận động \"Người Việt Nam ưu tiên dùng hàng Việt Nam\", phong trào \"Bình dân học vụ số\", phong trào \"Cả nước đồng lòng chung sức xây dựng cơ sở hạ tầng đồng bộ hiện đại\"; tích cực đổi mới nội dung phương thức hoạt động của Mặt trận, chú trọng đào tạo, bồi dưỡng, rèn luyện đội ngũ cán bộ có bản lĩnh, tinh thông nghiệp vụ, sát dân, chủ động phục vụ Nhân dân, nhất là đội ngũ cán bộ cấp xã. Triển khai thực hiện hiệu quả Nghị quyết số 57 của Bộ Chính trị về đột phá phát triển khoa học công nghệ, đổi mới sáng tạo và chuyển đổi số quốc gia. Ứng dụng công nghệ số sâu rộng trong mọi mặt hoạt động của MTTQ Việt Nam, nhất là trong việc nắm tâm tư nguyện vọng của Nhân dân, chuyển tải chủ trương đường lối của Đảng, chính sách pháp luật của Nhà nước đến với Nhân dân. Đồng thời, tham gia tổ chức cuộc bầu cử đại biểu Quốc hội và HĐND các cấp nhiệm kỳ 2026 - 2031, theo chức năng nhiệm vụ của Mặt trận đã được pháp luật quy định, lựa chọn những người đủ đức, đủ tài, đủ sức gánh vác nhiệm vụ đại diện Nhân dân.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><img src=\"/documents/37632/23288878/mt1+%281%29.png/468ca254-2ff9-5601-841a-002883e90f01?t=1761705114569\" style=\"height: 527px; width: 900px;\" /></span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"color:#0000ff;\">Đồng chí Nguyễn Thị Hà trao Bằng khen của Chủ tịch UBND tỉnh cho các tập thể có thành tích xuất sắc.</span></span></span></span></p>\n\n<p style=\"margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại Đại hội, thay mặt Ban Chấp hành Đảng bộ tỉnh, Bí thư Tỉnh ủy Nguyễn Hồng Thái ghi nhận, biểu dương và chúc mừng những thành tích mà Ủy ban MTTQ tỉnh, MTTQ các cấp đã đạt được trong nhiệm kỳ vừa qua. Đồng thời, đề nghị thời gian tới, MTTQ các cấp bám sát Nghị quyết số 43 của Ban Chấp hành Trung ương Đảng khóa XIII về “Tiếp tục phát huy truyền thống, sức mạnh đại đoàn kết toàn dân tộc, xây dựng đất nước ta ngày càng phồn vinh, hạnh phúc\"; Dự thảo Văn kiện Đại hội Trung ương MTTQ Việt Nam, Nghị quyết Đại hội đại biểu Đảng bộ tỉnh lần thứ I, nhiệm kỳ 2025-2030 và các Nghị quyết, chỉ thị, kế hoạch của tỉnh để xác định đúng trọng tâm, trọng điểm trong nhiệm kỳ mới. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp tục phát huy vai trò nòng cốt của MTTQ trong xây dựng, củng cố, tăng cường và phát huy sức mạnh khối đại đoàn kết toàn dân; xác định rõ đây là nhiệm vụ quan trọng hàng đầu của MTTQ các cấp; tích cực đổi mới phương thức, cơ chế hoạt động của MTTQ và các tổ chức chính trị - xã hội theo hướng sâu sát với dân; hướng mạnh về cơ sở, đa dạng hóa các hình thức tập hợp và giải quyết tốt mối quan hệ lợi ích giữa các tầng lớp Nhân dân; phát huy vai trò của lực lượng nòng cốt, các cá nhân tiêu biểu, có uy tín trong các dân tộc, tôn giáo. Đồng thời, quan tâm đẩy mạnh và đổi mới, năng cao chất lượng, hiệu quả các cuộc vận động, phong trào thi đua yêu nước theo hướng thiết thực, phù hợp với từng khu vực, đối tượng, điều kiện thực tiễn, đáp ứng nguyện vọng của Nhân dân. Triển khai đa dạng, linh hoạt, sáng tạo các hoạt động nhằm phát huy tiềm năng, trí tuệ, hiệu triệu mọi tầng lớp Nhân dân thể hiện khát vọng vươn lên, cống hiến, tham gia thực hiện các nhiệm vụ phát triển kinh tế - xã hội, bảo đảm quốc phòng, an ninh. </span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt2+%282%29.png/73141c69-6e99-3dd9-6f3c-5d334085ed84?t=1761720120970\" style=\"height: 528px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\">Các tập thể có thành tích xuất sắc nhận Bằng khen của Chủ tịch UBND tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với đó, tích cực phối hợp với các cấp, các ngành đẩy mạnh cải cách hành chính, chuyển đổi số trong quản lý, điều hành, kết nối thông tin với Nhân dân; đẩy mạnh phong trào “bình dân học vụ số\" tại các khu dân cư. Tăng cường vai trò giám sát, phản biện xã hội của MTTQ và các đoàn thể. Phát huy vai trò MTTQ trong thực hiện dân chủ ở cơ sở. Phát huy ngày càng hiệu quả bài học lớn về “Trọng dân, gần dân, sát dân, hiểu dân, an dân”, tạo sự đồng thuận trong xã hội, hướng tới mục tiêu “Đảng nói dân tin, chính quyền làm dân ủng hộ, MTTQ và các đoàn thể vận động dân theo”, xứng đáng là cầu nối giữa Nhân dân với Đảng, chính quyền. Đồng thời, quan tâm chăm lo công tác cán bộ MTTQ, nhất là cán bộ cơ sở thực sự nhiệt huyết, năng lực, uy tín và am hiểu thực tiễn, “Tận tụy để dân mến - Trách nhiệm để dân thương - Kỷ cương để dân trọng - Năng động để dân được nhờ\"; mỗi cán bộ Mặt trận phải là hạt nhân đoàn kết, mở rộng các hoạt động đối ngoại Nhân dân, tích cực vận động, tập hợp, đoàn kết, phát huy vai trò của cộng đồng người Bắc Ninh ở trong nước và ở nước ngoài hướng về xây dựng quê hương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại hội tiến hành hiệp thương cử 119 đại biểu tham gia Ủy ban MTTQ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025-2030; hiệp thương cử 16 đại biểu chính thức và 02 đại biểu dự khuyết dự Đại hội đại biểu MTTQ Việt Nam lần thứ XI, nhiệm kỳ 2026 - 2031.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại Hội nghị lần thứ Nhất của Ủy ban MTTQ tỉnh khóa I, nhiệm kỳ 2025-2030 đã hiệp thương cử các chức danh trong Ban Thường trực Ủy ban MTTQ tỉnh Bắc Ninh khóa I, nhiệm kỳ 2025-2030. Trong đó, đồng chí Nguyễn Thị Hà tái cử Chủ tịch Ủy ban MTTQ tỉnh; các Phó Chủ tịch gồm các đồng chí: Ngụy Thị Tuyến, Nguyễn Nhân Chinh, Thạch Văn Chung, Nguyễn Hoàng Trung, Nguyễn Phương Mai, Nguyễn Đức Thuận, Trần Văn Đăng, Trần Quang Đạo, Ngô Biên Cương, Nguyễn Văn Triển, Thái Hải Anh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/mt5+%281%29.png/dffc3d37-6bde-c9ce-84ba-5bc2561a7b28?t=1761719943041\" style=\"height: 522px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiết mục văn nghệ chào mừng Đại hội.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, Chủ tịch UBND tỉnh tặng Bằng khen cho 15 tập thể, 20 cá nhân có thành tích xuất sắc trong thực hiện Chương trình phối hợp, thống nhất hành động và triển khai&nbsp;thực hiện Nghị quyết Đại hội đại biểu MTTQ&nbsp;Việt Nam các cấp tỉnh Bắc Ninh nhiệm kỳ 2024-2029; Ủy ban MTTQ tỉnh tặng Bằng khen cho 20 tập thể, 13 cá nhân đã có thành tích xuất sắc tiêu biểu trong công tác xây dựng khối Đại đoàn kết toàn dân tộc giai đoạn 2024-2029./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '29/10/2025 01:00', 'https://bacninh.gov.vn/news/-/details/37632/-ai-hoi-ai-bieu-mttq-viet-nam-tinh-bac-ninh-lan-thu-i-nhiem-ky-2025-2030-thanh-cong-tot-ep-29278401', '', 'Nguyễn Nhàn', 283, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:02.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (48, '29188141', 'Tòa án Nhân dân tỉnh Bắc Ninh – Phát huy truyền thống, vững bước tương lai', 'Tòa án Nhân dân tỉnh Bắc Ninh – Phát huy truyền thống, vững bước tương lai', '/documents/37632/23288878/pv-1-final.jpg/a5293144-50a6-4813-bd19-92063e6a8626?t=1761650414537', '<p>Từ những ngày đầu gian khó của chính quyền cách mạng non trẻ, đến nay, TAND hai cấp tỉnh Bắc Ninh (sau sáp nhập) đã trở thành một biểu tượng của công lý, vững mạnh về tổ chức,&nbsp;tinh thông&nbsp;về nghiệp vụ và luôn tận tâm phục vụ nhân dân.</p>', '<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/pv-1-final.jpg/a5293144-50a6-4813-bd19-92063e6a8626?t=1761650414537\" style=\"height: 474px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Một chặng đường lịch sử nhiều dấu mốc quan trọng</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với sự ra đời và phát triển của ngành TAND, TAND hai cấp tỉnh Bắc Ninh trải qua một chặng đường lịch sử với nhiều dấu mốc quan trọng. Trải qua các giai đoạn sáp nhập, chia tách, hợp nhất địa giới hành chính, tên gọi và tổ chức bộ máy của TAND tỉnh cũng có những thay đổi để phù hợp với yêu cầu thực tiễn.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song hành cùng với sự ra đời của nhà nước ta, TAND tỉnh Bắc Giang và TAND tỉnh Bắc Ninh được thành lập. Năm 1962, Quốc hội khóa II thông qua Nghị quyết hợp nhất hai tỉnh Bắc Ninh và Bắc Giang thành tỉnh Hà Bắc. Tòa án nhân dân tỉnh Hà Bắc chính thức làm việc từ ngày 01/4/1963. Năm 1996, Quốc hội khóa IX ban hành Nghị quyết chia tách địa giới hành chính của tỉnh Hà Bắc thành hai tỉnh Bắc Giang và Bắc Ninh. Tòa án nhân dân tỉnh Bắc Giang, TAND tỉnh Bắc Ninh được tái lập và hoạt động từ ngày 01/01/1997.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với sự nghiệp công nghiệp hóa, hiện đại hóa của cả nước, tỉnh Bắc Ninh (cũ) và Bắc Giang (cũ) đã có sự phát triển vượt bậc về kinh tế - xã hội, văn hóa, an ninh chính trị; trật tự an toàn xã hội được giữ vững. Trải qua gần 20 năm xây dựng và trưởng thành, hàng năm TAND tỉnh Bắc Ninh (cũ), TAND tỉnh Bắc Giang (cũ) đã trực tiếp và chỉ đạo các TAND huyện, thị xã, thành phố trên địa bàn tỉnh xét xử, giải quyết hàng nghìn vụ việc các loại, góp phần giữ vững an ninh chính trị, trật tự an toàn xã hội, tạo môi trường pháp lý thuận lợi cho phát triển kinh tế - xã hội tại địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thực hiện Nghị quyết của Bộ Chính trị và Quốc hội, từ ngày 01/7/2025, hai tỉnh Bắc Ninh và Bắc Giang chính thức hợp nhất thành một đơn vị hành chính mới - tỉnh Bắc Ninh. Đây là sự kiện chính trị - hành chính có ý nghĩa lịch sử, mở ra một giai đoạn phát triển mới cho vùng đất giàu truyền thống cách mạng.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">TAND hai cấp tỉnh Bắc Ninh mới được kiện toàn trên cơ sở hợp nhất TAND tỉnh Bắc Ninh và TAND tỉnh Bắc Giang trước đây; các TAND cấp huyện kết thúc hoạt động, thành lập 9 TAND khu vực.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Chánh án TAND tỉnh Bắc Ninh - Mai Anh Tài, đây là một dấu mốc lịch sử là bước chuyển quan trọng trong tiến trình đổi mới tổ chức bộ máy Tòa án theo tinh thần cải cách tư pháp và sắp xếp lại đơn vị hành chính; thể hiện quyết tâm cải cách, hiện đại hóa nền tư pháp, đáp ứng yêu cầu xây dựng Nhà nước pháp quyền xã hội chủ nghĩa Việt Nam.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc sáp nhập tỉnh Bắc Giang và tỉnh Bắc Ninh là một chủ trương lớn, mang tính chiến lược của Đảng và Nhà nước nhằm tinh gọn bộ máy, nâng cao hiệu lực, hiệu quả hoạt động của hệ thống chính trị. Với vai trò là cơ quan xét xử ở địa phương, TAND tỉnh Bắc Ninh đã chủ động triển khai đồng bộ các giải pháp để bảo đảm sớm ổn định tổ chức bộ máy, duy trì hiệu quả công tác xét xử trong giai đoạn chuyển tiếp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Ổn định nhanh sau sáp nhập, giữ vững nhịp cầu công lý</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay từ khi có chủ trương, TAND hai tỉnh Bắc Giang và Bắc Ninh cũ đã phối hợp chặt chẽ để chuẩn bị tốt các điều kiện sáp nhập, bảo đảm tính đồng bộ, thống nhất và ổn định. TAND hai tỉnh đã đề ra lộ trình, từ sắp xếp cán bộ, cơ sở vật chất, đến quản trị nội bộ với mục tiêu xuyên suốt là không để công tác xét xử bị gián đoạn, đảm bảo tốt quyền và lợi ích hợp pháp của người dân trong mọi hoàn cảnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chia sẻ với phóng viên, Chánh án Mai Anh Tài cho biết, TAND tỉnh đã thực hiện nghiêm túc việc rà soát, đánh giá tổng thể đội ngũ cán bộ, công chức, từ đó bố trí, phân công hợp lý theo năng lực, sở trường, bảo đảm không có tình trạng xáo trộn gây ảnh hưởng đến công việc.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>“Chúng tôi đặt trọng tâm vào xây dựng khối đoàn kết nội bộ, phát huy truyền thống tốt đẹp của hai đơn vị cũ, đồng thời xây dựng văn hóa Tòa án mới - thống nhất, dân chủ, kỷ cương và trách nhiệm. Bầu không khí đoàn kết, sẻ chia, vì nhiệm vụ chung đã được duy trì ngay từ đầu, giúp quá trình chuyển tiếp diễn ra trong tinh thần chủ động, tích cực và trách nhiệm cao”,&nbsp;</i>Chánh án Mai Anh Tài chia sẻ<i>.</i></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các vị trí lãnh đạo chủ chốt được kiện toàn kịp thời, bảo đảm sự chỉ đạo xuyên suốt, đồng bộ trong Tòa án hai cấp. Bên cạnh đó, các đơn vị chuyên môn, tổ chức Đảng, đoàn thể cũng được củng cố nhanh chóng, giữ vững kỷ luật, kỷ cương công vụ trong toàn hệ thống. Tinh thần đổi mới, trách nhiệm và sáng tạo đã được lan tỏa rộng khắp trong đội ngũ cán bộ, công chức TAND tỉnh.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/pv2-final.jpg/59d6b04f-f234-9ec9-977c-920d14f39b5a?t=1761650544196\" style=\"height: 486px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngay trong thời điểm sáp nhập, đơn vị xác định việc bảo đảm xét xử thông suốt là nhiệm vụ ưu tiên hàng đầu. Do đó, Tòa án đã thực hiện song song hai việc: ổn định tổ chức bộ máy và duy trì tiến độ giải quyết, xét xử các vụ việc theo kế hoạch. Các bộ phận duy trì hoạt động bình thường, không để bất kỳ vụ việc nào bị đình trệ.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>“Chúng tôi thực hiện đúng lịch xét xử, đảm bảo quyền tiếp cận công lý của người dân không bị gián đoạn dù có nhiều khó khăn trong thời điểm sáp nhập đồng thời là cuối năm công tác. Để giữ vững nhịp cầu công lý, hoàn thành chỉ tiêu đăng ký, chúng tôi đã làm việc không quản ngày đêm,</i>&nbsp;<i>xét xử cả ngày thứ 7 và chủ nhật”</i>, Chánh án Mai Anh Tài nhấn mạnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh đó, TAND tỉnh cũng triển khai ứng dụng công nghệ thông tin vào công tác điều hành, quản lý hồ sơ và xét xử. Đơn vị đẩy mạnh xử lý văn bản điện tử, tổ chức các phiên họp và xét xử trực tuyến trong điều kiện phù hợp, góp phần nâng cao hiệu quả công việc, tiết kiệm thời gian và chi phí cho người dân cũng như các cơ quan tiến hành tố tụng. Đây là bước chuyển đổi quan trọng, giúp Tòa án thích ứng linh hoạt với yêu cầu cải cách tư pháp trong bối cảnh mới.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Phát huy truyền thống, viết tiếp trang sử vàng</b></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trải qua 80 năm xây dựng và trưởng thành, dưới sự lãnh đạo của Đảng, TANDTC, Tỉnh ủy, sự phối hợp của HĐND, UBND cùng sự đồng hành của các cơ quan, đoàn thể, TAND hai cấp tỉnh Bắc Ninh đã trưởng thành về nhiều mặt. Từ khi thành lập đến nay, TAND hai cấp tỉnh Bắc Ninh luôn bám sát yêu cầu nhiệm vụ cách mạng, thường xuyên gắn việc thực hiện nhiệm vụ chính trị của Tòa án với nhiệm vụ chính trị của địa phương.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong công tác xét xử, các Tòa án luôn chú trọng nâng cao chất lượng tranh tụng tại phiên tòa theo hướng thực chất, bảo đảm tính dân chủ, công khai, đúng quy định pháp luật, qua đó bảo vệ quyền và lợi ích hợp pháp của Nhà nước, tổ chức, cá nhân . Đối với các vụ việc dân sự, hành chính, Tòa án hai cấp đặc biệt coi trọng công tác hòa giải, đối thoại, giúp đương sự rút ngắn thời gian giải quyết tranh chấp và hiệu quả hơn do các bên tự giác thực hiện thỏa thuận.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/phien-xet-xu.jpg/75fa222b-a95b-91d7-4b9d-0ddcb9cf0787?t=1761650593353\" style=\"height: 630px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác thi hành án hình sự đảm bảo 100% người bị kết án khi bản án có hiệu lực pháp luật đều được ra quyết định thi hành án, việc giảm thời hạn chấp hành hình phạt tù đối với phạm nhân đang cải tạo đều được thực hiện đúng quy định của pháp luật. Tòa án hai cấp tỉnh đã hoàn thành xuất sắc nhiệm vụ xét xử các loại án, góp phần thực hiện thắng lợi nhiệm vụ chính trị của địa phương và bảo đảm an ninh trật tự trên địa bàn. Đặc biệt, thực hiện việc triển khai cập nhật dữ liệu lên phần mềm quản lý án, TAND tỉnh Bắc Ninh là đơn vị hoàn thành 100% khối lượng công việc và báo cáo sớm nhất trước ngày 31/8/2025.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bước sang giai đoạn mới, công tác cải cách tư pháp đang được tiến hành mạnh mẽ; tình hình an ninh, trật tự an toàn xã hội và tội phạm có nhiều diễn biến phức tạp, đòi hỏi đội ngũ Thẩm phán, cán bộ, công chức TAND tỉnh Bắc Ninh phải giữ vững phẩm chất, bản lĩnh chính trị, không ngừng rèn luyện, nâng cao trình độ chuyên môn, nghiệp vụ để hoàn thành tốt nhiệm vụ mà Đảng và nhân dân giao phó, đáp ứng tốt những yêu cầu đặt ra đối với công tác TAND trong tình hình mới.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/pv3-final.jpg/fde9e74b-c49d-47c7-befc-d29b1f83a4f6?t=1761650658138\" style=\"height: 438px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo Chánh án Mai Anh Tài, TAND tỉnh Bắc Ninh sẽ tiếp tục nâng cao chất lượng xét xử; đẩy mạnh cải cách tư pháp, ứng dụng mạnh mẽ chuyển đổi số, xây dựng Tòa án điện tử, nâng cao tính minh bạch, hiệu quả và phục vụ nhân dân ngày càng tốt hơn; chú trọng công tác đào tạo, bồi dưỡng đội ngũ cán bộ nhằm đáp ứng yêu cầu ngày càng cao của công tác Tòa án. Tăng cường phối hợp với các cơ quan tố tụng, chính quyền, đoàn thể để hoàn thành tốt nhiệm vụ chính trị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trước bối cảnh số lượng án Tòa án hai cấp thụ lý, giải quyết hàng năm tăng, tính chất các loại vụ án ngày càng phức tạp, cùng với một số khó khăn về cơ sở vật chất, trụ sở làm việc… sau sáp nhập là thách thức lớn với đơn vị.&nbsp;<i>“Nhưng để viết tiếp trang sử vàng của ngành, chúng tôi đã vượt qua khó khăn,</i>&nbsp;<i>thách thức bằng sự đoàn kết, quyết tâm và sáng tạo,&nbsp;giữ vững kỷ cương, kỷ luật trong công việc”</i>, Chánh án Tài khẳng định.</span></span></span></p>\n\n<p style=\"margin-bottom: 11px; text-align: center;\"><img src=\"/documents/37632/23288878/co-thi-dua-tand-bac-ninh.jpg/033706e8-31fd-370e-8c00-c1027fa98845?t=1761650728549\" style=\"height: 682px; width: 900px;\" /></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với những kết quả đã đạt được trong nhiều năm phấn đấu, nỗ lực của các thế hệ cán bộ công chức, nhiều đơn vị trong TAND hai cấp tỉnh Bắc Ninh đã vinh dự được tặng thưởng: Huân chương lao động hạng Nhất, Cờ thi đuacủa Chính phủ, Cờ thi đua TAND, Cờ thi đua của UBND tỉnh.... Và mới đây, tại Đại hội thi đua yêu nước TAND lần thứ V, Tòa án tỉnh Bắc Ninh tiếp tục vinh dự được nhận “Cờ thi đua Tòa án nhân dân” giai đoạn 2020-2025 vì có thành tích xuất sắc trong công tác. Đây là sự ghi nhận của Đảng, Nhà nước đối với những đóng góp quan trọng của TAND hai cấp tỉnh Bắc Ninh; đồng thời cũng là nguồn cổ vũ, động viên to lớn, là niềm tự hào sâu sắc của các thế hệ cán bộ, công chức, người lao động trong đơn vị.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát huy truyền thống vẻ vang 80 năm xây dựng và phát triển, TAND hai cấp tỉnh Bắc Ninh quyết tâm thực hiện tốt lời dạy của Chủ tịch Hồ Chí Minh đối với cán bộ Tòa án: “Phụng công, thủ pháp, chí công, vô tư”. Với khẩu hiệu “liêm chính, công bằng, trách nhiệm, vượt khó, đổi mới, hiệu quả”, tin tưởng rằng TAND tỉnh Bắc Ninh sẽ tiếp tục là một trong những đơn vị dẫn đầu, nối dài trang sử vàng, cùng hệ thống Tòa án nói riêng và đất nước nói chung vững bước tiến vào kỷ nguyên vươn mình của dân tộc.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:11px\"><span style=\"font-size:12pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"></span></span></span></span></span></span></p>', '28/10/2025 18:19', 'https://bacninh.gov.vn/news/-/details/37632/toa-an-nhan-dan-tinh-bac-ninh-phat-huy-truyen-thong-vung-buoc-tuong-lai-29188141', '', 'Congly.vn', 296, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:02.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (49, '29168064', 'Bắc Ninh triển khai rà soát, cắt giảm, đơn giản hoá thủ tục hành chính dựa trên thành...', 'Bắc Ninh triển khai rà soát, cắt giảm, đơn giản hoá thủ tục hành chính dựa trên thành phần hồ sơ thay thế bằng dữ liệu', '/documents/37632/23288878/TTHC.jpg/62a71b7f-4a26-8c98-7f53-88305accd5b0?t=1761639592455', '<p>(BNP) - Chủ tịch UBND tỉnh vừa ban hành&nbsp;<a href=\"/documents/37632/23288878/4049-UBND-HCC.pdf/73c3c70e-423e-a795-51c9-67ca6ade83a0?t=1761639423807\">Công văn số 4049/UBND-HCC </a>về việc triển khai rà soát, cắt giảm, đơn giản hoá thủ tục hành chính (TTHC) dựa trên thành phần hồ sơ thay thế...', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span><img src=\"/documents/37632/23288878/TTHC.jpg/62a71b7f-4a26-8c98-7f53-88305accd5b0?t=1761639592455\" style=\"width: 900px; height: 596px;\" /></p>\n\n<p style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"></span></span></span></span><span style=\"color:#0000ff;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ảnh minh họa.</span></span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm tạo thuận lợi, cắt giảm thời gian, chi phí cho cá nhân, tổ chức, góp phần thúc đẩy phát triển kinh tế, Chủ tịch UBND tỉnh yêu cầu các sở, ban, ngành thuộc UBND tỉnh trên cơ sở hướng dẫn của Bộ Tư pháp khẩn trương rà soát đối với 734 TTHC kèm theo Công văn số 6723/BTP-CTXDVBQPPL, Công văn số 4735/TCT và các TTHC khác có chứa 01 trong 153 loại giấy tờ đã có thông tin trên các cơ sở dữ liệu quốc gia, cơ sở dữ liệu chuyên ngành có thể cắt giảm ngay; đề xuất phương án cắt giảm, đơn giản hóa TTHC, trong đó xác định rõ điều, khoản, điểm tại các văn bản quy phạm pháp luật có chứa TTHC của tỉnh cần sửa đổi, bổ sung để bảo đảm thực thi phương án đơn giản hóa.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đối với các TTHC đặc thù do địa phương ban hành, các đơn vị rà soát, tham mưu cơ quan có thẩm quyền sửa đổi, bổ sung các văn bản quy phạm pháp luật để thực hiện việc cắt giảm hoặc không yêu cầu cá nhân, tổ chức cung cấp thành phần hồ sơ mà thông tin đã có trong các cơ sở dữ liệu, thời hạn hoàn thành trước ngày 15/11/2025 hoặc trong kỳ họp HĐND gần nhất.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong quá trình triển khai thực hiện các nhiệm vụ về bố trí kinh phí chuyển đổi số của các sở, ban, ngành về giải quyết TTHC cho người dân, doanh nghiệp và các lĩnh vực khác có liên quan, nếu gặp khó khăn, vướng mắc gửi Văn phòng UBND tỉnh (Trung tâm Phục vụ hành chính công) tổng hợp, báo cáo về Công an tỉnh để tổng hợp, hoàn thiện báo cáo Bộ Công an.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sở Tư pháp chủ trì, hướng dẫn các sở, ban, ngành thực hiện rà soát cụ thể đối với các TTHC có thành phần hồ sơ là 01 trong 15 loại giấy tờ đã có trong dữ liệu, có thể cắt giảm trên cơ sở hướng dẫn của Bộ Tư pháp tại Công văn số 6723/BTP-CTXDVBQPPL; kịp thời báo cáo, tham mưu, đề xuất UBND tỉnh xem xét, chỉ đạo đối với những khó khăn, vướng mắc vượt thẩm quyền.</span></span></span></p>\n\n<p style=\"margin-top:8px; margin-bottom:8px; text-align:justify\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Văn phòng UBND tỉnh (Trung tâm Phục vụ hành chính công tỉnh) phối hợp với Sở Tư pháp trong việc hướng dẫn, đôn đốc các sở, ban, ngành thuộc UBND tỉnh thực hiện các nội dung theo yêu cầu tại Công văn này, bảo đảm đầy đủ nội dung và thời gian quy định./.</span></span></span></p>', '28/10/2025 15:15', 'https://bacninh.gov.vn/news/-/details/37632/bac-ninh-trien-khai-ra-soat-cat-giam-on-gian-hoa-thu-tuc-hanh-chinh-dua-tren-thanh-phan-ho-so-thay-the-bang-du-lieu-29168064', '', 'Dương Thuỷ', 124, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:02.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (50, '29169454', 'Đoàn công tác Công ty QXQ Inc, Hoa Kỳ đến tìm hiểu môi trường đầu tư tại tỉnh Bắc Ninh', 'Đoàn công tác Công ty QXQ Inc, Hoa Kỳ đến tìm hiểu môi trường đầu tư tại tỉnh Bắc Ninh', '/documents/37632/23288878/2+%284%29.jpg/64304d96-4f21-f93d-f676-8ac8613b5ceb?t=1761639386449', '<p>(BNP) - Chiều 28/10, tại Văn phòng UBND tỉnh, Đoàn công tác do ông Quan Roger Chi, Chủ tịch Công ty QXQ Inc, Hoa Kỳ đã đến tìm hiểu môi trường đầu tư tỉnh Bắc Ninh. Phó Giám đốc Sở Tài chính Vũ Thị Phương Thảo chủ trì buổi tiếp và làm việc với đoàn. Cùng dự có đại diện lãnh đạo Văn phòng UBND...', '<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/2+%284%29.jpg/64304d96-4f21-f93d-f676-8ac8613b5ceb?t=1761639386449\" style=\"height: 485px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"font-size:16px;\">Quang cảnh buổi tiếp.</span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thay mặt lãnh đạo tỉnh, Phó Giám đốc Sở Tài chính Vũ Thị Phương Thảo bày tỏ vui mừng&nbsp;được đón tiếp và&nbsp;làm việc với Đoàn công tác Công ty QXQ Inc. Đồng thời thông tin khái quát về tình hình thực hiện kế hoạch phát triển kinh tế - xã hội năm 2025, kế hoạch phát triển kinh tế - xã hội năm 2026 của tỉnh. Trong đó nhấn mạnh về lợi thế của tỉnh trong phát triển công nghiệp điện tử, công nghệ cao, công nghệ bán dẫn và các chính sách hỗ trợ đầu tư, định hướng thu hút đầu tư của tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bắc Ninh là tỉnh tiếp giáp thủ đô Hà Nội, có mạng lưới giao thông thuận tiện dễ dàng kết nối với sân bay, cảng biển và sang Trung Quốc (cách sân bay Nội Bài 40 km, cách cảng Hải Phòng khoảng 90 km, cách cửa khẩu Quốc tế Hữu Nghị quan sang Trung Quốc khoảng 100 km). Đặc biệt, tỉnh đang được đầu tư xây dựng sân bay quốc tế Gia Bình, với công suất hàng hóa dự kiến lên tới 2,5 triệu tấn/năm, dự kiến khánh thành vào cuối năm 2026.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tỉnh Bắc Ninh đã quy hoạch có 52 KCN với tổng diện tích 15.202ha; 43 KCN được phê duyệt Quy hoạch với diện tích 13.141ha; 35 KCN được được chấp thuận chủ trương đầu tư với tổng diện tích khoảng 10.495,86 ha; 17 dự án hạ tầng KCN cơ bản lấp đầy. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lũy kế đến thời điểm hiện tại, Ban Quản lý các KCN tỉnh đã cấp phép cho 2.881 dự án đầu tư thứ cấp, với tổng vốn cấp mới và điều chỉnh đạt 46.456,08 triệu USD. Các tập đoàn lớn đầu tư tại các KCN sử dụng công nghệ hiện đại, có dây chuyền sản xuất lớn đã làm thay đổi cơ cấu sản phẩm công nghiệp của&nbsp;tỉnh.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2026, dự kiến doanh thu của các doanh nghiệp KCN năm 2026 đạt khoảng 2.097.000 tỷ đồng; giá trị xuất nhập khẩu của các doanh nghiệp KCN năm 2026 đạt khoảng 126,4 tỷ USD. Tỉnh tiếp tục tập trung phát triển công nghiệp mũi nhọn đi đôi với bảo vệ môi trường, đảm bảo 100% KCN đi vào hoạt động có hệ thống xử lý nước thải tập trung đạt chuẩn môi trường. </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Song song với phát triển kinh tế, tỉnh luôn quan tâm, ưu tiên phát triển chính sách giáo dục, đào tạo để cung cấp nguồn nhân lực chất lượng cao. Hạ tầng khu, cụm công nghiệp được đầu tư đồng bộ, mạnh mẽ, bao gồm hệ thống điện, nước, kết nối giao thông, đảm bảo sản xuất ổn định cho các doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng với việc cải cách mạnh mẽ thủ tục hành chính, các chính sách ưu đãi, hỗ trợ nhà đầu tư được lãnh đạo UBND tỉnh đặc biệt quan tâm. Những năm gần đây, Bắc Ninh luôn đứng trong top đầu cả nước về thu hút đầu tư FDI, với sự có mặt của tập đoàn lớn trên thế giới như: Samsung, Canon, Amkor, Goertek, Hana Micron.</span></span></span></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><img src=\"/documents/37632/23288878/3+%283%29.jpg/c350e422-ecfc-e210-90d1-dfb075db2ab0?t=1761639573080\" style=\"height: 527px; width: 900px;\" /></p>\n\n<p style=\"margin-bottom: 13px; text-align: center;\"><span style=\"color:#0000cd;\"><span style=\"line-height:1.3;\"><span style=\"font-size:16px;\">Các đại biểu chụp ảnh lưu niệm với đại diện&nbsp;<span style=\"font-family:Arial,Helvetica,sans-serif;\">Công ty QXQ Inc.</span></span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại buổi tiếp, ông Quan Roger Chi, Chủ tịch QXQ Inc cho biết Công ty QXQ Inc chuyên thiết kế và sản xuất công cụ kiểm thử cho các ngành điện tử, tiêu dùng, ô tô, hàng không vũ trụ, R&amp;D... Đây là lĩnh vực đang được nhiều khách hàng lớn tin tưởng, đặt hàng tìm hiểu thị trường, đầu tư, sản xuất, chuyển giao công nghệ.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Qua buổi tiếp, làm việc với lãnh đạo sở, ban, ngành của tỉnh, ông Quan Roger Chi mong muốn được trao đổi, tìm hiểu sâu hơn về quy trình thủ tục tài chính liên quan đến hoạt động đầu tư, tình hình phát triển hạ tầng, quy hoạch đất cho các khu, cụm công nghiệp, các ưu đãi đầu tư… </span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, các nội dung câu hỏi của Đoàn công tác được lãnh đạo Sở Tài chính, Ban Quản lý các KCN tỉnh trao đổi cởi mở, trực tiếp giải đáp đầy đủ, thể hiện tinh thần hợp tác, trách nhiệm, cam kết đồng hành, tạo điều kiện thuận lợi nhất để các nhà đầu tư, các tập đoàn kinh tế có môi trường đầu tư, kinh doanh thông thoáng, minh bạch, ổn định lâu dài, đóng góp cho sự phát triển kinh tế - xã hội của tỉnh./.</span></span></span></p>\n\n<p style=\"text-align:justify; margin-bottom:13px\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:14.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"></span></span></span></span></span></span></p>', '28/10/2025 15:14', 'https://bacninh.gov.vn/news/-/details/37632/-oan-cong-tac-cong-ty-qxq-inc-hoa-ky-en-tim-hieu-moi-truong-au-tu-tai-tinh-bac-ninh-29169454', '', 'Nguyễn Miền', 595, 'Sở, ngành, địa phương', 7, '', '38762', '{}', '2025-10-31 08:45:02.000000', 7, 11);
INSERT INTO `sync_articles` VALUES (51, '29177402', 'HSBC nâng dự báo tăng trưởng Việt Nam lên gần 8%, dẫn đầu ASEAN', 'HSBC nâng dự báo tăng trưởng Việt Nam lên gần 8%, dẫn đầu ASEAN', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/2/17/ktvn-1739759304211364774278-0-52-446-766-crop-17397593207611335673681.jpeg', '<p>Ngân hàng HSBC đánh giá Việt Nam đang duy trì tốc độ tăng trưởng hàng đầu khu vực. Sau khi GDP quý III/2025 tăng 8,2%, HSBC nâng dự báo tăng trưởng GDP năm 2025 lên 7,9%, cho thấy nền kinh tế đang phục hồi toàn diện.</p>', '<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"justify-content:space-between\"></span></span></span></span><span style=\"font-size:17px\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:column\"><span style=\"position:relative\"><span style=\"transition:0.3s ease-in-out\"><span style=\"z-index:96\"><span style=\"overflow-wrap:break-word\"><span style=\"cursor:default\"><span style=\"color:#333333\"><span style=\"font-family:NotoSerif\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"font-weight:400\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><span style=\"box-sizing:border-box\"><span style=\"float:right\"><span style=\"display:block\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:row\"></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span style=\"font-size:17px\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:column\"><span style=\"position:relative\"><span style=\"transition:0.3s ease-in-out\"><span style=\"z-index:96\"><span style=\"overflow-wrap:break-word\"><span style=\"cursor:default\"><span style=\"color:#333333\"><span style=\"font-family:NotoSerif\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"font-weight:400\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><span style=\"box-sizing:border-box\"><span style=\"float:right\"><span style=\"display:block\"><span style=\"box-sizing:border-box\"><span style=\"display:flex\"><span style=\"flex-direction:row\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"justify-content:space-between\"><a class=\"kbwscwlrl-thumb-avata\" href=\"https://baochinhphu.vn/hsbc-ky-vong-viet-nam-tang-truong-nhanh-nhat-asean-trong-nam-2025-102250217093019447.htm\" style=\"box-sizing:border-box; padding:0px; text-decoration:none; color:-webkit-link; flex-basis:100px; flex-shrink:0; display:inline-block\" target=\"_blank\"><img alt=\"HSBC: Kỳ vọng Việt Nam tăng trưởng nhanh nhất ASEAN trong năm 2025\" loading=\"lazy\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/2/17/ktvn-1739759304211364774278-0-52-446-766-crop-17397593207611335673681.jpeg\" style=\"box-sizing: border-box; padding: 0px; width: 100%; max-width: 100%; display: block; text-align: justify;\" title=\"HSBC nâng dự báo tăng trưởng Việt Nam lên gần 8%, dẫn đầu ASEAN- Ảnh 2.\" /></a></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style:normal\"><span style=\"font-variant:normal\"><span style=\"font-size-adjust:none\"><span style=\"font-kerning:auto\"><span style=\"font-optical-sizing:auto\"><span style=\"font-feature-settings:normal\"><span style=\"font-variation-settings:normal\"><span style=\"font-weight:normal\"><span style=\"font-stretch:normal\">Ngân hàng HSBC đánh giá Việt Nam đang duy trì tốc độ tăng trưởng hàng đầu khu vực</span></span></span></span></span></span></span></span></span></span></span></span></span></p>\n\n<figure class=\"VCSortableInPreviewMode\" style=\"box-sizing:border-box; padding:0px; display:inline-block; flex-direction:column; position:relative; transition:0.3s ease-in-out; width:776.997px; z-index:96; overflow-wrap:break-word; cursor:default; color:#333333; font-family:NotoSerif; font-size:17px; font-style:normal; font-variant-ligatures:normal; font-weight:400; text-align:start; white-space:normal; background-color:#ffffff; text-decoration-thickness:initial; text-decoration-style:initial; text-decoration-color:initial; margin-bottom:15px\" type=\"Photo\">\n<figcaption class=\"PhotoCMS_Caption\" style=\"box-sizing:border-box; padding:5px 8px; background:#e9e9e9; margin-bottom:24px\">\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"padding: 0px; text-align: justify;\">&nbsp;</p>\n</figcaption>\n</figure>\n\n<h2 style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"color:#333333\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><b style=\"box-sizing:border-box; padding:0px\"><font style=\"box-sizing:border-box; padding:0px; font-size:22px\">Đầu tư công và FDI tiếp sức tăng trưởng</font></b></span></span></span></span></span></span></span></span></span></span></span></span></h2>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Báo cáo \"Vietnam at a glance - Không ngừng sải bước\" của Bộ phận Nghiên cứu Đầu tư Toàn cầu HSBC công bố ngày 28/10 cho thấy Việt Nam tiếp tục ghi nhận mức tăng trưởng nổi bật trong khu vực. GDP quý III tăng 8,2%, vượt xa dự báo của thị trường và duy trì vị thế nền kinh tế tăng trưởng nhanh nhất Đông Nam Á. Đây là quý thứ hai liên tiếp mức tăng vượt 8%, khẳng định đà phục hồi bền vững.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Theo HSBC, kết quả này phản ánh sự phục hồi toàn diện của nền kinh tế, không chỉ trong sản xuất mà cả dịch vụ và tiêu dùng. Trong khi nhiều quốc gia ASEAN chứng kiến xuất khẩu giảm tốc do hoạt động \"đặt hàng sớm\" (frontloading) chững lại, thương mại Việt Nam vẫn tăng hai con số, cho thấy năng lực thích ứng linh hoạt và khả năng mở rộng thị trường hiệu quả.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Sản xuất công nghiệp quý III tăng 10% so với cùng kỳ; kim ngạch xuất nhập khẩu tăng gần 20%. Thặng dư thương mại gấp đôi nửa đầu năm nhờ mở rộng xuất khẩu sang các thị trường ngoài Mỹ. HSBC đánh giá đây là minh chứng cho vai trò trung tâm của Việt Nam trong chuỗi cung ứng khu vực.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Nhóm hàng điện tử, đặc biệt là thiết bị tiêu dùng và linh kiện, tiếp tục dẫn dắt tăng trưởng. Xuất khẩu sang Mỹ tăng gần 30% nhờ nhu cầu mạnh với sản phẩm phục vụ trí tuệ nhân tạo. \"Việt Nam đang trở thành mắt xích quan trọng trong chuỗi cung ứng công nghệ toàn cầu,\" báo cáo nêu.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Song song, khu vực dịch vụ và tiêu dùng nội địa phục hồi rõ nét. Doanh thu bán lẻ quý III tăng 12%, phản ánh niềm tin tiêu dùng cải thiện. Du lịch dẫn đầu khu vực với 15 triệu lượt khách quốc tế, tương đương 120% mức trước dịch. Đáng chú ý, lượng khách Trung Quốc tăng mạnh dù chưa được miễn thị thực, khẳng định sức hấp dẫn và năng lực cạnh tranh của điểm đến Việt Nam.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Theo HSBC, đầu tư công và vốn đầu tư trực tiếp nước ngoài (FDI) tiếp tục là động lực then chốt. Trong quý III, đầu tư thực tế tăng gần 10% so với cùng kỳ, nhưng tiến độ giải ngân mới đạt khoảng 50% kế hoạch năm. FDI tăng 15% so với cùng kỳ, trong đó Singapore, Trung Quốc và Mỹ là ba nhà đầu tư lớn nhất.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Cơ cấu FDI năm nay có sự thay đổi đáng chú ý: Singapore và Trung Quốc đại lục mỗi nước chiếm khoảng 25% tổng vốn đăng ký mới, trong khi thị phần của Hàn Quốc giảm, nhường chỗ cho Mỹ. Sự dịch chuyển này cho thấy Việt Nam vẫn là điểm đến an toàn, hấp dẫn giữa bối cảnh thương mại toàn cầu biến động.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Mặt khác, tiêu dùng thực tế quý III tăng hơn 8% so với cùng kỳ, cho thấy sức cầu nội địa vững vàng. Các lĩnh vực vận tải, lưu trú và du lịch tiếp tục ghi nhận tăng trưởng cao, góp phần củng cố đà phục hồi chung.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Môi trường vĩ mô duy trì ổn định: lạm phát ở mức 3,4%, tín dụng tăng cao. Chính sách tiền tệ linh hoạt giúp cân bằng giữa ổn định kinh tế và hỗ trợ tăng trưởng. Ngân hàng Nhà nước định hướng tăng tín dụng năm 2025 ở mức 19–20% nhằm tiếp sức cho nền kinh tế, nhất là khu vực sản xuất và tiêu dùng.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<h3 style=\"padding: 0px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"color:#333333\"><span style=\"font-style:normal\"><span style=\"font-variant-ligatures:normal\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\"><b style=\"box-sizing:border-box; padding:0px\"><font style=\"box-sizing:border-box; padding:0px; font-size:20px\">HSBC nâng dự báo GDP Việt Nam lên 7,9% - cao nhất ASEAN</font></b></span></span></span></span></span></span></span></span></span></span></span></span></h3>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Trước kết quả tích cực, HSBC đã nâng mạnh dự báo tăng trưởng GDP Việt Nam năm 2025 từ 6,6% lên 7,9% và năm 2026 từ 5,8% lên 6,7% - mức cao nhất trong số các nền kinh tế ASEAN. Đồng thời, ngân hàng này điều chỉnh nhẹ dự báo lạm phát lên 3,3% cho năm 2025 và 3,5% cho năm 2026.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">HSBC nhận định, Việt Nam nổi bật nhờ sự cân bằng giữa ba trụ cột: sản xuất, dịch vụ và đầu tư. Các chính sách ổn định kinh tế vĩ mô, kiểm soát giá cả và thúc đẩy hạ tầng đã giúp duy trì tốc độ tăng trưởng cao, đồng thời thu hút dòng vốn FDI chất lượng.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">Đặc biệt, việc đón đầu làn sóng công nghệ mới, nhất là trong lĩnh vực điện tử và AI, đang mở ra cơ hội để Việt Nam vươn lên trong chuỗi giá trị toàn cầu. HSBC đánh giá, nếu cải thiện tốc độ giải ngân đầu tư công và duy trì ổn định tài chính, Việt Nam hoàn toàn có thể đạt tăng trưởng 8% trong năm tới - tiến gần mục tiêu 10% cho giai đoạn 2026.</span></span></span></span></span></span></span></span></span></span></span></p>\n\n<p style=\"padding: 0px; margin-top: 16px; margin-bottom: 16px; text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"box-sizing:border-box\"><span style=\"font-style: normal; font-variant: normal; font-size-adjust: none; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-weight: 400; font-stretch: normal;\"><span style=\"color:#333333\"><span style=\"white-space:normal\"><span style=\"background-color:#ffffff\"><span style=\"text-decoration-thickness:initial\"><span style=\"text-decoration-style:initial\"><span style=\"text-decoration-color:initial\">\"Việt Nam tiếp tục chứng minh khả năng thích ứng nhanh và bền bỉ trước biến động toàn cầu. Sự kết hợp giữa năng lực sản xuất, sức tiêu dùng và chính sách ổn định đã giúp Việt Nam duy trì tốc độ phát triển hàng đầu châu Á\", các chuyên gia của HSBC nhận định.</span></span></span></span></span></span></span></span></span></span></span></p>', '28/10/2025 16:16', 'https://bacninh.gov.vn/news/-/details/37632/hsbc-nang-du-bao-tang-truong-viet-nam-len-gan-8-dan-au-asean-29177402', '', 'Theo Chinhphu.vn', 66, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (52, '29178759', 'Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục', 'Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg', '<p>Tin từ Cục Hàng không Việt Nam (Bộ Xây dựng), sau giai đoạn bị sụt giảm nghiêm trọng do đại dịch, hoạt động vận tải hàng không đã từng bước phục hồi và tăng trưởng trở lại mạnh mẽ.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg\" target=\"_blank\" title=\"Dự kiến, năm 2025, hàng không Việt Nam sẽ vận chuyển khoảng 84 triệu khách\"><img alt=\"Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg\" h=\"734\" id=\"img_907168993063587840\" loading=\"lazy\" photoid=\"907168993063587840\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/54bd04137080fddea491-1761549940292625412061.jpg\" style=\"width: 900px; height: 543px;\" title=\"Vượt qua khó khăn, hàng không Việt Nam phục hồi ngoạn mục- Ảnh 1.\" type=\"photo\" w=\"1216\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự kiến, năm 2025, hàng không Việt Nam sẽ vận chuyển khoảng 84 triệu khách</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2021, tổng thị trường vận chuyển hàng không chỉ đạt gần 16 triệu hành khách; đến năm 2024, con số này đã tăng trưởng gấp gần 5 lần, đạt hơn 75 triệu hành khách.&nbsp;Dự kiến, năm 2025, hàng không Việt Nam sẽ vận chuyển khoảng 84 triệu khách.</span></span></span></p>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày càng nhiều hành khách lựa chọn di chuyển bằng đường hàng không</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cục Hàng không Việt Nam nhìn nhận: Việc ngày càng nhiều khách lựa chọn hàng không làm phương thức di chuyển cho thấy nhu cầu đi lại, giao thương quốc tế tăng cao và vai trò tích cực của hoạt động vận tải hàng không, góp phần vào sự phát triển kinh tế - xã hội, du lịch Việt Nam.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về mở rộng mạng bay quốc tế, số liệu từ Cục Hàng không Việt Nam cho thấy đến năm 2025, mạng đường bay quốc tế của Việt Nam đã không những được khôi phục hoàn toàn mà còn tăng từ 130 đường bay (trước đại dịch COVID-19) lên con số 150 đường bay kết nối với hơn 30 quốc gia và vùng lãnh thổ.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều đường bay thẳng đến các thị trường xa như châu Âu, Bắc Mỹ đã được Cục Hàng không Việt Nam nghiên cứu và ký kết các hiệp định mới, tạo tiền đề cho việc khai thác trong tương lai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong nước, mạng bay nội địa được tối ưu hóa, tần suất khai thác trên các đường bay trục chính tăng lên và các hãng hàng không cũng liên tục mở mới các đường bay đến các địa phương có tiềm năng du lịch.</span></span></span></p>\n\n<h3 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thêm hãng bay, hành khách thêm lựa chọn</span></span></span></h3>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bên cạnh các hãng hàng không Việt Nam đã tham gia thị trường trước đó (Vietnam Airlines, Vietjet Air, Pacific Airlines, Bamboo Airways), một điểm sáng thể hiện sức sống và tiềm năng của thị trường hàng không Việt Nam là sự ra đời của hai hãng hàng không mới: VietravelAirlines và SunPhuQuoc Airways.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cục trưởng Cục Hàng không Việt Nam Uông Việt Dũng đánh giá: Việc ra đời của hai hãng hàng không mới cho thấy sức hấp dẫn của thị trường hàng không Việt Nam. Đồng thời, mở ra những cơ hội phát triển mới, góp phần đa dạng hóa thị trường, tạo ra sự cạnh tranh lành mạnh, thúc đẩy các hãng hàng không cải thiện chất lượng dịch vụ, đa dạng hóa sản phẩm và giảm giá vé đến tay hành khách. Đồng thời, hoạt động vận tải hàng không phát triển cũng sẽ có tác động lan toả, thúc đẩy việc tiếp tục đầu tư, phát triển hạ tầng giao thông và kích thích du lịch góp phần phát triển kinh tế địa phương và khu vực.&nbsp;</span></span></span></p>', '27/10/2025 16:31', 'https://bacninh.gov.vn/news/-/details/37632/vuot-qua-kho-khan-hang-khong-viet-nam-phuc-hoi-ngoan-muc-29178759', '', 'Theo Chinhphu.vn', 33, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (53, '29178428', 'Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương', 'Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg', '<p>Ngày thứ hai của Hội chợ mùa Thu lần thứ nhất – năm 2025 chứng kiến sự chuyển dịch rõ rệt trong hoạt động của các doanh nghiệp: Từ thu hút khách tham quan sang tăng cường kết nối, tìm kiếm cơ hội hợp tác và mở rộng giao thương.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg\" target=\"_blank\" title=\"Các gian hành công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong\"><img alt=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg\" h=\"1331\" id=\"img_907156085085904896\" loading=\"lazy\" photoid=\"907156085085904896\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/nam8150-17615468600521995114496.jpg\" style=\"width: 900px; height: 599px;\" title=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các gian hành công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Theo thống kê sơ bộ của Ban Tổ chức, trong 2 ngày đầu, đã có hơn 40 biên bản ghi nhớ và thỏa thuận hợp tác được ký kết, hàng chục doanh nghiệp đạt doanh số vượt kỳ vọng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Không chỉ là nơi trưng bày sản phẩm, Hội chợ mà còn phản ánh sự chuyên nghiệp trong cách tiếp cận thị trường của doanh nghiệp Việt. Nhiều gian hàng thể hiện năng lực quản trị, công nghệ, quy trình sản xuất và dịch vụ hậu mãi, hướng tới tiêu chuẩn quốc tế. Đây cũng là cơ hội để doanh nghiệp giới thiệu năng lực sản xuất, chất lượng sản phẩm và khả năng tham gia chuỗi cung ứng toàn cầu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một số doanh nghiệp tham gia Hội chợ đang tập trung vào việc nâng cao tiêu chuẩn sản xuất và quản lý chất lượng, nhằm phục vụ cả thị trường trong nước lẫn xuất khẩu. Việc chuẩn hóa quy trình, áp dụng tiêu chuẩn quốc tế và nâng cấp dịch vụ hậu mãi được coi là các yếu tố then chốt để tăng sức cạnh tranh và xây dựng niềm tin với khách hàng, đặc biệt là đối tác nước ngoài.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các gian hàng được đầu tư bài bản hơn, từ thiết kế, trưng bày sản phẩm đến đội ngũ tư vấn và dịch vụ hậu mãi, nhằm tạo ấn tượng và thúc đẩy hợp tác lâu dài. Đây là minh chứng cho việc doanh nghiệp Việt ngày càng nhìn nhận hội chợ như một kênh xúc tiến thương mại chuyên nghiệp, gắn với chiến lược phát triển dài hạn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại gian hàng của Dekko, đại diện doanh nghiệp cho biết lượng khách tham quan khá đông, tập trung vào các sản phẩm nhựa và thiết bị dân dụng. Khách hàng trung niên chủ yếu quan tâm đến sản phẩm phục vụ xây dựng và vật tư điện nước, trong khi nhóm khách lớn tuổi chú ý hơn đến thiết bị dân dụng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">\"Hội chợ là dịp để chúng tôi giới thiệu năng lực sản xuất, khả năng cung ứng và chính sách hậu mãi, đồng thời tạo cơ hội kết nối với các đối tác trong nước và quốc tế, hướng tới mở rộng giao thương trong khu vực\", đại diện Dekko cho biết.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8041-17615468075241151102156.jpg\" target=\"_blank\" title=\"Đông đảo du khách tham quan các gian hàng công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong\"><img alt=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/nam8041-17615468075241151102156.jpg\" h=\"1331\" id=\"img_907155874622853120\" loading=\"lazy\" photoid=\"907155874622853120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/nam8041-17615468075241151102156.jpg\" style=\"width: 900px; height: 599px;\" title=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 2.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đông đảo du khách tham quan các gian hàng công nghiệp tại Hội chợ - Ảnh: VGP/Vũ Phong</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Một trong những điểm nổi bật của Hội chợ là sự chuyển dịch rõ ràng trong cách doanh nghiệp nhìn nhận hoạt động xúc tiến thương mại. Không còn dừng ở việc \"đem hàng ra bán\", nhiều doanh nghiệp đã coi đây là \"phòng trưng bày năng lực\", nơi thể hiện bản sắc, trình độ và định hướng phát triển.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện Công ty Cổ phần Thép Nam Kim, cho rằng: \"Hội chợ năm nay có quy mô cực lớn, lượng khách rất đông cả trong và ngoài nước. Đây là cơ hội tuyệt vời để Công ty quảng bá dòng sản phẩm mới. Chúng tôi mong muốn Bộ Công Thương tiếp tục duy trì và mở rộng các \"sân chơi xúc tiến thương mại quy mô lớn\", tạo điều kiện cho doanh nghiệp Việt tiếp cận khách hàng chuyên ngành, mở rộng hợp tác quốc tế\".</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/a-17615464195772033874226.jpg\" target=\"_blank\" title=\"Các gian hàng bày bán hàng Việt thu hút đông đảo người tiêu dùng mua sắm - Ảnh: VGP/Vũ Phong\"><img alt=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/27/a-17615464195772033874226.jpg\" h=\"1500\" id=\"img_907154236142616576\" loading=\"lazy\" photoid=\"907154236142616576\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/27/a-17615464195772033874226.jpg\" style=\"width: 900px; height: 675px;\" title=\"Ngày thứ hai Hội chợ mùa Thu 2025: Doanh nghiệp tập trung kết nối giao thương- Ảnh 3.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các gian hàng bày bán hàng Việt thu hút đông đảo người tiêu dùng mua sắm - Ảnh: VGP/Vũ Phong</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Niềm tự hào hàng Việt</b></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày thứ 2 Hội chợ, không gian tại đây vẫn ngập tràn âm thanh và sắc màu của mùa thu Hà Nội. Các gian hàng được trang trí bắt mắt, mang đậm bản sắc vùng miền: Từ những gian hàng nông sản vùng cao Tây Bắc, sản phẩm thủ công mỹ nghệ miền Trung, đến khu vực hàng tiêu dùng và thực phẩm chế biến của các tập đoàn, doanh nghiệp lớn. Không khí mua sắm tấp nập, nhộn nhịp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đại diện WinMart cho biết, chỉ trong hai ngày đầu, lượng khách đến mua sắm tăng gấp đôi so với dự kiến. \"Điều khiến chúng tôi vui nhất là người tiêu dùng đến không chỉ để mua hàng, mà còn để trải nghiệm tinh thần Người Việt Nam ưu tiên dùng hàng Việt Nam\", đại diện WinMart nói.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ cũng quy tụ hàng loạt thương hiệu OCOP 4 sao, 5 sao, sản phẩm đặc sản vùng miền, từ trà La Bằng (Thái Nguyên), mật ong Mường Lát (Thanh Hóa), đến tinh dầu quế Bắc Giang, khẳng định vị thế hàng Việt trên bản đồ tiêu dùng trong nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội chợ mùa Thu lần thứ nhất - 2025 sẽ diễn ra đến ngày 4/11/2025 tại Trung tâm Triển lãm Quốc gia Việt Nam (VEC) - Đông Anh - Hà Nội.</span></span></span></p>', '27/10/2025 16:27', 'https://bacninh.gov.vn/news/-/details/37632/ngay-thu-hai-hoi-cho-mua-thu-2025-doanh-nghiep-tap-trung-ket-noi-giao-thuong-29178428', '', 'Theo Chinhphu.vn', 34, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (54, '29029501', 'Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình', 'Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg', '<p>Là nước láng giềng của Campuchia và Thái Lan và là thành viên ASEAN, Việt Nam quan tâm và hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình ngày 26/10/2025.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg\" target=\"_blank\" title=\"Người Phát ngôn Bộ Ngoại giao Việt Nam Phạm Thu Hằng\"><img alt=\"Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg\" h=\"570\" id=\"img_906862359364214784\" loading=\"lazy\" photoid=\"906862359364214784\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/nguoi-phat-ngon-bng-pham-thu-hang-17614768331981122969605.jpg\" style=\"width: 854px; height: 570px;\" title=\"Việt Nam hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình- Ảnh 1.\" type=\"photo\" w=\"854\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Người Phát ngôn Bộ Ngoại giao Việt Nam Phạm Thu Hằng</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày 26/10/2025, trả lời câu hỏi của phóng viên đề nghị cho biết phản ứng của Việt Nam trước việc Campuchia và Thái Lan ký kết văn kiện hòa bình nhân dịp tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các hội nghị cấp cao liên quan được tổ chức tại Malaysia, Người Phát ngôn Bộ Ngoại giao Việt Nam Phạm Thu Hằng nêu rõ:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">“Là nước láng giềng của Campuchia và Thái Lan và là thành viên ASEAN, Việt Nam quan tâm và hoan nghênh Campuchia và Thái Lan ký văn kiện hòa bình ngày 26/10/2025. Đây là bước tiến quan trọng, tích cực, thể hiện cam kết của hai nước đối với hòa bình, hợp tác và phát triển, phù hợp với Hiến chương ASEAN và Hiệp ước Thân thiện và Hợp tác ở Đông Nam Á (TAC). Chúng tôi đánh giá cao nỗ lực của các nước, trong đó có Malaysia, Chủ tịch ASEAN 2025 và Thủ tướng Anwar Ibrahim, Hoa Kỳ và Tổng thống Donald Trump, và các bên liên quan trong quá trình tìm kiếm một giải pháp hòa bình cho vấn đề.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam tin rằng văn kiện hòa bình sẽ tạo cơ sở để củng cố lòng tin và hướng tới giải pháp hòa bình lâu dài. Việt Nam tiếp tục tích cực tham gia các nỗ lực chung của ASEAN hỗ trợ Campuchia và Thái Lan triển khai đầy đủ, hiệu quả văn kiện này.”./.</span></span></span></p>', '27/10/2025 08:00', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-hoan-nghenh-campuchia-va-thai-lan-ky-van-kien-hoa-binh-29029501', '', 'Theo Chinhphu.vn', 32, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (55, '29179537', 'Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng', 'Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg', '<p>Theo thông tin từ Bộ Công Thương, ngày 26/10, Việt Nam và Hoa Kỳ đã đồng ý công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng, công bằng và cân bằng (Tuyên bố chung) nhân dịp Thủ tướng Chính phủ Phạm Minh Chính và Tổng thống Donald Trump tham dự Hội nghị Cấp cao ASEAN tổ chức từ...', '<figure type=\"Photo\">\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính có cuộc tiếp xúc ngắn với Tổng thống Hoa Kỳ Donald Trump bên lề Hội nghị Cấp cao ASEAN - Hoa Kỳ - Ảnh: VGP\"><img alt=\"Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg\" h=\"1334\" id=\"img_906864523261059072\" loading=\"lazy\" photoid=\"906864523261059072\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/img8785-17614723994521741481990-17614773495421156056497.jpg\" style=\"width: 900px; height: 600px;\" title=\"Việt Nam, Hoa Kỳ công bố Tuyên bố chung về Khuôn khổ Hiệp định Thương mại đối ứng- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính có cuộc tiếp xúc ngắn với Tổng thống Hoa Kỳ Donald Trump bên lề Hội nghị Cấp cao ASEAN - Hoa Kỳ - Ảnh: VGP</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuyên bố chung là văn bản mà Việt Nam và Hoa Kỳ thống nhất đưa ra để thể hiện kết quả về đàm phán thương mại đối ứng giữa hai nước cho đến nay cũng như để ghi nhận nỗ lực của các cơ quan chính phủ, doanh nghiệp Việt Nam và Hoa Kỳ trong việc xây dựng quan hệ kinh tế, thương mại trên cơ sở cân bằng, ổn định và bền vững, phù hợp với mối quan hệ Đối tác Chiến lược Toàn diện Việt Nam - Hoa Kỳ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tuyên bố chung đề cập đến các nội dung chính của Hiệp định Thương mại đối ứng, công bằng và cân bằng, theo đó cả Việt Nam và Hoa Kỳ sẽ cùng hợp tác trên tinh thần xây dựng để giải quyết mối quan tâm của cả hai bên liên quan đến các rào cản phi thuế quan, thống nhất các cam kết liên quan đến thương mại số, dịch vụ và đầu tư; thảo luận về sở hữu trí tuệ, phát triển bền vững cũng như tăng cường hợp tác để nâng cao khả năng chống chịu của chuỗi cung ứng…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong thời gian tới, hai bên sẽ tiếp tục thảo luận và triển khai các công việc tiếp theo hướng đến hoàn thành Hiệp định Thương mại đối ứng, công bằng và cân bằng trên nguyên tắc cởi mở, xây dựng, bình đẳng, tôn trọng độc lập, tự chủ, thể chế chính trị, cùng có lợi và cân nhắc tới trình độ phát triển của nhau.&nbsp;</span></span></span></p>\n\n<p id=\"\" style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xem toàn văn Tuyên bố chung&nbsp;</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/2025-10-25-us-vn-joint-sttement-on-reciprocal-trade-finall-v-version-176147713457454924216.docx\" ref=\"nofollow\" rel=\"nofollow\" target=\"_blank\" title=\"tại đây\"><i>tại đây</i><i></i></a></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Từ cuối tháng 4/2025, Việt Nam và Hoa Kỳ đã tổ chức nhiều phiên đàm phán thương mại đối ứng ở cả cấp kỹ thuật và cấp Bộ trưởng. Đoàn đàm phán Chính phủ Việt Nam do Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên làm Trưởng đoàn, thành viên gồm lãnh đạo và cán bộ của các bộ và cơ quan: Công Thương, Ngoại giao, Công an, Tài chính, Tư pháp, Nông nghiệp và Môi trường, Khoa học Công nghệ, Nội vụ, Xây dựng, Y tế, Ngân hàng Nhà nước và Đại sứ quán Việt Nam tại Hoa Kỳ. Nhiều phiên đàm phán trực tiếp và trực tuyến đã diễn ra giữa Bộ trưởng Bộ Công Thương Nguyễn Hồng Diên với Trưởng Cơ quan Đại diện thương mại Hoa Kỳ (USTR) Jamieson Greer và Bộ trưởng Thương mại Hoa Kỳ Howard Lutnick.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Rạng sáng ngày 1/8/2025 (giờ Việt Nam), Nhà Trắng đã đăng tải Sắc lệnh của Tổng thống Donald Trump về việc điều chỉnh mức thuế đối ứng, theo đó Hoa Kỳ điều chỉnh mức thuế đối ứng cho 69 nước và vùng lãnh thổ được liệt kê trong Phụ lục I. Theo Phụ lục này, mức thuế đối ứng dành cho Việt Nam giảm từ 46% xuống còn 20%.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Theo số liệu của Hải quan Việt Nam tính đến hết tháng 9 năm 2025, tổng kim ngạch trao đổi thương mại song phương đạt khoảng 126,4 tỷ USD.</i></span></span></span></p>', '27/10/2025 08:00', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-hoa-ky-cong-bo-tuyen-bo-chung-ve-khuon-kho-hiep-inh-thuong-mai-oi-ung-29179537', '', 'Theo Chinhphu.vn', 33, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (56, '29180021', 'Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng', 'Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg', '<p>Ngành sầu riêng Việt Nam đang ở thời điểm vừa có tiềm năng lớn, vừa đối mặt nhiều thách thức. Việc các phòng kiểm nghiệm được GACC công nhận hoạt động tốt chính là một khâu then chốt để mở lại \"cánh cửa\" thị trường Trung Quốc - thị trường lớn nhất hiện nay.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg\" target=\"_blank\" title=\"Dự báo kim ngạch xuất khẩu sầu riêng năm 2025 có thể phục hồi đạt mốc 5 tỷ USD - Ảnh: VGP/Đỗ Hương\"><img alt=\"Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg\" h=\"797\" id=\"img_906825742407507968\" loading=\"lazy\" photoid=\"906825742407507968\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/5599286768078686955533195143800408381951779n-17614682038381347150210.jpg\" style=\"width: 900px; height: 521px;\" title=\"Nâng cao chất lượng kiểm nghiệm để phục vụ xuất khẩu sầu riêng- Ảnh 1.\" type=\"photo\" w=\"1375\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Dự báo kim ngạch xuất khẩu sầu riêng năm 2025 có thể phục hồi đạt mốc 5 tỷ USD - Ảnh: VGP/Đỗ Hương</span></span></span></p>\n</figcaption>\n</figure>\n\n<h2 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Siết chặt quy trình kiểm nghiệm, bảo vệ uy tín hàng Việt</span></span></span></h2>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Sau giai đoạn bùng nổ năm 2024 với kim ngạch 3,3 tỷ USD, sầu riêng trở thành \"ngôi sao\" của ngành trái cây Việt Nam, chiếm gần 46% tổng giá trị xuất khẩu rau quả cả nước. Trong đó, thị trường Trung Quốc chiếm tới 97% tổng lượng sầu riêng xuất khẩu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Tuy nhiên, bước sang năm 2025, ngành hàng này đối mặt cú sốc lớn. Chỉ trong 4 tháng đầu năm, giá trị xuất khẩu sầu riêng của Việt Nam chỉ đạt khoảng 183 triệu USD, giảm tới hơn 60% so với cùng kỳ năm trước. Nguyên nhân chủ yếu đến từ việc Trung Quốc siết chặt kiểm tra an toàn thực phẩm, truy xuất nguồn gốc và tăng cường xét nghiệm dư lượng kim loại nặng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Một phần khác đến từ năng lực kiểm nghiệm trong nước chưa ổn định, dẫn tới thời gian chờ kết quả kéo dài, làm chậm tiến độ giao hàng. Nhiều doanh nghiệp phản ánh việc chờ kết quả kiểm nghiệm khiến sầu riêng chín vượt thời hạn bảo quản, buộc phải tiêu thụ nội địa với giá thấp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Trước những biến động mạnh của thị trường sầu riêng, ngày 24/10 vừa qua, Thứ trưởng Bộ Nông nghiệp và Môi trường Hoàng Trung vừa yêu cầu các phòng kiểm nghiệm được Tổng cục Hải quan Trung Quốc (GACC) công nhận đủ điều kiện phải hoạt động hết công suất, bảo đảm thông suốt cho hoạt động xuất khẩu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo chỉ đạo của Thứ trưởng Hoàng Trung, Cục Chất lượng, Chế biến và Phát triển thị trường cần rà soát toàn bộ các trung tâm kiểm nghiệm đang được GACC công nhận; xác định rõ đơn vị còn hoạt động, đơn vị tạm dừng, cũng như năng lực kiểm tra thực tế với các chỉ tiêu đặc biệt như Cadimi và Vàng O.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Thứ trưởng nhấn mạnh, các trung tâm kiểm nghiệm phải thực hiện nghiêm túc, chính xác và nhanh chóng toàn bộ quy trình, từ lấy mẫu, tiếp nhận, phân tích đến trả kết quả. \"Việc kiểm nghiệm phải tránh tối đa sai sót, vì chỉ một lỗi nhỏ cũng có thể làm ảnh hưởng uy tín của hàng sầu riêng Việt Nam tại thị trường quốc tế,\" ông Hoàng Trung nói.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo ông Phạm Văn Duy, Phó Cục trưởng Cục Chất lượng, Chế biến và Phát triển thị trường, hiện Việt Nam có 24 phòng kiểm nghiệm được GACC công nhận phục vụ kiểm tra dư lượng Cadimi và Vàng O, với tổng công suất xử lý khoảng 3.200 mẫu/ngày. Về lý thuyết, con số này đủ đáp ứng nhu cầu thực tế. Tuy nhiên, nhiều phòng thử nghiệm đang tạm ngừng do bảo trì, sửa chữa hoặc chờ đánh giá công nhận lại, khiến hệ thống bị \"nghẽn mạch\" cục bộ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Việc Trung Quốc yêu cầu kiểm soát nghiêm ngặt chỉ tiêu Cadimi (kim loại nặng tích tụ trong đất) và Vàng O (phẩm màu bị cấm sử dụng trong nông sản) đã tạo áp lực lớn cho toàn chuỗi xuất khẩu. Nếu quy trình kiểm nghiệm trong nước không đảm bảo, doanh nghiệp có thể bị trả hàng hoặc đình chỉ thông quan, kéo theo thiệt hại lớn cho cả ngành.</span></span></span></p>\n\n<h4 style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Cơ hội phục hồi từ xuất khẩu chế biến và đa dạng hóa thị trường</span></span></span></h4>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Dù gặp khó với hàng tươi, xuất khẩu sầu riêng chế biến, đông lạnh của Việt Nam lại đang tăng mạnh. Trong quý I/2025, Việt Nam xuất khoảng 8.700 tấn sầu riêng đông lạnh, tăng hơn 60% so với cùng kỳ 2024, đạt giá trị hơn 31 triệu USD.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Các chuyên gia nhận định, đây là hướng đi khả thi giúp ngành giảm phụ thuộc vào thị trường Trung Quốc và kéo dài thời gian tiêu thụ sản phẩm. Cùng với đó, nhu cầu sầu riêng tại các thị trường mới như Mỹ, Nhật Bản, Hàn Quốc, UAE… đang tăng nhanh, mở ra cơ hội mở rộng xuất khẩu cho Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo thống kê của Bộ Nông nghiệp và Môi trường, đến nay Việt Nam đã được Trung Quốc phê duyệt 829 mã vùng trồng và 131 cơ sở đóng gói sầu riêng. Bộ cũng đang tiếp tục làm việc với phía bạn để mở rộng thêm vùng trồng, đồng thời thúc đẩy công nhận thêm các phòng kiểm nghiệm đạt chuẩn nhằm giảm tải cho hệ thống hiện nay.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Nếu các \"nút thắt\" về kiểm nghiệm, truy xuất nguồn gốc và chất lượng được tháo gỡ, nhiều chuyên gia dự báo kim ngạch xuất khẩu sầu riêng năm 2025 có thể phục hồi đạt mốc 5 tỷ USD, tiếp tục khẳng định vị thế của Việt Nam trên bản đồ sầu riêng thế giới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Theo Thứ trưởng Hoàng Trung, để tận dụng cơ hội này, các đơn vị kiểm nghiệm cần \"vào guồng\" ngay, hoạt động hết công suất, nâng cao tính chính xác và tốc độ trả kết quả. Bộ Nông nghiệp và Môi trường yêu cầu Cục Chất lượng, Chế biến và Phát triển thị trường phối hợp chặt với các địa phương, doanh nghiệp, đảm bảo mẫu kiểm nghiệm được xử lý kịp thời, tránh dồn ứ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Bên cạnh đó, Bộ cũng yêu cầu tăng cường đào tạo và hướng dẫn doanh nghiệp, hợp tác xã, nhà vườn về quy trình kiểm soát chất lượng, sử dụng phân bón hợp lý để tránh tích tụ Cadimi, tuân thủ quy định về mã số vùng trồng và cơ sở đóng gói.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Đồng thời, ngành nông nghiệp cũng đang đẩy nhanh chuyển đổi sang mô hình sản xuất xanh, giảm phát thải, tăng giá trị xuất khẩu bền vững, phù hợp với xu hướng tiêu dùng và yêu cầu nhập khẩu của các thị trường lớn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Từ câu chuyện của sầu riêng có thể thấy rõ, năng lực kiểm nghiệm không chỉ là vấn đề kỹ thuật mà là \"chìa khóa chiến lược\" quyết định thành bại của xuất khẩu nông sản. Khi các phòng thí nghiệm vận hành hiệu quả, quy trình kiểm soát chất lượng chặt chẽ, hàng Việt Nam mới đủ sức cạnh tranh, đáp ứng tiêu chuẩn cao của những thị trường khó tính.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><span style=\"font-size:18px;\">Việc Bộ Nông nghiệp và Môi trường yêu cầu hệ thống kiểm nghiệm hoạt động hết công suất không chỉ nhằm tháo gỡ khó khăn trước mắt, mà còn hướng tới xây dựng chuỗi giá trị nông sản an toàn - minh bạch - bền vững, để trái sầu riêng Việt Nam không chỉ đứng vững tại Trung Quốc mà .</span></span></span></p>', '26/10/2025 16:40', 'https://bacninh.gov.vn/news/-/details/37632/nang-cao-chat-luong-kiem-nghiem-e-phuc-vu-xuat-khau-sau-rieng-29180021', '', 'Theo Chinhphu.vn', 32, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (57, '29030402', 'Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7', 'Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg', '<p>Sáng 26/10, tại Trụ sở Trung ương Đảng, Tổng Bí thư Tô Lâm đã tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7.</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/viet-nam-hoc-261025-10-1761463228451-1761463228859719132181.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và các đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7 - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 1.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/viet-nam-hoc-261025-10-1761463228451-1761463228859719132181.jpg\" h=\"489\" height=\"489\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/viet-nam-hoc-261025-10-1761463228451-1761463228859719132181.jpg\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 1.\" type=\"photo\" w=\"665\" width=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và các đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7 - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, Tổng Bí thư Tô Lâm cho rằng sự có mặt đông đảo của các nhà Việt Nam học trong nước và quốc tế thể hiện một thông điệp quan trọng: Việt Nam không chỉ là đối tượng nghiên cứu, mà đã trở thành một đối tác trí tuệ của các nhà Việt Nam học.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lịch sử hình thành, xây dựng, bảo vệ và phát triển dân tộc liên tục hàng nghìn năm đã tạo nên bản sắc đặc biệt, một nền văn hiến lâu đời, lấy lòng dân làm gốc, lấy đạo lý nhân nghĩa làm nền, lấy tinh thần độc lập và tự chủ làm mạch sống. Văn hóa Việt Nam là kết tinh của bản sắc dân tộc và sự giao thoa với nhân loại; là nền tảng tinh thần của xã hội, là sức mạnh mềm, là “căn cước phát triển” của quốc gia. Sức sống ấy đã giúp dân tộc vượt qua chiến tranh, tái sinh sau đổ nát và bước vào thời kỳ phát triển mới với tư thế ngày càng tự tin.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh hai dấu mốc lịch sử mang tính bước ngoặt của dân tộc: Trước tiên là sự ra đời của Đảng Cộng sản Việt Nam năm 1930, lãnh đạo nhân dân Việt Nam giành độc lập, thống nhất đất nước, mở ra con đường phát triển theo định hướng xã hội chủ nghĩa; tiếp theo là Đổi mới - quyết định chiến lược, tạo ra bước phát triển nhảy vọt, đưa Việt Nam vươn lên thành nền kinh tế năng động, hội nhập sâu, tham gia tích cực vào các chuỗi giá trị khu vực và toàn cầu.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt3-261025-1761463229829-1761463229971909701010.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm cho rằng sự có mặt đông đảo của các nhà Việt Nam học trong nước và quốc tế thể hiện một thông điệp quan trọng: Việt Nam không chỉ là đối tượng nghiên cứu, mà đã trở thành một đối tác trí tuệ của các nhà Việt Nam học - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 2.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt3-261025-1761463229829-1761463229971909701010.jpg\" h=\"464\" height=\"464\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/tbt3-261025-1761463229829-1761463229971909701010.jpg\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 2.\" type=\"photo\" w=\"665\" width=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm cho rằng sự có mặt đông đảo của các nhà Việt Nam học trong nước và quốc tế thể hiện một thông điệp quan trọng: Việt Nam không chỉ là đối tượng nghiên cứu, mà đã trở thành một đối tác trí tuệ của các nhà Việt Nam học - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đánh giá cao chủ đề hội thảo: \"Việt Nam: phát triển bền vững trong kỷ nguyên mới\", Tổng Bí thư nhấn mạnh Việt Nam chủ trương phát triển dựa trên 3 trụ cột gắn bó chặt chẽ:&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ nhất, phát triển thể chế, chính sách, quản trị quốc gia theo hướng tự chủ chiến lược, hiện đại, minh bạch, liêm chính, hiệu lực, hiệu quả; xây dựng Nhà nước pháp quyền xã hội chủ nghĩa của nhân dân, do nhân dân, vì nhân dân, một Nhà nước kiến tạo phát triển.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai, phát triển con người Việt Nam toàn diện; tài nguyên quý nhất của Việt Nam là 106 triệu người Việt Nam cần cù, sáng tạo, giàu lòng yêu nước, giàu ý thức cộng đồng, ham học hỏi và biết vươn lên trong hoàn cảnh khó khăn.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ ba, phát triển kinh tế xanh, kinh tế tuần hoàn, kinh tế tri thức, kinh tế số, gắn với khoa học - công nghệ và đổi mới sáng tạo, chuyển đổi số. Đặc biệt, phát triển bền vững không chỉ là vấn đề kinh tế và môi trường mà còn là vấn đề văn hóa, xã hội, con người, đạo lý.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư đánh giá&nbsp;cao các nhà khoa học, học giả đã đi sâu vào những chủ đề có tính cấu trúc, có ý nghĩa chiến lược đối với tương lai đất nước; khẳng định trong quá trình hoạch định đường lối, chủ trương, chính sách phát triển đất nước, Đảng và Nhà nước luôn lắng nghe những ý kiến phản biện khoa học độc lập, nghiêm túc, thiện chí.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh khát vọng rất rõ ràng, cụ thể, nhất quán xây dựng Việt Nam trở thành một nước phát triển, có thu nhập cao, theo định hướng xã hội chủ nghĩa vào giữa thế kỷ 21, khẳng định đó là lời cam kết trước nhân dân Việt Nam hôm nay và trước thế hệ mai sau, cũng là cam kết trước bạn bè quốc tế: Việt Nam muốn lớn mạnh bằng tri thức, bằng sáng tạo, bằng hợp tác bình đẳng và tôn trọng lẫn nhau; Việt Nam muốn đóng góp vào tiến bộ chung của nhân loại, cùng tạo ra thành quả qua lao động sáng tạo và cùng hưởng thụ những thành quả đó.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt2-261025-1761463230531-17614632306961047508387.jpg\" target=\"_blank\" title=\"Tổng Bí thư nhấn mạnh khát vọng rất rõ ràng, cụ thể, nhất quán xây dựng Việt Nam trở thành một nước phát triển, có thu nhập cao, theo định hướng xã hội chủ nghĩa vào giữa thế kỷ 21 - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 3.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/tbt2-261025-1761463230531-17614632306961047508387.jpg\" h=\"509\" height=\"509\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/tbt2-261025-1761463230531-17614632306961047508387.jpg\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 3.\" type=\"photo\" w=\"665\" width=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh khát vọng rất rõ ràng, cụ thể, nhất quán xây dựng Việt Nam trở thành một nước phát triển, có thu nhập cao, theo định hướng xã hội chủ nghĩa vào giữa thế kỷ 21 - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư khẳng định đất nước bước vào giai đoạn phát triển mới với tư duy mới, nhưng với những giá trị không bao giờ thay đổi. Một là, độc lập dân tộc, chủ quyền quốc gia, toàn vẹn lãnh thổ là thiêng liêng, là bất khả xâm phạm. Hai là, hạnh phúc của nhân dân, mọi quyết sách đều hướng tới nâng cao đời sống thực của người dân. Ba là, sức mạnh Việt Nam trước hết là sức mạnh đại đoàn kết toàn dân tộc.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong giai đoạn phát triển mới, đại đoàn kết phải được mở rộng hơn nữa, bao gồm đội ngũ trí thức trong và ngoài nước, cộng đồng doanh nghiệp, đội ngũ văn nghệ sĩ, thanh niên, phụ nữ, đồng bào các dân tộc anh em, các tôn giáo, người Việt Nam ở nước ngoài, bạn quốc tế gắn bó với Việt Nam bằng thiện chí và sự tôn trọng lẫn nhau.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư cảm ơn cộng đồng các nhà Việt Nam học đã dành tâm huyết cho Việt Nam nhiều năm qua, bày tỏ mong muốn các chuyên gia, học giả tiếp tục đồng hành, không chỉ bằng tình cảm mà bằng tri thức khoa học, phân tích chính sách dựa trên chứng cứ khoa học, khuyến nghị cụ thể, thiết thực, có thể triển khai được. Đồng thời, Tổng Bí thư kỳ vọng và đặt hàng các nghiên cứu về Việt Nam sẽ ngày càng gắn với các vấn đề đang đặt ra một cách cấp bách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhất trí tổ chức thường xuyên hơn hội thảo quốc tế Việt Nam học ở Việt Nam và nước ngoài, thành lập Quỹ Việt Nam trong năm nay; đề nghị giới nghiên cứu quốc tế, các nghiên cứu sinh, các nhà khoa học đến Việt Nam nhiều hơn, ở lại Việt Nam lâu hơn, làm việc cùng các đồng nghiệp Việt Nam bình đẳng hơn và lắng nghe tiếng nói từ cơ sở, từ địa phương, từ cộng đồng, chứ không chỉ nhìn Việt Nam qua các số liệu tổng hợp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Với khát vọng rất lớn, nhưng cũng với tâm thế khiêm tốn, cầu thị, lắng nghe, Tổng Bí thư khẳng định Việt Nam luôn coi trọng đối thoại, hợp tác, tôn trọng luật pháp quốc tế, đề cao chủ nghĩa đa phương hiệu quả, công bằng để kiến tạo một Việt Nam độc lập, tự cường, đổi mới sáng tạo, phát triển nhanh và bền vững trong kỷ nguyên mới.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg\" target=\"_blank\" title=\"Tổng Bí thư khẳng định Việt Nam luôn coi trọng đối thoại, hợp tác, tôn trọng luật pháp quốc tế, đề cao chủ nghĩa đa phương hiệu quả, công bằng để kiến tạo một Việt Nam độc lập, tự cường, đổi mới sáng tạo, phát triển nhanh và bền vững trong kỷ nguyên mới - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg\" h=\"510\" id=\"img_906806440988131328\" loading=\"lazy\" photoid=\"906806440988131328\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/vnapotaltongbithutiepdaibieuduhoithaoquoctevietnamhoclanthu7stand-1761463503090695907980.jpg\" style=\"width: 665px; height: 510px;\" title=\"Tổng Bí thư Tô Lâm tiếp Đoàn đại biểu tham dự Hội thảo quốc tế Việt Nam học lần thứ 7- Ảnh 4.\" type=\"photo\" w=\"665\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư khẳng định Việt Nam luôn coi trọng đối thoại, hợp tác, tôn trọng luật pháp quốc tế, đề cao chủ nghĩa đa phương hiệu quả, công bằng để kiến tạo một Việt Nam độc lập, tự cường, đổi mới sáng tạo, phát triển nhanh và bền vững trong kỷ nguyên mới - Ảnh: TTXVN</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu tại cuộc gặp, các nhà khoa học tiêu biểu đại diện cho gần 1.300 đại biểu tham dự hội thảo bày tỏ cảm kích, đánh giá cao sự quan tâm của cá nhân Tổng Bí thư Tô Lâm và lãnh đạo Đảng, Nhà nước Việt Nam đối với mạng lưới toàn cầu các nhà khoa học và chuyên gia nghiên cứu về Việt Nam nói chung và hội thảo lần này nói riêng.&nbsp;</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các học giả bày tỏ ấn tượng về sự phát triển năng động của Việt Nam, cũng như tầm nhìn và sự lãnh đạo sáng suốt của Đảng, đồng tình những chủ trương, quyết sách mà Đảng và Nhà nước đang quyết liệt triển khai nhận được sự đồng thuận cao của người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong không khí trao đổi cởi mở, nhiều ý kiến tâm huyết khuyến nghị các biện pháp cụ thể nhằm kịp thời hiện thực hóa&nbsp;các nghị quyết đúng đắn của Đảng mới ban hành, đồng thời bày tỏ niềm tin với quyết tâm và sự chỉ đạo sát sao của lãnh đạo Đảng và Nhà nước, sự đoàn kết, đồng lòng của đông đảo nhân dân, đất nước Việt Nam sẽ sớm đạt các mục tiêu phát triển toàn diện đã đề ra.</span></span></span></p>', '26/10/2025 16:00', 'https://bacninh.gov.vn/news/-/details/37632/tong-bi-thu-to-lam-tiep-oan-ai-bieu-tham-du-hoi-thao-quoc-te-viet-nam-hoc-lan-thu-7-29030402', '', 'Theo Chinhphu.vn', 25, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (58, '29031610', 'Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn', 'Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg', '<p>Sáng 26/10, Phó Thủ tướng Chính phủ Bùi Thanh Sơn đã tiếp Phó Thủ tướng Campuchia Sok Chenda Sophea nhân dịp sang Việt Nam dự Lễ mở ký công ước Liên Hợp Quốc về chống tội phạm mạng (Công ước Hà Nội).</p>', '<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg\" target=\"_blank\" title=\"Phó Thủ tướng Bùi Thanh Sơn tiếp Phó Thủ tướng Campuchia Sok Chenda Sophea nhân dịp sang Việt Nam dự Lễ mở ký Công ước Liên Hợp Quốc về chống tội phạm mạng - Ảnh: VGP/Hải Minh\"><img alt=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg\" h=\"1502\" id=\"img_906767351245062144\" loading=\"lazy\" photoid=\"906767351245062144\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thuaa13i0449-17614541779672124269535.jpg\" style=\"width: 900px; height: 676px;\" title=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Bùi Thanh Sơn tiếp Phó Thủ tướng Campuchia Sok Chenda Sophea nhân dịp sang Việt Nam dự Lễ mở ký Công ước Liên Hợp Quốc về chống tội phạm mạng - Ảnh: VGP/Hải Minh</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tại buổi tiếp, Phó Thủ tướng Bùi Thanh Sơn chúc mừng những thành tựu to lớn trong phát triển kinh tế-xã hội, nâng cao vị thế đất nước mà nhân dân Campuchia đã đạt được dưới sự trị vì của Quốc vương Norodom Sihamoni, sự lãnh đạo của Chính phủ do Đảng Nhân dân Campuchia làm nòng cốt, đứng đầu là Chủ tịch Hun Sen; tin tưởng Campuchia sẽ tiếp tục gặt hái được nhiều thành công hơn nữa trong công cuộc xây dựng và phát triển đất nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Bùi Thanh Sơn cảm ơn Phó Thủ tướng Sok Chenda Sophea đã dẫn đầu đoàn Đại biểu Campuchia tham dự Lễ mở ký Công ước Hà Nội, thể hiện sự ủng hộ của Campuchia đối với Việt Nam, đồng thời góp phần vào thành công chung của Lễ mở ký - sự kiện có ý nghĩa lịch sử của cộng đồng quốc tế trong cuộc chiến chống tội phạm mạng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng cho biết, Tổng Bí thư Tô Lâm và các nhà lãnh đạo cấp cao Việt Nam đánh giá cao việc Campuchia cử Đoàn đại biểu cấp cao do Chủ tịch Hun Sen dẫn đầu và sự tham gia diễu binh của lực lượng vũ trang Campuchia tại Lễ kỷ niệm 50 năm giải phóng miền Nam, thống nhất đất nước (30/4/1975-30/4/2025) và Lễ kỷ niệm 80 năm Cách mạng tháng Tám và Quốc khánh Việt Nam (2/9/1945-2/9/2025).</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0415-1761454177942480915329.jpg\" target=\"_blank\" title=\"Phó Thủ tướng đề nghị Campuchia tiếp tục phối hợp chặt chẽ với Việt Nam, các nước Tiểu vùng sông Mekong và ASEAN trong lĩnh vực an ninh mạng và phòng chống tội phạm thông qua chia sẻ thông tin và kinh nghiệm lập pháp và phối hợp đấu tranh các loại hình tội phạm mạng, nhất là tội phạm xuyên quốc gia - Ảnh: VGP/Hải Minh\"><img alt=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thuaa13i0415-1761454177942480915329.jpg\" h=\"1368\" id=\"img_906767352292298752\" loading=\"lazy\" photoid=\"906767352292298752\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thuaa13i0415-1761454177942480915329.jpg\" style=\"width: 900px; height: 615px;\" title=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 2.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng đề nghị Campuchia tiếp tục phối hợp chặt chẽ với Việt Nam, các nước Tiểu vùng sông Mekong và ASEAN trong lĩnh vực an ninh mạng và phòng chống tội phạm thông qua chia sẻ thông tin và kinh nghiệm lập pháp và phối hợp đấu tranh các loại hình tội phạm mạng, nhất là tội phạm xuyên quốc gia - Ảnh: VGP/Hải Minh</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng vui mừng nhận thấy quan hệ hai nước thời gian qua tiếp tục được củng cố và phát triển, trong đó hợp tác kênh Đảng giúp củng cố tin cậy lẫn nhau, hợp tác an ninh-quốc phòng giữ vai trò trụ cột, kim ngạch thương mại đạt trung bình trên 10 tỷ USD/năm, trong đó 9 tháng năm 2025 đạt gần 9 tỷ USD, số lượng khách du lịch giữa hai nước tăng cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong thời gian tới, Phó Thủ tướng đề nghị hai bên tập trung tạo đột phát trong hợp tác kinh tế để đạt mục tiêu nâng kim ngạch thương mại song phương lên 20 tỷ USD vào năm 2030 thông qua đẩy nhanh kết nối hạ tầng giao thông đặc biệt là dự án kết nối cao tốc TPHCM-Mộc Bài-Bavet-Phnom Penh; đề ra các biện pháp dài hạn thúc đẩy hợp tác kinh tế; phát triển hệ thống cửa khẩu và hạ tầng thương mại biên giới, trong đó có việc sớm tổ chức khánh thành cặp cửa khẩu quốc tế Tân Nam-Meun Chey; tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam đầu tư vào Campuchia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng cũng đề nghị Campuchia tiếp tục phối hợp chặt chẽ với Việt Nam, các nước Tiểu vùng sông Mekong và ASEAN trong lĩnh vực an ninh mạng và phòng chống tội phạm thông qua chia sẻ thông tin và kinh nghiệm lập pháp và phối hợp đấu tranh các loại hình tội phạm mạng, nhất là tội phạm xuyên quốc gia.</span></span></span></p>\n\n<figure type=\"Photo\">\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thua-a13i0478-17614541778811590359884.jpg\" target=\"_blank\" title=\"Phó Thủ tướng Campuchia Sok Chenda Sophea chúc mừng Việt Nam đăng cai thành công mỹ mãn Lễ mở ký Công ước Hà Nội, qua đó giúp nâng cao vai trò, vị thế của Việt Nam trên trường quốc tế, để lại dấu ấn sâu đậm về đất nước, con người Việt Nam trong lòng bạn bè quốc tế - Ảnh: VGP/Hải Minh\"><img alt=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/26/a-thua-a13i0478-17614541778811590359884.jpg\" h=\"1377\" id=\"img_906767352232796160\" loading=\"lazy\" photoid=\"906767352232796160\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/26/a-thua-a13i0478-17614541778811590359884.jpg\" style=\"width: 900px; height: 620px;\" title=\"Việt Nam tổ chức Lễ mở ký Công ước Hà Nội thành công mỹ mãn- Ảnh 3.\" type=\"photo\" w=\"2000\" /></a></span></span></span></p>\n\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Campuchia Sok Chenda Sophea chúc mừng Việt Nam đăng cai thành công mỹ mãn Lễ mở ký Công ước Hà Nội, qua đó giúp nâng cao vai trò, vị thế của Việt Nam trên trường quốc tế, để lại dấu ấn sâu đậm về đất nước, con người Việt Nam trong lòng bạn bè quốc tế - Ảnh: VGP/Hải Minh</span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Campuchia Sok Chenda Sophea bày tỏ vui mừng gặp lại Phó Thủ tướng Bùi Thanh Sơn; chúc mừng Việt Nam đăng cai thành công mỹ mãn Lễ mở ký Công ước Hà Nội, qua đó giúp nâng cao vai trò, vị thế của Việt Nam trên trường quốc tế, để lại dấu ấn sâu đậm về đất nước, con người Việt Nam trong lòng bạn bè quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Thủ tướng Sok Chenda Sophea cho hay, trong Lễ mở ký Công ước, ông ngồi cạnh Phó Thủ tướng Ba Lan Krzysztof Gawkowski và Phó Tổng thống Ecuador Maria Jose Pinto Gonzalez Artigas. Cả hai vị trưởng đoàn của Ba Lan và Ecuador đều đánh giá cao cương vị của Việt Nam trong tổ chức đăng cai Lễ mở ký, cũng như đà phát triển nhanh chóng của Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Bày tỏ ấn tượng với những thành tựu và định hướng phát triển của Việt Nam, Phó Thủ tướng Sok Chenda Sophea tin tưởng Việt Nam sẽ hiện thực hoá những mục tiêu phát triển của mình nhờ đi đúng hướng trong việc tập trung phát triển cơ sở hạ tầng cứng và đa dạng hoá phương thức phát triển nguồn nhân lực; khẳng định Campuchia mong muốn tiếp tục hợp tác chặt chẽ với Việt Nam để cùng phát triển.</span></span></span></p>', '26/10/2025 14:00', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-to-chuc-le-mo-ky-cong-uoc-ha-noi-thanh-cong-my-man-29031610', '', 'Theo Chinhphu.vn', 20, 'Tin trong nước', 8, '', '38762', '{}', '2025-10-31 08:45:03.000000', 8, 11);
INSERT INTO `sync_articles` VALUES (83, '29278299', 'PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD', 'PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg', '<p>Trong khuôn khổ chuyến thăm chính thức Liên hiệp Vương quốc Anh và Bắc Ireland, Tổng Bí thư Tô Lâm có bài phát biểu chính sách quan trọng tại Đại học Oxford - trung tâm nghiên cứu đào tạo hàng đầu của Anh - về tầm nhìn cho khuôn khổ quan hệ Việt Nam - Anh và công cuộc đổi mới, định hướng phát...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm: Việt Nam đã lựa chọn một hướng đi rất rõ ràng: khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và kinh tế tri thức sẽ là động lực tăng trưởng chủ yếu trong giai đoạn tới.\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg\" h=\"1054\" id=\"img_907670501442048000\" loading=\"lazy\" photoid=\"907670501442048000\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam-17616695105391604971883.jpg\" style=\"width: 700px; height: 495px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 1.\" type=\"photo\" w=\"1492\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm: Việt Nam đã lựa chọn một hướng đi rất rõ ràng: khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và kinh tế tri thức sẽ là động lực tăng trưởng chủ yếu trong giai đoạn tới.</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa bà&nbsp;</i><i>H</i><i>iệu trưởng, các vị lãnh đạo Nhà trường,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa các giáo sư, giảng viên, các nhà nghiên cứu, các sinh viên và bạn bè của Việt Nam tại Đại học Oxford,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa toàn thể quý vị,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi cùng đoàn đại biểu Việt Nam rất vui khi có mặt tại trường Đại học có truyền thống lâu đời trong việc thúc đẩy tự do học thuật và khai phóng tri thức toàn cầu. Oxford là một trong những trung tâm giáo dục Đại học hàng đầu của thế giới, là biểu tượng tri thức của nước Anh, là nơi đã đào tạo nhiều thế hệ những con người dấn thân cho hòa bình, công lý và sự tiến bộ của nhân loại.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Được chia sẻ tầm nhìn của Việt Nam trong kỷ nguyên mới với các bạn, đặc biệt là với những người trẻ đang chuẩn bị định hình tương lai thế giới, với các nhà khoa học và hoạch định chính sách tương lai là một vinh dự đối với chúng tôi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong buổi gặp mặt hôm nay, tôi muốn nói với các bạn ba nội dung:&nbsp;<i>Thứ nhất</i>: thế giới đang bước vào một giai đoạn cạnh tranh chiến lược gay gắt, đầy rủi ro nhưng cũng mở ra các cơ hội phát triển mới.&nbsp;<i>Thứ hai</i>: Việt Nam lựa chọn con đường phát triển hòa bình, độc lập, tự chủ, tự cường, sáng tạo, vì con người, không chỉ để xây dựng một đất nước giàu mạnh cho nhân dân mình, mà còn để đóng góp có trách nhiệm cho ổn định khu vực và trật tự quốc tế dựa trên luật pháp quốc tế.&nbsp;<i>Thứ ba:</i>&nbsp;Quan hệ Đối tác Chiến lược Toàn diện giữa Việt Nam và Vương quốc Anh, cấp độ hợp tác cao nhất trong chính sách đối ngoại của Việt Nam, cần và sẽ trở thành một hình mẫu hợp tác mới, thực chất, bình đẳng, cùng có lợi, cùng phát triển.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam2-1761669869207517797402.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm phát biểu chính sách tại Đại học Oxford\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam2-1761669869207517797402.jpg\" h=\"1003\" id=\"img_907672005582757888\" loading=\"lazy\" photoid=\"907672005582757888\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam2-1761669869207517797402.jpg\" style=\"width: 700px; height: 439px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 2.\" type=\"photo\" w=\"1600\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm phát biểu chính sách tại Đại học Oxford</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa các quý</i><i>&nbsp;</i><i>vị</i><i>,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng ta đang sống trong một thời kỳ mà các đường biên giới và khái niệm quyền lực đang thay đổi từng ngày, thậm chí từng giờ. Cục diện địa chính trị đang chứng kiến cạnh tranh chiến lược giữa các trung tâm quyền lực lớn, không chỉ về ảnh hưởng chính trị-an ninh mà cả trong kinh tế, công nghệ, chuỗi cung ứng, tiêu chuẩn dữ liệu, trí tuệ nhân tạo và công nghệ sinh học. Cạnh tranh trong đổi mới sáng tạo, trong quyền kiểm soát các công nghệ lõi, trong năng lượng sạch, trong hạ tầng số, đã trở thành cuộc đua quyền lực mới. Nói một cách thẳng thắn: ai làm chủ chiến lược, ai nắm công nghệ chiến lược, người đó sẽ định hình luật chơi và nhiều khả năng đó là người chiến thắng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng lúc đó, các nguy cơ xung đột cục bộ, tranh chấp chủ quyền, lãnh thổ, va chạm lợi ích trên biển, trên không gian mạng, trong không gian số, gia tăng cả về tần suất lẫn mức độ phức tạp. Áp lực \"chọn bên\", \"phân cực\", \"liên minh để kiềm chế nhau\" xuất hiện trở lại dưới những hình thức tinh vi hơn. Những đường ranh mới không chỉ nằm ở lãnh thổ, kinh tuyến, vĩ tuyến mà nằm trong dữ liệu, trong công nghệ, trong chuỗi giá trị. Thế giới dường như đang<b>&nbsp;</b>vận hành đồng thời theo hai xu hướng: vừa kết nối sâu hơn, vừa chia rẽ nhanh hơn.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam3-1761669893232961583781.jpg\" target=\"_blank\" title=\"Các đại biểu dự buổi phát biểu chính sách của Tổng Bí thư Tô Lâm tại Đại học Oxford\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam3-1761669893232961583781.jpg\" h=\"1066\" id=\"img_907672105477570560\" loading=\"lazy\" photoid=\"907672105477570560\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam3-1761669893232961583781.jpg\" style=\"width: 700px; height: 467px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 3.\" type=\"photo\" w=\"1600\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đại biểu dự buổi phát biểu chính sách của Tổng Bí thư Tô Lâm tại Đại học Oxford</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những thách thức an ninh truyền thống và phi truyền thống đan xen: an ninh năng lượng, an ninh lương thực, an ninh nguồn nước, biến đổi khí hậu, dịch bệnh toàn cầu, tội phạm công nghệ cao, tấn công mạng vào các hệ thống trọng yếu. Không một quốc gia nào, dù lớn hay nhỏ, có thể tự mình xử lý tất cả các rủi ro này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cạnh tranh địa kinh tế ngày nay không chỉ là vấn đề thị trường, thuế quan hay thâm hụt thương mại. Đó là cạnh tranh giành chuỗi cung ứng chiến lược, giành quyền tiếp cận khoáng sản quan trọng, giành quyền đặt chuẩn mực công nghệ mới. Nhiều nước đang điều chỉnh chiến lược công nghiệp, thúc đẩy \"tự cường\", \"đa dạng hóa\", \"giảm phụ thuộc\", \"an ninh chuỗi cung ứng\". Điều đó đang định hình lại bản đồ sản xuất toàn cầu và tái cấu trúc luồng đầu tư.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong bối cảnh đó, câu hỏi đặt ra cho các quốc gia không chỉ là \"đứng về phía ai, đứng ở đâu\", mà là \"đứng vững bằng cách nào, tự chủ như thế nào\". Đối với Việt Nam, đó cũng là câu hỏi sinh tử.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam chọn con đường hòa bình, độc lập, tự chủ, hợp tác cùng phát triển. Việt Nam là một dân tộc đã phải giành độc lập bằng xương máu và đã trả giá cho chiến tranh để có hòa bình. Chúng tôi hiểu rõ giá trị tối thượng của hòa bình. Chân lý&nbsp;<i>\"không có gì quý hơn độc lập, tự do\"</i>&nbsp;của Chủ tịch Hồ Chí Minh là kim chỉ nam cho hành động của dân tộc tôi. Đó là nền tảng đạo lý và nguyên tắc sống của chúng tôi trong đời sống xã hội và quan hệ quốc tế hôm nay.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam4-17616699303071869015691.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và Đoàn đại biểu cấp cao Việt Nam trong khuôn viên trường Đại học Oxford\"><img alt=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt-to-lam4-17616699303071869015691.jpg\" h=\"1099\" id=\"img_907672261116534784\" loading=\"lazy\" photoid=\"907672261116534784\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt-to-lam4-17616699303071869015691.jpg\" style=\"width: 700px; height: 481px;\" title=\"PHÁT BIỂU CỦA TỔNG BÍ THƯ TÔ LÂM TẠI ĐẠI HỌC OXFORD- Ảnh 4.\" type=\"photo\" w=\"1600\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và Đoàn đại biểu cấp cao Việt Nam trong khuôn viên trường Đại học Oxford</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong một thế giới đầy sức ép chọn bên, Việt Nam kiên trì đường lối đối ngoại độc lập, tự chủ, đa phương hóa, đa dạng hóa quan hệ đối ngoại; Việt Nam mong muốn là bạn, là đối tác tin cậy, là thành viên có trách nhiệm của cộng đồng quốc tế. Việt Nam nỗ lực xây dựng \"trong ấm, ngoài êm\": giữ ổn định chính trị- phát triển kinh tế, xã hội bên trong, giữ môi trường hòa bình, hợp tác, tôn trọng lẫn nhau bên ngoài; xử lý khác biệt bằng biện pháp hòa bình và luật pháp quốc tế; đặt con người, lợi ích chính đáng của nhân dân lên trên hết, trước hết.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi kiên định nguyên tắc: bảo vệ vững chắc độc lập, chủ quyền, toàn vẹn lãnh thổ; đồng thời tạo dựng môi trường bên ngoài thuận lợi nhất để phát triển đất nước, nâng cao chất lượng cuộc sống của người dân, thu hẹp khoảng cách phát triển, đóng góp vào hòa bình, ổn định chung của khu vực và&nbsp;<b>phạm</b><b>&nbsp;vi toàn</b>&nbsp;thế giới. Chúng tôi bảo vệ Tổ quốc bằng hòa bình, bằng luật pháp quốc tế, bằng văn hóa, truyền thống dân tộc, bằng hợp tác cùng có lợi. Đó là lựa chọn chiến lược chủ động, có trách nhiệm&nbsp;<b>của Việt Nam chúng tôi.</b></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi muốn nhấn mạnh rằng: Việt Nam không cổ vũ đối đầu. Việt Nam không chọn cách phát triển dựa trên xung đột hay đối kháng. Chúng tôi tin vào đối thoại bình đẳng, tin vào luật pháp quốc tế, tin rằng chủ quyền không nên được khẳng định bằng súng đạn, bằng áp đặt, mà bằng sự tôn trọng lẫn nhau, bằng thỏa thuận tôn trọng luật lệ chung và bằng lợi ích cùng chia sẻ.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tinh thần đó đã giúp Việt Nam vừa giữ được ổn định chính trị-xã hội, vừa chủ động hội nhập kinh tế quốc tế, tham gia các hiệp định thương mại tự do thế hệ mới, mở rộng hợp tác nhiều tầng nấc với các đối tác ở mọi khu vực, trong đó có Vương quốc Anh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa</i><i>&nbsp;các bạn</i><i>,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Muốn tiến xa, tiến nhanh, ổn định, bền vững và chủ động, chúng tôi hiểu rằng không thể chỉ dựa vào tài nguyên thiên nhiên, lao động giá rẻ, hay lợi thế về nguồn nhân công... Việt Nam đã lựa chọn một hướng đi rất rõ ràng: khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số và kinh tế tri thức sẽ là động lực tăng trưởng chủ yếu trong giai đoạn tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi đang thúc đẩy mạnh mẽ chiến lược chuyển đổi số quốc gia, phát triển kinh tế số, kinh tế xanh, kinh tế tuần hoàn, kinh tế carbon thấp. Chúng tôi coi đổi mới sáng tạo không chỉ là phòng thí nghiệm khoa học thuần túy, mà là sức sống của nền kinh tế, là năng lực cạnh tranh quốc gia, là khả năng đứng vững trước các cú sốc địa chính trị và địa kinh tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều đó kéo theo yêu cầu cải cách thể chế. Chúng tôi tiếp tục xây dựng và hoàn thiện mô hình&nbsp;<i>\"kinh tế thị trường định hướng xã hội chủ nghĩa\"</i>: một nền kinh tế vận hành theo quy luật thị trường, khuyến khích cạnh tranh lành mạnh, tôn trọng vai trò của doanh nghiệp tư nhân như một động lực quan trọng của tăng trưởng; đồng thời khẳng định vai trò định hướng, dẫn dắt, điều tiết của Nhà nước pháp quyền xã hội chủ nghĩa, dưới sự lãnh đạo của Đảng Cộng sản Việt Nam, nhằm bảo đảm phát triển đi đôi với tiến bộ và công bằng xã hội.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nói ngắn gọn: chúng tôi coi kinh tế tư nhân là động lực quan trọng nhất để thúc đẩy tốc độ phát triển kinh tế; coi khu vực kinh tế nhà nước là lực lượng giữ vai trò dẫn dắt, bảo đảm ổn định vĩ mô, an ninh kinh tế, an ninh năng lượng, an ninh lương thực; coi Nhà nước pháp quyền, quản trị liêm chính, phòng chống tham nhũng, lãng phí, lợi ích nhóm là điều kiện để xã hội tin tưởng, để nguồn lực xã hội được phân bổ hiệu quả, để mọi&nbsp;<b>n</b>gười dân được hưởng thành quả phát triển một cách công bằng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cùng lúc, chúng tôi đặt con người ở vị trí trung tâm của mọi chiến lược phát triển. Mục tiêu chính không phải là những con số thống kê tăng trưởng, mà là nâng cao thực sự chất lượng cuộc sống của người dân: thu nhập, nhà ở, y tế công, giáo dục chất lượng, an sinh xã hội, cơ hội phát triển cá nhân, môi trường sống an toàn, trong lành. Chúng tôi muốn tăng trưởng mà không đánh đổi môi trường. Chúng tôi muốn công nghiệp hóa mà không đánh mất văn hóa. Chúng tôi muốn đô thị hóa nhưng không để ai bị bỏ lại phía sau.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đây là điểm rất căn bản trong tư duy phát triển của Việt Nam: tăng trưởng nhanh phải gắn liền với phát triển bền vững; phát triển bền vững phải dựa trên tri thức, khoa học-công nghệ và đổi mới sáng tạo; đổi mới sáng tạo chỉ có ý nghĩa khi người dân được hưởng lợi thực chất, công bằng, bình đẳng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên nền tảng đó, Việt Nam đặt ra hai mục tiêu chiến lược rất rõ ràng, chúng tôi gọi đó là hai mục tiêu 100 năm. Mục tiêu thứ nhất: đến năm 2030, đánh dấu 100 năm đất nước phát triển dưới sự lãnh đạo của Đảng Cộng sản Việt Nam, chúng tôi quyết tâm trở thành nước đang phát triển có công nghiệp hiện đại, thu nhập trung bình cao. Mục tiêu thứ hai: đến năm 2045, kỷ niệm 100 năm thành lập nước CHXHCN Việt Nam, Việt Nam phấn đấu trở thành nước phát triển, thu nhập cao, có nền kinh tế hiện đại, xã hội văn minh, người dân có đời sống vật chất và tinh thần ở mức cao, đất nước có vị thế xứng đáng trong cộng đồng quốc tế. Đây là cam kết chính trị-lịch sử mà chúng tôi tuyên bố trước nhân dân mình và trước cộng đồng quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa</i><i>&nbsp;các bạn,</i><i></i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam và Vương quốc Anh thiết lập quan hệ ngoại giao vào năm 1973. Từ đó đến nay, hai bên đã đi một chặng đường dài và đầy ý nghĩa, bất chấp những khác biệt về địa lý, trình độ phát triển và hệ thống chính trị.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Năm 2010, hai nước ký Tuyên bố chung thiết lập Quan hệ Đối tác Chiến lược. Đây là một bước ngoặt lớn, mở ra hợp tác sâu rộng trên nhiều lĩnh vực như chính trị-ngoại giao, thương mại-đầu tư, giáo dục-đào tạo, khoa học- công nghệ, quốc phòng-an ninh, phát triển bền vững và giao lưu nhân dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đến nay, hợp tác kinh tế-thương mại giữa Việt Nam và Vương quốc Anh ngày càng mang tính chiến lược cao. Sau khi Vương quốc Anh rời Liên minh châu Âu, hai nước đã ký hiệp định thương mại tự do song phương dựa trên nền tảng các cam kết chất lượng cao, qua đó bảo đảm tính liên tục của dòng thương mại và đầu tư. Đồng thời, Vương quốc Anh đã tham gia Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP), nơi Việt Nam là một trong các thành viên sáng lập, tạo thêm một cấu trúc hợp tác kinh tế mở, dựa trên tiêu chuẩn cao về thương mại số, sở hữu trí tuệ, dịch vụ và đầu tư.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hợp tác giáo dục là một trụ cột rất nổi bật. Hàng chục nghìn sinh viên Việt Nam đã, đang học tập tại Anh trên các lĩnh vực từ khoa học kỹ thuật, công nghệ thông tin, tài chính, y khoa, y sinh học, đến chính sách công và đào tạo nguồn nhân lực chất lượng cao chính là chiếc cầu tri thức nối hai nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngày hôm nay, chúng ta đứng trước một bước phát triển mới: hai nước đang thúc đẩy nâng cấp quan hệ lên Đối tác Chiến lược Toàn diện-cấp độ cao nhất trong hệ thống đối ngoại của Việt Nam. Đây là sự khẳng định rõ ràng rằng Việt Nam coi Anh không chỉ là một đối tác thương mại, một đối tác giáo dục, một đối tác về khoa học công nghệ, mà là một đối tác chiến lược dài hạn để cùng nhau định hình các chuẩn mực hợp tác trong thế kỷ XXI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Tôi muốn nhấn mạnh hai điều.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ nhất:&nbsp;</i>Quan hệ Việt Nam-Vương quốc Anh là mối quan hệ hữu nghị, hợp tác và cùng phát triển. Đây là một quan hệ đối tác mà cả hai bên đều có lợi ích căn bản trong việc duy trì hòa bình, ổn định, tôn trọng luật pháp quốc tế, bảo đảm tự do hàng hải, bảo vệ chuỗi cung ứng toàn cầu, thúc đẩy thương mại công bằng và bền vững, ứng phó biến đổi khí hậu, phát triển xanh, phát triển bao trùm. Nói cách khác, đây là sự gặp nhau giữa nhu cầu tham gia sâu hơn vào khu vực châu Á-Thái Bình Dương của Anh và nhu cầu mở rộng không gian chiến lược, công nghệ, giáo dục, tài chính chất lượng cao của Việt Nam với Anh, với châu Âu, với cộng đồng quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ hai:</i>&nbsp;chúng ta cần một mô hình hợp tác mới-thiết thực, có thể đo đếm, lan tỏa lợi ích trực tiếp tới người dân hai nước. Khi tôi nói \"một hình mẫu hợp tác mới\", tôi muốn nói đến sự hợp tác giữa thế mạnh khoa học cơ bản, khoa học ứng dụng, công nghệ cao, y sinh, y tế cộng đồng, giáo dục đại học, quản trị đô thị, chuyển đổi năng lượng, dịch vụ tài chính, của Vương quốc Anh với nhu cầu chuyển đổi số, chuyển đổi xanh, nâng cao chất lượng nguồn nhân lực, đổi mới quản trị phát triển, hoàn thiện thể chế kinh tế thị trường định hướng xã hội chủ nghĩa tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đó không chỉ là hợp tác \"chuyển giao công nghệ\". Đó là đồng kiến tạo tương lai. Tôi tin rằng chính Oxford-với truyền thống kết nối tri thức và chính sách công, với mạng lưới cựu sinh viên có ảnh hưởng trên toàn thế giới- có thể đóng vai trò rất cụ thể trong quá trình này. Tôi hình dung ít nhất bốn hướng: (1) Hợp tác đào tạo và nghiên cứu chung trong các lĩnh vực then chốt như y tế cộng đồng<b>,</b>&nbsp;công nghệ sinh học, khoa học hạt nhân, khoa học cơ bản, trí tuệ nhân tạo có trách nhiệm, biến đổi khí hậu, chính sách năng lượng sạch. (2) Chương trình trao đổi chuyên gia giữa các viện nghiên cứu chính sách của Việt Nam và các trung tâm nghiên cứu chính sách, quản trị công, phát triển bền vững tại Anh, để cùng xây dựng khuyến nghị chính sách có thể áp dụng được vào thực tiễn, đem lại những kết quả hữu hiệu, cụ thể cho những nơi áp dụng, ứng dụng những khuyến nghị của các bạn. (3) Hợp tác hỗ trợ đổi mới sáng tạo và khởi nghiệp công nghệ cho doanh nghiệp Việt Nam, đặc biệt là doanh nghiệp vừa và nhỏ, doanh nghiệp khởi nghiệp đổi mới sáng tạo, những chủ thể sẽ quyết định tốc độ chuyển đổi số và chuyển đổi xanh của nền kinh tế Việt Nam trong thập kỷ tới. (4) Cùng nhau thử nghiệm các mô hình phát triển đô thị bền vững, tài chính xanh, giáo dục mở, y tế số và chăm sóc sức khỏe cộng đồng, những lĩnh vực mà cả hai bên đều quan tâm và đều có nhu cầu cấp bách.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nếu chúng ta làm được những điều đó, thì quan hệ Việt Nam-Vương quốc Anh sẽ không chỉ là những tuyên bố chính trị cấp cao. Nó sẽ trở thành một nguồn lực sống, một mạng lưới tri thức và công nghệ trải dài từ Hà Nội đến London, từ Thành phố Hồ Chí Minh đến Oxford, giữa các viện nghiên cứu, trường Đại học, doanh nghiệp, thậm chí từ người dân đến người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thưa các bạn,</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam bước vào giai đoạn phát triển mới với khát vọng mạnh mẽ: xây dựng một đất nước hùng cường, thịnh vượng, nhân ái; một nền kinh tế hiện đại, xanh, thông minh; một xã hội công bằng, văn minh, nơi người dân được bảo đảm an ninh con người, được tạo điều kiện phát triển toàn diện. Chúng tôi phấn đấu vì mục tiêu \"dân giàu, nước mạnh, dân chủ, công bằng, văn minh\". Đây là định hướng nhất quán trong chiến lược phát triển quốc gia của chúng tôi.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi tin vào sức mạnh của nhân nghĩa. Từ lịch sử, dân tộc Việt Nam luôn lấy nhân nghĩa để thắng hung tàn, lấy chí nhân để thay cường bạo. Chúng tôi tin rằng sức mạnh bền vững nhất của một quốc gia không chỉ là sức mạnh quân sự hay tài chính, mà là sức mạnh đạo lý, sức mạnh gắn kết lòng dân, sức mạnh tạo dựng niềm tin với bạn bè quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chúng tôi yêu chuộng hòa bình, khát vọng tự do và phát triển. Chúng tôi tìm kiếm hợp tác bình đẳng. Chúng tôi không chấp nhận áp đặt. Chúng tôi tôn trọng luật pháp quốc tế. Chúng tôi không muốn thế giới chia rẽ thành các khối đối đầu mà mong mỏi một thế giới đoàn kết vì \"trái đất này là của chúng ta\". Chúng tôi muốn thế giới cùng nhau phát triển.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trên tinh thần đó, tôi mong muốn rằng thế hệ trẻ tại Anh, các viện nghiên cứu, các trường đại học, các doanh nghiệp đổi mới sáng tạo, các tổ chức xã hội dân sự, các nhà hoạch định chính sách tương lai-&nbsp;<b>hãy luôn</b><b>&nbsp;tin rằng có một người bạn</b>&nbsp;<b>Việt Nam</b>&nbsp;là một đối tác chân thành, đáng tin cậy, cùng chia sẻ trách nhiệm và lợi ích trong một trật tự thế giới đang tái định hình.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi tin rằng nếu chúng ta cùng chung tay xây dựng một khuôn khổ hợp tác chiến lược toàn diện, thực chất, dựa trên tôn trọng lẫn nhau, dựa trên cùng có lợi, dựa trên tầm nhìn dài hạn, thì quan hệ Việt Nam-Vương quốc Anh không chỉ tiến thêm một nấc mới trên bản đồ ngoại giao thời đại mới. Đó sẽ trở thành một lực đẩy, một hình mẫu, một câu chuyện thành công chung- không chỉ cho hai nước chúng ta, mà cho cả hòa bình, ổn định và phát triển bền vững trong thế kỷ XXI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xin trân trọng cảm ơn các quý vị.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Xin cảm ơn Đại học Oxford đã tạo không gian để chúng ta trao đổi thẳng thắn, cởi mở, khách quan, cùng nhau nghĩ về một tương lai tốt đẹp hơn.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tôi xin trân trọng cảm ơn.</span></span></span></p>', '29/10/2025 07:00', 'https://bacninh.gov.vn/news/-/details/37632/phat-bieu-cua-tong-bi-thu-to-lam-tai-ai-hoc-oxford-29278299', '', 'chinhphu.vn', 26, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (84, '29279415', 'Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh', 'Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg', '<p>Trong khuôn khổ chuyến thăm chính thức Liên hiệp Vương quốc Anh và Bắc Ireland từ ngày 28 - 30/10, Tổng Bí thư Tô Lâm và Đoàn đại biểu cấp cao Việt Nam đã dự buổi tọa đàm với các nhà chiến lược về trí tuệ nhân tạo (AI) và công nghệ hàng đầu của Anh cũng như thế giới.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1761663016253-17616630165281323676551.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm dự toạ đàm với các chuyên gia công nghệ của Anh và thế giới về AI và chip bán dẫn - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 1.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1761663016253-17616630165281323676551.jpg\" h=\"541\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1761663016253-17616630165281323676551.jpg\" style=\"width: 700px; height: 569px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 1.\" type=\"photo\" w=\"665\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm dự toạ đàm với các chuyên gia công nghệ của Anh và thế giới về AI và chip bán dẫn - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tọa đàm diễn ra sáng 28/10 theo giờ địa phương tại thủ đô London, do Diễn đàn Toàn cầu Boston (BGF) phối hợp tổ chức và là bước đi chiến lược nhằm thúc đẩy hợp tác giữa Việt Nam và các cường quốc công nghệ trong kỷ nguyên AI, đồng thời khẳng định vị thế của Việt Nam trong chuyển đổi số toàn cầu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sự kiện diễn ra trong bối cảnh thế giới đang chứng kiến sự bùng nổ của AI và chip bán dẫn, hai lĩnh vực định hình tương lai kinh tế toàn cầu. Với khát vọng trở thành quốc gia tiên phong trong kinh tế số, Việt Nam mong muốn học hỏi kinh nghiệm từ Anh - cái nôi của Cách mạng công nghiệp và quê hương của những trí tuệ vĩ đại như Isaac Newton, John Locke, Adam Smith, Alan Turing, William Shakespeare và Charles Dickens - để xây dựng một hệ sinh thái công nghệ sáng tạo, nhân văn và bền vững.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu mở đầu tọa đàm, Tổng Bí thư Tô Lâm bày tỏ vui mừng khi gặp gỡ và lắng nghe những ý kiến tâm huyết, thiết thực của các chuyên gia và các nhà chiến lược tại London, một trung tâm công nghệ và sáng tạo của thế giới. Tổng Bí thư nhấn mạnh thế giới đang chứng kiến sự phát triển vượt bậc của khoa học công nghệ, nhất là khi AI trở thành động lực then chốt thúc đẩy tăng trưởng kinh tế và đổi mới sáng tạo.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a-1761663017440-1761663017636399745493.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm nhấn mạnh Việt Nam sẵn sàng đón nhận và thử nghiệm các ý tưởng tiên phong - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 2.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a-1761663017440-1761663017636399745493.jpg\" h=\"462\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a-1761663017440-1761663017636399745493.jpg\" style=\"width: 700px; height: 486px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 2.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: justify;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm nhấn mạnh Việt Nam sẵn sàng đón nhận và thử nghiệm các ý tưởng tiên phong - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việt Nam cũng đã xác định khoa học công nghệ và chuyển đổi số là điểm đột phá hàng đầu để phát triển nhanh, bền vững và vươn lên trong chuỗi giá trị toàn cầu. Vì vậy, Việt Nam mong muốn đồng hành cùng các nước tiên tiến nhằm chia sẻ tầm nhìn và giá trị chung, qua đó xây dựng một thế giới tốt đẹp hơn, nơi AI phục vụ con người, thúc đẩy sáng tạo, nhân ái, hòa bình và thịnh vượng. Tổng Bí thư nhấn mạnh Việt Nam sẵn sàng đón nhận và thử nghiệm các ý tưởng tiên phong.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhiều chuyên gia công nghệ đánh giá cao sự phát triển năng động của Việt Nam. Chỉ trong vòng một thế hệ, Việt Nam đã đưa hàng triệu người thoát nghèo, xây dựng một trong những nền kinh tế sản xuất cạnh tranh nhất châu Á và có lực lượng lao động trẻ, thành thạo kỹ năng số. Đặc biệt, những tiến bộ trong cải cách hành chính của Việt Nam, sự cởi mở trong hợp tác quốc tế đã định vị Việt Nam trở thành một đối tác chủ chốt trong mạng lưới toàn cầu của những quốc gia số đáng tin cậy. Một số ý kiến cũng khuyến nghị, để AI thực sự phục vụ cho quá trình phát triển kinh tế - xã hội nhằm mang lại cuộc sống tốt hơn cho người dân, chính phủ các nước cần chú trọng xây dựng hạ tầng số tin cậy, phát triển các tiêu chuẩn AI có trách nhiệm bảo vệ quyền riêng tư, công bằng và minh bạch…</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ai-va-chip-ban-dan-1761663018388-17616630187131517258901.jpg\" target=\"_blank\" title=\"Các chuyên gia công nghệ đánh giá cao sự phát triển năng động của Việt Nam - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 3.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ai-va-chip-ban-dan-1761663018388-17616630187131517258901.jpg\" h=\"483\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/ai-va-chip-ban-dan-1761663018388-17616630187131517258901.jpg\" style=\"width: 700px; height: 508px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 3.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các chuyên gia công nghệ đánh giá cao sự phát triển năng động của Việt Nam - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu kết luận tọa đàm, Tổng Bí thư Tô Lâm bày tỏ ấn tượng với các vấn đề và ý tưởng được các chuyên gia, nhà quản lý có nhiều kinh nghiệm trong lĩnh vực AI trình bày, đồng thời cho rằng những giải pháp, khuyến nghị đã nêu rất phù hợp với định hướng, mục tiêu phát triển của Việt Nam. Tổng Bí thư cho biết sẽ giao cơ quan chức năng nghiên cứu, phối hợp làm rõ nội dung, tiến tới triển khai các bước cụ thể nhằm biến ý tưởng thành các dự án, chương trình tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư nhấn mạnh buổi tọa đàm là bước khởi đầu đầy ý nghĩa và sẽ mở ra hành trình hợp tác lâu dài, sâu sắc giữa Việt Nam với các trí tuệ, tinh hoa của Vương quốc Anh và thế giới. Tổng Bí thư mong muốn trong thời gian tới, các chuyên gia tiếp tục đồng hành, hỗ trợ Việt Nam phát triển về AI nói riêng và khoa học - công nghệ nói chung, đặc biệt trong ba lĩnh vực ưu tiên gồm chia sẻ tri thức và kinh nghiệm trong hoạch định chiến lược AI quốc gia, phát triển hạ tầng số và hệ sinh thái đổi mới sáng tạo; thúc đẩy đầu tư và chuyển giao công nghệ, ứng dụng AI trong các lĩnh vực trọng điểm như y tế, nông nghiệp thông minh và giáo dục số; và cùng Việt Nam triển khai thành công các chương trình trọng điểm về khoa học công nghệ, nhất là các lĩnh vực mới, tiên phong nhằm giúp Việt Nam xây dựng nền kinh tế sáng tạo, tự cường.</span></span></span></p>\n\n<p style=\"text-align: center;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm trân trọng mời các chuyên gia, nhà khoa học có nhiều kinh nghiệm trong lĩnh vực khoa học công nghệ và AI đến Việt Nam - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 4.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg\" h=\"445\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tong-bi-thu-to-lam-1a1-1761663019255-17616630199511171648444.jpg\" style=\"width: 700px; height: 468px;\" title=\"Tổng Bí thư Tô Lâm dự tọa đàm về công nghệ AI và chip bán dẫn tại Anh- Ảnh 4.\" type=\"photo\" w=\"665\" /></a></span></span></span></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm trân trọng mời các chuyên gia, nhà khoa học có nhiều kinh nghiệm trong lĩnh vực khoa học công nghệ và AI đến Việt Nam - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm trân trọng mời các chuyên gia, nhà khoa học có nhiều kinh nghiệm trong lĩnh vực khoa học công nghệ và AI đến Việt Nam để có thêm nhiều thời gian trao đổi và điều kiện làm việc trực tiếp với các cơ quan hoạch định, thực thi chính sách khoa học công nghệ của Việt Nam nhằm sớm đưa những ý tưởng được thảo luận trong cuộc tọa đàm trở thành hiện thực, mang lại nhiều giá trị mới, mô hình mới và niềm tin mới cho nhân loại trong kỷ nguyên AI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Buổi tọa đàm không chỉ góp phần củng cố quan hệ hợp tác toàn diện giữa Việt Nam và Anh mà còn mở ra triển vọng phát triển trong lĩnh vực AI và chip bán dẫn cho nền kinh tế Việt Nam. Sự kiện đánh dấu bước tiến quan trọng trong hành trình đưa Việt Nam trở thành quốc gia tiên phong trong kinh tế số và sáng tạo toàn cầu, đồng thời góp phần xây dựng một thế giới nơi công nghệ phục vụ con người, thúc đẩy hòa bình và thịnh vượng.</span></span></span></p>', '29/10/2025 06:30', 'https://bacninh.gov.vn/news/-/details/37632/tong-bi-thu-to-lam-du-toa-am-ve-cong-nghe-ai-va-chip-ban-dan-tai-anh-29279415', '', 'chinhphu.vn', 24, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (85, '29280301', 'Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản', 'Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg', '<p>Trong khuôn khổ chuyến thăm chính thức Liên hiệp Vương quốc Anh và Bắc Ireland, sáng 28/10 (giờ địa phương), Tổng Bí thư Tô Lâm và Phu nhân Ngô Phương Ly cùng Đoàn đại biểu cấp cao Việt Nam đã đến viếng mộ Lãnh tụ giai cấp vô sản, Karl Marx, tại nghĩa trang Highgate, thủ đô London.</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm đặt vòng hoa viếng tại mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 1.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg\" h=\"535\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt03-1761658414036-1761658414655111549303.jpg\" style=\"width: 700px; height: 563px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 1.\" type=\"photo\" w=\"665\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm đặt vòng hoa viếng tại mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhà triết học Karl Marx sinh năm 1818 tại Đức, định cư tại London năm 1849 cho tới khi ông qua đời năm 1883. Ông là lãnh tụ kiệt xuất của giai cấp công nhân, nhân dân lao động, các dân tộc bị áp bức và loài người tiến bộ nói chung.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngôi mộ của Karl Marx tọa lạc tại Nghĩa trang Highgate, là điểm dừng chân vừa mang đậm ý nghĩa lịch sử - tư tưởng, vừa là địa danh tham quan nổi bật của thủ đô nước Anh. Ban đầu, vào năm 1883, nhà tư tưởng Karl Marx được chôn cất tại một vị trí khiêm tốn trong nghĩa trang này. Sau đó, năm 1954, thi hài ông và các thành viên trong gia đình được di chuyển vào cùng một khu vực và đặt dưới một đài tưởng niệm lớn hơn, được khánh thành năm 1956.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt02-1761658415648-1761658415857701900358.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam tưởng niệm trước mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 2.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt02-1761658415648-1761658415857701900358.jpg\" h=\"507\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt02-1761658415648-1761658415857701900358.jpg\" style=\"width: 700px; height: 533px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 2.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam tưởng niệm trước mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đài mộ do nhà điêu khắc Laurence Bradshaw thiết kế gồm một bức phù điêu bán thân bằng đồng của Karl Marx đặt trên bệ đá cẩm thạch khắc dòng khẩu hiệu nổi tiếng \"Workers of all lands, unite\" (Vô sản toàn thế giới, liên hiệp lại) - được trích từ tác phẩm The Communist Manifesto (Tuyên ngôn của Đảng Cộng sản) của ông. Vị trí hiện tại của ngôi mộ đã được xếp hạng “Grade I listed\" - hạng cao nhất dành cho các di sản có giá trị xuất sắc về kiến trúc, lịch sử tại Anh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Ngôi mộ không chỉ là nơi an nghỉ mà còn mang tính biểu tượng mạnh mẽ. Nhiều người theo tư tưởng Marxist, học giả và du khách quốc tế đến đây như một cuộc hành hương tinh thần để tưởng nhớ tác giả của những ý tưởng ảnh hưởng sâu rộng đến chính trị, xã hội thế giới.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt04-1761658416632-1761658416838362598298.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam viếng mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 3.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt04-1761658416632-1761658416838362598298.jpg\" h=\"485\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt04-1761658416632-1761658416838362598298.jpg\" style=\"width: 700px; height: 511px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 3.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và Phu nhân cùng Đoàn đại biểu cấp cao Việt Nam viếng mộ Karl Marx - Lãnh tụ của giai cấp vô sản - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghĩa trang Highgate nằm trên một quả đồi ở vùng ngoại ô phía Bắc London, tạo cho người đến viếng thăm một cảm giác thanh bình, trầm lắng. Đây cũng là nơi an nghỉ của nhiều nhân vật nổi tiếng như nhà vật lý học Michael Faraday, cha mẹ của nhà văn Charles Dickens, nhà triết học, xã hội học, chính trị học Herbert Spencer, nhà văn George Eliot…</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt01-1761658417539-1761658417720258468952.jpg\" target=\"_blank\" title=\"Tổng Bí thư Tô Lâm và các đại biểu tại mộ Karl Marx ở nghĩa trang Highgate, thủ đô London - Ảnh: TTXVN\"><img alt=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 4.\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/tbt01-1761658417539-1761658417720258468952.jpg\" h=\"463\" loading=\"lazy\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/tbt01-1761658417539-1761658417720258468952.jpg\" style=\"width: 700px; height: 487px;\" title=\"Tổng Bí thư Tô Lâm viếng Karl Marx - Lãnh tụ của giai cấp vô sản- Ảnh 4.\" type=\"photo\" w=\"665\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng Bí thư Tô Lâm và các đại biểu tại mộ Karl Marx ở nghĩa trang Highgate, thủ đô London - Ảnh: TTXVN</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nghĩa trang mở cửa đón du khách với thời gian và quy định riêng. Khi đến Nghĩa trang Highgate, du khách có thể tìm đến phần phía Đông (East Side) để nhìn thấy rõ đài mộ Karl Marx, nổi bật giữa không gian tĩnh lặng, xanh mướt./.</span></span></span></p>', '28/10/2025 22:00', 'https://bacninh.gov.vn/news/-/details/37632/tong-bi-thu-to-lam-vieng-karl-marx-lanh-tu-cua-giai-cap-vo-san-29280301', '', 'chinhphu.vn', 11, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (86, '29281340', 'Việt Nam và các đối tác quan trọng, chủ chốt đã \"chốt\" được nhiều vấn đề quan trọng', 'Việt Nam và các đối tác quan trọng, chủ chốt đã \"chốt\" được nhiều vấn đề quan trọng', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg', '<p>Trả lời phỏng vấn báo chí ngay sau khi Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị liên quan tại Malaysia vừa kết thúc, Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang cho biết đoàn Việt Nam do Thủ tướng Phạm Minh Chính dẫn đầu đã tiếp tục thể hiện vai trò thành viên tích cực, có trách nhiệm với...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị Cấp cao ASEAN-Trung Quốc 28  - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg\" h=\"1334\" id=\"img_907459773483909120\" loading=\"lazy\" photoid=\"907459773483909120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4203-17616192595921710875280.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 1.\" type=\"photo\" w=\"2000\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị Cấp cao ASEAN-Trung Quốc 28 - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xin&nbsp;</i><i>Thứ trưởng cho biết kết quả các Hội nghị Cấp cao ASEAN và giữa ASEAN với các đối tác?</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang:&nbsp;</b>Diễn ra trong bối cảnh thế giới có nhiều biến động, đặt ra thách thức cho toàn cầu và khu vực, Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị liên quan vừa khép lại với nhiều kết quả quan trọng. Trong đó có những điểm nhấn nổi bật như sau:</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Trước hết,</i>&nbsp;Hội nghị ghi nhận thành quả 10 năm xây dựng cộng đồng thông qua triển khai Tầm nhìn ASEAN 2025, là cơ sở để ASEAN triển khai thành công Tầm nhìn Cộng đồng ASEAN (ACV) 2045 cùng các Kế hoạch Chiến lược về chính trị-an ninh, kinh tế, văn hóa-xã hội và kết nối ASEAN.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội nghị đã thông qua gần 70 văn kiện thuộc ba trụ cột chính trị-an ninh, kinh tế và văn hóa-xã hội, cụ thể hóa cam kết của ASEAN với tiến trình xây dựng cộng đồng và thúc đẩy quan hệ đối tác thời gian tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Việc kết nạp Timor-Leste là một dấu mốc đáng nhớ, đánh dấu lần mở rộng thứ hai của ASEAN sau 30 năm (đợt thứ nhất bắt đầu với Việt Nam năm 1995). Đây là sự bổ sung đúng thời điểm nhằm mở rộng không gian phát triển, tạo thế và lực mới cho tiến trình phát triển của Hiệp hội.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ hai</i>, ASEAN tiếp tục thể hiện vai trò trung tâm và dẫn dắt trong việc duy trì hoà bình, ổn định ở khu vực, thể hiện qua việc hỗ trợ Campuchia và Thái Lan đã ký Tuyên bố chung triển khai các thỏa thuận đảm bảo hòa bình và bình thường hóa quan hệ tại biên giới, góp phần củng cố an ninh, ổn định chung của khu vực.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các nước cũng đánh giá cao vai trò và nỗ lực của Chủ tịch Malaysia trong thúc đẩy thực thi Đồng thuận 5 điểm về Myanmar; nhất trí Đồng thuận tiếp tục là định hướng chính cho các nỗ lực can dự của ASEAN thời gian tới, trong đó ưu tiên ngừng bắn và chấm dứt các hành động bạo lực, nối lại đối thoại và triển khai viện trợ nhân đạo đến người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sự tham gia đông đảo của lãnh đạo cấp cao các nước đối tác và các tổ chức quốc tế như Tổng thống Hoa Kỳ, Thủ tướng Trung Quốc, Tổng Thư ký Liên hợp quốc, Chủ tịch Hội đồng châu Âu... cũng một lần nữa khẳng định vị thế của ASEAN trong chính sách của các nước đối tác lớn, các nước lớn trên thế giới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ ba,</i>&nbsp;Hội nghị một lần nữa khẳng định vị thế của ASEAN với tư cách một động lực tăng trưởng và mắt xích không thể thiếu trong chuỗi cung ứng, kết nối thương mại và đầu tư toàn cầu, với GDP 3,8 nghìn tỷ USD (2023), đầu tư nước ngoài 226 tỷ USD (2024) và mạng lưới 08 hiệp định thương mại bao trùm cả khu vực.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhằm nâng cao tự chủ về kinh tế, củng cố liên kết nội khối, ASEAN đã nâng cấp Hiệp định thương mại hàng hóa (ATIGA), cơ bản hoàn tất Hiệp định khung kinh tế số (DEFA), và thúc đẩy kết nối Lưới điện ASEAN (APG). Đồng thời ASEAN cũng thống nhất về chiến lược tranh thủ các xu thế lớn như kinh tế xanh, kinh tế số, trí tuệ nhân tạo, ứng phó các thách thức nổi lên như tội phạm xuyên quốc gia, tội phạm mạng, biến đổi khí hậu…</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hội nghị đã thể hiện cam kết dài hạn của ASEAN với chủ nghĩa đa phương thông qua thực hiện hiệu quả các Hiệp định Thương mại Tự do (FTA) với đối tác, mà điểm nhấn là nâng cấp FTA ASEAN-Trung Quốc (ACFTA 3.0), xúc tiến nâng cấp FTA với Hàn Quốc và nghiên cứu đàm phán FTA với EU và GCC…</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/789-17616529188511688153445.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị ASEAN – Australia - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/789-17616529188511688153445.jpg\" h=\"518\" id=\"img_907600895319187456\" loading=\"lazy\" photoid=\"907600895319187456\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/789-17616529188511688153445.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 2.\" type=\"photo\" w=\"777\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" id=\"\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính phát biểu tại Hội nghị ASEAN – Australia - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cũng trong dịp này, Việt Nam tiếp tục thể hiện vai trò thành viên tích cực, có trách nhiệm với hai đóng góp quan trọng.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ nhất là dưới sự điều phối của Việt Nam, ASEAN và New Zealand ra Tuyên bố chung nâng cấp quan hệ lên Đối tác Chiến lược Toàn diện và thông qua Kế hoạch hành động 2026-2030 triển khai khuôn khổ vừa thiết lập.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thứ hai là trên cương vị Chủ tịch Nhóm đặc trách Sáng kiến hội nhập ASEAN (IAI), Việt Nam chủ trì xây dựng Kế hoạch công tác IAI 2026-2030, được Hội nghị cấp cao thông qua. Văn kiện này hướng tới mục tiêu thu hẹp khoảng cách phát triển, củng cố đoàn kết, ưu tiên hỗ trợ Timor-Leste bắt kịp tiến trình hội nhập chung của ASEAN. Vai trò, nỗ lực của Việt Nam được các nước cảm ơn và đánh giá cao.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trong thành công chung, những phát biểu sâu sắc, chân tình, thẳng thắn của Thủ tướng Chính phủ Phạm Minh Chính tại các hội nghị đã nhấn mạnh tầm quan trọng của hòa bình, ổn định, nêu rõ đây là điều kiện tiên quyết cho phát triển, đề cao ý nghĩa của đoàn kết ASEAN, khẳng định cam kết của Việt Nam đóng góp cho ASEAN, vì lợi ích thiết thân của người dân và doanh nghiệp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những chia sẻ của Thủ tướng Chính phủ, đặc biệt là đề xuất ASEAN phát huy mạnh mẽ ba nguồn lực chiến lược – sức mạnh đoàn kết, sức sống năng động và sức bật đổi mới – đã được các nước thành viên và đối tác ghi nhận, đánh giá cao về tinh thần trách nhiệm, tính đúng đắn của nội dung và tính khả thi, hiệu quả của phương hướng triển khai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xin Thứ trưởng chia sẻ những kết quả chính của các cuộc tiếp xúc song phương của Đoàn Việt Nam với các nước, các đối tác trong dịp này?</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang:&nbsp;</b>Chỉ trong 3 ngày dự Hội nghị, Thủ tướng Chính phủ Phạm Minh Chính đã có các cuộc gặp, tiếp xúc song phương với lãnh đạo khoảng hơn 20 đối tác từ bao gồm toàn bộ các quốc gia ASEAN, nhiều lãnh đạo các nước đối tác lớn, lãnh đạo các tổ chức quốc tế và khu vực. Các cuộc gặp, trao đổi tuy ngắn nhưng đạt nhiều kết quả cụ thể và thực chất, nổi bật nhất là:</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/5-17616533390411932516060.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Tổng thống Hoa Kỳ Donald Trump - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/5-17616533390411932516060.jpg\" h=\"518\" id=\"img_907602656663584768\" loading=\"lazy\" photoid=\"907602656663584768\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/5-17616533390411932516060.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 3.\" type=\"photo\" w=\"777\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Tổng thống Hoa Kỳ Donald Trump - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ nhất, tin cậy chính trị giữa Việt Nam và các nước được tăng cường.</i>&nbsp;Các nước đều mong muốn đẩy mạnh quan hệ với Việt Nam. Việc Tổng thống Hoa Kỳ Donald Trump, Thủ tướng Trung Quốc Lý Cường, tân Thủ tướng Nhật Takaichi Sanae, Tổng thống Brazil Lula da Silva, Thủ tướng Canada Mark Carney và nhiều lãnh đạo khác đều nhất trí với đề nghị của Việt Nam về tăng cường trao đổi đoàn cấp cao thời gian tới cho thấy các nước nhìn nhận, đánh giá cao vai trò của Việt Nam ở khu vực, ủng hộ Việt Nam ổn định, phát triển, đóng vai trò ngày càng quan trọng trong ASEAN và trên trường quốc tế.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ hai, Việt Nam và các đối tác quan trọng, chủ chốt đã \"chốt\" được nhiều vấn đề quan trọng</i>&nbsp;phản ánh lợi ích chung của Việt Nam với các đối tác. Thủ tướng Trung Quốc Lý Cường nhất trí tích cực thúc đẩy việc khởi công tuyến đường sắt cao tốc Hà Nội – Hải Phòng – Lào Cai.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Canada Mark Carney cho biết sẽ sớm công bố dự án trị giá 20 triệu USD xây dựng thành phố thông minh ven biển thích ứng với thiên tai, biến đổi khí hậu.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phó Chủ tịch Ngân hàng Thế giới Carlos Felipe Jaramillo khẳng định sẽ đáp ứng các đề nghị của Việt Nam về việc huy động nguồn lực nhanh, hiệu quả hơn trong hỗ trợ các mục tiêu phát triển kinh tế - xã hội của Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đặc biệt, điểm nhấn rất quan trọng dịp này là Việt Nam và Hoa Kỳ đã công bố Tuyên bố chung về Hiệp định thương mại đối ứng, công bằng và cân bằng ngày 26/10/2025.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đó đều là những bước tiến quan trọng góp phần tạo nền tảng ổn định, bền vững trong quan hệ của Việt Nam với các đối tác quan trọng, chủ chốt, góp phần huy động thêm nguồn lực bên ngoài để hiện thực hóa các mục tiêu chiến lược của đất nước, đặc biệt là mục tiêu tăng trưởng hai con số từ sau Đại hội Đảng XIV.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4227-17616297796251891938746.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Singapore Lawrence Wong - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4227-17616297796251891938746.jpg\" h=\"1069\" id=\"img_907503859865079808\" loading=\"lazy\" photoid=\"907503859865079808\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4227-17616297796251891938746.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 4.\" type=\"photo\" w=\"1604\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Singapore Lawrence Wong - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Thứ ba, trong trao đổi, có thể thấy các đối tác thực sự ủng hộ, mong muốn Việt Nam đóng vai trò lớn hơn trong ASEAN, ở khu vực Châu Á-Thái Bình Dương cũng như trên trường quốc tế.</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Lãnh đạo nhiều nước và tổ chức quốc tế rất ấn tượng với tốc độ phát triển của Việt Nam trong mấy chục năm qua. Các đối tác đều khẳng định coi trọng vai trò, vị thế của Việt Nam, mong muốn Việt Nam ủng hộ thúc đẩy quan hệ hợp tác giữa các nước với ASEAN.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Điều này cho thấy các nước nhìn nhận Việt Nam là một trong những quốc gia thành viên chủ chốt, có khả năng dẫn dắt trong ASEAN. Trong bối cảnh Việt Nam đang đẩy mạnh triển khai Nghị quyết 59 của Bộ Chính trị về hội nhập quốc tế trong tình hình mới và nâng tầm đối ngoại đa phương, sự tin cậy, ủng hộ của bạn bè quốc tế là vốn chính trị rất quý báu để Việt Nam đóng góp lớn hơn vào nền chính trị thế giới, kinh tế toàn cầu và văn minh nhân loại như Đảng ta và Tổng Bí thư Tô Lâm nhiều lần nhấn mạnh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Xin ông cho biết các định hướng cụ thể triển khai kết quả của việc Việt Nam tham dự Hội nghị Cấp cao ASEAN lần này?</i></span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><b>Thứ trưởng Bộ Ngoại giao Đặng Hoàng Giang:&nbsp;</b>Hội nghị lần này khép lại năm ASEAN 2025, năm bản lề đánh dấu ASEAN bước sang giai đoạn phát triển mới. Các kết quả đạt được trong các cuộc gặp gỡ, trao đổi của Thủ tướng Chính phủ với lãnh đạo các nước, tổ chức cũng cần được đôn đốc. Bởi vậy việc triển khai các kết quả nhiều mặt có ý nghĩa đặc biệt quan trọng, đòi hỏi sự tham gia chủ động và đồng bộ từ tất cả các Bộ, ngành, địa phương.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Về chỉ đạo – điều hành,</i>&nbsp;chúng ta cần sớm xây dựng Đề án Tổng thể và các chương trình hành động tương ứng để triển khai Tầm nhìn Cộng đồng ASEAN (ACV) 2045, lồng ghép định hướng lớn của các Nghị quyết trụ cột được Bộ Chính trị ban hành, từ đó triển khai đồng bộ, toàn diện ACV 2045, cùng ASEAN bắt kịp các xu thế lớn và bứt lên trong kỷ nguyên phát triển mới của dân tộc.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Công tác triển khai cần đảm bảo hai tiêu chí, một là không chỉ tập trung về lượng mà phải đi sâu về chất, hai là không chỉ là nhiệm vụ của riêng các cơ quan chủ trì các trụ cột hay chuyên ngành, mà là nhiệm vụ chung của hệ thống chính trị, nhằm đảm bảo tính gắn kết liên ngành trong nước và hiệu quả điều phối liên trụ cột trong ASEAN. Do đó, cũng cần chú trọng nâng cao nhận thức của các Bộ, ngành, địa phương về vai trò và trách nhiệm thực thi trong dài hạn.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim- Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 5.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" h=\"1069\" id=\"img_907495201910915072\" loading=\"lazy\" photoid=\"907495201910915072\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam và các đối tác quan trọng, chủ chốt đã &quot;chốt&quot; được nhiều vấn đề quan trọng- Ảnh 5.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim- Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời, các Bộ ngành cần chủ động có kế hoạch đưa các văn kiện đã hoặc sắp hoàn tất như ATIGA, ACFTA 3.0, DEFA vào thực thi, nhằm khai mở tiềm năng của các cam kết, thỏa thuận, mang lại lợi ích trực tiếp, thiết thân cho doanh nghiệp và người dân.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\"><i>Về nhiệm vụ cụ thể,&nbsp;</i>trước mắt, ta cần đóng góp tích cực vào xây dựng đoàn kết ASEAN, nhất là trong nỗ lực giải quyết vấn đề Myanmar, triển khai thỏa thuận hòa bình Campuchia và Thái Lan, góp phần duy trì môi trường hòa bình, ổn định trong khu vực, thuận lợi cho ASEAN, trong đó có Việt Nam, theo đuổi các mục tiêu dài hạn được vạch ra trong ACV 2045.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đồng thời, cần chú trọng hỗ trợ Timor-Leste nâng cao năng lực, hội nhập ASEAN hiệu quả trên cả ba trụ cột. Là nước gia nhập trước và đạt nhiều thành tựu sau 30 năm tham gia ASEAN, Việt Nam có vị thế phù hợp để chia sẻ kinh nghiệm và hỗ trợ toàn diện Timor-Leste trong tiến trình này. Bộ Ngoại giao cũng đang xúc tiến sớm mở Đại sứ quán tại Timor-Leste, góp phần triển khai hiệu quả nhiệm vụ này.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Cuối cùng, cần khẩn trương triển khai các thỏa thuận, cam kết mà Việt Nam và các đối tác đã đạt được tại các cuộc gặp song phương trong khuôn khổ Hội nghị, trong đó có trao đổi đoàn, thúc đẩy hợp tác kinh tế - thương mại, an ninh lương thực, năng lượng, và đặc biệt là giải quyết dứt điểm các vấn đề tồn tại để gỡ thẻ vàng IUU của EU. Các bộ, ngành, địa phương, doanh nghiệp cần phối hợp chặt chẽ, tích cực và khẩn trương để bảo đảm triển khai đồng bộ, hiệu quả các kết quả đạt được với các đối tác./.</span></span></span></p>', '28/10/2025 21:30', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-va-cac-oi-tac-quan-trong-chu-chot-a-chot-uoc-nhieu-van-e-quan-trong-29281340', '', 'chinhphu.vn', 11, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (87, '29282427', 'Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN...', 'Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg', '<p>Chiều 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính cùng Lãnh đạo các nước ASEAN tham dự Lễ bế mạc Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị Cấp cao liên quan, Lễ chuyển giao cương vị Chủ tịch ASEAN từ Malaysia sang Philippines. Đoàn Việt Nam đã tham gia gần 20...', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4273-17616427767721062062598.jpg\" target=\"_blank\" title=\"Thủ tướng Malaysia Anwar Ibrahim phát biểu bế mạc Hội nghị- Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4273-17616427767721062062598.jpg\" h=\"1069\" id=\"img_907558372477698048\" loading=\"lazy\" photoid=\"907558372477698048\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4273-17616427767721062062598.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 1.\" type=\"photo\" w=\"1603\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Malaysia Anwar Ibrahim phát biểu bế mạc Hội nghị- Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Sau ba ngày làm việc khẩn trương với hơn 20 hoạt động, Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị liên quan đã thành công tốt đẹp.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Phát biểu bế mạc Hội nghị, Thủ tướng Malaysia Anwar Ibrahim cảm ơn tất cả nước thành viên và các đối tác về những đóng góp thực chất và những nỗ lực bền bỉ góp phần làm nên thành công của Hội nghị, một sự kiện \"được dẫn dắt bởi lòng kiên trì và lý trí sáng suốt trong một thời khắc đầy biến động\", một kết quả tiêu biểu cho \"phương cách ASEAN.\"</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Những kết quả quan trọng đạt được sẽ tiếp thêm sức sống cho tiến trình liên kết khu vực, gia tăng sức mạnh tổng hợp và vị thế của Cộng đồng ASEAN \"bao trùm và bền vững\" theo đúng chủ đề của năm 2025, giúp ASEAN sẵn sàng vững bước trên chặng đường phát triển mới với 11 thành viên.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Kết quả của các Hội nghị giữa ASEAN và các nước Đối tác cũng khẳng định vị thế, vai trò trung tâm của ASEAN và giúp tiếp tục củng cố và mở rộng quan hệ đối ngoại của ASEAN vì hòa bình, ổn định và phát triển.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4276-1761642776789394683402.jpg\" target=\"_blank\" title=\"Tổng thống Philippines Ferdinand Marcos Jr. tiếp nhận vai trò Chủ tịch ASEAN năm 2026 từ Thủ tướng Malaysia - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4276-1761642776789394683402.jpg\" h=\"1069\" id=\"img_907558372409155584\" loading=\"lazy\" photoid=\"907558372409155584\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4276-1761642776789394683402.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 2.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng thống Philippines Ferdinand Marcos Jr. tiếp nhận vai trò Chủ tịch ASEAN năm 2026 từ Thủ tướng Malaysia - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tiếp nhận vai trò Chủ tịch ASEAN năm 2026 từ Thủ tướng Malaysia, Tổng thống Philippines Ferdinand Marcos Jr. công bố Chủ đề Năm ASEAN 2026 của Philippines là \"Cùng chèo lái tới tương lai\" (Navigating our future together) với ba ưu tiên lớn là củng cố hòa bình và an ninh, tăng cường các hành lang thịnh vượng, và thúc đẩy trao quyền cho người dân.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4278-17616427768231612770244.jpg\" target=\"_blank\" title=\"Tổng thống Philippines Ferdinand Marcos Jr. công bố Chủ đề Năm ASEAN 2026 của Philippines là &quot;Cùng chèo lái tới tương lai&quot; - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4278-17616427768231612770244.jpg\" h=\"1069\" id=\"img_907558372600045568\" loading=\"lazy\" photoid=\"907558372600045568\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4278-17616427768231612770244.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 3.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tổng thống Philippines Ferdinand Marcos Jr. công bố Chủ đề Năm ASEAN 2026 của Philippines là \"Cùng chèo lái tới tương lai\" - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Đoàn Việt Nam do Thủ tướng Chính phủ Phạm Minh Chính dẫn đầu đã tham gia tích cực, đóng góp hiệu quả vào gần 20 hoạt động đa phương trong khuôn khổ Hội nghị, chia sẻ nhiều định hướng quan trọng định hình tương lai của ASEAN. Quan hệ hữu nghị và hợp tác thực chất giữa Việt Nam với các đối tác cũng được thúc đẩy thực chất thông qua hơn 20 cuộc tiếp xúc song phương.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4272-17616427767491648420788.jpg\" target=\"_blank\" title=\"Chương trình văn nghệ tại Lễ bế mạc - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 4.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4272-17616427767491648420788.jpg\" h=\"1069\" id=\"img_907558372543447040\" loading=\"lazy\" photoid=\"907558372543447040\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4272-17616427767491648420788.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 4.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Chương trình văn nghệ tại Lễ bế mạc - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Các đóng góp, đề xuất và sáng kiến của Việt Nam tập trung thúc đẩy xây dựng Cộng đồng ASEAN đoàn kết, tự cường, bao trùm và bền vững, lấy người dân làm trung tâm, gắn kết phát triển quốc gia với phát triển khu vực. Qua đó, Việt Nam tiếp tục thể hiện vai trò thành viên chủ động, tích cực và có trách nhiệm, đóng góp thiết thực vào củng cố đoàn kết nội khối, nâng cao vai trò trung tâm của ASEAN, vì hòa bình, ổn định, hợp tác và phát triển trong khu vực.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính rời Kuala Lumpur về nước, kết thúc thành công chuyến công tác tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị cấp cao liên quan - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 7.\" data-author=\"\" data-mobile-url=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" h=\"1653\" id=\"img_907606293057970176\" loading=\"lazy\" photoid=\"907606293057970176\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/ttg-17616541834381148616301.jpg\" style=\"width: 700px; height: 578px;\" title=\"Thủ tướng hoàn thành hơn 40 hoạt động trong chuyến công tác dự Hội nghị Cấp cao ASEAN 47- Ảnh 7.\" type=\"photo\" w=\"2000\" /></a></p>\n\n<figure allow-zoom=\"true\" type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính rời Kuala Lumpur về nước, kết thúc thành công chuyến công tác tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị cấp cao liên quan - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Tối 28/10, Thủ tướng Chính phủ Phạm Minh Chính và Đoàn Việt Nam đã rời Kuala Lumpur về nước, kết thúc thành công chuyến công tác tham dự Hội nghị Cấp cao ASEAN lần thứ 47 và các Hội nghị cấp cao liên quan từ ngày 25 đến ngày 28/10/2025 theo lời mời của Thủ tướng Malaysia Anwar Ibrahim, Chủ tịch ASEAN 2025.</span></span></span></p>', '28/10/2025 20:00', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-hoan-thanh-hon-40-hoat-ong-trong-chuyen-cong-tac-du-hoi-nghi-cap-cao-asean-47-29282427', '', 'chinhphu.vn', 11, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (88, '29283201', 'Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal', 'Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg', '<p>Ngày 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính đã gặp Thủ tướng Malaysia Anwar Ibrahim nhân dịp dự Hội nghị Cấp cao ASEAN.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg\" h=\"1069\" id=\"img_907495201721221120\" loading=\"lazy\" photoid=\"907495201721221120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4219-17616277160031411220599.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 1.\" type=\"photo\" w=\"1603\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Malaysia Anwar Ibrahim - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà lãnh đạo đánh giá cao những nỗ lực của các bộ, ngành hai nước trong khẩn trương triển khai các lĩnh vực hợp tác, góp phần đưa quan hệ Đối tác Chiến lược toàn diện Việt Nam – Malaysia ngày càng đi vào chiều sâu và thực chất và xác định hợp tác kinh tế vẫn là trụ cột quan trọng trong quan hệ hai nước thời gian tới.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Vui mừng gặp lại Thủ tướng Anwar Ibrahim sau chuyến thăm chính thức Malaysia nhân dịp dự Hội nghị cấp cao ASEAN lần thứ 46 (5/2025), Thủ tướng Chính phủ Phạm Minh Chính đánh giá cao các bước tiến lớn trong hợp tác kinh tế hai nước thời gian qua, theo đó kim ngạch thương mại hai chiều tính tới tháng 9/2025 đã đạt hơn 12 tỷ USD, tăng 12,9% so với cùng kỳ năm trước.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính đề nghị hai nước tiếp tục phối hợp thúc đẩy quan hệ quốc phòng trên cơ sở triển khai hiệu quả Bản ghi nhớ về Hợp tác quốc phòng song phương - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" h=\"1069\" id=\"img_907495201910915072\" loading=\"lazy\" photoid=\"907495201910915072\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4223-1761627716045201804370.jpg\" style=\"width: 700px; height: 467px;\" title=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 2.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính đề nghị hai nước tiếp tục phối hợp thúc đẩy quan hệ quốc phòng trên cơ sở triển khai hiệu quả Bản ghi nhớ về Hợp tác quốc phòng song phương - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Anwar Ibrahim ủng hộ đề xuất của Thủ tướng Chính phủ Phạm Minh Chính về việc hai bên sớm ký văn kiện hợp tác trong lĩnh vực phát triển công nghiệp Halal và khẳng định Malaysia sẵn sàng hỗ trợ Việt Nam tổ chức các hoạt động xúc tiến quảng bá hàng nông sản để tăng độ nhận diện tại thị trường Malaysia.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính đề nghị hai nước tiếp tục phối hợp thúc đẩy quan hệ quốc phòng trên cơ sở triển khai hiệu quả Bản ghi nhớ về Hợp tác quốc phòng song phương ký tháng 12/2023.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4224-17616277160681273654453.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ cũng mong muốn hai bên sớm ký kết các thỏa thuận hợp tác trong lĩnh vực an ninh, giáo dục, hàng không - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4224-17616277160681273654453.jpg\" h=\"1069\" id=\"img_907495201830985728\" loading=\"lazy\" photoid=\"907495201830985728\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4224-17616277160681273654453.jpg\" style=\"width: 700px; height: 450px;\" title=\"Thủ tướng Malaysia ủng hộ sớm ký văn kiện hợp tác với Việt Nam về Halal- Ảnh 3.\" type=\"photo\" w=\"1660\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ cũng mong muốn hai bên sớm ký kết các thỏa thuận hợp tác trong lĩnh vực an ninh, giáo dục, hàng không - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ cũng mong muốn hai bên sớm ký kết các thỏa thuận hợp tác trong lĩnh vực an ninh, giáo dục, hàng không; thúc đẩy mở rộng hợp tác trong các lĩnh vực kinh tế số, kinh tế xanh, khoa học công nghệ, đổi mới sáng tạo, nông nghiệp thông minh, chính phủ điện tử, an ninh mạng, đào tạo nhân lực AI.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Anwar Ibrahim nhất trí hai nước thiết lập cơ chế tham vấn và quản lý về biển, phối hợp với các nước ASEAN triển khai hợp tác thiết thực về biển và đại dương, hợp tác ngư nghiệp và hoan nghênh nỗ lực của Việt Nam trong công tác phòng chống khai thác hải sản trái phép, không báo cáo và không theo quy định (IUU), nhất trí sẽ phối hợp chặt chẽ, hướng tới gỡ \"thẻ vàng\" của EU.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Malaysia tổ chức Hội nghị cấp cao ASEAN 47 thành công về mọi mặt, phát huy vai trò trung tâm của ASEAN trong giải quyết các vấn đề khu vực và giữ vững đoàn kết nội khối, góp phần vào hòa bình, an ninh và phát triển khu vực.</span></span></span></p>', '28/10/2025 19:30', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-malaysia-ung-ho-som-ky-van-kien-hop-tac-voi-viet-nam-ve-halal-29283201', '', 'chinhphu.vn', 13, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (89, '29283811', 'Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam', 'Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg', '<p>Ngày 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính đã hội kiến Quốc vương Brunei Darussalam Sultan Haji Hassanal Bolkiah nhân dịp dự Hội nghị Cấp cao ASEAN.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính hội kiến Quốc vương Brunei Darussalam Sultan Haji Hassanal Bolkiah- Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg\" h=\"1337\" id=\"img_907570557481766912\" loading=\"lazy\" photoid=\"907570557481766912\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z7164375698791a3698a6a1e9ae528d78d951a4cd823d5-1761645682082211932546.jpg\" style=\"width: 700px; height: 495px;\" title=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 1.\" type=\"photo\" w=\"1888\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính hội kiến Quốc vương Brunei Darussalam Sultan Haji Hassanal Bolkiah- Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính trân trọng chuyển lời thăm hỏi của Tổng Bí thư Tô Lâm, Chủ tịch nước Lương Cường, Chủ tịch Quốc hội Trần Thanh Mẫn tới Quốc vương Brunei.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ khẳng định các bộ, ngành hữu quan của Việt Nam sẽ tích cực phối hợp với phía Brunei để chuẩn bị mọi mặt cho chuyến thăm Việt Nam của Quốc vương và Hoàng hậu trong thời gian tới, đạt những kết quả tốt đẹp, thực chất.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987878bd8c9a949c5ee9f774b59e865768288-1761645682028604991344.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính đề nghị Brunei tiếp tục tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam hợp tác kinh doanh tất cả các lĩnh vực cùng có lợi - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987878bd8c9a949c5ee9f774b59e865768288-1761645682028604991344.jpg\" h=\"1360\" id=\"img_907570557674160128\" loading=\"lazy\" photoid=\"907570557674160128\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z71643756987878bd8c9a949c5ee9f774b59e865768288-1761645682028604991344.jpg\" style=\"width: 700px; height: 505px;\" title=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 2.\" type=\"photo\" w=\"1888\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính đề nghị Brunei tiếp tục tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam hợp tác kinh doanh tất cả các lĩnh vực cùng có lợi - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Quốc vương Brunei vui mừng nhận thấy quan hệ giữa Việt Nam và Brunei Darussalam tiếp tục phát triển tốt đẹp. Đánh giá tiềm năng thúc đẩy hợp tác trong thời gian tới, Quốc vương Brunei cho rằng hai nước còn nhiều dư địa, tiềm năng cần khai thác, phát huy tốt hơn nữa như dầu khí, thủy hải sản, du lịch, đặc biệt là liên doanh chế biến thực phẩm Halal tại Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Về định hướng hợp tác song phương, Thủ tướng Chính phủ Phạm Minh Chính nhấn mạnh hai nền kinh tế có tính bổ sung cao, đề nghị Brunei tiếp tục tạo điều kiện thuận lợi cho các doanh nghiệp Việt Nam hợp tác kinh doanh tất cả các lĩnh vực cùng có lợi; cấp thêm giấy phép cho các tàu cá, ngư dân Việt Nam được đánh bắt thủy, hải sản tại vùng biển Brunei; đồng thời hỗ trợ Việt Nam cấp chứng chỉ, sản xuất thực phẩm Halal và tận dụng lợi thế nguyên liệu phong phú, dồi dào của Việt Nam.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987881e0e3b7494b0f03b130a68cb4820b030-1761645682051823337356.jpg\" target=\"_blank\" title=\"Hai nhà Lãnh đạo nhất trí tiếp tục thực hiện hiệu quả Chương trình hành động triển khai quan hệ Đối tác Toàn diện Việt Nam - Brunei giai đoạn 2023-2027 - Ảnh: VGP/Nhật Bắc\"><img alt=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/gen-h-z71643756987881e0e3b7494b0f03b130a68cb4820b030-1761645682051823337356.jpg\" h=\"1207\" id=\"img_907570557617250304\" loading=\"lazy\" photoid=\"907570557617250304\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/gen-h-z71643756987881e0e3b7494b0f03b130a68cb4820b030-1761645682051823337356.jpg\" style=\"width: 700px; height: 448px;\" title=\"Thủ tướng đề nghị Brunei cấp thêm giấy phép đánh bắt cho các tàu cá Việt Nam- Ảnh 3.\" type=\"photo\" w=\"1888\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà Lãnh đạo nhất trí tiếp tục thực hiện hiệu quả Chương trình hành động triển khai quan hệ Đối tác Toàn diện Việt Nam - Brunei giai đoạn 2023-2027 - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Nhân dịp này, hai nhà Lãnh đạo nhất trí tiếp tục thực hiện hiệu quả Chương trình hành động triển khai quan hệ Đối tác Toàn diện Việt Nam - Brunei giai đoạn 2023-2027, tăng cường tiếp xúc, trao đổi ở các cấp và thúc đẩy giao lưu nhân dân, góp phần tạo đà và làm sâu sắc hơn quan hệ song phương trong thời gian tới.</span></span></span></p>', '28/10/2025 19:00', 'https://bacninh.gov.vn/news/-/details/37632/thu-tuong-e-nghi-brunei-cap-them-giay-phep-anh-bat-cho-cac-tau-ca-viet-nam-29283811', '', 'chinhphu.vn', 14, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
INSERT INTO `sync_articles` VALUES (90, '29283991', 'Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN', 'Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN', 'https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg', '<p>Ngày 28/10, tại Kuala Lumpur, Malaysia, Thủ tướng Chính phủ Phạm Minh Chính đã gặp Thủ tướng Timor-Leste Xanana Gusmão nhân dịp dự Hội nghị Cấp cao ASEAN.</p>\n\n<p>&nbsp;</p>', '<h1 data-role=\"title\" style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Timor-Leste Xanana Gusmão - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 1.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg\" h=\"1069\" id=\"img_907561952438267904\" loading=\"lazy\" photoid=\"907561952438267904\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4282-17616436305631433974777.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 1.\" type=\"photo\" w=\"1603\" /></a></h1>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính gặp Thủ tướng Timor-Leste Xanana Gusmão - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Timor-Leste chính thức trở thành thành viên thứ 11 của ASEAN, đánh dấu bước ngoặt lịch sử trong tiến trình hội nhập của nước này, cũng là dấu mốc lịch sử trong tiến trình phát triển của ASEAN.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ khẳng định Việt Nam sẽ tiếp tục đồng hành, sẵn sàng hỗ trợ, chia sẻ kinh nghiệm để Timor-Leste tham gia một cách hiệu quả và đóng góp tích cực vào Cộng đồng ASEAN.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4285-17616436306451466724560.jpg\" target=\"_blank\" title=\"Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Timor-Leste chính thức trở thành thành viên thứ 11 của ASEAN - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 2.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4285-17616436306451466724560.jpg\" h=\"1069\" id=\"img_907561952496517120\" loading=\"lazy\" photoid=\"907561952496517120\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4285-17616436306451466724560.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 2.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng Chính phủ Phạm Minh Chính chúc mừng Timor-Leste chính thức trở thành thành viên thứ 11 của ASEAN - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Thủ tướng hai nước đánh giá quan hệ hữu nghị, hợp tác giữa Việt Nam và Timor-Leste thời gian qua tiếp tục phát triển tích cực, đặc biệt trong các lĩnh vực kinh tế - thương mại, nông nghiệp, viễn thông và giáo dục.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai bên nhất trí tăng cường trao đổi đoàn các cấp, thúc đẩy triển khai hiệu quả các thỏa thuận hợp tác đã ký kết; mở rộng hợp tác trong các lĩnh vực tiềm năng như kinh tế xanh, kinh tế số, năng lượng sạch, đổi mới sáng tạo, trí tuệ thông minh.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà lãnh đạo nhất trí làm sâu sắc hơn quan hệ song phương của hai nước trong thời gian tới, thúc đẩy các chuyến thăm cấp cao và các cấp, sớm tổ chức cuộc họp đầu tiên của Uỷ ban hỗn hợp Việt Nam - Timor-Leste cấp Bộ trưởng Ngoại giao, triển khai hiệu quả các thỏa thuận đã ký kết; khai thác các tiềm năng hợp tác kinh tế, đặc biệt là thương mại đầu tư, và tạo điều kiện thuận lệ, cho doanh nghiệp hai nước kinh doanh, hoạt động tại thị trường của nhau.</span></span></span></p>\n\n<p style=\"text-align: center;\"><a data-fancybox=\"img-lightbox\" href=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4284-1761643630612739622404.jpg\" target=\"_blank\" title=\"Hai nhà lãnh đạo nhất trí làm sâu sắc hơn quan hệ song phương của hai nước trong thời gian tới - Ảnh: VGP/Nhật Bắc\"><img alt=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 3.\" data-author=\"\" data-original=\"https://bcp.cdnchinhphu.vn/334894974524682240/2025/10/28/img4284-1761643630612739622404.jpg\" h=\"1069\" id=\"img_907561952610476032\" loading=\"lazy\" photoid=\"907561952610476032\" rel=\"lightbox\" src=\"https://bcp.cdnchinhphu.vn/thumb_w/777/334894974524682240/2025/10/28/img4284-1761643630612739622404.jpg\" style=\"width: 700px; height: 467px;\" title=\"Việt Nam sẵn sàng hỗ trợ Timor-Leste tham gia hiệu quả vào Cộng đồng ASEAN- Ảnh 3.\" type=\"photo\" w=\"1603\" /></a></p>\n\n<figure type=\"Photo\">\n<figcaption>\n<p data-placeholder=\"Nhập chú thích ảnh\" style=\"text-align: center;\"><span style=\"color:#0000ff;\"><span style=\"font-size:16px;\"><span style=\"line-height:1.3;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai nhà lãnh đạo nhất trí làm sâu sắc hơn quan hệ song phương của hai nước trong thời gian tới - Ảnh: VGP/Nhật Bắc</span></span></span></span></p>\n</figcaption>\n</figure>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Hai bên cùng nhất trí đẩy mạnh hợp tác văn hóa, du lịch, giáo dục, đóng góp tích cực vào việc triển khai giao lưu nhân dân và thúc đẩy quan hệ hữu nghị và hợp tác nhiều mặt giữa hai nước.</span></span></span></p>\n\n<p style=\"text-align: justify;\"><span style=\"line-height:1.3;\"><span style=\"font-size:18px;\"><span style=\"font-family:Arial,Helvetica,sans-serif;\">Trao đổi về các vấn đề quốc tế và khu vực, hai bên nhất trí tiếp tục phối hợp chặt chẽ và ủng hộ lẫn nhau tại các diễn đàn đa phương. Thủ tướng Chính phủ Phạm Mình Chính nhấn mạnh Việt Nam cam kết tiếp tục hỗ trợ Timor-Leste tham gia hiệu quả vào các hoạt động của ASEAN; mong Timor-Leste, với tư cách là một quốc gia thành viên UNCLOS 1982 và là một thành viên thứ 11 của ASEAN, tiếp tục ủng hộ lập trường chung của ASEAN về vấn đề Biển Đông và cùng nỗ lực đạt được một COC thực sự hiệu lực, thực chất, phù hợp với luật pháp quốc tế, nhất là UNCLOS 1982, góp phần xây dựng Biển Đông thành vùng biển hòa bình. ổn định, hợp tác và phát triển.</span></span></span></p>', '28/10/2025 19:00', 'https://bacninh.gov.vn/news/-/details/37632/viet-nam-san-sang-ho-tro-timor-leste-tham-gia-hieu-qua-vao-cong-ong-asean-29283991', '', 'chinhphu.vn', 16, 'Tin quốc tế', 9, '', '38762', '{}', '2025-10-31 09:00:35.000000', 9, 11);
